INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/liquid-glass-design', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'liquid-glass-design', 61988, 7678, 89, '2026-03-06T03:39:20Z', '2026-03-06T04:20:45.609Z', '024aa207eb3d4d31d868954a7352a40b78c61f2fd007ab8b452afb6217070f84', '{"id":"affaan-m/everything-claude-code/liquid-glass-design","name":"liquid-glass-design","description":{"en":"This AI agent skill provides implementation patterns for Apple''s iOS 26 Liquid Glass design system. It enables developers to create dynamic glass materials with blur, reflection, and interactive morphing for SwiftUI, UIKit, and WidgetKit applications.","zh":"Liquid Glass 设计系统是一种动态玻璃材质，能够模糊内容、反射颜色和光线，并对触摸和指针交互做出反应","ja":"Liquid Glass デザインシステムは、動的なガラス素材で、内容をぼかしたり、周囲の内容からの色や光を反射したり、タッチやポインターの操作に反応したりします","ko":"Liquid Glass 디자인 시스템은 동적 유리 재료로 내용을 흐리게 하거나 주변 내용의 색상 및 빛을 반사하며 터치나 포인터 조작에 반응합니다","es":"El sistema de diseño Liquid Glass para iOS 26 proporciona patrones para implementar un material de vidrio dinámico con desenfoque de contenido, reflexión de color y luz, y reacción a interacciones táctiles. Cubre integración con SwiftUI, UIKit y WidgetKit.","fr":"Le système de design Liquid Glass pour iOS 26 fournit des modèles pour implémenter un matériau verre dynamique avec flou de contenu, réflexion de couleur et lumière, et réaction aux interactions tactiles. Couvre l''intégration avec SwiftUI, UIKit et WidgetKit.","de":"Das Liquid Glass Design System für iOS 26 bietet Muster zur Implementierung eines dynamischen Glas-Materials mit Inhaltsunschärfe, Farb- und Lichtreflexion und Reaktion auf Touch-Interaktionen. Deckt Integration mit SwiftUI, UIKit und WidgetKit ab.","pt":"Sistema de design Liquid Glass para iOS 26+, implementando um material de vidro dinâmico com blur de conteúdo, reflexão de cores e morphing interativo. Cobre integração com SwiftUI, UIKit e WidgetKit.","ru":"Система дизайна Liquid Glass для iOS 26+, реализующая динамический стеклянный материал с размытием контента, отражением цвета и интерактивным морфингом. Охватывает интеграцию с SwiftUI, UIKit и WidgetKit.","ar":"نظام تصميم Liquid Glass لنظام iOS 26+، ينفذ مادة زجاجية ديناميكية مع طمس المحتوى، انعكاس اللون، والتحويل التفاعلي. يغطي التكامل مع SwiftUI وUIKit وWidgetKit."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"liquid-glass-design","description":"iOS 26 Liquid Glass design system — dynamic glass material with blur, reflection, and interactive morphing for SwiftUI, UIKit, and WidgetKit.","bodyPreview":"# Liquid Glass Design System (iOS 26)\n\nPatterns for implementing Apple''s Liquid Glass — a dynamic material that blurs content behind it, reflects color and light from surrounding content, and reacts to touch and pointer interactions. Covers SwiftUI, UIKit, and WidgetKit integration.\n\n## When to Activate\n\n- Building or updating apps for iOS 26+ with the new design language\n- Implementing glass-style buttons, cards, toolbars, or containers\n- Creating morphing transitions between glass elements\n- A","body":"# Liquid Glass Design System (iOS 26)\n\nPatterns for implementing Apple''s Liquid Glass — a dynamic material that blurs content behind it, reflects color and light from surrounding content, and reacts to touch and pointer interactions. Covers SwiftUI, UIKit, and WidgetKit integration.\n\n## When to Activate\n\n- Building or updating apps for iOS 26+ with the new design language\n- Implementing glass-style buttons, cards, toolbars, or containers\n- Creating morphing transitions between glass elements\n- Applying Liquid Glass effects to widgets\n- Migrating existing blur/material effects to the new Liquid Glass API\n\n## Core Pattern — SwiftUI\n\n### Basic Glass Effect\n\nThe simplest way to add Liquid Glass to any view:\n\n```swift\nText(\"Hello, World!\")\n    .font(.title)\n    .padding()\n    .glassEffect()  // Default: regular variant, capsule shape\n```\n\n### Customizing Shape and Tint\n\n```swift\nText(\"Hello, World!\")\n    .font(.title)\n    .padding()\n    .glassEffect(.regular.tint(.orange).interactive(), in: .rect(cornerRadius: 16.0))\n```\n\nKey customization options:\n- `.regular` — standard glass effect\n- `.tint(Color)` — add color tint for prominence\n- `.interactive()` — react to touch and pointer interactions\n- Shape: `.capsule` (default), `.rect(cornerRadius:)`, `.circle`\n\n### Glass Button Styles\n\n```swift\nButton(\"Click Me\") { /* action */ }\n    .buttonStyle(.glass)\n\nButton(\"Important\") { /* action */ }\n    .buttonStyle(.glassProminent)\n```\n\n### GlassEffectContainer for Multiple Elements\n\nAlways wrap multiple glass views in a container for performance and morphing:\n\n```swift\nGlassEffectContainer(spacing: 40.0) {\n    HStack(spacing: 40.0) {\n        Image(systemName: \"scribble.variable\")\n            .frame(width: 80.0, height: 80.0)\n            .font(.system(size: 36))\n            .glassEffect()\n\n        Image(systemName: \"eraser.fill\")\n            .frame(width: 80.0, height: 80.0)\n            .font(.system(size: 36))\n            .glassEffect()\n    }\n}\n```\n\nThe `spacing` parameter controls merge distance — closer elements blend their glass shapes together.\n\n### Uniting Glass Effects\n\nCombine multiple views into a single glass shape with `glassEffectUnion`:\n\n```swift\n@Namespace private var namespace\n\nGlassEffectContainer(spacing: 20.0) {\n    HStack(spacing: 20.0) {\n        ForEach(symbolSet.indices, id: \\.self) { item in\n            Image(systemName: symbolSet[item])\n                .frame(width: 80.0, height: 80.0)\n                .glassEffect()\n                .glassEffectUnion(id: item < 2 ? \"group1\" : \"group2\", namespace: namespace)\n        }\n    }\n}\n```\n\n### Morphing Transitions\n\nCreate smooth morphing when glass elements appear/disappear:\n\n```swift\n@State private var isExpanded = false\n@Namespace private var namespace\n\nGlassEffectContainer(spacing: 40.0) {\n    HStack(spacing: 40.0) {\n        Image(systemName: \"scribble.variable\")\n            .frame(width: 80.0, height: 80.0)\n            .glassEffect()\n            .glassEffectID(\"pencil\", in: namespace)\n\n        if isExpanded {\n            Image(systemName: \"eraser.fill\")\n                .frame(width: 80.0, height: 80.0)\n                .glassEffect()\n                .glassEffectID(\"eraser\", in: namespace)\n        }\n    }\n}\n\nButton(\"Toggle\") {\n    withAnimation { isExpanded.toggle() }\n}\n.buttonStyle(.glass)\n```\n\n### Extending Horizontal Scrolling Under Sidebar\n\nTo allow horizontal scroll content to extend under a sidebar or inspector, ensure the `ScrollView` content reaches the leading/trailing edges of the container. The system automatically handles the under-sidebar scrolling behavior when the layout extends to the edges — no additional modifier is needed.\n\n## Core Pattern — UIKit\n\n### Basic UIGlassEffect\n\n```swift\nlet glassEffect = UIGlassEffect()\nglassEffect.tintColor = UIColor.systemBlue.withAlphaComponent(0.3)\nglassEffect.isInteractive = true\n\nlet visualEffectView = UIVisualEffectView(effect: glassEffect)\nvisualEffectView.translatesAutoresizingMaskIntoConstraints = false\nvisualEffectView.layer.cornerRadius = 20\nvisualEffectView.clipsToBounds = true\n\nview.addSubview(visualEffectView)\nNSLayoutConstraint.activate([\n    visualEffectView.centerXAnchor.constraint(equalTo: view.centerXAnchor),\n    visualEffectView.centerYAnchor.constraint(equalTo: view.centerYAnchor),\n    visualEffectView.widthAnchor.constraint(equalToConstant: 200),\n    visualEffectView.heightAnchor.constraint(equalToConstant: 120)\n])\n\n// Add content to contentView\nlet label = UILabel()\nlabel.text = \"Liquid Glass\"\nlabel.translatesAutoresizingMaskIntoConstraints = false\nvisualEffectView.contentView.addSubview(label)\nNSLayoutConstraint.activate([\n    label.centerXAnchor.constraint(equalTo: visualEffectView.contentView.centerXAnchor),\n    label.centerYAnchor.constraint(equalTo: visualEffectView.contentView.centerYAnchor)\n])\n```\n\n### UIGlassContainerEffect for Multiple Elements\n\n```swift\nlet containerEffect = UIGlassContainerEffect()\ncontainerEffect.spacing = 40.0\n\nlet containerView = UIVisualEffectView(effect: containerEffect)\n\nlet firstGlass = UIVisualEffectView(effect: UIGlassEffect())\nlet secondGlass = UIVisualEffectView(effect: UIGlassEffect())\n\ncontainerView.contentView.addSubview(firstGlass)\ncontainerView.contentView.addSubview(secondGlass)\n```\n\n### Scroll Edge Effects\n\n```swift\nscrollView.topEdgeEffect.style = .automatic\nscrollView.bottomEdgeEffect.style = .hard\nscrollView.leftEdgeEffect.isHidden = true\n```\n\n### Toolbar Glass Integration\n\n```swift\nlet favoriteButton = UIBarButtonItem(image: UIImage(systemName: \"heart\"), style: .plain, target: self, action: #selector(favoriteAction))\nfavoriteButton.hidesSharedBackground = true  // Opt out of shared glass background\n```\n\n## Core Pattern — WidgetKit\n\n### Rendering Mode Detection\n\n```swift\nstruct MyWidgetView: View {\n    @Environment(\\.widgetRenderingMode) var renderingMode\n\n    var body: some View {\n        if renderingMode == .accented {\n            // Tinted mode: white-tinted, themed glass background\n        } else {\n            // Full color mode: standard appearance\n        }\n    }\n}\n```\n\n### Accent Groups for Visual Hierarchy\n\n```swift\nHStack {\n    VStack(alignment: .leading) {\n        Text(\"Title\")\n            .widgetAccentable()  // Accent group\n        Text(\"Subtitle\")\n            // Primary group (default)\n    }\n    Image(systemName: \"star.fill\")\n        .widgetAccentable()  // Accent group\n}\n```\n\n### Image Rendering in Accented Mode\n\n```swift\nImage(\"myImage\")\n    .widgetAccentedRenderingMode(.monochrome)\n```\n\n### Container Background\n\n```swift\nVStack { /* content */ }\n    .containerBackground(for: .widget) {\n        Color.blue.opacity(0.2)\n    }\n```\n\n## Key Design Decisions\n\n| Decision | Rationale |\n|----------|-----------|\n| GlassEffectContainer wrapping | Performance optimization, enables morphing between glass elements |\n| `spacing` parameter | Controls merge distance — fine-tune how close elements must be to blend |\n| `@Namespace` + `glassEffectID` | Enables smooth morphing transitions on view hierarchy changes |\n| `interactive()` modifier | Explicit opt-in for touch/pointer reactions — not all glass should respond |\n| UIGlassContainerEffect in UIKit | Same container pattern as SwiftUI for consistency |\n| Accented rendering mode in widgets | System applies tinted glass when user selects tinted Home Screen |\n\n## Best Practices\n\n- **Always use GlassEffectContainer** when applying glass to multiple sibling views — it enables morphing and improves rendering performance\n- **Apply `.glassEffect()` after** other appearance modifiers (frame, font, padding)\n- **Use `.interactive()`** only on elements that respond to user interaction (buttons, toggleable items)\n- **Choose spacing carefully** in containers to control when glass effects merge\n- **Use `withAnimation`** when changing view hierarchies to enable smooth morphing transitions\n- **Test across appearances** — light mode, dark mode, and accented/tinted modes\n- **Ensure accessibility contrast** — text on glass must remain readable\n\n## Anti-Patterns to Avoid\n\n- Using multiple standalone `.glassEffect()` views without a GlassEffectContainer\n- Nesting too many glass effects — degrades performance and visual clarity\n- Applying glass to every view — reserve for interactive elements, toolbars, and cards\n- Forgetting `clipsToBounds = true` in UIKit when using corner radii\n- Ignoring accented rendering mode in widgets — breaks tinted Home Screen appearance\n- Using opaque backgrounds behind glass — defeats the translucency effect\n\n## When to Use\n\n- Navigation bars, toolbars, and tab bars with the new iOS 26 design\n- Floating action buttons and card-style containers\n- Interactive controls that need visual depth and touch feedback\n- Widgets that should integrate with the system''s Liquid Glass appearance\n- Morphing transitions between related UI states\n"},"category":"official","lastSynced":"2026-03-06T04:20:45.609Z","seo":{"title":{"en":"Liquid Glass Design: iOS 26 Implementation Guide | AI Age...","zh":"Liquid Glass 设计系统集成指南 - SwiftUI、UIKit 和 WidgetKit","ja":"Liquid Glass デザインシステムの実装ガイド - SwiftUI、UIKit、WidgetKit","ko":"Liquid Glass 디자인 시스템 설정 가이드 - SwiftUI, UIKit, WidgetKit","es":"Liquid Glass Design System para iOS 26: Guía de Implement...","fr":"Système de Design Liquid Glass pour iOS 26 : Guide d''Impl...","de":"Liquid Glass Design System für iOS 26: Implementierungsle...","pt":"Liquid Glass Design System: Implementação iOS 26 com SwiftUI","ru":"Liquid Glass Design System: Руководство по реализации для...","ar":"Liquid Glass Design System: دليل الإعداد لنظام iOS 26"},"description":{"en":"Master Apple''s iOS 26 Liquid Glass design system with this AI agent skill. Get patterns for dynamic blur, reflections, and morphing interactions in SwiftUI, ...","zh":"了解如何在 iOS 26 中实现 Liquid Glass 设计系统，包括动态玻璃材质、模糊、反射和交互式变形","ja":"iOS 26 における Liquid Glass デザインシステムの実装方法を学びます。動的なガラス素材、ぼかし、反射、インタラクティブな変形など","ko":"iOS 26에서 Liquid Glass 디자인 시스템을 구현하는 방법에 대해 알아보세요. 동적 유리 재료, 블러, 반사 및 상호 작용 변형과 같은 기능","es":"Implementa el material de vidrio dinámico de iOS 26 con desenfoque, reflexión y morphing interactivo. Guía completa para SwiftUI, UIKit y WidgetKit usando he...","fr":"Implémentez le matériau verre dynamique d''iOS 26 avec flou, réflexion et morphing interactif. Guide complet pour SwiftUI, UIKit et WidgetKit utilisant des ou...","de":"Implementieren Sie das dynamische Glas-Material von iOS 26 mit Unschärfe, Reflexion und interaktivem Morphing. Umfassende Anleitung für SwiftUI, UIKit und Wi...","pt":"Implemente o material dinâmico Liquid Glass do iOS 26 com SwiftUI e UIKit. Aprenda a criar efeitos de blur, reflexão e morphing interativo para botões, cards...","ru":"Реализуйте динамический материал Liquid Glass для iOS 26 на SwiftUI и UIKit. Создавайте эффекты размытия, отражения и интерактивного морфинга для кнопок, кар...","ar":"قم بتنفيذ مادة Liquid Glass الديناميكية لنظام iOS 26 باستخدام SwiftUI وUIKit. تعلم إنشاء تأثيرات الطمس، الانعكاس، والتحويل التفاعلي للأزرار، البطاقات، وأشرطة..."},"definition":{"en":"liquid-glass-design is an AI agent skill providing implementation patterns for Apple''s iOS 26 Liquid Glass design system. It covers creating dynamic glass materials with content blur, environmental reflection, and touch-responsive morphing across SwiftUI, UIKit, and WidgetKit frameworks.","zh":"Liquid Glass 设计系统是一种 iOS 26 的动态玻璃材质设计语言","ja":"Liquid Glass デザインシステムは、iOS 26 用の動的なガラス素材設計言語です","ko":"Liquid Glass 디자인 시스템은 iOS 26용 동적 유리 재료 디자인 언어입니다","es":"Liquid Glass Design System es un conjunto de patrones para implementar el material de vidrio dinámico de iOS 26. Incluye efectos de desenfoque, reflexión de color y luz del contenido circundante, y capacidad de morphing interactivo para botones, tarjetas y barras de herramientas en SwiftUI, UIKit y WidgetKit.","fr":"Liquid Glass Design System est un ensemble de modèles pour implémenter le matériau verre dynamique d''iOS 26. Il inclut des effets de flou, réflexion de couleur et lumière du contenu environnant, et capacité de morphing interactif pour boutons, cartes et barres d''outils dans SwiftUI, UIKit et WidgetKit.","de":"Liquid Glass Design System ist eine Sammlung von Mustern zur Implementierung des dynamischen Glas-Materials von iOS 26. Es beinhaltet Unschärfe-Effekte, Reflexion von Farbe und Licht umgebender Inhalte und interaktive Morphing-Fähigkeiten für Buttons, Karten und Toolbars in SwiftUI, UIKit und WidgetKit.","pt":"Liquid Glass Design System é um conjunto de padrões para implementar o material dinâmico de vidro do iOS 26. Ele proporciona efeitos de desfoque de conteúdo, reflexão de luz e cor do conteúdo circundante, e reage a interações de toque e ponteiro no SwiftUI e UIKit.","ru":"Liquid Glass Design System — это набор шаблонов для реализации динамического стеклянного материала iOS 26. Он обеспечивает эффекты размытия контента, отражения света и цвета от окружающего контента и реагирует на сенсорные взаимодействия и взаимодействия с указателем в SwiftUI и UIKit.","ar":"Liquid Glass Design System هو مجموعة أنماط لتنفيذ المادة الزجاجية الديناميكية لنظام iOS 26. يوفر تأثيرات طمس المحتوى، انعكاس الضوء واللون من المحتوى المحيط، ويتفاعل مع اللمس وحركات المؤشر في SwiftUI وUIKit."},"features":{"en":["Implements dynamic glass material with content blur for iOS 26","Creates color and light reflections from surrounding UI elements","Adds touch and pointer interaction responses for glass components","Provides patterns for SwiftUI, UIKit, and WidgetKit integration","Supports creation of glass-style buttons, cards, and toolbars","Enables morphing transitions between glass material elements"],"zh":["动态玻璃材质","模糊和反射效果","交互式变形","SwiftUI、UIKit 和 WidgetKit 集成"],"ja":["動的なガラス素材","ぼかしと反射の効果","インタラクティブな変形","SwiftUI、UIKit、WidgetKit との統合"],"ko":["동적 유리 재료","블러 및 반사 효과","상호 작용 변형","SwiftUI, UIKit, WidgetKit 통합"],"es":["Material de vidrio dinámico con desenfoque de contenido para iOS 26","Reflexión automática de color y luz desde el contenido circundante","Morphing interactivo que reacciona a toques e interacciones de puntero","Implementación nativa para SwiftUI con componentes preconstruidos","Soporte completo para UIKit con transiciones personalizables","Integración con WidgetKit para widgets de estilo glass"],"fr":["Matériau verre dynamique avec flou de contenu pour iOS 26","Réflexion automatique de couleur et lumière depuis le contenu environnant","Morphing interactif réagissant aux touches et interactions de pointeur","Implémentation native pour SwiftUI avec composants préconstruits","Support complet pour UIKit avec transitions personnalisables","Intégration avec WidgetKit pour widgets de style verre"],"de":["Dynamisches Glas-Material mit Inhaltsunschärfe für iOS 26","Automatische Reflexion von Farbe und Licht aus umgebenden Inhalten","Interaktives Morphing, das auf Touch- und Pointer-Interaktionen reagiert","Native Implementierung für SwiftUI mit vorgefertigten Komponenten","Vollständige Unterstützung für UIKit mit anpassbaren Übergängen","Integration mit WidgetKit für Glass-style Widgets"],"pt":["Implementação do material dinâmico Liquid Glass para iOS 26+","Efeitos de blur de conteúdo de fundo com SwiftUI e UIKit","Sistema de reflexão de cores e luz do conteúdo circundante","Reação a interações de toque e ponteiro para morphing interativo","Padrões para botões, cards, toolbars e containers em estilo glass","Integração completa com WidgetKit para extensões de aplicativo"],"ru":["Реализация динамического материала Liquid Glass для iOS 26+","Эффекты размытия фонового контента с SwiftUI и UIKit","Система отражения цвета и света от окружающего контента","Реакция на сенсорные взаимодействия и взаимодействия с указателем для интерактивного морфинга","Шаблоны для стеклянных кнопок, карточек, панелей инструментов и контейнеров","Полная интеграция с WidgetKit для расширений приложений"],"ar":["تنفيذ مادة Liquid Glass الديناميكية لنظام iOS 26+","تأثيرات طمس المحتوى الخلفي باستخدام SwiftUI وUIKit","نظام انعكاس اللون والضوء من المحتوى المحيط","تفاعل مع اللمس وحركات المؤشر للتحويل التفاعلي (morphing)","أنماط لأزرار، بطاقات، أشرطة أدوات، وحاويات على الطراز الزجاجي","تكامل كامل مع WidgetKit لتوسعات التطبيقات"]},"keywords":{"en":["iOS 26 Liquid Glass implementation","SwiftUI glass material tutorial","UIKit dynamic blur setup","WidgetKit glass design patterns","how to use liquid-glass-design skill","liquid-glass-design vs other iOS design systems","install liquid-glass-design MCP client","liquid-glass-design setup guide for developers","iOS 26 morphing transitions code","Apple Liquid Glass development patterns"],"zh":["Liquid Glass 设计系统","iOS 26 设计语言","动态玻璃材质","SwiftUI","UIKit","WidgetKit","AI 设计工具","AI エージェント"],"ja":["Liquid Glass デザインシステム","iOS 26 デザイン言語","動的なガラス素材","SwiftUI","UIKit","WidgetKit","AI デザインツール","AI エージェント"],"ko":["Liquid Glass 디자인 시스템","iOS 26 디자인 언어","동적 유리 재료","SwiftUI","UIKit","WidgetKit","AI 디자인 도구","인공지능 에이전트"],"es":["iOS 26 Liquid Glass implementation","SwiftUI glass material tutorial","UIKit dynamic glass effects","WidgetKit glass widgets","iOS glass morphing transitions","herramientas de IA para desarrollo iOS","claude-code SwiftUI patterns","MCP iOS development"],"fr":["iOS 26 Liquid Glass implémentation","SwiftUI matériau verre tutoriel","UIKit effets verre dynamiques","WidgetKit widgets verre","iOS transitions morphing verre","outils d''IA pour développement iOS","claude-code modèles SwiftUI","MCP développement iOS"],"de":["iOS 26 Liquid Glass Implementierung","SwiftUI Glas-Material Tutorial","UIKit dynamische Glaseffekte","WidgetKit Glass Widgets","iOS Glass Morphing Übergänge","KI-Tools für iOS Entwicklung","claude-code SwiftUI Muster","MCP iOS Entwicklung"],"pt":["liquid glass design system ios 26","swiftui glass material implementation","uilkit dynamic glass blur effect","ios 26 morphing transitions tutorial","widgetkit glass integration guide","ai agents desenvolvimento ios","interactive glass buttons swiftui","reflection effect ios development"],"ru":["liquid glass design system ios 26","swiftui стеклянный материал реализация","uilkit динамическое стекло эффект размытия","ios 26 морфинг переходы руководство","widgetkit стекло интеграция руководство","ии агенты разработка ios","интерактивные стеклянные кнопки swiftui","эффект отражения ios разработка"],"ar":["liquid glass design system ios 26","swiftui مادة زجاجية تنفيذ","uilkit زجاج ديناميكي تأثير طمس","ios 26 تحولات morphing دليل","widgetkit تكامل زجاج دليل","أدوات الذكاء الاصطناعي تطوير ios","أزرار زجاجية تفاعلية swiftui","تأثير انعكاس تطوير ios"]}},"agentAnalysis":{"suitability":{"en":"Essential for iOS UI/UX Agents crafting immersive glass-morphism interfaces for iOS 26+ applications.","zh":"对于为 iOS 26+ 应用程序打造沉浸式玻璃拟态界面的 iOS UI/UX Agent 而言，这是必不可少的技能。","ja":"iOS 26+ アプリケーションの没入型ガラスモーフィズムインターフェースを構築する iOS UI/UX Agent にとって必須です。","ko":"iOS 26+ 애플리케이션을 위한 몰입형 글래스 모피즘 인터페이스를 제작하는 iOS UI/UX Agent에게 필수적입니다.","es":"Esencial para agentes de UI/UX de iOS que crean interfaces inmersivas de glass-morphism para aplicaciones iOS 26+.","fr":"Essentiel pour les agents UI/UX iOS créant des interfaces immersives de glass-morphism pour les applications iOS 26+.","de":"Essenziell für iOS UI/UX Agents, die immersive Glass-Morphism-Interfaces für iOS 26+-Anwendungen entwickeln.","pt":"Essencial para Agentes de UI/UX do iOS que criam interfaces de glass-morphism imersivas para aplicações do iOS 26+.","ru":"Необходим для агентов iOS UI/UX, создающих погружающие интерфейсы glass-morphism для приложений iOS 26+.","ar":"ضروري للوكلاء UI/UX من iOS الذين يصممون واجهات glass-morphism غامرة لتطبيقات iOS 26+."},"recommendation":{"en":"Enables the implementation of Apple''s Liquid Glass material with dynamic blur, real-time color reflection, and interactive morphing reactions to touch and pointer events. Provides direct integration patterns for SwiftUI, UIKit, and WidgetKit to create authentic glass-style UI components.","zh":"支持实现 Apple 的 Liquid Glass 材质，具备动态模糊、实时颜色反射以及对触摸和指针事件的交互式变形反应。为 SwiftUI、UIKit 和 WidgetKit 提供直接集成模式，以创建地道的玻璃风格 UI 组件。","ja":"ダイナミックブラー、リアルタイムカラーリフレクション、タッチおよびポインターイベントへのインタラクティブなモーフィング反応を備えた Apple の Liquid Glass マテリアルの実装を可能にします。SwiftUI、UIKit、WidgetKit との直接的な統合パターンを提供し、本物のガラススタイルの UI コンポーネントを作成します。","ko":"동적 블러, 실시간 색상 반사, 터치 및 포인터 이벤트에 대한 인터랙티브한 모핑 반응을 갖춘 Apple의 Liquid Glass 재질 구현을 가능하게 합니다. SwiftUI, UIKit 및 WidgetKit을 위한 직접 통합 패턴을 제공하여 정통적인 글래스 스타일 UI 컴포넌트를 생성합니다.","es":"Permite la implementación del material Liquid Glass de Apple con desenfoque dinámico, reflexión de color en tiempo real y reacciones de morphing interactivas a eventos táctiles y de puntero. Proporciona patrones de integración directa para SwiftUI, UIKit y WidgetKit para crear componentes de UI con estilo de vidrio auténtico.","fr":"Permet la mise en œuvre du matériau Liquid Glass d''Apple avec flou dynamique, réflexion de couleur en temps réel et réactions de morphing interactives aux événements tactiles et de pointeur. Fournit des modèles d''intégration directe pour SwiftUI, UIKit et WidgetKit afin de créer des composants UI de style verre authentiques.","de":"Ermöglicht die Implementierung von Apples Liquid Glass-Material mit dynamischem Unschärfeeffekt, Echtzeit-Farbreflexion und interaktiven Morphing-Reaktionen auf Touch- und Pointer-Ereignisse. Bietet direkte Integrationsmuster für SwiftUI, UIKit und WidgetKit zur Erstellung authentischer UI-Komponenten im Glasstil.","pt":"Permite a implementação do material Liquid Glass da Apple com blur dinâmico, reflexo de cor em tempo real e reações de morphing interativas a eventos de toque e ponteiro. Fornece padrões de integração direta para SwiftUI, UIKit e WidgetKit para criar componentes de UI de estilo de vidro autênticos.","ru":"Позволяет реализовать материал Liquid Glass от Apple с динамическим размытием, рефлексией цвета в реальном времени и интерактивными морфинг-реакциями на события касания и указателя. Предоставляет прямые шаблоны интеграции для SwiftUI, UIKit и WidgetKit для создания аутентичных компонентов интерфейса пользователя в стиле стекла.","ar":"يمكّن تنفيذ مادة Liquid Glass من Apple مع ضباب ديناميكي و انعكاس لوني في الوقت الفعلي و تفاعلات تشكيلية تفاعلية على أحداث اللمس و النقطة. يوفر أنماط 集成 مباشرة لـ SwiftUI و UIKit و WidgetKit لإنشاء مكونات واجهة مستخدم أصلية بأسلوب زجاجي."},"useCases":{"en":["Implementing dynamic glass material overlays on background content","Creating interactive glass buttons and cards that morph on user touch","Designing system-wide toolbars and containers with light reflection effects","Building WidgetKit extensions that adhere to the iOS 26 design language"],"zh":["在背景内容上实现动态玻璃材质覆盖层","创建在用户触摸时变形的交互式玻璃按钮和卡片","设计具有光线反射效果的系统范围工具栏和容器","构建遵循 iOS 26 设计语言的 WidgetKit 扩展"],"ja":["背景コンテンツ上に動的なガラスマテリアルオーバーレイを実装する","ユーザーのタッチ時に変形するインタラクティブなガラスボタンとカードを作成する","光反射効果を備えたシステム全体のツールバーとコンテナを設計する","iOS 26 デザイン言語に準拠した WidgetKit 拡張を構築する"],"ko":["배경 콘텐츠 위에 동적인 글래스 재질 오버레이 구현","사용자 터치 시 형태가 변하는 인터랙티브 글래스 버튼 및 카드 생성","광선 반사 효과를 갖춘 시스템 전체 툴바 및 컨테이너 설계","iOS 26 디자인 언어를 준수하는 WidgetKit 확장 프로그램 구축"],"es":["Implementación de superposiciones de material de vidrio dinámico sobre contenido de fondo","Creación de botones y tarjetas de vidrio interactivos que se transforman con el tacto del usuario","Diseño de barras de herramientas y contenedores para todo el sistema con efectos de reflexión de luz","Creación de extensiones de WidgetKit que se adhieren al lenguaje de diseño de iOS 26"],"fr":["Mise en œuvre de superpositions de matériau verre dynamique sur un contenu d''arrière-plan","Création de boutons et cartes en verre interactifs qui se déforment au toucher de l''utilisateur","Conception de barres d''outils et de conteneurs à l''échelle du système avec des effets de réflexion de la lumière","Développement d''extensions WidgetKit respectant le langage de conception iOS 26"],"de":["Implementierung dynamischer Glass-Material-Overlays auf Hintergrundinhalten","Erstellung interaktiver Glass-Buttons und -Karten, die sich bei Berührung durch den Benutzer verformen","Entwicklung systemweiter Toolbars und Container mit Lichtreflexionseffekten","Erstellung von WidgetKit-Erweiterungen, die der iOS 26-Designsprache entsprechen"],"pt":["Implementar sobreposições de material de vidro dinâmico em conteúdo de fundo","Criar botões e cartões de vidro interativos que se transformam ao toque do usuário","Projetar barras de ferramentas e contêineres de sistema com efeitos de reflexão de luz","Construir extensões do WidgetKit que aderem à linguagem de design do iOS 26"],"ru":["Реализовать динамические наложения стекольного материала на фоновый контент","Создать интерактивные стеклянные кнопки и карточки, которые меняют форму при касании пользователя","Разработать системные панели инструментов и контейнеры с эффектами отражения света","Построить расширения WidgetKit, соответствующие языку дизайна iOS 26"],"ar":["تنفيذ طبقات مادة زجاجية ديناميكية على محتوى الخلفية","إنشاء أزرار وبطاقات زجاجية تفاعلية تتغير عند لمس المستخدم","تصميم شريط أدوات وحاويات النظام مع تأثيرات انعكاس الضوء","بناء ملحقات WidgetKit التي تتبع لغة التصميم لمنصة iOS 26"]},"limitations":{"en":["iOS 26+ compatibility only","Requires SwiftUI or UIKit development environment","Limited to Apple ecosystem implementations"],"zh":["仅兼容 iOS 26+","需要 SwiftUI 或 UIKit 开发环境","仅限于 Apple 生态系统内的实现"],"ja":["iOS 26+ との互換性のみ","SwiftUI または UIKit 開発環境が必要","Apple エコシステム内の実装に限定される"],"ko":["iOS 26+ 이상만 호환","SwiftUI 또는 UIKit 개발 환경 필요","Apple 생태계 내 구현으로 제한됨"],"es":["Solo compatible con iOS 26+","Requiere un entorno de desarrollo SwiftUI o UIKit","Limitado a implementaciones del ecosistema Apple"],"fr":["Compatibilité iOS 26+ uniquement","Nécessite un environnement de développement SwiftUI ou UIKit","Limité aux implémentations de l''écosystème Apple"],"de":["Nur iOS 26+-Kompatibilität","Erfordert eine SwiftUI- oder UIKit-Entwicklungsumgebung","Beschränkt auf Implementierungen im Apple-Ökosystem"],"pt":["Compatibilidade apenas com iOS 26+","Exige ambiente de desenvolvimento SwiftUI ou UIKit","Limitado a implementações do ecossistema da Apple"],"ru":["Совместимость только с iOS 26+","Требует среды разработки SwiftUI или UIKit","Ограничен реализациями экосистемы Apple"],"ar":["التوافق مع منصة iOS 26+ فقط","يتطلب بيئة تطوير SwiftUI أو UIKit","محدود بالتنفيذات النمطية لنظام تشغيل Apple"]},"version":4},"contentHash":"024aa207eb3d4d31d868954a7352a40b78c61f2fd007ab8b452afb6217070f84","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":89}');
