INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/regex-vs-llm-structured-text', 'regex-vs-llm-structured-text', 'affaan-m', 'everything-claude-code', 'official', 'regex-vs-llm-structured-text affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The regex-vs-llm-structured-text skill provides a decision framework for choosing between regex and LLM when parsing structured text, benefiting developers working with quizzes, forms, and documents. Regex-vs-llm-structured-text 是一个解析结构化文本的决策框架，使用正则表达式处理 95-98% 的情况，仅在低置信度边缘情况下使用 LLM。 Regex-vs-llm-structured-text は、構造化テキストを解析するための決定フレームワークで、正規表現を使用して 95-98% のケースを効率的に処理し、低信頼性のエッジケースのみで LLM を使用します。 Regex-vs-llm-structured-text는 구조화된 텍스트를 분석하기 위한 결정 프레임워크로, 정규식을 사용하여 95-98%의 경우를 효율적으로 처리하고, 저신뢰도 에지 ケース에만 LLM을 사용합니다. El marco de decisión para elegir entre regex y LLM cuando se parsea texto estructurado, comenzando con regex y agregando LLM solo para casos de borde de baja confianza Le cadre de décision pour choisir entre regex et LLM lors du parsing de texte structuré, en commençant par regex et en ajoutant LLM uniquement pour les cas de bordure de faible confiance Das Entscheidungsframework für die Wahl zwischen regex und LLM bei der Verarbeitung von strukturiertem Text, beginnend mit regex und LLM nur für Fälle mit geringer Konfidenz Esse skill fornece um framework de decisão prático para parsing de texto estruturado, recomendando começar com regex e adicionar LLM apenas para casos de borda de baixa confiança. Этот скилл предоставляет практический каркас для принятия решений по парсингу структурированного текста, рекомендуя начинать с regex и добавлять LLM только для случаев края с низкой уверенностью и использовать ИИ Агенты يوفر هذا المهارة إطار عمل قرارات عملي لتحليل النصوص المهيكلة، ويوصي بالبدء باستخدام regex وإضافة LLM فقط لحالات الحواف ذات الثقة المنخفضة واستخدام وكلاء الذكاء الاصطناعي how to use regex-vs-llm-structured-text regex-vs-llm-structured-text setup guide regex-vs-llm-structured-text alternative regex-vs-llm-structured-text vs competitors structured text parsing with regex and LLM optimizing text extraction with regex and LLM AIエージェント 结构化文本解析 正则表达式 LLM 解析效率 准确性 混合管道 优化 开发工具 AI开发 Handles 95-98% of structured text parsing cases using regex Reserves LLM calls for low-confidence edge cases Supports parsing structured text with repeating patterns Enables building hybrid pipelines combining regex and LLM approaches Optimizes text extraction for quizzes, forms, invoices, and documents regex-vs-llm-structured-text is a practical decision framework for parsing structured text using regex and LLM, handling 95-98% of cases cheaply and deterministically.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/tdd-workflow', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'tdd-workflow', 61988, 7678, 89, '2026-03-06T03:39:20Z', '2026-03-06T04:44:13.072Z', '0c0d287804b33a98bbba2df8169da80403b29fcae4a45aca96522e6c8d022d17', '{"id":"affaan-m/everything-claude-code/tdd-workflow","name":"tdd-workflow","description":{"en":"The tdd-workflow skill enforces Test-Driven Development principles for AI agents like Claude, mandating tests before code implementation. It ensures comprehensive test coverage exceeding 80% across unit, integration, and E2E tests, benefiting developers building features, fixing bugs, or refactor...","zh":"TDD 工作流技能确保所有代码开发遵循测试驱动开发原则，实现 80%+ 的测试覆盖率","ja":"TDD ワークフロー スキルは、すべてのコード開発がテスト駆動開発の原則に従って実施されるようにします","ko":"TDD 워크플로우 스킬은 모든 코드 개발을 테스트 주도 개발 원칙에 따라 수행할 수 있도록 합니다","es":"El flujo de trabajo de tdd garantiza que todos los proyectos de desarrollo sigan los principios de TDD con cobertura de pruebas completa","fr":"Le flux de travail tdd garantit que tous les projets de développement suivent les principes de TDD avec une couverture de tests complète","de":"Der tdd-Workflow stellt sicher, dass alle Entwicklungsprojekte den TDD-Prinzipien mit umfassender Testabdeckung folgen","pt":"O fluxo de desenvolvimento dirigido por testes (TDD) é uma abordagem que assegura que todos os códigos sejam desenvolvidos com testes abrangentes. Isso inclui testes unitários, de integração e de ponta a ponta","ru":"Поток разработки на основе тестирования (TDD) - это подход, обеспечивающий разработку всех кодов с помощью комплексных тестов, включая юнит-тесты, интеграционные и конечные тесты","ar":"تدفق التطوير الموجه بالاختبار (TDD) هو نهج يضمن أن يتم تطوير جميع الشفرات مع اختبارات شاملة ، بما في ذلك الاختبارات الوحدوية واختبارات التكامل واختبارات النهاية إلى النهاية"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"tdd-workflow","description":"Use this skill when writing new features, fixing bugs, or refactoring code. Enforces test-driven development with 80%+ coverage including unit, integration, and E2E tests.","bodyPreview":"# Test-Driven Development Workflow\n\nThis skill ensures all code development follows TDD principles with comprehensive test coverage.\n\n## When to Activate\n\n- Writing new features or functionality\n- Fixing bugs or issues\n- Refactoring existing code\n- Adding API endpoints\n- Creating new components\n\n## Core Principles\n\n### 1. Tests BEFORE Code\nALWAYS write tests first, then implement code to make tests pass.\n\n### 2. Coverage Requirements\n- Minimum 80% coverage (unit + integration + E2E)\n- All edge c","body":"# Test-Driven Development Workflow\n\nThis skill ensures all code development follows TDD principles with comprehensive test coverage.\n\n## When to Activate\n\n- Writing new features or functionality\n- Fixing bugs or issues\n- Refactoring existing code\n- Adding API endpoints\n- Creating new components\n\n## Core Principles\n\n### 1. Tests BEFORE Code\nALWAYS write tests first, then implement code to make tests pass.\n\n### 2. Coverage Requirements\n- Minimum 80% coverage (unit + integration + E2E)\n- All edge cases covered\n- Error scenarios tested\n- Boundary conditions verified\n\n### 3. Test Types\n\n#### Unit Tests\n- Individual functions and utilities\n- Component logic\n- Pure functions\n- Helpers and utilities\n\n#### Integration Tests\n- API endpoints\n- Database operations\n- Service interactions\n- External API calls\n\n#### E2E Tests (Playwright)\n- Critical user flows\n- Complete workflows\n- Browser automation\n- UI interactions\n\n## TDD Workflow Steps\n\n### Step 1: Write User Journeys\n```\nAs a [role], I want to [action], so that [benefit]\n\nExample:\nAs a user, I want to search for markets semantically,\nso that I can find relevant markets even without exact keywords.\n```\n\n### Step 2: Generate Test Cases\nFor each user journey, create comprehensive test cases:\n\n```typescript\ndescribe(''Semantic Search'', () => {\n  it(''returns relevant markets for query'', async () => {\n    // Test implementation\n  })\n\n  it(''handles empty query gracefully'', async () => {\n    // Test edge case\n  })\n\n  it(''falls back to substring search when Redis unavailable'', async () => {\n    // Test fallback behavior\n  })\n\n  it(''sorts results by similarity score'', async () => {\n    // Test sorting logic\n  })\n})\n```\n\n### Step 3: Run Tests (They Should Fail)\n```bash\nnpm test\n# Tests should fail - we haven''t implemented yet\n```\n\n### Step 4: Implement Code\nWrite minimal code to make tests pass:\n\n```typescript\n// Implementation guided by tests\nexport async function searchMarkets(query: string) {\n  // Implementation here\n}\n```\n\n### Step 5: Run Tests Again\n```bash\nnpm test\n# Tests should now pass\n```\n\n### Step 6: Refactor\nImprove code quality while keeping tests green:\n- Remove duplication\n- Improve naming\n- Optimize performance\n- Enhance readability\n\n### Step 7: Verify Coverage\n```bash\nnpm run test:coverage\n# Verify 80%+ coverage achieved\n```\n\n## Testing Patterns\n\n### Unit Test Pattern (Jest/Vitest)\n```typescript\nimport { render, screen, fireEvent } from ''@testing-library/react''\nimport { Button } from ''./Button''\n\ndescribe(''Button Component'', () => {\n  it(''renders with correct text'', () => {\n    render(<Button>Click me</Button>)\n    expect(screen.getByText(''Click me'')).toBeInTheDocument()\n  })\n\n  it(''calls onClick when clicked'', () => {\n    const handleClick = jest.fn()\n    render(<Button onClick={handleClick}>Click</Button>)\n\n    fireEvent.click(screen.getByRole(''button''))\n\n    expect(handleClick).toHaveBeenCalledTimes(1)\n  })\n\n  it(''is disabled when disabled prop is true'', () => {\n    render(<Button disabled>Click</Button>)\n    expect(screen.getByRole(''button'')).toBeDisabled()\n  })\n})\n```\n\n### API Integration Test Pattern\n```typescript\nimport { NextRequest } from ''next/server''\nimport { GET } from ''./route''\n\ndescribe(''GET /api/markets'', () => {\n  it(''returns markets successfully'', async () => {\n    const request = new NextRequest(''http://localhost/api/markets'')\n    const response = await GET(request)\n    const data = await response.json()\n\n    expect(response.status).toBe(200)\n    expect(data.success).toBe(true)\n    expect(Array.isArray(data.data)).toBe(true)\n  })\n\n  it(''validates query parameters'', async () => {\n    const request = new NextRequest(''http://localhost/api/markets?limit=invalid'')\n    const response = await GET(request)\n\n    expect(response.status).toBe(400)\n  })\n\n  it(''handles database errors gracefully'', async () => {\n    // Mock database failure\n    const request = new NextRequest(''http://localhost/api/markets'')\n    // Test error handling\n  })\n})\n```\n\n### E2E Test Pattern (Playwright)\n```typescript\nimport { test, expect } from ''@playwright/test''\n\ntest(''user can search and filter markets'', async ({ page }) => {\n  // Navigate to markets page\n  await page.goto(''/'')\n  await page.click(''a[href=\"/markets\"]'')\n\n  // Verify page loaded\n  await expect(page.locator(''h1'')).toContainText(''Markets'')\n\n  // Search for markets\n  await page.fill(''input[placeholder=\"Search markets\"]'', ''election'')\n\n  // Wait for debounce and results\n  await page.waitForTimeout(600)\n\n  // Verify search results displayed\n  const results = page.locator(''[data-testid=\"market-card\"]'')\n  await expect(results).toHaveCount(5, { timeout: 5000 })\n\n  // Verify results contain search term\n  const firstResult = results.first()\n  await expect(firstResult).toContainText(''election'', { ignoreCase: true })\n\n  // Filter by status\n  await page.click(''button:has-text(\"Active\")'')\n\n  // Verify filtered results\n  await expect(results).toHaveCount(3)\n})\n\ntest(''user can create a new market'', async ({ page }) => {\n  // Login first\n  await page.goto(''/creator-dashboard'')\n\n  // Fill market creation form\n  await page.fill(''input[name=\"name\"]'', ''Test Market'')\n  await page.fill(''textarea[name=\"description\"]'', ''Test description'')\n  await page.fill(''input[name=\"endDate\"]'', ''2025-12-31'')\n\n  // Submit form\n  await page.click(''button[type=\"submit\"]'')\n\n  // Verify success message\n  await expect(page.locator(''text=Market created successfully'')).toBeVisible()\n\n  // Verify redirect to market page\n  await expect(page).toHaveURL(/\\/markets\\/test-market/)\n})\n```\n\n## Test File Organization\n\n```\nsrc/\n├── components/\n│   ├── Button/\n│   │   ├── Button.tsx\n│   │   ├── Button.test.tsx          # Unit tests\n│   │   └── Button.stories.tsx       # Storybook\n│   └── MarketCard/\n│       ├── MarketCard.tsx\n│       └── MarketCard.test.tsx\n├── app/\n│   └── api/\n│       └── markets/\n│           ├── route.ts\n│           └── route.test.ts         # Integration tests\n└── e2e/\n    ├── markets.spec.ts               # E2E tests\n    ├── trading.spec.ts\n    └── auth.spec.ts\n```\n\n## Mocking External Services\n\n### Supabase Mock\n```typescript\njest.mock(''@/lib/supabase'', () => ({\n  supabase: {\n    from: jest.fn(() => ({\n      select: jest.fn(() => ({\n        eq: jest.fn(() => Promise.resolve({\n          data: [{ id: 1, name: ''Test Market'' }],\n          error: null\n        }))\n      }))\n    }))\n  }\n}))\n```\n\n### Redis Mock\n```typescript\njest.mock(''@/lib/redis'', () => ({\n  searchMarketsByVector: jest.fn(() => Promise.resolve([\n    { slug: ''test-market'', similarity_score: 0.95 }\n  ])),\n  checkRedisHealth: jest.fn(() => Promise.resolve({ connected: true }))\n}))\n```\n\n### OpenAI Mock\n```typescript\njest.mock(''@/lib/openai'', () => ({\n  generateEmbedding: jest.fn(() => Promise.resolve(\n    new Array(1536).fill(0.1) // Mock 1536-dim embedding\n  ))\n}))\n```\n\n## Test Coverage Verification\n\n### Run Coverage Report\n```bash\nnpm run test:coverage\n```\n\n### Coverage Thresholds\n```json\n{\n  \"jest\": {\n    \"coverageThresholds\": {\n      \"global\": {\n        \"branches\": 80,\n        \"functions\": 80,\n        \"lines\": 80,\n        \"statements\": 80\n      }\n    }\n  }\n}\n```\n\n## Common Testing Mistakes to Avoid\n\n### ❌ WRONG: Testing Implementation Details\n```typescript\n// Don''t test internal state\nexpect(component.state.count).toBe(5)\n```\n\n### ✅ CORRECT: Test User-Visible Behavior\n```typescript\n// Test what users see\nexpect(screen.getByText(''Count: 5'')).toBeInTheDocument()\n```\n\n### ❌ WRONG: Brittle Selectors\n```typescript\n// Breaks easily\nawait page.click(''.css-class-xyz'')\n```\n\n### ✅ CORRECT: Semantic Selectors\n```typescript\n// Resilient to changes\nawait page.click(''button:has-text(\"Submit\")'')\nawait page.click(''[data-testid=\"submit-button\"]'')\n```\n\n### ❌ WRONG: No Test Isolation\n```typescript\n// Tests depend on each other\ntest(''creates user'', () => { /* ... */ })\ntest(''updates same user'', () => { /* depends on previous test */ })\n```\n\n### ✅ CORRECT: Independent Tests\n```typescript\n// Each test sets up its own data\ntest(''creates user'', () => {\n  const user = createTestUser()\n  // Test logic\n})\n\ntest(''updates user'', () => {\n  const user = createTestUser()\n  // Update logic\n})\n```\n\n## Continuous Testing\n\n### Watch Mode During Development\n```bash\nnpm test -- --watch\n# Tests run automatically on file changes\n```\n\n### Pre-Commit Hook\n```bash\n# Runs before every commit\nnpm test && npm run lint\n```\n\n### CI/CD Integration\n```yaml\n# GitHub Actions\n- name: Run Tests\n  run: npm test -- --coverage\n- name: Upload Coverage\n  uses: codecov/codecov-action@v3\n```\n\n## Best Practices\n\n1. **Write Tests First** - Always TDD\n2. **One Assert Per Test** - Focus on single behavior\n3. **Descriptive Test Names** - Explain what''s tested\n4. **Arrange-Act-Assert** - Clear test structure\n5. **Mock External Dependencies** - Isolate unit tests\n6. **Test Edge Cases** - Null, undefined, empty, large\n7. **Test Error Paths** - Not just happy paths\n8. **Keep Tests Fast** - Unit tests < 50ms each\n9. **Clean Up After Tests** - No side effects\n10. **Review Coverage Reports** - Identify gaps\n\n## Success Metrics\n\n- 80%+ code coverage achieved\n- All tests passing (green)\n- No skipped or disabled tests\n- Fast test execution (< 30s for unit tests)\n- E2E tests cover critical user flows\n- Tests catch bugs before production\n\n---\n\n**Remember**: Tests are not optional. They are the safety net that enables confident refactoring, rapid development, and production reliability.\n"},"category":"official","lastSynced":"2026-03-06T04:44:13.072Z","seo":{"title":{"en":"tdd-workflow: Enforce TDD with 80%+ Test Coverage | AI Ag...","zh":"TDD 工作流 Setup Guide - 80%+ 测试覆盖率","ja":"TDD ワークフロー ベストプラクティス - 80%以上のテストカバレッジ","ko":"TDD 워크플로우 설정 가이드 - 80% 이상의 테스트 커버리지","es":"Guía de configuración de tdd-workflow para desarrolladores","fr":"Guide de mise en place de tdd-workflow pour les développeurs","de":"Einrichtungsleitfaden für tdd-workflow-Entwickler","pt":"Guia de Configuração do Fluxo de Desenvolvimento Dirigido...","ru":"Настройка Потока Разработки на Основе Тестирования (TDD) ...","ar":"دليل إعداد تدفق التطوير الموجه بالاختبار (TDD) باستخدام أ..."},"description":{"en":"This AI Agent Skill enforces strict TDD workflow for Claude, ensuring tests are written BEFORE code. Achieve 80%+ coverage across unit, integration & E2E tes...","zh":"使用 TDD 工作流技能，确保代码开发遵循测试驱动开发原则，实现 80%+ 的测试覆盖率，包括单元测试、集成测试和 E2E 测试","ja":"TDD ワークフロー スキルを使用して、コード開発をテスト駆動開発の原則に従って実施し、80%以上のテストカバレッジを実現します","ko":"TDD 워크플로우 스킬을 사용하여 코드 개발을 테스트 주도 개발 원칙에 따라 수행하고 80% 이상의 테스트 커버리지를 달성합니다","es":"Aprende a implementar tdd-workflow con cobertura de pruebas del 80%+ y mejora la productividad de tus proyectos de desarrollo","fr":"Découvrez comment mettre en œuvre tdd-workflow avec une couverture de tests de 80%+ et améliorez la productivité de vos projets de développement","de":"Erfahren Sie, wie Sie tdd-workflow mit einer Testabdeckung von 80%+ implementieren und die Produktivität Ihrer Entwicklungsprojekte verbessern","pt":"Aprenda a implementar o fluxo de desenvolvimento dirigido por testes com 80% de cobertura de teste, incluindo testes unitários, de integração e de ponta a ponta","ru":"Узнайте, как реализовать поток разработки на основе тестирования с 80% покрытием тестов, включая юнит-тесты, интеграционные и конечные тесты с ИИ Агентами","ar":"تعرف على كيفية تنفيذ تدفق التطوير الموجه بالاختبار مع تغطية اختبار 80% ، بما في ذلك الاختبارات الوحدوية واختبارات التكامل واختبارات النهاية إلى النهاية باستخ..."},"definition":{"en":"tdd-workflow is an AI Agent Skill designed for Claude that enforces a strict Test-Driven Development methodology. It mandates writing tests before implementing code and ensures a minimum of 80% test coverage across unit, integration, and end-to-end (E2E) test types.","zh":"TDD 工作流是一种确保代码开发遵循测试驱动开发原则的方法，实现 80%+ 的测试覆盖率","ja":"TDD ワークフローは、コード開発をテスト駆動開発の原則に従って実施する方法で、80%以上のテストカバレッジを実現します","ko":"TDD 워크플로우는 코드 개발을 테스트 주도 개발 원칙에 따라 수행하는 방법으로 80% 이상의 테스트 커버리지를 달성합니다","es":"tdd-workflow es una habilidad que aplica principios de desarrollo dirigido por pruebas con una cobertura mínima del 80%","fr":"tdd-workflow est une compétence qui applique les principes de développement piloté par les tests avec une couverture minimale de 80%","de":"tdd-workflow ist eine Fähigkeit, die die Prinzipien der testgetriebenen Entwicklung mit einer Mindestabdeckung von 80% anwendet","pt":"O que é TDD? É uma abordagem de desenvolvimento de software que prioriza a escrita de testes antes do código","ru":"Что такое TDD? Это подход к разработке программного обеспечения, который отдает приоритет написанию тестов до кода","ar":"ما هو TDD؟ إنه نهج لبرمجة البرمجيات يؤكد على كتابة الاختبارات قبل الشفرة"},"features":{"en":["Enforces writing tests BEFORE code implementation as a core TDD principle","Mandates a minimum of 80% test coverage for all code changes","Generates and manages unit, integration, and end-to-end (E2E) tests","Activates during new feature development, bug fixing, and code refactoring workflows","Provides structured workflow for adding new API endpoints and components"],"zh":["实现 80%+ 的测试覆盖率","包括单元测试、集成测试和 E2E 测试","遵循测试驱动开发原则","支持写新功能、修复 bug 和重构代码","支持添加 API 端点和创建新组件"],"ja":["80%以上のテストカバレッジを実現","ユニットテスト、統合テスト、E2E テストを含む","テスト駆動開発の原則に従う","新しい機能の作成、バグの修正、コードのリファクタリングをサポート","API エンドポイントの追加と新しいコンポーネントの作成をサポート"],"ko":["80% 이상의 테스트 커버리지를 달성","유닛 테스트, 통합 테스트, E2E 테스트를 포함","테스트 주도 개발 원칙을 따름","새 기능 작성, 버그 수정, 코드 리팩토링을 지원","API 엔드ポイント 추가와 새로운 컴포�ント 생성을 지원"],"es":["Cobertura de pruebas del 80%+ con tests unitarios, de integración y E2E","Desarrollo de nuevas características y funcionalidades con TDD","Depuración de errores y problemas con tests automatizados","Reestructuración de código existente con tests de cobertura","Creación de nuevos componentes y endpoints de API con TDD"],"fr":["Couverture de tests de 80%+ avec des tests unitaires, d''intégration et E2E","Développement de nouvelles fonctionnalités et caractéristiques avec TDD","Débogage de bogues et de problèmes avec des tests automatisés","Réorganisation de code existant avec des tests de couverture","Création de nouveaux composants et points de terminaison d''API avec TDD"],"de":["Testabdeckung von 80%+ mit Unit-Tests, Integrations- und E2E-Tests","Entwicklung neuer Funktionen und Funktionalitäten mit TDD","Fehlerbehebung und Problemlösung mit automatisierten Tests","Umstrukturierung von bestehendem Code mit Abdeckungstests","Erstellung neuer Komponenten und API-Endpunkte mit TDD"],"pt":["Garantia de 80% de cobertura de teste","Inclusão de testes unitários, de integração e de ponta a ponta","Desenvolvimento de código após a escrita de testes","Melhoria da qualidade do código","Redução de erros e bugs"],"ru":["Гарантия 80% покрытия тестов","Включение юнит-тестов, интеграционных и конечных тестов","Разработка кода после написания тестов","Улучшение качества кода","Снижение ошибок и багов"],"ar":["ضمان تغطية اختبار 80%","تضمين الاختبارات الوحدوية واختبارات التكامل واختبارات النهاية إلى النهاية","تطوير الشفرة بعد كتابة الاختبارات","تحسين جودة الشفرة","تقليل الأخطاء والعيوب"]},"keywords":{"en":["what is tdd-workflow","how to use tdd-workflow with claude","tdd-workflow vs other testing skills","tdd-workflow alternative","tdd-workflow install guide","tdd-workflow setup for MCP","tdd-workflow coverage requirements","enforce TDD with AI agent"],"zh":["TDD 工作流","测试驱动开发","80%+ 测试覆盖率","AI 工具","代码开发","单元测试","集成测试","E2E 测试"],"ja":["TDD ワークフロー","テスト駆動開発","80%以上のテストカバレッジ","AI エージェント","コード開発","ユニットテスト","統合テスト","E2E テスト"],"ko":["TDD 워크플로우","테스트 주도 개발","80% 이상의 테스트 커버리지","AI 툴","코드 개발","유닛 테스트","통합 테스트","E2E 테스트"],"es":["tdd-workflow","desarrollo dirigido por pruebas","cobertura de pruebas","tests unitarios","tests de integración","tests E2E","herramientas de desarrollo","productividad de desarrollo","Agente de IA para desarrolladores"],"fr":["tdd-workflow","développement piloté par les tests","couverture de tests","tests unitaires","tests d''intégration","tests E2E","outils de développement","productivité de développement","Agent IA pour les développeurs"],"de":["tdd-workflow","testgetriebene Entwicklung","Testabdeckung","Unit-Tests","Integrations-Tests","E2E-Tests","Entwicklungstools","Entwicklungsproduktivität","KI-Agent für Entwickler"],"pt":["tdd workflow","desenvolvimento dirigido por testes","cobertura de teste","testes unitários","testes de integração","testes de ponta a ponta","qualidade do código","redução de erros"],"ru":["tdd workflow","поток разработки на основе тестирования","покрытие тестов","юнит-тесты","интеграционные тесты","конечные тесты","качество кода","снижение ошибок"],"ar":["tdd workflow","تدفق التطوير الموجه بالاختبار","تغطية اختبار","اختبارات وحدوية","اختبارات تكامل","اختبارات نهاية إلى نهاية","جودة الشفرة","تقليل الأخطاء"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Code Optimization Agents requiring rigorous test-driven development with unit, integration, and E2E testing.","zh":"适用于需要严格测试驱动开发的代码优化代理，包括单元、集成和E2E测试。","ja":"厳密なテスト駆動開発が必要なコード最適化エージェントに適しています。ユニット、統合、E2Eテストを含みます。","ko":"严格한 테스트 주도 개발이 필요한 코드 최적화 에이전트에 적합합니다. 단위, 통합, E2E 테스트를 포함합니다.","es":"Ideal para Agentes de Optimización de Código que requieren un desarrollo riguroso basado en pruebas con testing unitario, de integración y E2E.","fr":"Idéal pour les Agents d''Optimisation de Code nécessitant un développement rigoureux piloté par les tests avec des tests unitaires, d''intégration et de bout en bout (E2E).","de":"Ideal für Code-Optimierungs-Agents, die eine rigorose testgetriebene Entwicklung mit Unit-, Integrations- und E2E-Tests erfordern.","pt":"Ideal para Agentes de Otimização de Código que requerem desenvolvimento rigoroso orientado a testes com testes unitários, de integração e E2E.","ru":"Идеально подходит для Агентов Оптимизации Кода, требующих строгой разработки через тестирование с модульным, интеграционным и сквозным (E2E) тестированием.","ar":"مثالي لوكلاء تحسين التعليمات البرمجية التي تتطلب تطويرًا صارمًا يقوده الاختبار مع اختبارات وحدة، ودمج، واختبارات من البداية إلى النهاية (E2E)."},"recommendation":{"en":"Empowers agents to enforce comprehensive test coverage of 80% or higher, ensuring code reliability and stability through test-driven development principles, including unit, integration, and end-to-end tests.","zh":"赋予代理执行全面测试覆盖率80%或更高，确保通过测试驱动开发原则的代码可靠性和稳定性，包括单元、集成和端到端测试。","ja":"エージェントに、テスト駆動開発の原則を含むユニット、統合、エンドツーエンドテストを含む、80%以上のテストカバレッジを実施することを可能にします。","ko":"에이전트가 테스트 주도 개발 원칙을 포함하여 단위, 통합, 종단 간 테스트를 포함한 80% 이상의 테스트 커버리지의 수행을 가능하게 합니다.","es":"Permite a los agentes aplicar una cobertura de pruebas integral del 80% o superior, garantizando la fiabilidad y estabilidad del código mediante los principios del desarrollo guiado por pruebas, incluyendo tests unitarios, de integración y end-to-end.","fr":"Permet aux agents d''appliquer une couverture de test complète de 80 % ou plus, garantissant la fiabilité et la stabilité du code grâce aux principes du développement piloté par les tests, incluant les tests unitaires, d''intégration et de bout en bout.","de":"Ermöglicht es Agents, eine umfassende Testabdeckung von 80 % oder höher durchzusetzen, und gewährleistet so Code-Zuverlässigkeit und Stabilität durch testgetriebene Entwicklungsprinzipien, einschließlich Unit-, Integrations- und End-to-End-Tests.","pt":"Capacita os agentes a impor uma cobertura de testes abrangente de 80% ou superior, garantindo confiabilidade e estabilidade do código através dos princípios do desenvolvimento orientado a testes, incluindo testes de unidade, integração e end-to-end.","ru":"Позволяет агентам обеспечивать комплексное покрытие тестами на 80% или выше, гарантируя надежность и стабильность кода через принципы разработки через тестирование, включая модульные, интеграционные и сквозные (end-to-end) тесты.","ar":"يمكن الوكلاء من فرض تغطية اختبار شاملة بنسبة 80٪ أو更高، مما يضمن موثوقية واستقرار التعليمات البرمجية من خلال مبادئ التطوير الذي يقوده الاختبار، بما في ذلك اختبارات الوحدة والدمج واختبارات من البداية إلى النهاية."},"useCases":{"en":["Implementing test-driven development for new feature development","Ensuring bug fixes with comprehensive test coverage","Refactoring existing code with confidence through thorough testing"],"zh":["为新功能开发实施测试驱动开发","通过全面测试覆盖确保bug修复","通过彻底测试以信心重构现有代码"],"ja":["新機能開発のためのテスト駆動開発の実施","包括的なテストカバレッジによるバグ修正の確保","徹底的なテストによる既存コードのリファクタリング"],"ko":["새 기능 개발을 위한 테스트 주도 개발의 구현","포괄적인 테스트 커버리지로 버그 수정을 확실히 하는 것"," 철저한 테스트를 통해 기존 코드를 자신감 있게 리팩토링"],"es":["Implementar desarrollo guiado por pruebas para el desarrollo de nuevas funcionalidades","Garantizar la corrección de errores con una cobertura de pruebas integral","Refactorizar código existente con confianza mediante pruebas exhaustivas"],"fr":["Mettre en œuvre le développement piloté par les tests pour le développement de nouvelles fonctionnalités","Garantir la correction des bogues avec une couverture de test complète","Refactoriser du code existant en toute confiance grâce à des tests approfondis"],"de":["Implementierung testgetriebener Entwicklung für die Entwicklung neuer Features","Sicherstellung von Bugfixes mit umfassender Testabdeckung","Refactoring von bestehendem Code mit Zuversicht durch gründliches Testen"],"pt":["Implementar desenvolvimento orientado a testes para o desenvolvimento de novos recursos","Garantir correções de bugs com cobertura abrangente de testes","Refatorar código existente com confiança através de testes completos"],"ru":["Внедрение разработки через тестирование для разработки новых функций","Обеспечение исправления ошибок с комплексным покрытием тестами","Рефакторинг существующего кода с уверенностью благодаря тщательному тестированию"],"ar":["تنفيذ التطوير الذي يقوده الاختبار لتطوير الميزات الجديدة","ضمان إصلاح الأخطاء مع تغطية اختبار شاملة","إعادة هيكلة التعليمات البرمجية الحالية بثقة من خلال الاختبار الشامل"]},"limitations":{"en":["Requires adherence to test-driven development principles","Minimum 80% test coverage required","Applies to code development, bug fixing, and refactoring scenarios"],"zh":["需要遵循测试驱动开发原则","需要至少80%的测试覆盖率","仅适用于代码开发、bug修复和重构场景"],"ja":["テスト駆動開発の原則に従う必要がある","少なくとも80%のテストカバレッジが必要","コード開発、バグ修正、リファクタリングシナリオにのみ適用"],"ko":["테스트 주도 개발 원칙을 따라야 함","최소 80%의 테스트 커버리지가 필요함","코드 개발, 버그 수정, 리팩토링 시나리오에만 적용"],"es":["Requiere la adhesión a los principios del desarrollo guiado por pruebas","Se requiere una cobertura de pruebas mínima del 80%","Se aplica a escenarios de desarrollo de código, corrección de errores y refactorización"],"fr":["Nécessite l''adhésion aux principes du développement piloté par les tests","Couverture de test minimale de 80 % requise","S''applique aux scénarios de développement de code, de correction de bogues et de refactorisation"],"de":["Erfordert die Einhaltung der Prinzipien der testgetriebenen Entwicklung","Mindesttestabdeckung von 80 % erforderlich","Gilt für Szenarien der Codeentwicklung, Bugfixing und Refactoring"],"pt":["Requer adesão aos princípios do desenvolvimento orientado a testes","Cobertura mínima de testes de 80% necessária","Aplica-se a cenários de desenvolvimento de código, correção de bugs e refatoração"],"ru":["Требует соблюдения принципов разработки через тестирование","Требуется минимальное покрытие тестами в 80%","Применяется к сценариям разработки кода, исправления ошибок и рефакторинга"],"ar":["يتطلب الالتزام بمبادئ التطوير الذي يقوده الاختبار","تغطية اختبار دنيا مطلوبة بنسبة 80٪","تنطبق على سيناريوهات تطوير التعليمات البرمجية، وإصلاح الأخطاء، وإعادة الهيكلة"]},"version":4},"contentHash":"0c0d287804b33a98bbba2df8169da80403b29fcae4a45aca96522e6c8d022d17","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":89}');
DELETE FROM skills_fts WHERE id = 'affaan-m/everything-claude-code/tdd-workflow';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/tdd-workflow', 'tdd-workflow', 'affaan-m', 'everything-claude-code', 'official', 'tdd-workflow affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The tdd-workflow skill enforces Test-Driven Development principles for AI agents like Claude, mandating tests before code implementation. It ensures comprehensive test coverage exceeding 80% across unit, integration, and E2E tests, benefiting developers building features, fixing bugs, or refactor... TDD 工作流技能确保所有代码开发遵循测试驱动开发原则，实现 80%+ 的测试覆盖率 TDD ワークフロー スキルは、すべてのコード開発がテスト駆動開発の原則に従って実施されるようにします TDD 워크플로우 스킬은 모든 코드 개발을 테스트 주도 개발 원칙에 따라 수행할 수 있도록 합니다 El flujo de trabajo de tdd garantiza que todos los proyectos de desarrollo sigan los principios de TDD con cobertura de pruebas completa Le flux de travail tdd garantit que tous les projets de développement suivent les principes de TDD avec une couverture de tests complète Der tdd-Workflow stellt sicher, dass alle Entwicklungsprojekte den TDD-Prinzipien mit umfassender Testabdeckung folgen O fluxo de desenvolvimento dirigido por testes (TDD) é uma abordagem que assegura que todos os códigos sejam desenvolvidos com testes abrangentes. Isso inclui testes unitários, de integração e de ponta a ponta Поток разработки на основе тестирования (TDD) - это подход, обеспечивающий разработку всех кодов с помощью комплексных тестов, включая юнит-тесты, интеграционные и конечные тесты تدفق التطوير الموجه بالاختبار (TDD) هو نهج يضمن أن يتم تطوير جميع الشفرات مع اختبارات شاملة ، بما في ذلك الاختبارات الوحدوية واختبارات التكامل واختبارات النهاية إلى النهاية what is tdd-workflow how to use tdd-workflow with claude tdd-workflow vs other testing skills tdd-workflow alternative tdd-workflow install guide tdd-workflow setup for MCP tdd-workflow coverage requirements enforce TDD with AI agent TDD 工作流 测试驱动开发 80%+ 测试覆盖率 AI 工具 代码开发 单元测试 集成测试 E2E 测试 Enforces writing tests BEFORE code implementation as a core TDD principle Mandates a minimum of 80% test coverage for all code changes Generates and manages unit, integration, and end-to-end (E2E) tests Activates during new feature development, bug fixing, and code refactoring workflows Provides structured workflow for adding new API endpoints and components tdd-workflow is an AI Agent Skill designed for Claude that enforces a strict Test-Driven Development methodology. It mandates writing tests before implementing code and ensures a minimum of 80% test coverage across unit, integration, and end-to-end (E2E) test types.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('huggingface/skills/hugging-face-trackio', 'official', 'huggingface', 'skills', 'huggingface/skills', 'hugging-face-trackio', 8290, 490, 89, '2026-03-06T05:28:53Z', '2026-03-06T05:41:15.996Z', '0d0654cc659bca435bb4b278ff7f1d6c2978caebed1adb5b01dcf5a69286ca2b', '{"id":"huggingface/skills/hugging-face-trackio","name":"hugging-face-trackio","description":{"en":"hugging-face-trackio is an ML experiment tracking skill that logs metrics via a Python API, retrieves data via CLI, and syncs visualizations to Hugging Face Spaces. It is designed for ML engineers and developers who need real-time monitoring and diagnostics for training runs.","zh":"Trackio 是一个机器学习实验跟踪库，提供 Python API 用于训练期间记录指标和触发诊断警报，以及 CLI 工具用于检索和分析日志数据。它支持实时仪表板可视化、Webhook 警报和 HF Space 同步。","ja":"Trackioは機械学習実験トラッキングライブラリで、トレーニング中のメトリクス記録や診断アラート発報にPython APIを、ログデータの取得・分析にCLIを提供します。リアルタイムダッシュボード可視化、Webhookアラート、HF Space同期をサポート。","ko":"Trackio는 머신러닝 실험 추적 라이브러리로, 훈련 중 메트릭 기록 및 진단 알림 발송을 위한 Python API와 로그 데이터 조회 및 분석을 위한 CLI를 제공합니다. 실시간 대시보드 시각화, Webhook 알림, HF Space 동기화를 지원합니다.","es":"hugging-face-trackio es una biblioteca de seguimiento de experimentos para el registro y la visualización de métricas de entrenamiento de ML. Soporta la sincronización con Hugging Face Spaces para paneles de monitoreo en tiempo real.","fr":"hugging-face-trackio est une bibliothèque de suivi d''expériences pour l''enregistrement et la visualisation des métriques d''entraînement de ML. Elle prend en charge la synchronisation avec Hugging Face Spaces pour des tableaux de bord de surveillance en temps réel.","de":"hugging-face-trackio ist eine Experiment-Verlaufs-Bibliothek für die Aufzeichnung und Visualisierung von ML-Trainingsmetriken. Sie unterstützt die Synchronisation mit Hugging Face Spaces für Echtzeit-Überwachungs-Dashboards.","pt":"Trackio é uma biblioteca para rastrear experimentos de ML, permitindo logging de métricas via Python API, análise via CLI e visualização em dashboards em tempo real no Hugging Face Spaces. Inclui alertas com webhooks para monitoramento de treinamento.","ru":"Trackio — это библиотека для отслеживания экспериментов ML, обеспечивающая логирование метрик через Python API, анализ через CLI и визуализацию в реальном времени на панелях Hugging Face Spaces. Включает оповещения через webhooks для мониторинга обучения.","ar":"Trackio هي مكتبة لتتبع تجارب التعلم الآلي، تتيح تسجيل المقاييس عبر واجهة برمجة Python، والتحليل عبر CLI، والتصور على لوحات التحكم في الوقت الفعلي على Hugging Face Spaces. تتضمن تنبيهات باستخدام webhooks لمراقبة التدريب."},"owner":"huggingface","repo":"skills","repoPath":"huggingface/skills","stars":8290,"forks":490,"updatedAt":"2026-03-06T05:28:53Z","topics":[],"skillMd":{"name":"hugging-face-trackio","description":"Track and visualize ML training experiments with Trackio. Use when logging metrics during training (Python API), firing alerts for training diagnostics, or retrieving/analyzing logged metrics (CLI). Supports real-time dashboard visualization, alerts with webhooks, HF Space syncing, and JSON output for automation.","bodyPreview":"# Trackio - Experiment Tracking for ML Training\n\nTrackio is an experiment tracking library for logging and visualizing ML training metrics. It syncs to Hugging Face Spaces for real-time monitoring dashboards.\n\n## Three Interfaces\n\n| Task | Interface | Reference |\n|------|-----------|-----------|\n| **Logging metrics** during training | Python API | [references/logging_metrics.md](references/logging_metrics.md) |\n| **Firing alerts** for training diagnostics | Python API | [references/alerts.md](re","body":"# Trackio - Experiment Tracking for ML Training\n\nTrackio is an experiment tracking library for logging and visualizing ML training metrics. It syncs to Hugging Face Spaces for real-time monitoring dashboards.\n\n## Three Interfaces\n\n| Task | Interface | Reference |\n|------|-----------|-----------|\n| **Logging metrics** during training | Python API | [references/logging_metrics.md](references/logging_metrics.md) |\n| **Firing alerts** for training diagnostics | Python API | [references/alerts.md](references/alerts.md) |\n| **Retrieving metrics & alerts** after/during training | CLI | [references/retrieving_metrics.md](references/retrieving_metrics.md) |\n\n## When to Use Each\n\n### Python API → Logging\n\nUse `import trackio` in your training scripts to log metrics:\n\n- Initialize tracking with `trackio.init()`\n- Log metrics with `trackio.log()` or use TRL''s `report_to=\"trackio\"`\n- Finalize with `trackio.finish()`\n\n**Key concept**: For remote/cloud training, pass `space_id` — metrics sync to a Space dashboard so they persist after the instance terminates.\n\n→ See [references/logging_metrics.md](references/logging_metrics.md) for setup, TRL integration, and configuration options.\n\n### Python API → Alerts\n\nInsert `trackio.alert()` calls in training code to flag important events — like inserting print statements for debugging, but structured and queryable:\n\n- `trackio.alert(title=\"...\", level=trackio.AlertLevel.WARN)` — fire an alert\n- Three severity levels: `INFO`, `WARN`, `ERROR`\n- Alerts are printed to terminal, stored in the database, shown in the dashboard, and optionally sent to webhooks (Slack/Discord)\n\n**Key concept for LLM agents**: Alerts are the primary mechanism for autonomous experiment iteration. An agent should insert alerts into training code for diagnostic conditions (loss spikes, NaN gradients, low accuracy, training stalls). Since alerts are printed to the terminal, an agent that is watching the training script''s output will see them automatically. For background or detached runs, the agent can poll via CLI instead.\n\n→ See [references/alerts.md](references/alerts.md) for the full alerts API, webhook setup, and autonomous agent workflows.\n\n### CLI → Retrieving\n\nUse the `trackio` command to query logged metrics and alerts:\n\n- `trackio list projects/runs/metrics` — discover what''s available\n- `trackio get project/run/metric` — retrieve summaries and values\n- `trackio list alerts --project <name> --json` — retrieve alerts\n- `trackio show` — launch the dashboard\n- `trackio sync` — sync to HF Space\n\n**Key concept**: Add `--json` for programmatic output suitable for automation and LLM agents.\n\n→ See [references/retrieving_metrics.md](references/retrieving_metrics.md) for all commands, workflows, and JSON output formats.\n\n## Minimal Logging Setup\n\n```python\nimport trackio\n\ntrackio.init(project=\"my-project\", space_id=\"username/trackio\")\ntrackio.log({\"loss\": 0.1, \"accuracy\": 0.9})\ntrackio.log({\"loss\": 0.09, \"accuracy\": 0.91})\ntrackio.finish()\n```\n\n### Minimal Retrieval\n\n```bash\ntrackio list projects --json\ntrackio get metric --project my-project --run my-run --metric loss --json\n```\n\n## Autonomous ML Experiment Workflow\n\nWhen running experiments autonomously as an LLM agent, the recommended workflow is:\n\n1. **Set up training with alerts** — insert `trackio.alert()` calls for diagnostic conditions\n2. **Launch training** — run the script in the background\n3. **Poll for alerts** — use `trackio list alerts --project <name> --json --since <timestamp>` to check for new alerts\n4. **Read metrics** — use `trackio get metric ...` to inspect specific values\n5. **Iterate** — based on alerts and metrics, stop the run, adjust hyperparameters, and launch a new run\n\n```python\nimport trackio\n\ntrackio.init(project=\"my-project\", config={\"lr\": 1e-4})\n\nfor step in range(num_steps):\n    loss = train_step()\n    trackio.log({\"loss\": loss, \"step\": step})\n\n    if step > 100 and loss > 5.0:\n        trackio.alert(\n            title=\"Loss divergence\",\n            text=f\"Loss {loss:.4f} still high after {step} steps\",\n            level=trackio.AlertLevel.ERROR,\n        )\n    if step > 0 and abs(loss) < 1e-8:\n        trackio.alert(\n            title=\"Vanishing loss\",\n            text=\"Loss near zero — possible gradient collapse\",\n            level=trackio.AlertLevel.WARN,\n        )\n\ntrackio.finish()\n```\n\nThen poll from a separate terminal/process:\n\n```bash\ntrackio list alerts --project my-project --json --since \"2025-01-01T00:00:00\"\n```\n"},"category":"official","lastSynced":"2026-03-06T05:41:15.996Z","seo":{"title":{"en":"hugging-face-trackio: Track ML Experiments & Sync Dashboa...","zh":"Hugging Face Trackio 设置指南：机器学习实验跟踪与可视化","ja":"Hugging Face Trackio セットアップガイド：ML実験のトラッキングと可視化","ko":"Hugging Face Trackio 설정 가이드: ML 실험 추적 및 시각화","es":"Guía de configuración de hugging-face-trackio para seguim...","fr":"Guide de mise en place de hugging-face-trackio pour le su...","de":"Einrichtungsleitfaden für hugging-face-trackio zur Nachve...","pt":"Trackio Setup Guide: Log e Visualize Experimentos ML com ...","ru":"Trackio Руководство: Отслеживание экспериментов ML с Hugg...","ar":"دليل إعداد Trackio: تسجيل وتصور تجارب التعلم الآلي مع Hug..."},"description":{"en":"Trackio logs ML training metrics via Python API & CLI, syncs real-time dashboards to Hugging Face Spaces, and fires webhook alerts. Learn how to integrate th...","zh":"Trackio 是专为 ML 训练设计的实验跟踪工具。通过 Python API 记录指标，CLI 检索数据，并实时同步到 Hugging Face Spaces 仪表板。支持 Webhook 警报和 JSON 输出，适合自动化工作流。","ja":"TrackioはMLトレーニング向けの実験トラッキングツールです。Python APIでメトリクスを記録、CLIでデータを取得し、Hugging Face Spacesダッシュボードにリアルタイム同期。WebhookアラートとJSON出力に対応。","ko":"Trackio는 ML 훈련을 위한 실험 추적 도구입니다. Python API로 메트릭 기록, CLI로 데이터 검색, Hugging Face Spaces 대시보드 실시간 동기화. Webhook 알림 및 JSON 출력 지원.","es":"Aprende a utilizar hugging-face-trackio para rastrear y visualizar métricas de entrenamiento de ML con nuestra guía paso a paso","fr":"Découvrez comment utiliser hugging-face-trackio pour suivre et visualiser les métriques d''entraînement de ML avec notre guide étape par étape","de":"Erfahren Sie, wie Sie hugging-face-trackio verwenden können, um ML-Trainingsmetriken zu verfolgen und zu visualisieren, mit unserem Schritt-für-Schritt-Leitf...","pt":"Use Trackio para logging de métricas ML via Python API, CLI para análise e alertas com webhooks. Visualize em tempo real em Hugging Face Spaces. Tutorial téc...","ru":"Trackio для логирования метрик ML через Python API, CLI для анализа и оповещений через webhooks. Визуализация в реальном времени в Hugging Face Spaces. Техни...","ar":"استخدم Trackio لتسجيل مقاييس التعلم الآلي عبر واجهة برمجة Python، وCLI للتحليل والتنبيهات باستخدام webhooks. تصور في الوقت الفعلي على Hugging Face Spaces. دل..."},"definition":{"en":"hugging-face-trackio is an AI Agent skill for tracking and visualizing machine learning training experiments. It provides a Python API for logging metrics, a CLI for retrieving and analyzing logs, and supports real-time dashboard visualization on Hugging Face Spaces.","zh":"Trackio 是 Hugging Face 生态系统中的一款实验跟踪工具，专为机器学习训练过程设计。它允许开发者通过 Python API 记录训练指标，使用 CLI 检索和分析数据，并能将实验结果实时同步到 Hugging Face Spaces 生成可视化仪表板。","ja":"TrackioはHugging Faceエコシステムの実験トラッキングツールで、機械学習トレーニングプロセス向けに設計されています。Python APIでトレーニングメトリクスを記録、CLIでデータを取得・分析し、実験結果をHugging Face Spacesにリアルタイム同期して可視化ダッシュボードを生成します。","ko":"Trackio는 Hugging Face 생태계의 실험 추적 도구로, 머신러닝 훈련 과정을 위해 설계되었습니다. Python API로 훈련 메트릭 기록, CLI로 데이터 검색 및 분석, 실험 결과를 Hugging Face Spaces에 실시간 동기화하여 시각화 대시보드를 생성합니다.","es":"hugging-face-trackio es una herramienta de seguimiento de experimentos de ML que permite registrar y visualizar métricas de entrenamiento","fr":"hugging-face-trackio est un outil de suivi d''expériences de ML qui permet d''enregistrer et de visualiser les métricas d''entraînement","de":"hugging-face-trackio ist ein Tool zur Nachverfolgung von ML-Experimenten, das das Aufzeichnen und Visualisieren von Trainingsmetriken ermöglicht","pt":"Trackio é uma ferramenta de tracking de experimentos para Machine Learning que sincroniza com Hugging Face Spaces. Oferece uma API Python para logging de métricas, um CLI para recuperação de dados e alertas via webhooks para diagnósticos de treinamento.","ru":"Trackio — это инструмент отслеживания экспериментов машинного обучения, который синхронизируется с Hugging Face Spaces. Предоставляет Python API для логирования метрик, CLI для извлечения данных и оповещения через webhooks для диагностики обучения.","ar":"Trackio هي أداة لتتبع تجارب التعلم الآلي التي تتم مزامنتها مع Hugging Face Spaces. توفر واجهة برمجة Python لتسجيل المقاييس، وواجهة سطر الأوامر لاسترداد البيانات، وتنبيهات عبر webhooks لتشخيص التدريب."},"features":{"en":["Logs training metrics via a dedicated Python API","Fires alerts for training diagnostics using webhooks","Retrieves and analyzes logged metrics via a CLI","Syncs experiment data to Hugging Face Spaces for real-time dashboard visualization","Outputs data in JSON format for automation"],"zh":["Python API 用于训练期间记录指标和触发诊断警报","CLI 工具用于检索和分析已记录的指标数据","实时同步到 Hugging Face Spaces 生成可视化仪表板","支持 Webhook 集成实现训练警报功能","提供 JSON 输出格式便于自动化流程集成"],"ja":["トレーニング中のメトリクス記録と診断アラート発報のためのPython API","記録されたメトリクスデータの取得と分析のためのCLIツール","Hugging Face Spacesへのリアルタイム同期による可視化ダッシュボード生成","トレーニングアラート機能のためのWebhook連携サポート","自動化プロセス連携のためのJSON出力形式提供"],"ko":["훈련 중 메트릭 기록 및 진단 알림 발송을 위한 Python API","기록된 메트릭 데이터 검색 및 분석을 위한 CLI 도구","Hugging Face Spaces 실시간 동기화를 통한 시각화 대시보드 생성","훈련 알림 기능을 위한 Webhook 통합 지원","자동화 프로세스 연동을 위한 JSON 출력 형식 제공"],"es":["Registro de métricas de entrenamiento de ML mediante la API de Python","Alertas en tiempo real para diagnósticos de entrenamiento","Sincronización con Hugging Face Spaces para paneles de monitoreo en tiempo real","Visualización de dashboard en tiempo real","Salida JSON para automatización"],"fr":["Enregistrement des métriques d''entraînement de ML via l''API Python","Alertes en temps réel pour les diagnostics d''entraînement","Synchronisation avec Hugging Face Spaces pour des tableaux de bord de surveillance en temps réel","Visualisation de tableau de bord en temps réel","Sortie JSON pour l''automatisation"],"de":["Aufzeichnung von ML-Trainingsmetriken über die Python-API","Echtzeit-Alerts für Trainingsdiagnosen","Synchronisation mit Hugging Face Spaces für Echtzeit-Überwachungs-Dashboards","Echtzeit-Dashboard-Visualisierung","JSON-Ausgabe für Automatisierung"],"pt":["Logging de métricas durante o treinamento via Python API","CLI para recuperar e analisar métricas registradas","Alertas com webhooks para diagnósticos de treinamento","Visualização em dashboard em tempo real no Hugging Face Spaces","Sincronização automática com Hugging Face Spaces","Saída JSON para automação e integração"],"ru":["Логирование метрик во время обучения через Python API","CLI для извлечения и анализа записанных метрик","Оповещения через webhooks для диагностики обучения","Визуализация в реальном времени на панели Hugging Face Spaces","Автоматическая синхронизация с Hugging Face Spaces","Вывод в формате JSON для автоматизации и интеграции"],"ar":["تسجيل المقاييس أثناء التدريب عبر واجهة برمجة Python","واجهة سطر الأوامر لاسترداد وتحليل المقاييس المسجلة","تنبيهات باستخدام webhooks لتشخيص التدريب","تصور على لوحة التحكم في الوقت الفعلي على Hugging Face Spaces","مزامنة تلقائية مع Hugging Face Spaces","إخراج JSON للأتمتة والتكامل"]},"keywords":{"en":["how to use hugging-face-trackio","hugging-face-trackio vs mlflow","hugging-face-trackio python api","hugging-face-trackio install","hugging-face-trackio setup guide","what is hugging-face-trackio","hugging face spaces experiment tracking","hugging-face-trackio cli commands"],"zh":["Hugging Face Trackio","机器学习实验跟踪","Python API 记录指标","CLI 分析训练数据","HF Space 实时仪表板","Webhook 训练警报","ML 实验可视化","AI 工具自动化"],"ja":["Hugging Face Trackio","機械学習実験トラッキング","Python API メトリクス記録","CLI トレーニングデータ分析","HF Space リアルタイムダッシュボード","Webhook トレーニングアラート","ML 実験可視化","AIエージェント自動化"],"ko":["Hugging Face Trackio","머신러닝 실험 추적","Python API 메트릭 기록","CLI 훈련 데이터 분석","HF Space 실시간 대시보드","Webhook 훈련 알림","ML 실험 시각화","AI 에이전트 자동화"],"es":["herramientas de seguimiento de experimentos de ML","registro de métricas de entrenamiento de ML","visualización de dashboard en tiempo real","sincronización con Hugging Face Spaces","API de Python para ML","alertas en tiempo real para diagnósticos de entrenamiento"],"fr":["outils de suivi d''expériences de ML","enregistrement des métriques d''entraînement de ML","visualisation de tableau de bord en temps réel","synchronisation avec Hugging Face Spaces","API Python pour ML","alertes en temps réel pour les diagnostics d''entraînement"],"de":["Tools zur Nachverfolgung von ML-Experimenten","Aufzeichnung von ML-Trainingsmetriken","Echtzeit-Dashboard-Visualisierung","Synchronisation mit Hugging Face Spaces","Python-API für ML","Echtzeit-Alerts für Trainingsdiagnosen"],"pt":["trackio logging métricas python","hugging face spaces dashboard","cli trackio analisar métricas","alertas webhooks ml training","visualização experimentos ml em tempo real","ferramenta ai trackio","como usar trackio hugging face","automação json trackio"],"ru":["trackio логирование метрик python","hugging face spaces дашборд","cli trackio анализ метрик","оповещения webhooks ml обучение","визуализация экспериментов ml в реальном времени","ИИ инструмент trackio","как использовать trackio hugging face","автоматизация json trackio"],"ar":["trackio تسجيل المقاييس python","hugging face spaces لوحة تحكم","واجهة سطر الأوامر trackio تحليل المقاييس","تنبيهات webhooks تدريب التعلم الآلي","تصور تجارب التعلم الآلي في الوقت الفعلي","أداة الذكاء الاصطناعي trackio","كيفية استخدام trackio hugging face","أتمتة json trackio"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Machine Learning Agents needing advanced experiment tracking and visualization capabilities with Hugging Face Spaces integration.","zh":"非常适合需要高级实验跟踪和可视化功能的机器学习代理，特别是与 Hugging Face Spaces 集成。","ja":"Hugging Face Spaces 統合を備えた高度な実験トラッキングおよび視覚化機能を必要とする機械学習エージェントに最適です。","ko":"Hugging Face Spaces와의 통합을 통해 고급 실험 추적 및 시각화 기능을 필요로 하는 기계 학습 에이전트에게 적합합니다.","es":"Perfecto para agentes de aprendizaje automático que necesitan capacidades de seguimiento y visualización de experimentos avanzadas con integración de Hugging Face Spaces.","fr":"Parfait pour les agents d''apprentissage automatique nécessitant des fonctionnalités de suivi et de visualisation d''expériences avancées avec une intégration de Hugging Face Spaces.","de":"Perfekt für Machine-Learning-Agents, die erweiterte Experiment-Tracking- und Visualisierungsfunktionen mit Hugging Face Spaces-Integration benötigen.","pt":"Perfeito para agentes de Aprendizado de Máquina que necessitam de capacidades avançadas de rastreamento e visualização de experimentos com integração do Hugging Face Spaces.","ru":"Идеально подходит для агентов машинного обучения, которым требуются расширенные возможности отслеживания и визуализации экспериментов с интеграцией Hugging Face Spaces.","ar":"مثالي لوكلاء التعلم الآلي الذين يحتاجون إلى إمكانيات متقدمة لتتبع التجارب وتصورها مع دمج مساحات Hugging Face."},"recommendation":{"en":"Empowers agents to log and visualize ML training metrics in real-time using the Trackio Python API, enabling features like real-time dashboard visualization, alerts with webhooks, and JSON output for automation, all synced with Hugging Face Spaces.","zh":"通过 Trackio Python API，使代理能够实时记录和可视化机器学习训练指标，实现实时仪表盘可视化、Webhook 报警和 JSON 输出以实现自动化，并与 Hugging Face Spaces 同步。","ja":"Trackio Python API を使用して、エージェントが機械学習のトレーニング メトリックをリアルタイムに記録および視覚化できるようにし、リアルタイム ダッシュボード視覚化、Webhook アラート、自動化のための JSON 出力を可能にし、Hugging Face Spaces と同期します。","ko":"Trackio Python API를 사용하여 에이전트가 기계 학습 훈련 메트릭을 실시간으로 기록하고 시각화 할 수 있도록 하여 실시간 대시보드 시각화, 웹후크 경고 및 자동화를 위한 JSON 출력을 가능하게 하고 Hugging Face Spaces와 동기화합니다.","es":"Habilita a los agentes a registrar y visualizar métricas de entrenamiento de ML en tiempo real utilizando la API de Python de Trackio, lo que permite características como la visualización de panel de control en tiempo real, alertas con webhooks y salida JSON para la automatización, todo sincronizado con Hugging Face Spaces.","fr":"Permet aux agents de consigner et de visualiser les métriques d''entraînement de ML en temps réel en utilisant l''API Python de Trackio, permettant des fonctionnalités telles que la visualisation du tableau de bord en temps réel, les alertes avec les webhooks et la sortie JSON pour l''automatisation, le tout synchronisé avec Hugging Face Spaces.","de":"Ermächtigt Agenten, ML-Trainingsmetriken in Echtzeit mithilfe der Trackio-Python-API zu protokollieren und zu visualisieren, wodurch Funktionen wie Echtzeit-Dashboard-Visualisierung, Warnungen mit Webhooks und JSON-Ausgabe für die Automatisierung möglich werden, all dies synchronisiert mit Hugging Face Spaces.","pt":"Habilita os agentes a registrar e visualizar métricas de treinamento de ML em tempo real usando a API Python do Trackio, habilitando recursos como visualização de painel em tempo real, alertas com webhooks e saída JSON para automação, todos sincronizados com o Hugging Face Spaces.","ru":"Наделяет агентов возможностью регистрировать и визуализировать метрики обучения ML в режиме реального времени с помощью API Python Trackio, обеспечивая функции, такие как визуализация панели в режиме реального времени, оповещения с помощью веб-хуков и вывод JSON для автоматизации, все синхронизированы с Hugging Face Spaces.","ar":"يمنح الوكلاء khảية تسجيل وتصور معايير تدريب ML في الوقت الفعلي باستخدام واجهة برمجة التطبيقات Python من Trackio، وتفعيل الميزات مثل تصور لوحة القيادة في الوقت الفعلي والتنبيهات مع الويب هوك وخرج JSON للآليّة، كلها متزامنة مع مساحات Hugging Face."},"useCases":{"en":["Logging metrics during ML training sessions for detailed analysis","Firing alerts for training diagnostics to ensure model performance","Retrieving and analyzing logged metrics for model optimization"],"zh":["记录机器学习训练会话期间的指标以进行详细分析","触发训练诊断警报以确保模型性能","检索和分析记录的指标以优化模型"],"ja":["機械学習トレーニング セッション中にメトリックを記録して詳細な分析を実行する","トレーニング診断の警報をトリガーしてモデル性能を確保する","記録されたメトリックを取得して分析してモデルを最適化する"],"ko":["기계 학습 훈련 세션 중에 메트릭을 기록하여 자세한 분석을 수행하는 것","훈련 진단 경고를 발동하여 모델 성능을 보장하는 것","기록된 메트릭을 검색하여 분석하여 모델을 최적화하는 것"],"es":["Registro de métricas durante las sesiones de entrenamiento de ML para un análisis detallado","Disparo de alertas para diagnostics de entrenamiento para garantizar el rendimiento del modelo","Recuperación y análisis de métricas registradas para la optimización del modelo"],"fr":["Enregistrement de métriques pendant les sessions d''entraînement de ML pour une analyse détaillée","Déclenchement d''alertes pour les diagnostics d''entraînement pour assurer les performances du modèle","Récupération et analyse des métriques enregistrées pour l''optimisation du modèle"],"de":["Protokollierung von Metriken während der ML-Trainings-Sitzungen für eine detaillierte Analyse","Auslösen von Warnungen für Trainingsdiagnosen, um die Modellleistung zu gewährleisten","Abrufen und Analysieren der protokollierten Metriken für die Modelloptimierung"],"pt":["Registro de métricas durante sessões de treinamento de ML para análise detalhada","Disparo de alertas para diagnósticos de treinamento para garantir o desempenho do modelo","Recuperação e análise de métricas registradas para otimização do modelo"],"ru":["Регистрация метрик во время сессий обучения ML для детального анализа","Выпуск предупреждений для диагностических целей обучения для обеспечения производительности модели","Получение и анализ зарегистрированных метрик для оптимизации модели"],"ar":["تسجيل المعايير أثناء جلسات تدريب ML للتحليل المعمق","إطلاق التنبيهات لأغراض تشخيص التدريب لضمان أداء النموذج","استرجاع وتصور المعايير المسجلة لتحسين النموذج"]},"limitations":{"en":["Requires Hugging Face account for Space syncing","Python API usage necessary for logging metrics and firing alerts","Dependent on Trackio library compatibility with agent''s Python environment"],"zh":["需要 Hugging Face 账户用于空间同步","需要使用 Python API记录指标和触发警报","依赖 Trackio 库与代理的 Python 环境的兼容性"],"ja":["Hugging Face アカウントが Space の同期に必要","メトリックを記録して警報をトリガーするために Python API の使用が必要","エージェントの Python 環境との Trackio ライブラリの互換性に依存"],"ko":["공간 동기화를 위해 Hugging Face 계정이 필요합니다","메트릭을 기록하고 경고를 발생시키기 위해 Python API 사용이 필요합니다","에이전트의 Python 환경과 Trackio 라이브러리의 호환성에 의존합니다"],"es":["Requiere una cuenta de Hugging Face para la sincronización de espacios","Uso de la API de Python necesario para registrar métricas y disparar alertas","Dependiente de la compatibilidad de la biblioteca Trackio con el entorno de Python del agente"],"fr":["Nécessite un compte Hugging Face pour la synchronisation des espaces","Utilisation de l''API Python nécessaire pour consigner des métriques et déclencher des alertes","Dépend de la compatibilité de la bibliothèque Trackio avec l''environnement Python de l''agent"],"de":["Benötigt ein Hugging Face-Konto für die Synchronisierung von Räumen","Verwendung der Python-API erforderlich für die Protokollierung von Metriken und das Auslösen von Warnungen","Abhängig von der Kompatibilität der Trackio-Bibliothek mit der Python-Umgebung des Agents"],"pt":["Requer conta do Hugging Face para sincronização do Space","Uso da API Python necessário para registro de métricas e disparo de alertas","Dependente da compatibilidade da biblioteca Trackio com o ambiente Python do agente"],"ru":["Требуется учетная запись Hugging Face для синхронизации Space","Необходимо использование API Python для регистрации метрик и выпуска предупреждений","Зависит от совместимости библиотеки Trackio с окружением Python агента"],"ar":["يتطلب حساب Hugging Face لمزامنة الفضاء","استخدام واجهة برمجة التطبيقات Python ضروري لتسجيل المعايير وإطلاق التنبيهات","يعتمد على توافق مكتبة Trackio مع بيئة Python للوكيل"]},"version":4},"contentHash":"0d0654cc659bca435bb4b278ff7f1d6c2978caebed1adb5b01dcf5a69286ca2b","repoEtag":"W/\"3e8364a04a12bbf72e64808b1a78e3c2a1041cb67eca8016da4b98e27a299f18\"","qualityScore":89}');
