INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('huggingface/skills/hugging-face-trackio', 'hugging-face-trackio', 'huggingface', 'skills', 'official', 'hugging-face-trackio huggingface skills official hugging-face-trackio is an ML experiment tracking skill that logs metrics via a Python API, retrieves data via CLI, and syncs visualizations to Hugging Face Spaces. It is designed for ML engineers and developers who need real-time monitoring and diagnostics for training runs. Trackio 是一个机器学习实验跟踪库，提供 Python API 用于训练期间记录指标和触发诊断警报，以及 CLI 工具用于检索和分析日志数据。它支持实时仪表板可视化、Webhook 警报和 HF Space 同步。 Trackioは機械学習実験トラッキングライブラリで、トレーニング中のメトリクス記録や診断アラート発報にPython APIを、ログデータの取得・分析にCLIを提供します。リアルタイムダッシュボード可視化、Webhookアラート、HF Space同期をサポート。 Trackio는 머신러닝 실험 추적 라이브러리로, 훈련 중 메트릭 기록 및 진단 알림 발송을 위한 Python API와 로그 데이터 조회 및 분석을 위한 CLI를 제공합니다. 실시간 대시보드 시각화, Webhook 알림, HF Space 동기화를 지원합니다. hugging-face-trackio es una biblioteca de seguimiento de experimentos para el registro y la visualización de métricas de entrenamiento de ML. Soporta la sincronización con Hugging Face Spaces para paneles de monitoreo en tiempo real. hugging-face-trackio est une bibliothèque de suivi d''expériences pour l''enregistrement et la visualisation des métriques d''entraînement de ML. Elle prend en charge la synchronisation avec Hugging Face Spaces pour des tableaux de bord de surveillance en temps réel. hugging-face-trackio ist eine Experiment-Verlaufs-Bibliothek für die Aufzeichnung und Visualisierung von ML-Trainingsmetriken. Sie unterstützt die Synchronisation mit Hugging Face Spaces für Echtzeit-Überwachungs-Dashboards. Trackio é uma biblioteca para rastrear experimentos de ML, permitindo logging de métricas via Python API, análise via CLI e visualização em dashboards em tempo real no Hugging Face Spaces. Inclui alertas com webhooks para monitoramento de treinamento. Trackio — это библиотека для отслеживания экспериментов ML, обеспечивающая логирование метрик через Python API, анализ через CLI и визуализацию в реальном времени на панелях Hugging Face Spaces. Включает оповещения через webhooks для мониторинга обучения. Trackio هي مكتبة لتتبع تجارب التعلم الآلي، تتيح تسجيل المقاييس عبر واجهة برمجة Python، والتحليل عبر CLI، والتصور على لوحات التحكم في الوقت الفعلي على Hugging Face Spaces. تتضمن تنبيهات باستخدام webhooks لمراقبة التدريب. how to use hugging-face-trackio hugging-face-trackio vs mlflow hugging-face-trackio python api hugging-face-trackio install hugging-face-trackio setup guide what is hugging-face-trackio hugging face spaces experiment tracking hugging-face-trackio cli commands Hugging Face Trackio 机器学习实验跟踪 Python API 记录指标 CLI 分析训练数据 HF Space 实时仪表板 Webhook 训练警报 ML 实验可视化 AI 工具自动化 Logs training metrics via a dedicated Python API Fires alerts for training diagnostics using webhooks Retrieves and analyzes logged metrics via a CLI Syncs experiment data to Hugging Face Spaces for real-time dashboard visualization Outputs data in JSON format for automation hugging-face-trackio is an AI Agent skill for tracking and visualizing machine learning training experiments. It provides a Python API for logging metrics, a CLI for retrieving and analyzing logs, and supports real-time dashboard visualization on Hugging Face Spaces.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('google-labs-code/stitch-skills/enhance-prompt', 'official', 'google-labs-code', 'stitch-skills', 'google-labs-code/stitch-skills', 'enhance-prompt', 2204, 256, 89, '2026-03-06T05:29:41Z', '2026-03-06T05:44:26.494Z', 'ccb200c798072438b642b1fa6a5c515563159e2fab3d56e813d76d8afa9a7ce6', '{"id":"google-labs-code/stitch-skills/enhance-prompt","name":"enhance-prompt","description":{"en":"The enhance-prompt skill is a Stitch Prompt Engineer that refines rough UI generation ideas into polished, optimized prompts. It specifically benefits developers and AI practitioners using Stitch by enhancing prompt specificity and structure for better AI output.","zh":"增强提示引擎将粗糙的UI生成想法转化为精致的Stitch优化提示","ja":"プロンプト最適化エンジンは、Stitchのプロンプトを最適化して生成結果を向上させます","ko":"프로ンプ트 최적화 엔진은 Stitch 프로ンプ트를 최적화하여 결과를 향상합니다","es":"Enhance-prompt transforma ideas de UI vagas en promts de Stitch optimizados, mejorando la especificidad y la estructura para mejores resultados","fr":"Enhance-prompt améliore les invites de UI en les transformant en promts de Stitch optimisés, améliorant la spécificité et la structure pour de meilleurs résultats","de":"Enhance-prompt wandelt vage UI-Ideen in optimierte Stitch-Prompts um, verbessert die Spezifität und Struktur für bessere Ergebnisse","pt":"O Enhance-Prompt transforma ideias de UI vagas em prompts polidos e otimizados para Stitch, adicionando palavras-chave de UI/UX e contexto de design system","ru":"Enhance-Prompt преобразует нечеткие идеи UI в оптимизированные подсказки для Stitch, добавляя ключевые слова UI/UX и контекст дизайн-системы для ИИ Агентов","ar":"يحول Enhance-Prompt الأفكار الغامضة لUI إلى ملحوظات محسنة ومتقنة لستيتش، بإضافة كلمات مفتاحية لUI/UX وسياق نظام التصميم للأدوات الذكية"},"owner":"google-labs-code","repo":"stitch-skills","repoPath":"google-labs-code/stitch-skills","stars":2204,"forks":256,"updatedAt":"2026-03-06T05:29:41Z","topics":[],"skillMd":{"name":"enhance-prompt","description":"Transforms vague UI ideas into polished, Stitch-optimized prompts. Enhances specificity, adds UI/UX keywords, injects design system context, and structures output for better generation results.","bodyPreview":"# Enhance Prompt for Stitch\n\nYou are a **Stitch Prompt Engineer**. Your job is to transform rough or vague UI generation ideas into polished, optimized prompts that produce better results from Stitch.\n\n## Prerequisites\n\nBefore enhancing prompts, consult the official Stitch documentation for the latest best practices:\n\n- **Stitch Effective Prompting Guide**: https://stitch.withgoogle.com/docs/learn/prompting/\n\nThis guide contains up-to-date recommendations that may supersede or complement the pat","body":"# Enhance Prompt for Stitch\n\nYou are a **Stitch Prompt Engineer**. Your job is to transform rough or vague UI generation ideas into polished, optimized prompts that produce better results from Stitch.\n\n## Prerequisites\n\nBefore enhancing prompts, consult the official Stitch documentation for the latest best practices:\n\n- **Stitch Effective Prompting Guide**: https://stitch.withgoogle.com/docs/learn/prompting/\n\nThis guide contains up-to-date recommendations that may supersede or complement the patterns in this skill.\n\n## When to Use This Skill\n\nActivate when a user wants to:\n- Polish a UI prompt before sending to Stitch\n- Improve a prompt that produced poor results\n- Add design system consistency to a simple idea\n- Structure a vague concept into an actionable prompt\n\n## Enhancement Pipeline\n\nFollow these steps to enhance any prompt:\n\n### Step 1: Assess the Input\n\nEvaluate what''s missing from the user''s prompt:\n\n| Element | Check for | If missing... |\n|---------|-----------|---------------|\n| **Platform** | \"web\", \"mobile\", \"desktop\" | Add based on context or ask |\n| **Page type** | \"landing page\", \"dashboard\", \"form\" | Infer from description |\n| **Structure** | Numbered sections/components | Create logical page structure |\n| **Visual style** | Adjectives, mood, vibe | Add appropriate descriptors |\n| **Colors** | Specific values or roles | Add design system or suggest |\n| **Components** | UI-specific terms | Translate to proper keywords |\n\n### Step 2: Check for DESIGN.md\n\nLook for a `DESIGN.md` file in the current project:\n\n**If DESIGN.md exists:**\n1. Read the file to extract the design system block\n2. Include the color palette, typography, and component styles\n3. Format as a \"DESIGN SYSTEM (REQUIRED)\" section in the output\n\n**If DESIGN.md does not exist:**\n1. Add this note at the end of the enhanced prompt:\n\n```\n---\n💡 **Tip:** For consistent designs across multiple screens, create a DESIGN.md \nfile using the `design-md` skill. This ensures all generated pages share the \nsame visual language.\n```\n\n### Step 3: Apply Enhancements\n\nTransform the input using these techniques:\n\n#### A. Add UI/UX Keywords\n\nReplace vague terms with specific component names:\n\n| Vague | Enhanced |\n|-------|----------|\n| \"menu at the top\" | \"navigation bar with logo and menu items\" |\n| \"button\" | \"primary call-to-action button\" |\n| \"list of items\" | \"card grid layout\" or \"vertical list with thumbnails\" |\n| \"form\" | \"form with labeled input fields and submit button\" |\n| \"picture area\" | \"hero section with full-width image\" |\n\n#### B. Amplify the Vibe\n\nAdd descriptive adjectives to set the mood:\n\n| Basic | Enhanced |\n|-------|----------|\n| \"modern\" | \"clean, minimal, with generous whitespace\" |\n| \"professional\" | \"sophisticated, trustworthy, with subtle shadows\" |\n| \"fun\" | \"vibrant, playful, with rounded corners and bold colors\" |\n| \"dark mode\" | \"dark theme with high-contrast accents on deep backgrounds\" |\n\n#### C. Structure the Page\n\nOrganize content into numbered sections:\n\n```markdown\n**Page Structure:**\n1. **Header:** Navigation with logo and menu items\n2. **Hero Section:** Headline, subtext, and primary CTA\n3. **Content Area:** [Describe the main content]\n4. **Footer:** Links, social icons, copyright\n```\n\n#### D. Format Colors Properly\n\nWhen colors are mentioned, format them as:\n```\nDescriptive Name (#hexcode) for functional role\n```\n\nExamples:\n- \"Deep Ocean Blue (#1a365d) for primary buttons and links\"\n- \"Warm Cream (#faf5f0) for page background\"\n- \"Soft Gray (#6b7280) for secondary text\"\n\n### Step 4: Format the Output\n\nStructure the enhanced prompt in this order:\n\n```markdown\n[One-line description of the page purpose and vibe]\n\n**DESIGN SYSTEM (REQUIRED):**\n- Platform: [Web/Mobile], [Desktop/Mobile]-first\n- Theme: [Light/Dark], [style descriptors]\n- Background: [Color description] (#hex)\n- Primary Accent: [Color description] (#hex) for [role]\n- Text Primary: [Color description] (#hex)\n- [Additional design tokens...]\n\n**Page Structure:**\n1. **[Section]:** [Description]\n2. **[Section]:** [Description]\n...\n```\n\n## Output Options\n\n**Default:** Return the enhanced prompt as text for the user to copy.\n\n**Optional file output:** If the user requests, write to a file:\n- `next-prompt.md` — for use with the `stitch-loop` skill\n- Custom filename specified by user\n\n## Examples\n\n### Example 1: Vague Input → Structured Prompt\n\n**User input:**\n> \"make me a login page\"\n\n**Enhanced output:**\n```markdown\nA clean, trustworthy login page with a centered form and subtle branding.\n\n**DESIGN SYSTEM (REQUIRED):**\n- Platform: Web, Desktop-first\n- Theme: Light, minimal, professional\n- Background: Clean White (#ffffff)\n- Surface: Soft Gray (#f9fafb) for form card\n- Primary Accent: Deep Blue (#2563eb) for submit button and links\n- Text Primary: Near Black (#111827) for headings\n- Text Secondary: Medium Gray (#6b7280) for labels\n- Buttons: Subtly rounded (8px), full-width on form\n- Cards: Gently rounded (12px), soft shadow for elevation\n\n**Page Structure:**\n1. **Header:** Minimal logo, centered\n2. **Login Card:** Centered form with email, password fields, \"Forgot password?\" link\n3. **Submit Button:** Primary blue \"Sign In\" button\n4. **Footer:** \"Don''t have an account? Sign up\" link\n\n---\n💡 **Tip:** For consistent designs across multiple screens, create a DESIGN.md \nfile using the `design-md` skill.\n```\n\n### Example 2: Feature Request → Targeted Edit\n\n**User input:**\n> \"add a search bar\"\n\n**Enhanced output:**\n```markdown\nAdd a search bar to the header navigation.\n\n**Specific changes:**\n- Location: Header, right side before user avatar\n- Style: Pill-shaped input with subtle gray background (#f3f4f6)\n- Icon: Magnifying glass icon on the left, inside the input\n- Placeholder: \"Search...\" in light gray (#9ca3af)\n- Behavior: Expands on focus with subtle shadow\n- Width: 240px default, 320px on focus\n\n**Context:** This is a targeted edit. Make only this change while preserving all existing elements.\n```\n\n## Tips for Best Results\n\n1. **Be specific early** — Vague inputs need more enhancement\n2. **Match the user''s intent** — Don''t over-design if they want simple\n3. **Keep it structured** — Numbered sections help Stitch understand hierarchy\n4. **Include the design system** — Consistency is key for multi-page projects\n5. **One change at a time for edits** — Don''t bundle unrelated changes\n"},"category":"official","lastSynced":"2026-03-06T05:44:26.494Z","seo":{"title":{"en":"enhance-prompt: Stitch-Optimized Prompt Engineering | AI ...","zh":"增强提示引擎设置指南 - AIエージェント工具","ja":"AIエージェントを使用したプロンプト最適化ガイド","ko":"프로ンプ트 최적화 설정 가이드 - AI 에이전트 도구","es":"Guía de configuración para enhance-prompt: Mejora de prom...","fr":"Guide de configuration pour enhance-prompt : Amélioration...","de":"Konfigurationsleitfaden für enhance-prompt: Optimierung v...","pt":"Guia de Configuração do Enhance-Prompt para Stitch","ru":"Руководство по настройке Enhance-Prompt для Stitch ИИ Аге...","ar":"دليل إعداد Enhance-Prompt لستيتش للأدوات الذكية"},"description":{"en":"Transform vague UI ideas into precise Stitch prompts. This AI agent skill injects UI/UX keywords & design system context for superior generation results. Con...","zh":"了解增强提示引擎的技术细节，优化您的Stitch提示，提高生成结果","ja":"Stitchのプロンプトを最適化し、生成結果を向上させるためのテクニック","ko":"Stitch 프로ンプ트 최적화 및 결과 향상을 위한 기술 정보","es":"Aprende a transformar ideas de UI vagas en promts de Stitch optimizados con enhance-prompt, la herramienta de AI para desarrolladores","fr":"Découvrez comment améliorer les invites de UI avec enhance-prompt, l''outil d''IA pour les développeurs","de":"Erfahren Sie, wie Sie vage UI-Ideen mit enhance-prompt in optimierte Stitch-Prompts umwandeln, das AI-Tool für Entwickler","pt":"Aprenda a transformar ideias de UI vagas em prompts otimizados para Stitch. Consulte nossa guia para obter os melhores resultados","ru":"Преобразуйте нечеткие идеи UI в оптимизированные подсказки для Stitch. Изучите наше руководство для лучших результатов ИИ Агентов","ar":"تعلم كيفية تحويل الأفكار الغامضة لUI إلى ملحوظات محسنة لستيتش. استشر دليلنا للحصول على أفضل النتائج للأدوات الذكية"},"definition":{"en":"enhance-prompt is an AI agent skill that acts as a Stitch Prompt Engineer. It transforms vague UI ideas into polished prompts optimized for the Stitch platform by enhancing specificity, adding UI/UX keywords, and injecting design system context.","zh":"增强提示引擎是一种将UI生成想法转化为Stitch优化提示的技术","ja":"プロンプト最適化エンジンとは、Stitchのプロンプトを最適化する技術です","ko":"프로ンプ트 최적화 엔진은 Stitch 프로ンプ트를 최적화하는 기술입니다","es":"Enhance-prompt es una herramienta de AI que transforma ideas de UI vagas en promts de Stitch optimizados","fr":"Enhance-prompt est un outil d''IA qui améliore les invites de UI en les transformant en promts de Stitch optimisés","de":"Enhance-prompt ist ein AI-Tool, das vage UI-Ideen in optimierte Stitch-Prompts umwandelt","pt":"O Enhance-Prompt é uma ferramenta que transforma ideias de UI vagas em prompts otimizados para Stitch","ru":"Enhance-Prompt - это инструмент, преобразующий нечеткие идеи UI в оптимизированные подсказки для Stitch ИИ Агентов","ar":"Enhance-Prompt هو أداة تحول الأفكار الغامضة لUI إلى ملحوظات محسنة لستيتش للأدوات الذكية"},"features":{"en":["Transforms vague UI generation ideas into polished prompts","Optimizes prompts specifically for the Stitch platform","Enhances prompt specificity for better generation results","Adds relevant UI/UX keywords to the input prompt","Injects design system context into the final prompt","Consults the official Stitch Effective Prompting Guide for best practices"],"zh":["添加UI/UX关键词","注入设计系统上下文","优化输出结构","提高生成结果","支持Stitch Effective Prompting Guide","增强提示的具体性"],"ja":["UI/UXキーワードの追加","デザインシステムのコンテキストを注入","出力構造の最適化","生成結果の向上","Stitch Effective Prompting Guideのサポート","プロンプトの具体性の向上"],"ko":["UI/UX 키워드 추가","디자인 시스템 컨텍스트 삽입","출력 구조 최적화","생성 결과 향상","Stitch Effective Prompting Guide 지원","프로ンプ트의 구체성 향상"],"es":["Mejora la especificidad de los promts de UI","Agrega palabras clave de UI/UX","Inyecta contexto de sistema de diseño","Estructura la salida para mejores resultados de generación","Se basa en las mejores prácticas de Stitch","Utiliza la guía de prompting efectiva de Stitch"],"fr":["Améliore la spécificité des invites de UI","Ajoute des mots-clés d''UI/UX","Injecte le contexte de système de conception","Structure la sortie pour de meilleurs résultats de génération","Se base sur les meilleures pratiques de Stitch","Utilise le guide de prompting efficace de Stitch"],"de":["Verbessert die Spezifität von UI-Prompts","Fügt UI/UX-Schlüsselwörter hinzu","Injiziert Designsystem-Kontext","Strukturiert die Ausgabe für bessere Generierungsergebnisse","Basierend auf den besten Praktiken von Stitch","Verwenden Sie die effektive Prompting-Anleitung von Stitch"],"pt":["Adiciona palavras-chave de UI/UX","Injeta contexto de design system","Estrutura a saída para melhores resultados de geração","Otimiza prompts para Stitch","Melhora a especificidade das ideias de UI"],"ru":["Добавляет ключевые слова UI/UX","Вводит контекст дизайн-системы","Структурирует вывод для лучших результатов генерации","Оптимизирует подсказки для Stitch ИИ Агентов","Улучшает конкретность идей UI"],"ar":["يضيف كلمات مفتاحية لUI/UX","ي ввسياق نظام التصميم","يهيكل الإخراج للحصول على أفضل النتائج للتوليد","يحسن الملحوظات لستيتش للأدوات الذكية","يحسن دقة الأفكار لUI"]},"keywords":{"en":["how to use enhance-prompt skill","what is enhance-prompt for Stitch","enhance-prompt alternative","enhance-prompt vs other prompt engineers","enhance-prompt install guide","Stitch Effective Prompting Guide","Stitch prompt optimization","AI agent prompt engineering"],"zh":["增强提示引擎","Stitch优化","UI生成","AIエージェント工具","プロンプト最適化","生成结果","Stitch Effective Prompting Guide","设计系统","UI/UX关键词"],"ja":["AIエージェント","プロンプト最適化","Stitch","UI生成","生成結果","Stitch Effective Prompting Guide","デザインシステム","UI/UXキーワード","プロンプトエンジン"],"ko":["AI 에이전트","프로ンプ트 최적화","Stitch","UI 생성","생성 결과","Stitch Effective Prompting Guide","디자인 시스템","UI/UX 키워드","프로ンプ트 엔진"],"es":["enhance-prompt","Stitch","UI","UX","prompts de UI","herramientas de AI para desarrolladores","mejora de promts de UI","optimización de promts de Stitch","guias de prompting de Stitch","desarrollo de UI con AI"],"fr":["enhance-prompt","Stitch","UI","UX","invites de UI","outils d''IA pour les développeurs","amélioration des invites de UI","optimisation des invites de Stitch","guides de prompting de Stitch","développement d''UI avec l''IA"],"de":["enhance-prompt","Stitch","UI","UX","UI-Prompts","AI-Tools für Entwickler","Optimierung von UI-Prompts","Optimierung von Stitch-Prompts","Prompting-Anleitungen von Stitch","UI-Entwicklung mit AI"],"pt":["Enhance-Prompt","Stitch","UI/UX","design system","otimização de prompts","ferramentas de UI","desenvolvimento de UI","guias de configuração"],"ru":["Enhance-Prompt","Stitch","ИИ Агенты","UI/UX","дизайн-система","оптимизация подсказок","инструменты UI","разработка UI","руководство по настройке"],"ar":["Enhance-Prompt","ستيتش","الأدوات الذكية","UI/UX","نظام التصميم","تحسين الملحوظات","أدوات UI","تطوير UI","دليل الإعداد"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Prompt Engineering Agents specializing in UI/UX design optimization and structured output generation.","zh":"非常适合专注于 UI/UX 设计优化和结构化输出生成的 Prompt Engineering Agent。","ja":"UI/UX 設計の最適化と構造化された出力生成を専門とする Prompt Engineering Agent に最適です。","ko":"UI/UX 디자인 최적화 및 구조화된 출력 생성을 전문으로 하는 Prompt Engineering Agent에 이상적입니다.","es":"Ideal para Prompt Engineering Agents especializados en optimización de UI/UX design y generación de structured output.","fr":"Idéal pour les Prompt Engineering Agents spécialisés dans l''optimisation de l''UI/UX design et la génération de structured output.","de":"Ideal für Prompt Engineering Agents, die sich auf die Optimierung von UI/UX design und die Generierung von structured output spezialisieren.","pt":"Ideal para Agentes de Engenharia de Prompt especializados em otimização de design de UI/UX e geração de saída estruturada.","ru":"Идеально подходит для агентов инженерии подсказок, специализирующихся на оптимизации дизайна UI/UX и генерации структурированного вывода.","ar":"مثالي لعميل هندسة الطلبات المتخصصة في تحسين تصميم الواجهة و chod الإخراج المنظم."},"recommendation":{"en":"Transforms vague UI concepts into Stitch-optimized prompts by enhancing specificity, injecting UI/UX keywords, adding design system context, and structuring outputs for superior generation results. Provides direct integration with Stitch''s prompting guidelines and best practices for maximum compatibility.","zh":"通过增强具体性、注入 UI/UX 关键词、添加设计系统上下文以及为输出结果构建结构，将模糊的 UI 概念转化为针对 Stitch 优化的 prompt，从而实现卓越的生成效果。提供与 Stitch 的 prompting 指南和最佳实践的直接集成，以实现最大兼容性。","ja":"具体性の向上、UI/UX キーワードの注入、デザインシステムコンテキストの追加、優れた生成結果のための出力構造化を通じて、漠然とした UI の概念を Stitch に最適化された prompt に変換します。最大限の互換性を実現するために、Stitch の prompting ガイドラインとベストプラクティスとの直接統合を提供します。","ko":"구체성 향상, UI/UX 키워드 주입, 디자인 시스템 컨텍스트 추가, 그리고 우수한 생성 결과를 위한 출력 구조화를 통해 모호한 UI 개념을 Stitch에 최적화된 prompt로 변환합니다. 최대 호환성을 위해 Stitch의 prompting 가이드라인 및 모범 사례와의 직접적인 통합을 제공합니다.","es":"Transforma conceptos de UI vagos en prompts optimizados para Stitch mediante el aumento de la especificidad, la inyección de palabras clave de UI/UX, la adición de contexto del design system y la estructuración de outputs para obtener resultados de generación superiores. Proporciona integración directa con las directrices de prompting y las best practices de Stitch para una máxima compatibilidad.","fr":"Transforme des concepts d''UI vagues en des prompts optimisés pour Stitch en améliorant la spécificité, en injectant des mots-clés UI/UX, en ajoutant du contexte de design system et en structurant les outputs pour des résultats de génération supérieurs. Fournit une intégration directe avec les directives de prompting et les best practices de Stitch pour une compatibilité maximale.","de":"Verwandelt vage UI-Konzepte in für Stitch optimierte Prompts, indem die Spezifität erhöht, UI/UX-Keywords eingefügt, Design-System-Kontext hinzugefügt und Outputs für überlegene Generierungsergebnisse strukturiert werden. Bietet direkte Integration mit den Prompting-Richtlinien und Best Practices von Stitch für maximale Kompatibilität.","pt":"Transforma conceitos vagos de UI em prompts otimizados para Stitch, aumentando a especificidade, injetando palavras-chave de UI/UX, adicionando contexto de sistema de design e estruturando saídas para resultados de geração superiores. Fornece integração direta com as diretrizes e as melhores práticas de prompting do Stitch para compatibilidade máxima.","ru":"Преобразует расплывчатые концепции UI в подсказки, оптимизированные для Stitch, повышая конкретность, вводя ключевые слова UI/UX, добавляя контекст системы дизайна и структурируя выходные данные для получения лучших результатов генерации. Обеспечивает прямую интеграцию с рекомендациями по созданию подсказок и передовым опытом Stitch для максимальной совместимости.","ar":"يحول المفاهيم الغامضة لواجهة المستخدم إلى مؤشرات محسّنة لبرنامج Stitch من خلال تعزيز الدقة و الحقن الكلمات الرئيسية لواجهة المستخدم و تجربة المستخدم و إضافة سياق نظام التصميم و هيكلة الإخراج للحصول على نتائج جيدة للجيل. يوفر التكامل المباشر مع إرشادات و أفضل الممارسات لبرنامج Stitch للحصول على أقصى توافق."},"useCases":{"en":["Converting rough UI ideas into polished prompts","Injecting design system context into generation requests","Structuring output specifications for Stitch compatibility","Optimizing prompts with UI/UX terminology"],"zh":["将粗略的 UI 想法转化为精美的 prompt","将设计系统上下文注入生成请求中","构建符合 Stitch 兼容性的输出规范","使用 UI/UX 术语优化 prompt"],"ja":["大まかな UI のアイデアを洗練された prompt に変換する","生成リクエストにデザインシステムのコンテキストを注入する","Stitch 互換性のための出力仕様を構造化する","UI/UX 用語を使用して prompt を最適化する"],"ko":["거친 UI 아이디어를 세련된 prompt로 전환","생성 요청에 디자인 시스템 컨텍스트 주입","Stitch 호환성을 위한 출력 사양 구조화","UI/UX 용어를 사용하여 prompt 최적화"],"es":["Convertir ideas aproximadas de UI en prompts pulidos","Inyectar contexto del design system en las solicitudes de generación","Estructurar especificaciones de output para la compatibilidad con Stitch","Optimizar prompts con terminología de UI/UX"],"fr":["Convertir des idées approximatives d''UI en prompts polis","Injecter du contexte de design system dans les requêtes de génération","Structurer les spécifications d''output pour la compatibilité avec Stitch","Optimiser les prompts avec la terminologie UI/UX"],"de":["Umsetzen grober UI-Ideen in polierte Prompts","Einbringen von Design-System-Kontext in Generierungsanfragen","Strukturieren von Output-Spezifikationen für die Stitch-Kompatibilität","Optimieren von Prompts mit UI/UX-Terminologie"],"pt":["Conversão de ideias de UI粗as em prompts polidos","Injeção de contexto de sistema de design em solicitações de geração","Estruturação de especificações de saída para compatibilidade com o Stitch","Otimização de prompts com terminologia de UI/UX"],"ru":["Преобразование грубых идей UI в отполированные подсказки","Ввод контекста системы дизайна в запросы генерации","Структуризация спецификаций вывода для совместимости с Stitch","Оптимизация подсказок с терминологией UI/UX"],"ar":["تحويل أفكار واجهة المستخدم الخام إلى مؤشرات متطورة","الحقن سياق نظام التصميم في طلبات الجيل","هيكلة مواصفات الإخراج لتوافق برنامج Stitch","تحسين المؤشرات بالترميز لواجهة المستخدم و تجربة المستخدم"]},"limitations":{"en":["Requires familiarity with Stitch documentation","Limited to text-based prompt enhancement","Dependent on current Stitch API specifications"],"zh":["需要熟悉 Stitch 文档","仅限于基于文本的 prompt 增强","依赖于当前的 Stitch API 规范"],"ja":["Stitch のドキュメントに関する知識が必要","テキストベースの prompt 拡張に限定される","現在の Stitch API 仕様に依存"],"ko":["Stitch 문서에 대한 숙련도 필요","텍스트 기반 prompt 향상으로 제한됨","현재 Stitch API 사양에 의존"],"es":["Requiere familiaridad con la documentación de Stitch","Limitado a la mejora de prompts basada en texto","Dependiente de las especificaciones actuales de la API de Stitch"],"fr":["Nécessite une familiarité avec la documentation de Stitch","Limité à l''amélioration de prompts basée sur le texte","Dépend des spécifications actuelles de l''API Stitch"],"de":["Erfordert Vertrautheit mit der Stitch-Dokumentation","Beschränkt auf textbasierte Prompt-Verbesserung","Abhängig von den aktuellen Stitch-API-Spezifikationen"],"pt":["Requer familiaridade com a documentação do Stitch","Limitado a melhoria de prompts baseados em texto","Dependente das especificações atuais da API do Stitch"],"ru":["Требует знакомства с документацией Stitch","Ограничен до улучшения текстовых подсказок","Зависит от текущих спецификаций API Stitch"],"ar":["يتطلب معرفة بوثائق برنامج Stitch","محدود إلى تحسين مؤشرات النص","يعتمد على مواصفات API الحالية لبرنامج Stitch"]},"version":4},"contentHash":"ccb200c798072438b642b1fa6a5c515563159e2fab3d56e813d76d8afa9a7ce6","repoEtag":"W/\"bb47617e3029a9b4385327f9dc9702c508cf6c4fbacc7fed320cabd4b144bac3\"","qualityScore":89}');
