INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('google-labs-code/stitch-skills/enhance-prompt', 'enhance-prompt', 'google-labs-code', 'stitch-skills', 'official', 'enhance-prompt google-labs-code stitch-skills official The enhance-prompt skill is a Stitch Prompt Engineer that refines rough UI generation ideas into polished, optimized prompts. It specifically benefits developers and AI practitioners using Stitch by enhancing prompt specificity and structure for better AI output. 增强提示引擎将粗糙的UI生成想法转化为精致的Stitch优化提示 プロンプト最適化エンジンは、Stitchのプロンプトを最適化して生成結果を向上させます 프로ンプ트 최적화 엔진은 Stitch 프로ンプ트를 최적화하여 결과를 향상합니다 Enhance-prompt transforma ideas de UI vagas en promts de Stitch optimizados, mejorando la especificidad y la estructura para mejores resultados Enhance-prompt améliore les invites de UI en les transformant en promts de Stitch optimisés, améliorant la spécificité et la structure pour de meilleurs résultats Enhance-prompt wandelt vage UI-Ideen in optimierte Stitch-Prompts um, verbessert die Spezifität und Struktur für bessere Ergebnisse O Enhance-Prompt transforma ideias de UI vagas em prompts polidos e otimizados para Stitch, adicionando palavras-chave de UI/UX e contexto de design system Enhance-Prompt преобразует нечеткие идеи UI в оптимизированные подсказки для Stitch, добавляя ключевые слова UI/UX и контекст дизайн-системы для ИИ Агентов يحول Enhance-Prompt الأفكار الغامضة لUI إلى ملحوظات محسنة ومتقنة لستيتش، بإضافة كلمات مفتاحية لUI/UX وسياق نظام التصميم للأدوات الذكية how to use enhance-prompt skill what is enhance-prompt for Stitch enhance-prompt alternative enhance-prompt vs other prompt engineers enhance-prompt install guide Stitch Effective Prompting Guide Stitch prompt optimization AI agent prompt engineering 增强提示引擎 Stitch优化 UI生成 AIエージェント工具 プロンプト最適化 生成结果 Stitch Effective Prompting Guide 设计系统 UI/UX关键词 Transforms vague UI generation ideas into polished prompts Optimizes prompts specifically for the Stitch platform Enhances prompt specificity for better generation results Adds relevant UI/UX keywords to the input prompt Injects design system context into the final prompt Consults the official Stitch Effective Prompting Guide for best practices enhance-prompt is an AI agent skill that acts as a Stitch Prompt Engineer. It transforms vague UI ideas into polished prompts optimized for the Stitch platform by enhancing specificity, adding UI/UX keywords, and injecting design system context.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cloudflare/skills/durable-objects', 'official', 'cloudflare', 'skills', 'cloudflare/skills', 'durable-objects', 535, 66, 89, '2026-03-06T05:33:24Z', '2026-03-06T05:55:47.072Z', 'cd6797cb18f3ae8f721dfd2e5cb27b73a0aa8636683f1a38163dab2fd51a8dfb', '{"id":"cloudflare/skills/durable-objects","name":"durable-objects","description":{"en":"The durable-objects skill enables developers to build stateful, coordinated applications on Cloudflare''s edge. It supports Workers integration, wrangler config, and testing with Vitest.","zh":"Durable Objects是Cloudflare的边缘计算服务，用于构建有状态的协调应用","ja":"Durable ObjectsはCloudflareのエッジコンピューティングサービスであり、状態fulな協調アプリケーションを構築するために使用されます","ko":"Durable Objects는 Cloudflare의 에지 컴퓨팅 서비스로 상태가 있는 협調 애플리케이션을 구축하는 데 사용됩니다","es":"Durable Objects es una tecnología de Cloudflare que permite crear aplicaciones estatales y coordina las acciones con Workers y WebSockets.","fr":"Les objets durables sont une technologie Cloudflare qui permet de créer des applications coordonnées et d''intégrer les Workers et WebSockets.","de":"Durable Objects ist eine Cloudflare-Technologie, die die Erstellung von stateful Anwendungen ermöglicht und Workers sowie WebSockets integriert."},"owner":"cloudflare","repo":"skills","repoPath":"cloudflare/skills","stars":535,"forks":66,"updatedAt":"2026-03-06T05:33:24Z","topics":["agents","cloudflare","skills","workers"],"skillMd":{"name":"durable-objects","description":"Create and review Cloudflare Durable Objects. Use when building stateful coordination (chat rooms, multiplayer games, booking systems), implementing RPC methods, SQLite storage, alarms, WebSockets, or reviewing DO code for best practices. Covers Workers integration, wrangler config, and testing with Vitest. Biases towards retrieval from Cloudflare docs over pre-trained knowledge.","bodyPreview":"# Durable Objects\n\nBuild stateful, coordinated applications on Cloudflare''s edge using Durable Objects.\n\n## Retrieval Sources\n\nYour knowledge of Durable Objects APIs and configuration may be outdated. **Prefer retrieval over pre-training** for any Durable Objects task.\n\n| Resource | URL |\n|----------|-----|\n| Docs | https://developers.cloudflare.com/durable-objects/ |\n| API Reference | https://developers.cloudflare.com/durable-objects/api/ |\n| Best Practices | https://developers.cloudflare.com/d","body":"# Durable Objects\n\nBuild stateful, coordinated applications on Cloudflare''s edge using Durable Objects.\n\n## Retrieval Sources\n\nYour knowledge of Durable Objects APIs and configuration may be outdated. **Prefer retrieval over pre-training** for any Durable Objects task.\n\n| Resource | URL |\n|----------|-----|\n| Docs | https://developers.cloudflare.com/durable-objects/ |\n| API Reference | https://developers.cloudflare.com/durable-objects/api/ |\n| Best Practices | https://developers.cloudflare.com/durable-objects/best-practices/ |\n| Examples | https://developers.cloudflare.com/durable-objects/examples/ |\n\nFetch the relevant doc page when implementing features.\n\n## When to Use\n\n- Creating new Durable Object classes for stateful coordination\n- Implementing RPC methods, alarms, or WebSocket handlers\n- Reviewing existing DO code for best practices\n- Configuring wrangler.jsonc/toml for DO bindings and migrations\n- Writing tests with `@cloudflare/vitest-pool-workers`\n- Designing sharding strategies and parent-child relationships\n\n## Reference Documentation\n\n- `./references/rules.md` - Core rules, storage, concurrency, RPC, alarms\n- `./references/testing.md` - Vitest setup, unit/integration tests, alarm testing\n- `./references/workers.md` - Workers handlers, types, wrangler config, observability\n\nSearch: `blockConcurrencyWhile`, `idFromName`, `getByName`, `setAlarm`, `sql.exec`\n\n## Core Principles\n\n### Use Durable Objects For\n\n| Need | Example |\n|------|---------|\n| Coordination | Chat rooms, multiplayer games, collaborative docs |\n| Strong consistency | Inventory, booking systems, turn-based games |\n| Per-entity storage | Multi-tenant SaaS, per-user data |\n| Persistent connections | WebSockets, real-time notifications |\n| Scheduled work per entity | Subscription renewals, game timeouts |\n\n### Do NOT Use For\n\n- Stateless request handling (use plain Workers)\n- Maximum global distribution needs\n- High fan-out independent requests\n\n## Quick Reference\n\n### Wrangler Configuration\n\n```jsonc\n// wrangler.jsonc\n{\n  \"durable_objects\": {\n    \"bindings\": [{ \"name\": \"MY_DO\", \"class_name\": \"MyDurableObject\" }]\n  },\n  \"migrations\": [{ \"tag\": \"v1\", \"new_sqlite_classes\": [\"MyDurableObject\"] }]\n}\n```\n\n### Basic Durable Object Pattern\n\n```typescript\nimport { DurableObject } from \"cloudflare:workers\";\n\nexport interface Env {\n  MY_DO: DurableObjectNamespace<MyDurableObject>;\n}\n\nexport class MyDurableObject extends DurableObject<Env> {\n  constructor(ctx: DurableObjectState, env: Env) {\n    super(ctx, env);\n    ctx.blockConcurrencyWhile(async () => {\n      this.ctx.storage.sql.exec(`\n        CREATE TABLE IF NOT EXISTS items (\n          id INTEGER PRIMARY KEY AUTOINCREMENT,\n          data TEXT NOT NULL\n        )\n      `);\n    });\n  }\n\n  async addItem(data: string): Promise<number> {\n    const result = this.ctx.storage.sql.exec<{ id: number }>(\n      \"INSERT INTO items (data) VALUES (?) RETURNING id\",\n      data\n    );\n    return result.one().id;\n  }\n}\n\nexport default {\n  async fetch(request: Request, env: Env): Promise<Response> {\n    const stub = env.MY_DO.getByName(\"my-instance\");\n    const id = await stub.addItem(\"hello\");\n    return Response.json({ id });\n  },\n};\n```\n\n## Critical Rules\n\n1. **Model around coordination atoms** - One DO per chat room/game/user, not one global DO\n2. **Use `getByName()` for deterministic routing** - Same input = same DO instance\n3. **Use SQLite storage** - Configure `new_sqlite_classes` in migrations\n4. **Initialize in constructor** - Use `blockConcurrencyWhile()` for schema setup only\n5. **Use RPC methods** - Not fetch() handler (compatibility date >= 2024-04-03)\n6. **Persist first, cache second** - Always write to storage before updating in-memory state\n7. **One alarm per DO** - `setAlarm()` replaces any existing alarm\n\n## Anti-Patterns (NEVER)\n\n- Single global DO handling all requests (bottleneck)\n- Using `blockConcurrencyWhile()` on every request (kills throughput)\n- Storing critical state only in memory (lost on eviction/crash)\n- Using `await` between related storage writes (breaks atomicity)\n- Holding `blockConcurrencyWhile()` across `fetch()` or external I/O\n\n## Stub Creation\n\n```typescript\n// Deterministic - preferred for most cases\nconst stub = env.MY_DO.getByName(\"room-123\");\n\n// From existing ID string\nconst id = env.MY_DO.idFromString(storedIdString);\nconst stub = env.MY_DO.get(id);\n\n// New unique ID - store mapping externally\nconst id = env.MY_DO.newUniqueId();\nconst stub = env.MY_DO.get(id);\n```\n\n## Storage Operations\n\n```typescript\n// SQL (synchronous, recommended)\nthis.ctx.storage.sql.exec(\"INSERT INTO t (c) VALUES (?)\", value);\nconst rows = this.ctx.storage.sql.exec<Row>(\"SELECT * FROM t\").toArray();\n\n// KV (async)\nawait this.ctx.storage.put(\"key\", value);\nconst val = await this.ctx.storage.get<Type>(\"key\");\n```\n\n## Alarms\n\n```typescript\n// Schedule (replaces existing)\nawait this.ctx.storage.setAlarm(Date.now() + 60_000);\n\n// Handler\nasync alarm(): Promise<void> {\n  // Process scheduled work\n  // Optionally reschedule: await this.ctx.storage.setAlarm(...)\n}\n\n// Cancel\nawait this.ctx.storage.deleteAlarm();\n```\n\n## Testing Quick Start\n\n```typescript\nimport { env } from \"cloudflare:test\";\nimport { describe, it, expect } from \"vitest\";\n\ndescribe(\"MyDO\", () => {\n  it(\"should work\", async () => {\n    const stub = env.MY_DO.getByName(\"test\");\n    const result = await stub.addItem(\"test\");\n    expect(result).toBe(1);\n  });\n});\n```\n"},"category":"official","lastSynced":"2026-03-06T05:55:47.072Z","seo":{"title":{"en":"Durable-Objects: Setup Guide for AI Agents | Cloudflare Edge","zh":"Durable Objects入门指南 - Cloudflare AIエージェント","ja":"Durable Objectsの設定方法 - Cloudflare AIエージェント","ko":"Durable Objects 설정 가이드 - Cloudflare AI 도구","es":"Guía de configuración de Durable Objects para aplicacione...","fr":"Guide de mise en place des objets durables pour applicati...","de":"Einrichtungsleitfaden für Durable Objects in stateful Anw..."},"description":{"en":"Learn how to create and review Cloudflare Durable Objects with our expert AI agent skill. Get started with stateful coordination and Workers integration today!","zh":"使用Durable Objects构建有状态的协调应用，实现RPC方法、SQLite存储和WebSockets等功能","ja":"Durable Objectsを使用して状態fulな協調アプリケーションを構築し、RPCメソッド、SQLiteストレージ、WebSocketsなどを実現する","ko":"Durable Objects를 사용하여 상태가 있는 협調 애플리케이션을 구축하고 RPC 메서드, SQLite 저장소, WebSockets 등을 구현합니다","es":"Aprende a crear y revisar objetos durables de Cloudflare para aplicaciones estatales y coordina las acciones con Workers y WebSockets","fr":"Découvrez comment créer et examiner des objets durables Cloudflare pour des applications coordonnées et intégrer les Workers et WebSockets","de":"Erfahren Sie, wie Sie Durable Objects von Cloudflare für stateful Anwendungen erstellen und überprüfen und Workers sowie WebSockets integrieren"},"definition":{"en":"Durable-objects is a Cloudflare feature for building stateful, coordinated applications on the edge, using APIs and configuration for tasks like chat rooms and multiplayer games.","zh":"Durable Objects是一种Cloudflare服务，用于构建有状态的协调应用","ja":"Durable Objectsは、状態fulな協調アプリケーションを構築するためのCloudflareサービスです","ko":"Durable Objects는 상태가 있는 협調 애플리케이션을 구축하는 데 사용되는 Cloudflare 서비스입니다","es":"Durable Objects es un servicio de Cloudflare que permite la creación de aplicaciones estatales y coordina las acciones","fr":"Les objets durables sont un service Cloudflare qui permet de créer des applications coordonnées","de":"Durable Objects ist ein Cloudflare-Dienst, der die Erstellung von stateful Anwendungen ermöglicht"},"features":{"en":["Builds stateful coordination applications like chat rooms and multiplayer games","Supports Workers integration for edge computing","Configures wrangler for efficient deployment","Tests applications with Vitest for reliability","Implements RPC methods for remote communication","Utilizes SQLite storage for data management"],"zh":["构建有状态的协调应用","实现RPC方法和SQLite存储","支持WebSockets和alarms","与Cloudflare Workers集成","使用Vitest进行测试"],"ja":["状態fulな協調アプリケーションの構築","RPCメソッドとSQLiteストレージの実現","WebSocketsとalarmsのサポート","Cloudflare Workersとの統合","Vitestを使用したテスト"],"ko":["상태가 있는 협調 애플리케이션 구축","RPC 메서드와 SQLite 저장소 구현","WebSockets와 알람 지원","Cloudflare Workers와의 통합","Vitest를 사용한 테스트"],"es":["Integración con Workers","Configuración de Wrangler","Almacenamiento de SQLite","Uso de WebSockets","Implementación de métodos RPC","Uso de alarmas"],"fr":["Intégration avec les Workers","Configuration de Wrangler","Stockage SQLite","Utilisation de WebSockets","Mise en œuvre de méthodes RPC","Utilisation d''alarmes"],"de":["Integration mit Workers","Wrangler-Konfiguration","SQLite-Speicher","Verwendung von WebSockets","Implementierung von RPC-Methoden","Verwendung von Alarmen"]},"keywords":{"en":["how to use durable-objects","what is durable-objects","durable-objects alternative","durable-objects vs cloud storage","durable-objects install guide","durable-objects setup for AI agents","cloudflare durable objects tutorial","durable objects rpc methods","durable objects sqlite storage"],"zh":["Durable Objects","Cloudflare","有状态的协调应用","RPC方法","SQLite存储","WebSockets","alarms","Cloudflare Workers","Vitest"],"ja":["Durable Objects","Cloudflare","状態fulな協調アプリケーション","RPCメソッド","SQLiteストレージ","WebSockets","alarms","Cloudflare Workers","Vitest"],"ko":["Durable Objects","Cloudflare","상태가 있는 협조 애플리케이션","RPC 메서드","SQLite 저장소","WebSockets","알람","Cloudflare Workers","Vitest"],"es":["Durable Objects","Cloudflare","Workers","WebSockets","SQLite","RPC","alarmas","desarrollo de aplicaciones estatales","coordenación de aplicaciones"],"fr":["Objets durables","Cloudflare","Workers","WebSockets","SQLite","RPC","alarmes","développement d''applications coordonnées","coordination d''applications"],"de":["Durable Objects","Cloudflare","Workers","WebSockets","SQLite","RPC","Alarmen","Entwicklung von stateful Anwendungen","Koordination von Anwendungen"]}},"agentAnalysis":{"suitability":{"en":"Essential for Cloudflare Workers Agents building stateful, coordinated applications on the edge.","zh":"对于构建基于边缘的有状态协调应用程序的Cloudflare Workers代理至关重要。","ja":"エッジ上でステートフルで協調的なアプリケーションを構築するCloudflare Workersエージェントに不可欠です。","ko":"에지에서 상태 저장 및 조정 가능한 애플리케이션을 구축하는 Cloudflare Workers 에이전트에 필수적입니다.","es":"Esencial para los agentes de Cloudflare Workers que construyen aplicaciones con estado y coordinadas en el edge.","fr":"Essentiel pour les agents Cloudflare Workers qui construisent des applications avec état et coordonnées à la périphérie (edge).","de":"Essenziell für Cloudflare Workers Agents, die zustandsbehaftete, koordinierte Anwendungen am Edge erstellen.","pt":"Essencial para Agentes Cloudflare Workers que constroem aplicações stateful e coordenadas na edge.","ru":"Необходимо для агентов Cloudflare Workers, создающих stateful, скоординированные приложения на грани сети (edge).","ar":"أساسي لوكلاء Cloudflare Workers الذين يقومون ببناء تطبيقات حالة (stateful) ومنسقة على الحافة (edge)."},"recommendation":{"en":"Enables agents to create and manage stateful coordination systems like chat rooms, multiplayer games, and booking systems using Durable Objects'' RPC methods, SQLite storage, alarms, and WebSocket integrations. Provides direct access to current Cloudflare Workers configurations, Wrangler setup, and Vitest testing protocols.","zh":"使代理能够使用Durable Objects的RPC方法、SQLite存储、警报和WebSocket集成，创建和管理聊天室、多人游戏和预订系统等有状态协调系统。提供对当前Cloudflare Workers配置、Wrangler设置和Vitest测试协议的直接访问。","ja":"Durable ObjectsのRPCメソッド、SQLiteストレージ、アラーム、WebSocket統合を使用して、チャットルーム、マルチプレイヤーゲーム、予約システムなどのステートフルな協調システムをエージェントが作成および管理できるようにします。現在のCloudflare Workers設定、Wranglerセットアップ、Vitestテストプロトコルへの直接アクセスを提供します。","ko":"Durable Objects의 RPC 메서드, SQLite 스토리지, 알람 및 WebSocket 통합을 사용하여 채팅방, 멀티플레이어 게임 및 예약 시스템과 같은 상태 저장 조정 시스템을 생성하고 관리할 수 있도록 합니다. 현재 Cloudflare Workers 구성, Wrangler 설정 및 Vitest 테스트 프로토콜에 대한 직접 액세스를 제공합니다.","es":"Permite a los agentes crear y gestionar sistemas de coordinación con estado, como salas de chat, juegos multijugador y sistemas de reservas, utilizando los métodos RPC de Durable Objects, el almacenamiento SQLite, las alarmas y las integraciones WebSocket. Proporciona acceso directo a las configuraciones actuales de Cloudflare Workers, la configuración de Wrangler y los protocolos de prueba de Vitest.","fr":"Permet aux agents de créer et de gérer des systèmes de coordination avec état, tels que des salons de discussion, des jeux multijoueur et des systèmes de réservation, en utilisant les méthodes RPC de Durable Objects, le stockage SQLite, les alarmes et les intégrations WebSocket. Fournit un accès direct aux configurations actuelles de Cloudflare Workers, à la configuration de Wrangler et aux protocoles de test Vitest.","de":"Ermöglicht es Agents, zustandsbehaftete Koordinierungssysteme wie Chaträume, Multiplayer-Spiele und Buchungssysteme unter Verwendung der RPC-Methoden von Durable Objects, SQLite-Speicher, Alarmen und WebSocket-Integrationen zu erstellen und zu verwalten. Bietet direkten Zugriff auf aktuelle Cloudflare Workers-Konfigurationen, Wrangler-Setup und Vitest-Testprotokolle.","pt":"Permite que os agentes criem e gerenciem sistemas de coordenação stateful como salas de chat, jogos multiplayer e sistemas de reserva usando os métodos RPC dos Durable Objects, armazenamento SQLite, alarms e integrações WebSocket. Fornece acesso direto às configurações atuais do Cloudflare Workers, configuração do Wrangler e protocolos de teste do Vitest.","ru":"Позволяет агентам создавать и управлять stateful системами координации, такими как чат-комнаты, многопользовательские игры и системы бронирования, используя RPC-методы Durable Objects, хранилище SQLite, alarms и интеграции WebSocket. Обеспечивает прямой доступ к текущим конфигурациям Cloudflare Workers, настройке Wrangler и протоколам тестирования Vitest.","ar":"يمكن الوكلاء من إنشاء وإدارة أنظمة تنسيق حالة (stateful) مثل غرف الدردشة والألعاب متعددة اللاعبين وأنظمة الحجز باستخدام طرق RPC الخاصة بـ Durable Objects، وتخزين SQLite، والإنذارات (alarms)، وتكاملات WebSocket. يوفر وصولاً مباشراً إلى تكوينات Cloudflare Workers الحالية، وإعداد Wrangler، وبروتوكولات اختبار Vitest."},"useCases":{"en":["Implementing stateful RPC methods for edge coordination","Configuring SQLite storage within Durable Objects","Setting up WebSocket connections for real-time applications","Creating and managing alarms for timed operations","Reviewing Durable Object code for Cloudflare best practices"],"zh":["为边缘协调实现有状态RPC方法","在Durable Objects内配置SQLite存储","为实时应用程序设置WebSocket连接","创建和管理定时操作警报","审查Cloudflare最佳实践的Durable Object代码"],"ja":["エッジ協調のためのステートフルRPCメソッドの実装","Durable Objects内でのSQLiteストレージの設定","リアルタイムアプリケーションのためのWebSocket接続の設定","時間指定操作のためのアラームの作成と管理","Cloudflareベストプラクティスに基づくDurable Objectコードのレビュー"],"ko":["에지 조정을 위한 상태 저장 RPC 메서드 구현","Durable Objects 내에서 SQLite 스토리지 구성","실시간 애플리케이션을 위한 WebSocket 연결 설정","시간 지정 작업을 위한 알람 생성 및 관리","Cloudflare 모범 사례에 대한 Durable Object 코드 검토"],"es":["Implementación de métodos RPC con estado para la coordinación en el edge","Configuración del almacenamiento SQLite dentro de Durable Objects","Configuración de conexiones WebSocket para aplicaciones en tiempo real","Creación y gestión de alarmas para operaciones temporizadas","Revisión del código de Durable Object para las mejores prácticas de Cloudflare"],"fr":["Mise en œuvre de méthodes RPC avec état pour la coordination à la périphérie (edge)","Configuration du stockage SQLite dans les Durable Objects","Configuration des connexions WebSocket pour les applications en temps réel","Création et gestion d''alarmes pour les opérations temporisées","Revue du code Durable Object pour les meilleures pratiques Cloudflare"],"de":["Implementierung zustandsbehafteter RPC-Methoden für die Edge-Koordinierung","Konfigurierung des SQLite-Speichers innerhalb von Durable Objects","Einrichtung von WebSocket-Verbindungen für Echtzeitanwendungen","Erstellung und Verwaltung von Alarmen für zeitgesteuerte Operationen","Überprüfung des Durable Object-Codes auf Cloudflare-Best Practices"],"pt":["Implementação de métodos RPC stateful para coordenação na edge","Configuração de armazenamento SQLite dentro de Durable Objects","Configuração de conexões WebSocket para aplicações em tempo real","Criação e gerenciamento de alarms para operações temporizadas","Revisão de código Durable Object para as melhores práticas da Cloudflare"],"ru":["Реализация stateful RPC-методов для координации на грани сети (edge)","Настройка хранилища SQLite в Durable Objects","Настройка подключений WebSocket для приложений реального времени","Создание и управление alarms для операций по времени","Проверка кода Durable Object на соответствие лучшим практикам Cloudflare"],"ar":["تنفيذ طرق RPC حالة (stateful) للتنسيق على الحافة (edge)","تكوين تخزين SQLite داخل Durable Objects","إعداد اتصالات WebSocket للتطبيقات في الوقت الفعلي","إنشاء وإدارة الإنذارات (alarms) للعمليات الموقوتة","مراجعة كود Durable Object لاتباع أفضل الممارسات لدى Cloudflare"]},"limitations":{"en":["Requires retrieval from Cloudflare documentation for current API specs","Dependent on Cloudflare Workers ecosystem integration","Limited to Cloudflare''s Durable Objects implementation"],"zh":["需要从Cloudflare文档中检索当前API规范","依赖于Cloudflare Workers生态系统集成","仅限于Cloudflare的Durable Objects实现"],"ja":["現在のAPI仕様についてはCloudflareドキュメントからの取得が必要","Cloudflare Workersエコシステム統合に依存","CloudflareのDurable Objects実装に限定"],"ko":["현재 API 사양을 위해 Cloudflare 문서에서 검색 필요","Cloudflare Workers 생태계 통합에 종속","Cloudflare의 Durable Objects 구현으로 제한"],"es":["Requiere la recuperación de la documentación de Cloudflare para las especificaciones actuales de la API","Dependiente de la integración con el ecosistema de Cloudflare Workers","Limitado a la implementación de Durable Objects de Cloudflare"],"fr":["Nécessite la récupération de la documentation Cloudflare pour les spécifications d''API actuelles","Dépend de l''intégration de l''écosystème Cloudflare Workers","Limité à l''implémentation des Durable Objects de Cloudflare"],"de":["Erfordert das Nachschlagen in der Cloudflare-Dokumentation für aktuelle API-Spezifikationen","Abhängig von der Integration in das Cloudflare Workers-Ökosystem","Beschränkt auf die Implementierung von Durable Objects durch Cloudflare"],"pt":["Requer recuperação da documentação da Cloudflare para as especificações atuais da API","Dependente da integração com o ecossistema do Cloudflare Workers","Limitado à implementação de Durable Objects da Cloudflare"],"ru":["Требуется обращение к документации Cloudflare для получения актуальных спецификаций API","Зависит от интеграции с экосистемой Cloudflare Workers","Ограничено реализацией Durable Objects от Cloudflare"],"ar":["يتطلب الرجوع إلى وثائق Cloudflare للحصول على مواصفات API الحالية","يعتمد على التكامل مع نظام Cloudflare Workers البيئي","مقتصر على تنفيذ Cloudflare لـ Durable Objects"]},"version":4},"contentHash":"cd6797cb18f3ae8f721dfd2e5cb27b73a0aa8636683f1a38163dab2fd51a8dfb","repoEtag":"W/\"295e4fcdb92b56b41ac51b00a34c693d22b101994424f954c0d419002c1abf71\"","qualityScore":89}');
