INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cloudflare/skills/durable-objects', 'durable-objects', 'cloudflare', 'skills', 'official', 'durable-objects cloudflare skills official agents cloudflare skills workers The durable-objects skill enables developers to build stateful, coordinated applications on Cloudflare''s edge. It supports Workers integration, wrangler config, and testing with Vitest. Durable Objects是Cloudflare的边缘计算服务，用于构建有状态的协调应用 Durable ObjectsはCloudflareのエッジコンピューティングサービスであり、状態fulな協調アプリケーションを構築するために使用されます Durable Objects는 Cloudflare의 에지 컴퓨팅 서비스로 상태가 있는 협調 애플리케이션을 구축하는 데 사용됩니다 Durable Objects es una tecnología de Cloudflare que permite crear aplicaciones estatales y coordina las acciones con Workers y WebSockets. Les objets durables sont une technologie Cloudflare qui permet de créer des applications coordonnées et d''intégrer les Workers et WebSockets. Durable Objects ist eine Cloudflare-Technologie, die die Erstellung von stateful Anwendungen ermöglicht und Workers sowie WebSockets integriert. how to use durable-objects what is durable-objects durable-objects alternative durable-objects vs cloud storage durable-objects install guide durable-objects setup for AI agents cloudflare durable objects tutorial durable objects rpc methods durable objects sqlite storage Durable Objects Cloudflare 有状态的协调应用 RPC方法 SQLite存储 WebSockets alarms Cloudflare Workers Vitest Builds stateful coordination applications like chat rooms and multiplayer games Supports Workers integration for edge computing Configures wrangler for efficient deployment Tests applications with Vitest for reliability Implements RPC methods for remote communication Utilizes SQLite storage for data management Durable-objects is a Cloudflare feature for building stateful, coordinated applications on the edge, using APIs and configuration for tasks like chat rooms and multiplayer games.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/verification-loop', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'verification-loop', 61988, 7678, 89, '2026-03-06T03:39:20Z', '2026-03-06T04:45:09.383Z', '01a9ae310ad4426bb05660dda6cefdeaac9513417585c09c8bb1b94738649a78', '{"id":"affaan-m/everything-claude-code/verification-loop","name":"verification-loop","description":{"en":"The verification-loop skill provides a comprehensive verification system for Claude Code sessions, benefiting developers by ensuring quality gates pass and code integrity. It''s ideal for use after completing features, creating PRs, or refactoring.","es":"Verification Loop es un sistema de verificación integral para sesiones de Claude Code, que garantiza la calidad del código a través de varias fases de verificación","fr":"La boucle de vérification est un système de vérification complet pour les sessions Claude Code, qui assure la qualité du code à travers plusieurs phases de vérification","de":"Die Verification Loop ist ein umfassendes Verifizierungssystem für Claude-Code-Sitzungen, das die Code-Qualität durch mehrere Verifizierungsphasen gewährleistet","pt":"O Verification-Loop é um sistema de verificação abrangente para sessões de Claude Code, garantindo a qualidade do código","ru":"Verification-Loop - это комплексная система верификации для сессий Claude Code, обеспечивающая качество кода","ar":"Verification-Loop هو نظام التحقق الشامل للجلسات Claude Code، يضمن جودة الكود"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"verification-loop","description":"A comprehensive verification system for Claude Code sessions.","bodyPreview":"# Verification Loop Skill\n\nA comprehensive verification system for Claude Code sessions.\n\n## When to Use\n\nInvoke this skill:\n- After completing a feature or significant code change\n- Before creating a PR\n- When you want to ensure quality gates pass\n- After refactoring\n\n## Verification Phases\n\n### Phase 1: Build Verification\n```bash\n# Check if project builds\nnpm run build 2>&1 | tail -20\n# OR\npnpm build 2>&1 | tail -20\n```\n\nIf build fails, STOP and fix before continuing.\n\n### Phase 2: Type Check","body":"# Verification Loop Skill\n\nA comprehensive verification system for Claude Code sessions.\n\n## When to Use\n\nInvoke this skill:\n- After completing a feature or significant code change\n- Before creating a PR\n- When you want to ensure quality gates pass\n- After refactoring\n\n## Verification Phases\n\n### Phase 1: Build Verification\n```bash\n# Check if project builds\nnpm run build 2>&1 | tail -20\n# OR\npnpm build 2>&1 | tail -20\n```\n\nIf build fails, STOP and fix before continuing.\n\n### Phase 2: Type Check\n```bash\n# TypeScript projects\nnpx tsc --noEmit 2>&1 | head -30\n\n# Python projects\npyright . 2>&1 | head -30\n```\n\nReport all type errors. Fix critical ones before continuing.\n\n### Phase 3: Lint Check\n```bash\n# JavaScript/TypeScript\nnpm run lint 2>&1 | head -30\n\n# Python\nruff check . 2>&1 | head -30\n```\n\n### Phase 4: Test Suite\n```bash\n# Run tests with coverage\nnpm run test -- --coverage 2>&1 | tail -50\n\n# Check coverage threshold\n# Target: 80% minimum\n```\n\nReport:\n- Total tests: X\n- Passed: X\n- Failed: X\n- Coverage: X%\n\n### Phase 5: Security Scan\n```bash\n# Check for secrets\ngrep -rn \"sk-\" --include=\"*.ts\" --include=\"*.js\" . 2>/dev/null | head -10\ngrep -rn \"api_key\" --include=\"*.ts\" --include=\"*.js\" . 2>/dev/null | head -10\n\n# Check for console.log\ngrep -rn \"console.log\" --include=\"*.ts\" --include=\"*.tsx\" src/ 2>/dev/null | head -10\n```\n\n### Phase 6: Diff Review\n```bash\n# Show what changed\ngit diff --stat\ngit diff HEAD~1 --name-only\n```\n\nReview each changed file for:\n- Unintended changes\n- Missing error handling\n- Potential edge cases\n\n## Output Format\n\nAfter running all phases, produce a verification report:\n\n```\nVERIFICATION REPORT\n==================\n\nBuild:     [PASS/FAIL]\nTypes:     [PASS/FAIL] (X errors)\nLint:      [PASS/FAIL] (X warnings)\nTests:     [PASS/FAIL] (X/Y passed, Z% coverage)\nSecurity:  [PASS/FAIL] (X issues)\nDiff:      [X files changed]\n\nOverall:   [READY/NOT READY] for PR\n\nIssues to Fix:\n1. ...\n2. ...\n```\n\n## Continuous Mode\n\nFor long sessions, run verification every 15 minutes or after major changes:\n\n```markdown\nSet a mental checkpoint:\n- After completing each function\n- After finishing a component\n- Before moving to next task\n\nRun: /verify\n```\n\n## Integration with Hooks\n\nThis skill complements PostToolUse hooks but provides deeper verification.\nHooks catch issues immediately; this skill provides comprehensive review.\n"},"category":"official","lastSynced":"2026-03-06T04:45:09.383Z","seo":{"title":{"en":"Verification-Loop: Comprehensive Code Verification Setup ...","es":"Guía de configuración de Verification Loop para Claude Code","fr":"Guide de mise en place de la boucle de vérification pour ...","de":"Einrichtungsleitfaden für Verification Loop in Claude Code","pt":"Guia de Configuração do Verification-Loop para Desenvolve...","ru":"ИИ Агенты: Руководство по Настройке Verification-Loop","ar":"دليل إعداد Verification-Loop لأدوات الذكاء الاصطناعي"},"description":{"en":"Boost code quality with verification-loop! Learn how to invoke this skill for efficient code verification and ensure quality gates pass. Get started now!","es":"Aprende a implementar la boucle de vérification en tus sesiones de Claude Code para asegurar la calidad del código","fr":"Découvrez comment mettre en place la boucle de vérification dans vos sessions Claude Code pour garantir la qualité du code","de":"Erfahren Sie, wie Sie die Verification Loop in Ihren Claude-Code-Sitzungen implementieren, um die Code-Qualität zu gewährleisten","pt":"Aprenda a configurar o Verification-Loop para melhorar a qualidade do código e aumentar a produtividade dos desenvolvedores","ru":"Узнайте, как настроить Verification-Loop для повышения качества кода и продуктивности разработчиков","ar":"تعرف على كيفية إعداد Verification-Loop لتحسين جودة الكود وزيادة إنتاجية المطورين"},"definition":{"en":"verification-loop is a comprehensive verification system for Claude Code sessions, comprising build verification and type checking phases to ensure code quality and integrity.","es":"La Verification Loop es una herramienta de desarrollo que verifica la calidad del código en varias fases","fr":"La boucle de vérification est un outil de développement qui vérifie la qualité du code en plusieurs phases","de":"Die Verification Loop ist ein Entwicklungstool, das die Code-Qualität in mehreren Phasen überprüft","pt":"O que é Verification-Loop? Um sistema de verificação para garantir a qualidade do código em sessões de Claude Code","ru":"Что такое Verification-Loop? Система верификации для обеспечения качества кода в сессиях Claude Code","ar":"ما هو Verification-Loop؟ نظام تحقق لضمان جودة الكود في جلسات Claude Code"},"features":{"en":["Performs build verification using npm run build or pnpm build commands","Executes type checking in Phase 2 to ensure code accuracy","Supports invocation after completing features or significant code changes","Integrates with Claude Code sessions for seamless verification","Includes a stop-and-fix approach if build fails, ensuring quality gates pass"],"es":["Verificación de compilación con npm o pnpm","Verificación de tipos en varias fases","Integración con Claude Code para asegurar la calidad del código","Soporte para la creación de solicitudes de cambios de código de alta calidad","Verificación automática en varias fases del ciclo de desarrollo"],"fr":["Vérification de la construction avec npm ou pnpm","Vérification des types dans plusieurs phases","Intégration avec Claude Code pour assurer la qualité du code","Prise en charge de la création de demandes de modification de code de haute qualité","Vérification automatique dans plusieurs phases du cycle de développement"],"de":["Build-Verifizierung mit npm oder pnpm","Typverifizierung in mehreren Phasen","Integration mit Claude Code zur Gewährleistung der Code-Qualität","Unterstützung für die Erstellung von Code-Änderungsanfragen hoher Qualität","Automatische Verifizierung in mehreren Phasen des Entwicklungszyklus"],"pt":["Verificação de compilação do projeto com npm ou pnpm","Verificação de tipos para garantir a qualidade do código","Integração com Claude Code para melhorar a produtividade","Fases de verificação para garantir a qualidade do código","Suporte a desenvolvedores para melhorar a qualidade do código"],"ru":["Проверка сборки проекта с помощью npm или pnpm","Проверка типов для обеспечения качества кода","Интеграция с Claude Code для повышения продуктивности","Фазы верификации для обеспечения качества кода","Поддержка разработчиков для улучшения качества кода"],"ar":["التحقق من بناء المشروع باستخدام npm أو pnpm","التحقق من الأنواع لضمان جودة الكود","التكامل مع Claude Code لتحسين الإنتاجية","مراحل التحقق لضمان جودة الكود","دعم المطورين لتحسين جودة الكود"]},"keywords":{"en":["how to use verification-loop","verification-loop setup guide","what is verification-loop","verification-loop alternative","verification-loop vs MCP","install verification-loop","verification-loop for AI agents","Claude Code verification","npm build verification","pnpm build verification"],"es":["herramientas de desarrollo de AI","verification loop","claude code","npm","pnpm","verificación de tipos","creación de solicitudes de cambios de código","desarrollo de software","calidad del código"],"fr":["outils de développement d''IA","boucle de vérification","claude code","npm","pnpm","vérification des types","création de demandes de modification de code","développement de logiciels","qualité du code"],"de":["AI-Entwicklungstools","verification loop","claude code","npm","pnpm","typverifizierung","erstellung von code-änderungsanfragen","softwareentwicklung","code-qualität"],"pt":["verification-loop","claude code","desenvolvedores","qualidade do código","produtividade","npm","pnpm","verificação de tipos","integração com claude code"],"ru":["verification-loop","claude code","разработчики","качество кода","продуктивность","npm","pnpm","проверка типов","интеграция с claude code"],"ar":["verification-loop","claude code","مطورون","جودة الكود","إنتاجية","npm","pnpm","التحقق من الأنواع","التكامل مع claude code"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Code Quality Assurance Agents needing automated build and test verification workflows.","zh":"非常适合需要自动化构建和测试验证工作流程的代码质量保证Agent。","ja":"自動化されたビルドおよびテスト検証ワークフローを必要とするコード品質保証エージェントに最適です。","ko":"자동화된 빌드 및 테스트 검증 워크플로우가 필요한 코드 품질 보증 에이전트에 완벽합니다.","es":"Perfecto para Agentes de Garantía de Calidad de Código que necesitan flujos de trabajo de verificación de compilación y prueba automatizados.","fr":"Parfait pour les Agents d''Assurance de la Qualité de Code nécessitant des flux de travail de vérification de construction et de test automatisés.","de":"Perfekt für Code-Qualitäts-Sicherheitsagenten, die automatisierte Build- und Test-Verifizierungs-Workflows benötigen.","pt":"Perfeito para Agentes de Garantia de Qualidade de Código que necessitam de fluxos de trabalho de verificação de compilação e teste automatizados.","ru":"Идеально подходит для агентов обеспечения качества кода, которым необходимы автоматизированные рабочие процессы проверки сборки и тестирования.","ar":"مثالي لعمليات ضمان جودة الشفرة التي تحتاج إلى عمليات تحقق بناء وتحقق اختبار آلية."},"recommendation":{"en":"Provides comprehensive quality gate enforcement through phased verification including build checks, type validation, and test execution. It enables automated code quality assessment using npm/pnpm build systems and type checking tools.","zh":"通过包括构建检查、类型验证和测试执行在内的分阶段验证，提供全面的质量门禁强制执行。它支持使用 npm/pnpm 构建系统和类型检查工具进行自动化的代码质量评估。","ja":"ビルドチェック、型検証、テスト実行を含む段階的な検証を通じて、包括的な品質ゲートの適用を提供します。npm/pnpm ビルドシステムと型チェックツールを使用した自動化されたコード品質評価を可能にします。","ko":"빌드 검사, 타입 검증 및 테스트 실행을 포함하는 단계적 검증을 통해 포괄적인 품질 게이트 적용을 제공합니다. npm/pnpm 빌드 시스템 및 타입 검사 도구를 사용한 자동화된 코드 품질 평가를 가능하게 합니다.","es":"Proporciona una aplicación integral de la verificación de la calidad a través de la verificación por fases, que incluye verificaciones de compilación, validación de tipos y ejecución de pruebas. Permite la evaluación automática de la calidad del código utilizando sistemas de compilación npm/pnpm y herramientas de verificación de tipos.","fr":"Fournit une application complète de la vérification de la qualité à travers une vérification par phases, y compris des vérifications de construction, une validation de types et une exécution de tests. Elle permet l''évaluation automatique de la qualité du code en utilisant des systèmes de construction npm/pnpm et des outils de vérification de types.","de":"Bietet eine umfassende Durchsetzung der Qualitätskontrolle durch phasenweise Überprüfung, einschließlich Build-Checks, Typvalidierung und Testausführung. Es ermöglicht die automatisierte Bewertung der Codequalität unter Verwendung von npm/pnpm-Build-Systemen und Typprüfungstools.","pt":"Fornece aplicação abrangente de portão de qualidade por meio de verificação faseada, incluindo verificações de compilação, validação de tipo e execução de testes. Ele permite a avaliação automatizada da qualidade do código usando sistemas de compilação npm/pnpm e ferramentas de verificação de tipo.","ru":"Предоставляет всестороннюю реализацию контроля качества через фазированную проверку, включая проверки сборки, валидацию типов и выполнение тестов. Он позволяет выполнять автоматическую оценку качества кода с использованием систем сборки npm/pnpm и инструментов проверки типов.","ar":"يوفر تطبيقًا شاملاً لتنفيذ بوابة الجودة من خلال التحقق المرحلي بما في ذلك فحص البناء والتحقق من نوع والتشغيل التلقائي لاختبارات. يتيح التقييم الآلي لجودة الشفرة باستخدام أنظمة البناء npm/pnpm وأدوات التحقق من النوع."},"useCases":{"en":["Automating pre-PR quality checks","Verifying build integrity after refactoring","Running comprehensive test suites before deployment","Validating type safety in TypeScript projects"],"zh":["自动化PR前的质量检查","重构后验证构建完整性","部署前运行全面的测试套件","验证TypeScript项目中的类型安全性"],"ja":["PR前の品質チェックの自動化","リファクタリング後のビルド整合性の検証","デプロイ前の包括的なテストスイートの実行","TypeScriptプロジェクトにおける型安全性の検証"],"ko":["PR 전 품질 검사 자동화","리팩토링 후 빌드 무결성 검증","배포 전 포괄적인 테스트 슈트 실행","TypeScript 프로젝트에서 타입 안전성 검증"],"es":["Automatizar las verificaciones de calidad pre-PR","Verificar la integridad de la compilación después de la reestructuración","Ejecutar suites de pruebas integrales antes de la implementación","Validar la seguridad de los tipos en proyectos TypeScript"],"fr":["Automatiser les vérifications de qualité pré-PR","Vérifier l''intégrité de la construction après une réorganisation","Exécuter des suites de tests complètes avant le déploiement","Valider la sécurité des types dans les projets TypeScript"],"de":["Automatisieren von Vor-PR-Qualitätsprüfungen","Überprüfen der Build-Integrität nach Refactoring","Ausführen umfassender Test-Suiten vor der Bereitstellung","Validieren der Typsicherheit in TypeScript-Projekten"],"pt":["Automatizar verificações de qualidade pré-PR","Verificar a integridade da compilação após refatoração","Executar conjuntos de testes abrangentes antes da implantação","Validar a segurança de tipo em projetos TypeScript"],"ru":["Автоматизировать предварительные проверки качества PR","Проверять целостность сборки после рефакторинга","Выполнять комплексные наборы тестов перед развертыванием","Проверять безопасность типов в проектах TypeScript"],"ar":["تأتمت اختبارات الجودة قبل الـPR","التحقق من سلامة البناء بعد إعادة هيكلة الشفرة","تشغيل مجموعات اختبارات شاملة قبل النشر","التحقق من سلامة النوع في مشاريع TypeScript"]},"limitations":{"en":["Requires npm/pnpm project structure","Assumes standard build/test scripts","Limited to CLI-based verification workflows"],"zh":["需要 npm/pnpm 项目结构","假定使用标准的构建/测试脚本","仅限于基于CLI的验证工作流程"],"ja":["npm/pnpmプロジェクト構造が必要","標準的なビルド/テストスクリプトを想定","CLIベースの検証ワークフローに限定"],"ko":["npm/pnpm 프로젝트 구조 필요","표준 빌드/테스트 스크립트를 가정","CLI 기반 검증 워크플로우로 제한됨"],"es":["Requiere estructura de proyecto npm/pnpm","Supone scripts de compilación y prueba estándar","Limitado a flujos de trabajo de verificación basados en CLI"],"fr":["Nécessite une structure de projet npm/pnpm","Suppose des scripts de construction et de test standard","Limité aux flux de travail de vérification basés sur CLI"],"de":["Benötigt npm/pnpm-Projektstruktur","Geht von standardmäßigen Build- und Test-Skripten aus","Begrenzt auf CLI-basierte Überprüfungs-Workflows"],"pt":["Exige estrutura de projeto npm/pnpm","Supõe scripts de compilação/teste padrão","Limitado a fluxos de trabalho de verificação baseados em CLI"],"ru":["Требует структуры проекта npm/pnpm","Предполагает стандартные сценарии сборки/тестирования","Ограничен рабочими процессами проверки на основе CLI"],"ar":["يتطلب هيكل مشروع npm/pnpm","يفترض سيناريوهات بناء/اختبار قياسية","محدود بعمليات التحقق القائمة على واجهة سطر الأوامر"]},"version":4},"contentHash":"01a9ae310ad4426bb05660dda6cefdeaac9513417585c09c8bb1b94738649a78","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":89}');
