INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/verification-loop', 'verification-loop', 'affaan-m', 'everything-claude-code', 'official', 'verification-loop affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The verification-loop skill provides a comprehensive verification system for Claude Code sessions, benefiting developers by ensuring quality gates pass and code integrity. It''s ideal for use after completing features, creating PRs, or refactoring. Verification Loop es un sistema de verificación integral para sesiones de Claude Code, que garantiza la calidad del código a través de varias fases de verificación La boucle de vérification est un système de vérification complet pour les sessions Claude Code, qui assure la qualité du code à travers plusieurs phases de vérification Die Verification Loop ist ein umfassendes Verifizierungssystem für Claude-Code-Sitzungen, das die Code-Qualität durch mehrere Verifizierungsphasen gewährleistet O Verification-Loop é um sistema de verificação abrangente para sessões de Claude Code, garantindo a qualidade do código Verification-Loop - это комплексная система верификации для сессий Claude Code, обеспечивающая качество кода Verification-Loop هو نظام التحقق الشامل للجلسات Claude Code، يضمن جودة الكود how to use verification-loop verification-loop setup guide what is verification-loop verification-loop alternative verification-loop vs MCP install verification-loop verification-loop for AI agents Claude Code verification npm build verification pnpm build verification Performs build verification using npm run build or pnpm build commands Executes type checking in Phase 2 to ensure code accuracy Supports invocation after completing features or significant code changes Integrates with Claude Code sessions for seamless verification Includes a stop-and-fix approach if build fails, ensuring quality gates pass verification-loop is a comprehensive verification system for Claude Code sessions, comprising build verification and type checking phases to ensure code quality and integrity.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/plankton-code-quality', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'plankton-code-quality', 61988, 7678, 89, '2026-03-06T03:39:20Z', '2026-03-06T04:24:23.171Z', 'e75be8a685f21a10c12e137a6500e349c242791c24d98dd118d5c1845f2070c2', '{"id":"affaan-m/everything-claude-code/plankton-code-quality","name":"plankton-code-quality","description":{"en":"Plankton-code-quality is a developer tool that enforces code quality at write-time by running formatters and linters on every file edit through PostToolUse hooks. It automatically spawns Claude subprocesses to fix violations that weren''t caught by initial linting, providing continuous code qualit...","zh":"Plankton代码质量技能在每次文件编辑时通过PostToolUse钩子自动运行格式化程序和linter，并使用Claude子进程修复代理未捕获的违规。提供实时代码质量保障。","ja":"Planktonコード品質スキルはファイル編集のたびにPostToolUseフックでフォーマッタとリンターを実行し、Claudeサブプロセスがエージェントが検出できなかった違反を修正します。","ko":"Plankton 코드 품질 스킬은 모든 파일 편집 시 PostToolUse 훅을 통해 포맷터와 린터를 실행하고 Claude 서브프로세스가 에이전트가 놓친 위반 사항을 수정합니다.","es":"Plankton es un sistema de calidad de código en tiempo de escritura para Claude Code. Ejecuta formateadores y linters en cada edición de archivo mediante hooks PostToolUse y utiliza subprocesos de Claude para corregir violaciones.","fr":"Plankton est un système de qualité de code en temps d''écriture pour Claude Code. Il exécoute des formateurs et linters à chaque modification de fichier via des hooks PostToolUse et utilise des sous-processus Claude pour corriger les violations.","de":"Plankton ist ein Code-Qualitätssystem zur Schreibzeit für Claude Code. Es führt Formatter und Linter bei jedem Datei-Edit via PostToolUse Hooks aus und nutzt Claude Subprozesse zur Behebung von Verstößen.","pt":"O Plankton Code Quality é uma ferramenta de garantia de qualidade de código em tempo de escrita que utiliza auto-formatação, linting e correções do Claude","ru":"Plankton Code Quality — это инструмент обеспечения качества кода в режиме реального времени, использующий форматирование, линтинг и исправления от Claude","ar":"Plankton Code Quality هو أداة لضمان جودة الكود في وقت الكتابة باستخدام التنسيق التلقائي وlinting وتصحيحات من Claude"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"plankton-code-quality","description":"Write-time code quality enforcement using Plankton — auto-formatting, linting, and Claude-powered fixes on every file edit via hooks.","bodyPreview":"# Plankton Code Quality Skill\n\nIntegration reference for Plankton (credit: @alxfazio), a write-time code quality enforcement system for Claude Code. Plankton runs formatters and linters on every file edit via PostToolUse hooks, then spawns Claude subprocesses to fix violations the agent didn''t catch.\n\n## When to Use\n\n- You want automatic formatting and linting on every file edit (not just at commit time)\n- You need defense against agents modifying linter configs to pass instead of fixing code\n-","body":"# Plankton Code Quality Skill\n\nIntegration reference for Plankton (credit: @alxfazio), a write-time code quality enforcement system for Claude Code. Plankton runs formatters and linters on every file edit via PostToolUse hooks, then spawns Claude subprocesses to fix violations the agent didn''t catch.\n\n## When to Use\n\n- You want automatic formatting and linting on every file edit (not just at commit time)\n- You need defense against agents modifying linter configs to pass instead of fixing code\n- You want tiered model routing for fixes (Haiku for simple style, Sonnet for logic, Opus for types)\n- You work with multiple languages (Python, TypeScript, Shell, YAML, JSON, TOML, Markdown, Dockerfile)\n\n## How It Works\n\n### Three-Phase Architecture\n\nEvery time Claude Code edits or writes a file, Plankton''s `multi_linter.sh` PostToolUse hook runs:\n\n```\nPhase 1: Auto-Format (Silent)\n├─ Runs formatters (ruff format, biome, shfmt, taplo, markdownlint)\n├─ Fixes 40-50% of issues silently\n└─ No output to main agent\n\nPhase 2: Collect Violations (JSON)\n├─ Runs linters and collects unfixable violations\n├─ Returns structured JSON: {line, column, code, message, linter}\n└─ Still no output to main agent\n\nPhase 3: Delegate + Verify\n├─ Spawns claude -p subprocess with violations JSON\n├─ Routes to model tier based on violation complexity:\n│   ├─ Haiku: formatting, imports, style (E/W/F codes) — 120s timeout\n│   ├─ Sonnet: complexity, refactoring (C901, PLR codes) — 300s timeout\n│   └─ Opus: type system, deep reasoning (unresolved-attribute) — 600s timeout\n├─ Re-runs Phase 1+2 to verify fixes\n└─ Exit 0 if clean, Exit 2 if violations remain (reported to main agent)\n```\n\n### What the Main Agent Sees\n\n| Scenario | Agent sees | Hook exit |\n|----------|-----------|-----------|\n| No violations | Nothing | 0 |\n| All fixed by subprocess | Nothing | 0 |\n| Violations remain after subprocess | `[hook] N violation(s) remain` | 2 |\n| Advisory (duplicates, old tooling) | `[hook:advisory] ...` | 0 |\n\nThe main agent only sees issues the subprocess couldn''t fix. Most quality problems are resolved transparently.\n\n### Config Protection (Defense Against Rule-Gaming)\n\nLLMs will modify `.ruff.toml` or `biome.json` to disable rules rather than fix code. Plankton blocks this with three layers:\n\n1. **PreToolUse hook** — `protect_linter_configs.sh` blocks edits to all linter configs before they happen\n2. **Stop hook** — `stop_config_guardian.sh` detects config changes via `git diff` at session end\n3. **Protected files list** — `.ruff.toml`, `biome.json`, `.shellcheckrc`, `.yamllint`, `.hadolint.yaml`, and more\n\n### Package Manager Enforcement\n\nA PreToolUse hook on Bash blocks legacy package managers:\n- `pip`, `pip3`, `poetry`, `pipenv` → Blocked (use `uv`)\n- `npm`, `yarn`, `pnpm` → Blocked (use `bun`)\n- Allowed exceptions: `npm audit`, `npm view`, `npm publish`\n\n## Setup\n\n### Quick Start\n\n```bash\n# Clone Plankton into your project (or a shared location)\n# Note: Plankton is by @alxfazio\ngit clone https://github.com/alexfazio/plankton.git\ncd plankton\n\n# Install core dependencies\nbrew install jaq ruff uv\n\n# Install Python linters\nuv sync --all-extras\n\n# Start Claude Code — hooks activate automatically\nclaude\n```\n\nNo install command, no plugin config. The hooks in `.claude/settings.json` are picked up automatically when you run Claude Code in the Plankton directory.\n\n### Per-Project Integration\n\nTo use Plankton hooks in your own project:\n\n1. Copy `.claude/hooks/` directory to your project\n2. Copy `.claude/settings.json` hook configuration\n3. Copy linter config files (`.ruff.toml`, `biome.json`, etc.)\n4. Install the linters for your languages\n\n### Language-Specific Dependencies\n\n| Language | Required | Optional |\n|----------|----------|----------|\n| Python | `ruff`, `uv` | `ty` (types), `vulture` (dead code), `bandit` (security) |\n| TypeScript/JS | `biome` | `oxlint`, `semgrep`, `knip` (dead exports) |\n| Shell | `shellcheck`, `shfmt` | — |\n| YAML | `yamllint` | — |\n| Markdown | `markdownlint-cli2` | — |\n| Dockerfile | `hadolint` (>= 2.12.0) | — |\n| TOML | `taplo` | — |\n| JSON | `jaq` | — |\n\n## Pairing with ECC\n\n### Complementary, Not Overlapping\n\n| Concern | ECC | Plankton |\n|---------|-----|----------|\n| Code quality enforcement | PostToolUse hooks (Prettier, tsc) | PostToolUse hooks (20+ linters + subprocess fixes) |\n| Security scanning | AgentShield, security-reviewer agent | Bandit (Python), Semgrep (TypeScript) |\n| Config protection | — | PreToolUse blocks + Stop hook detection |\n| Package manager | Detection + setup | Enforcement (blocks legacy PMs) |\n| CI integration | — | Pre-commit hooks for git |\n| Model routing | Manual (`/model opus`) | Automatic (violation complexity → tier) |\n\n### Recommended Combination\n\n1. Install ECC as your plugin (agents, skills, commands, rules)\n2. Add Plankton hooks for write-time quality enforcement\n3. Use AgentShield for security audits\n4. Use ECC''s verification-loop as a final gate before PRs\n\n### Avoiding Hook Conflicts\n\nIf running both ECC and Plankton hooks:\n- ECC''s Prettier hook and Plankton''s biome formatter may conflict on JS/TS files\n- Resolution: disable ECC''s Prettier PostToolUse hook when using Plankton (Plankton''s biome is more comprehensive)\n- Both can coexist on different file types (ECC handles what Plankton doesn''t cover)\n\n## Configuration Reference\n\nPlankton''s `.claude/hooks/config.json` controls all behavior:\n\n```json\n{\n  \"languages\": {\n    \"python\": true,\n    \"shell\": true,\n    \"yaml\": true,\n    \"json\": true,\n    \"toml\": true,\n    \"dockerfile\": true,\n    \"markdown\": true,\n    \"typescript\": {\n      \"enabled\": true,\n      \"js_runtime\": \"auto\",\n      \"biome_nursery\": \"warn\",\n      \"semgrep\": true\n    }\n  },\n  \"phases\": {\n    \"auto_format\": true,\n    \"subprocess_delegation\": true\n  },\n  \"subprocess\": {\n    \"tiers\": {\n      \"haiku\":  { \"timeout\": 120, \"max_turns\": 10 },\n      \"sonnet\": { \"timeout\": 300, \"max_turns\": 10 },\n      \"opus\":   { \"timeout\": 600, \"max_turns\": 15 }\n    },\n    \"volume_threshold\": 5\n  }\n}\n```\n\n**Key settings:**\n- Disable languages you don''t use to speed up hooks\n- `volume_threshold` — violations > this count auto-escalate to a higher model tier\n- `subprocess_delegation: false` — skip Phase 3 entirely (just report violations)\n\n## Environment Overrides\n\n| Variable | Purpose |\n|----------|---------|\n| `HOOK_SKIP_SUBPROCESS=1` | Skip Phase 3, report violations directly |\n| `HOOK_SUBPROCESS_TIMEOUT=N` | Override tier timeout |\n| `HOOK_DEBUG_MODEL=1` | Log model selection decisions |\n| `HOOK_SKIP_PM=1` | Bypass package manager enforcement |\n\n## References\n\n- Plankton (credit: @alxfazio)\n- Plankton REFERENCE.md — Full architecture documentation (credit: @alxfazio)\n- Plankton SETUP.md — Detailed installation guide (credit: @alxfazio)\n\n## ECC v1.8 Additions\n\n### Copyable Hook Profile\n\nSet strict quality behavior:\n\n```bash\nexport ECC_HOOK_PROFILE=strict\nexport ECC_QUALITY_GATE_FIX=true\nexport ECC_QUALITY_GATE_STRICT=true\n```\n\n### Language Gate Table\n\n- TypeScript/JavaScript: Biome preferred, Prettier fallback\n- Python: Ruff format/check\n- Go: gofmt\n\n### Config Tamper Guard\n\nDuring quality enforcement, flag changes to config files in same iteration:\n\n- `biome.json`, `.eslintrc*`, `prettier.config*`, `tsconfig.json`, `pyproject.toml`\n\nIf config is changed to suppress violations, require explicit review before merge.\n\n### CI Integration Pattern\n\nUse the same commands in CI as local hooks:\n\n1. run formatter checks\n2. run lint/type checks\n3. fail fast on strict mode\n4. publish remediation summary\n\n### Health Metrics\n\nTrack:\n- edits flagged by gates\n- average remediation time\n- repeat violations by category\n- merge blocks due to gate failures\n"},"category":"official","lastSynced":"2026-03-06T04:24:23.171Z","seo":{"title":{"en":"Plankton Code Quality Skill: Write-Time Code Enforcement ...","zh":"Plankton代码质量技能设置指南：实时AI代码修复","ja":"Planktonコード品質スキル設定ガイド：AIエージェントによる自動修正","ko":"Plankton 코드 품질 스킬 설정 가이드: 실시간 AI 코드 수정","es":"Plankton Code Quality: Guía de Configuración para Agentes IA","fr":"Plankton Code Quality : Guide d''Installation pour Outils IA","de":"Plankton Code Quality: Setup Guide für KI-Agenten Tools","pt":"Guia de Configuração do Plankton Code Quality para Desenv...","ru":"Настройка Plankton Code Quality: Руководство для Разработ...","ar":"دليل إعداد Plankton Code Quality لتنمية التطبيقات باستخدا..."},"description":{"en":"Plankton-code-quality integrates linting, formatting & Claude-powered fixes into your IDE via PostToolUse hooks. Learn setup for real-time code quality enfor...","zh":"Plankton代码质量技能通过PostToolUse钩子实现实时代码格式化与lint检查，Claude子进程自动修复违规。防止代理修改lint配置，确保每次编辑的代码质量。","ja":"Planktonコード品質スキルはPostToolUseフックで自動フォーマットとリンターを実行し、Claudeサブプロセスが違反を修正。AIエージェントが設定を変更するのを防止。","ko":"Plankton 코드 품질 스킬은 PostToolUse 훅으로 실시간 코드 포맷팅 및 린트 검사를 수행하고 Claude 서브프로세스가 자동으로 위반 사항을 수정합니다.","es":"Implementa Plankton para aplicar formateo automático y linting en cada edición de archivo mediante hooks PostToolUse. Previene que agentes modifiquen configu...","fr":"Configurez Plankton pour le formatage automatique et le linting à chaque modification de fichier via les hooks PostToolUse. Empêche les agents de modifier le...","de":"Richten Sie Plankton für automatische Formatierung und Linting bei jedem Datei-Edit via PostToolUse Hooks ein. Verhindert, dass Agenten Linter-Konfigs ändern.","pt":"Aprenda a configurar o Plankton Code Quality para garantir a qualidade do código em tempo de escrita com auto-formatação, linting e correções do Claude","ru":"Узнайте, как настроить Plankton Code Quality для обеспечения качества кода в режиме реального времени с помощью форматирования, линтинга и исправлений от Cla...","ar":"تعرف على كيفية إعداد Plankton Code Quality لضمان جودة الكود في وقت الكتابة باستخدام التنسيق التلقائي وlinting وتصحيحات من Claude وأدوات الذكاء الاصطناعي"},"definition":{"en":"Plankton-code-quality is a write-time code quality enforcement system that integrates formatting, linting, and Claude-powered fixes directly into developer workflows via PostToolUse hooks. It automatically processes code modifications and applies corrections through AI-assisted subprocesses.","zh":"Plankton代码质量技能是一个基于Claude Code的实时代码质量强制执行系统，通过PostToolUse钩子在每次文件编辑时运行格式化程序和linter，并调用Claude子进程修复代码违规。","ja":"Planktonコード品質スキルは、Claude Code向けの書き込み時コード品質強制システムです。PostToolUseフックでフォーマッタとリンターを実行し、Claudeサブプロセスが違反を修正します。","ko":"Plankton 코드 품질 스킬은 Claude Code용 실시간 코드 품질 강화 시스템으로, PostToolUse 훅을 통해 포맷터와 린터를 실행하고 Claude 서브프로세스가 코드 위반을 수정합니다.","es":"Plankton es una skill de MCP que aplica control de calidad de código durante la escritura. Utiliza hooks PostToolUse para ejecutar formateadores y linters automáticamente en cada edición de archivo, complementado con correcciones asistidas por Claude.","fr":"Plankton est une compétence MCP qui applique le contrôle de qualité du code pendant l''écriture. Il utilise des hooks PostToolUse pour exécuter automatiquement des formateurs et linters à chaque modification de fichier, complété par des corrections assistées par Claude.","de":"Plankton ist ein MCP Skill zur Code-Qualitätskontrolle während der Eingabe. Er nutzt PostToolUse Hooks für automatische Formatierer und Linter bei jedem Datei-Edit, ergänzt durch Claude-gestützte Korrekturen.","pt":"O que é Plankton Code Quality? É uma ferramenta de garantia de qualidade de código que executa formatação e linting em cada edição de arquivo","ru":"Что такое Plankton Code Quality? Это инструмент обеспечения качества кода, выполняющий форматирование и линтинг при каждом редактировании файла","ar":"ما هو Plankton Code Quality؟ هو أداة لضمان جودة الكود التي تقوم بتنسيق وlinting عند كل تعديل على الملف"},"features":{"en":["Real-time code formatting on file edits via PostToolUse hooks","Integrated linter execution with automatic violation detection","Claude subprocess spawning for AI-powered code corrections","Write-time quality enforcement (not just commit-time)","Defense against agents modifying linter configs instead of fixing code"],"zh":["每次文件编辑时通过PostToolUse钩子自动运行格式化程序","实时lint检查确保代码质量","Claude子进程自动修复未捕获的违规","防止代理修改lint配置通过而非修复代码","写入时代码质量强制执行而非仅提交时","基于MCP协议的开发者工具集成"],"ja":["PostToolUseフックによるファイル編集時の自動フォーマット","リアルタイムリンター実行によるコード品質確保","Claudeサブプロセスによる違反の自動修正","AIエージェントがリンター設定を変更するのを防止","コミット時だけでなく書き込み時の品質チェック","MCPプロトコル対応の開発者ツール統合"],"ko":["PostToolUse 훅을 통한 모든 파일 편집 시 자동 포맷팅","실시간 린터 실행으로 코드 품질 보장","Claude 서브프로세스가 자동으로 위반 사항 수정","에이전트가 린트 설정을 수정하는 것 방지","커밋 시점이 아닌 작성 시점 코드 품질 강화","MCP 프로토콜 기반 개발자 도구 통합"],"es":["Formateo automático en cada edición de archivo via hooks","Linting en tiempo real con ejecución en PostToolUse hooks","Correcciones asistidas por Claude mediante subprocesos","Defensa contra modificación de configuraciones de linter por agentes","Integración nativa con Claude Code para fixes automáticos","Sistema de calidad de código en tiempo de escritura (write-time)"],"fr":["Formatage automatique à chaque modification de fichier via hooks","Linting en temps réel avec exécution sur PostToolUse hooks","Corrections assistées par Claude via sous-processus","Défense contre la modification des configurations de linter par les agents","Intégration native avec Claude Code pour corrections automatiques","Système de qualité de code en temps d''écriture (write-time)"],"de":["Automatische Formatierung bei jedem Datei-Edit via Hooks","Echtzeit-Linting mit Ausführung auf PostToolUse Hooks","Claude-gestützte Korrekturen durch Subprozesse","Schutz vor Änderung von Linter-Konfigs durch Agenten","Native Integration mit Claude Code für automatische Fixes","Code-Qualitätssystem zur Schreibzeit (write-time)"],"pt":["Auto-formatação em tempo de escrita","Linting em cada edição de arquivo","Correções do Claude para violações de código","Integração com PostToolUse hooks","Suporte a formatters e linters personalizados"],"ru":["Автоформатирование в режиме реального времени","Линтинг при каждом редактировании файла","Исправления от Claude для нарушений кода","Интеграция с PostToolUse hooks","Поддержка пользовательских форматтеров и линтеров"],"ar":["التنسيق التلقائي في وقت الكتابة","linting عند كل تعديل على الملف","تصحيحات من Claude لانتهاكات الكود","التكامل مع PostToolUse hooks","دعم التنسيق التلقائي والlinting المخصص"]},"keywords":{"en":["plankton-code-quality setup","write-time code enforcement","PostToolUse hooks integration","Claude-powered code fixes","real-time linting formatting","plankton-code-quality vs pre-commit hooks","how to use plankton-code-quality","AI-assisted code quality tool","developer workflow code enforcement","plankton-code-quality install guide"],"zh":["plankton代码质量","PostToolUse钩子","Claude子进程","实时代码格式化","AI代理代码修复","写入时代码检查","MCP开发者工具","防止lint配置修改","Claude Code集成"],"ja":["planktonコード品質","PostToolUseフック","Claudeサブプロセス","リアルタイムコードフォーマット","AIエージェントコード修正","書き込み時コードチェック","MCP開発ツール","リンター設定変更防止","Claude Code連携"],"ko":["plankton 코드 품질","PostToolUse 훅","Claude 서브프로세스","실시간 코드 포맷팅","AI 에이전트 코드 수정","작성 시점 코드 검사","MCP 개발자 도구","린트 설정 변경 방지","Claude Code 통합"],"es":["plankton code quality setup","agentes IA linting automático","claude code formateo automático","posttooluse hooks tutorial","mcp skills calidad código","plankton configuracion linters","write-time code quality","claude subprocesos fixes"],"fr":["plankton code quality configuration","outils IA linting automatique","claude code formatage automatique","posttooluse hooks tutoriel","compétences mcp qualité code","plankton configuration linters","qualité code temps écriture","sous-processus claude corrections"],"de":["plankton code quality einrichtung","ki-agenten tools automatisches linting","claude code automatische formatierung","posttooluse hooks anleitung","mcp skills code qualität","plankton linter konfiguration","write-time code quality","claude subprozesse fixes"],"pt":["Plankton Code Quality","garantia de qualidade de código","auto-formatação","linting","correções do Claude","desenvolvimento de software","ferramentas de desenvolvimento","ÍI Agenst"],"ru":["Plankton Code Quality","обеспечение качества кода","автоформатирование","линтинг","исправления от Claude","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["Plankton Code Quality","ضمان جودة الكود","التنسيق التلقائي","linting","تصحيحات من Claude","تنمية التطبيقات","أدوات التنمية","أدوات الذكاء الاصطناعي"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Code Generation Agents requiring real-time quality enforcement and automated fix workflows.","zh":"适用于需要实时质量强制和自动修复工作流的代码生成代理。","ja":"リアルタイムの品質の強制と自動修復ワークフローを必要とするコード生成エージェントに適しています。","ko":"실시간 품질 강제 및 자동 수정 워크플ロー가 필요한 코드 생성 에이전트에 적합합니다.","es":"Ideal para agentes de generación de código que requieren aplicación de calidad en tiempo real y flujos de trabajo de corrección automatizados.","fr":"Idéal pour les agents de génération de code nécessitant une application de la qualité en temps réel et des flux de travail de correction automatisés.","de":"Ideal für Code-Generierungs-Agents, die Echtzeit-Qualitätsdurchsetzung und automatisierte Korrektur-Workflows erfordern.","pt":"Ideal para Agentes de Geração de Código que exigem aplicação de qualidade em tempo real e fluxos de trabalho de correção automatizados.","ru":"Идеально подходит для Агентов Генерации Кода, требующих обеспечения качества в реальном времени и автоматизированных рабочих процессов исправления.","ar":"مثالي لوكلاء توليد التعليمات البرمجية التي تتطلب فرض جودة في الوقت الفعلي وسير عمل التصحيحات الآلية."},"recommendation":{"en":"Enables write-time code quality enforcement through automated formatting, linting, and Claude-powered fixes triggered on every file edit via PostToolUse hooks. Provides defense against agents modifying linter configs instead of fixing actual code violations.","zh":"通过自动格式化、linting和Claude驱动的修复，启用写入时代码质量强制，每次文件编辑时通过PostToolUse hooks触发。防止代理修改linter配置而不是修复实际代码违规。","ja":"自動フォーマット、linting、およびClaude駆動の修復を通じて、書き込み時コード品質の強制を可能にします。PostToolUse hooksを介して毎回ファイル編集時にトリガーされ、実際のコード違反を修正するのではなく、linter構成を変更するエージェントを防ぎます。","ko":"자동 형식 지정, 린팅 및 Claude 구동 수정을 통해 쓰기 시 코드 품질 강제를 가능하게 합니다. PostToolUse hooks를 통해 파일 편집 시마다 트리거되고, 실제 코드 위반을 수정하는 대신 린터 구성만 변경하는 에이전트를 방지합니다.","es":"Permite la aplicación de la calidad del código en tiempo de escritura mediante formato automatizado, linting y correcciones impulsadas por Claude activadas en cada edición de archivo a través de hooks PostToolUse. Proporciona defensa contra agentes que modifican configuraciones de linter en lugar de corregir violaciones de código reales.","fr":"Permet l''application de la qualité du code en temps d''écriture grâce au formatage automatisé, au linting et aux corrections assistées par Claude déclenchées à chaque modification de fichier via des hooks PostToolUse. Offre une protection contre les agents modifiant les configurations de linter au lieu de corriger les violations de code réelles.","de":"Ermöglicht die Qualitätssicherung von Code zur Schreibzeit durch automatische Formatierung, Linting und Claude-gestützte Korrekturen, die bei jeder Dateibearbeitung über PostToolUse-Hooks ausgelöst werden. Bietet Schutz vor Agents, die Linter-Konfigurationen ändern, anstatt tatsächliche Code-Verstöße zu beheben.","pt":"Permite a aplicação da qualidade do código durante a escrita através de formatação automatizada, linting e correções acionadas por Claude em cada edição de arquivo via hooks PostToolUse. Fornece defesa contra agentes que modificam configurações do linter em vez de corrigir violações reais do código.","ru":"Обеспечивает контроль качества кода во время написания через автоматическое форматирование, линтинг и исправления с помощью Claude, запускаемые при каждом редактировании файла с помощью хуков PostToolUse. Обеспечивает защиту от агентов, изменяющих конфигурации линтера вместо исправления фактических нарушений кода.","ar":"يمكن من فرض جودة التعليمات البرمجية أثناء الكتابة من خلال التنسيق الآلي والتدقيق (linting) والتصحيحات التي تعمل بتقنية Claude والتي يتم تشغيلها في كل تعديل على الملف عبر خطافات PostToolUse. يوفر حماية ضد الوكلاء الذين يقومون بتعديل تكوينات أداة التدقيق بدلاً من إصلاح انتهاكات التعليمات البرمجية الفعلية."},"useCases":{"en":["Enforcing code style consistency during generation","Automating violation fixes via Claude subprocesses","Preventing config manipulation by quality-checking agents","Maintaining quality standards on every file edit"],"zh":["生成过程中执行代码样式的一致性","通过Claude子进程自动修复违规","防止质量检查代理修改配置","在每次文件编辑时维护质量标准"],"ja":["生成中コードスタイルの一貫性を実施する","Claudeサブプロセスを介して違反を自動修復する","品質チェックエージェントによる構成の変更を防ぐ","毎回ファイル編集時に品質基準を維持する"],"ko":["생성 중 코드 스타일 일관성을 강제执行","Claude 서브 프로세스를 통한 위반 자동 수정","품질 검사 에이전트의 구성 변경 방지","파일 편집 시마다 품질 기준 유지"],"es":["Aplicación de la coherencia del estilo de código durante la generación","Automatización de correcciones de violaciones mediante subprocesos de Claude","Prevención de la manipulación de configuraciones por parte de agentes de verificación de calidad","Mantenimiento de los estándares de calidad en cada edición de archivo"],"fr":["Application de la cohérence du style de code pendant la génération","Automatisation des corrections de violations via des sous-processus Claude","Prévention de la manipulation de configuration par les agents de vérification de la qualité","Maintien des normes de qualité à chaque modification de fichier"],"de":["Durchsetzung der Konsistenz des Code-Stils während der Generierung","Automatisierung von Verstoßkorrekturen über Claude-Subprozesse","Verhinderung von Konfigurationsmanipulation durch qualitätsprüfende Agents","Aufrechterhaltung von Qualitätsstandards bei jeder Dateibearbeitung"],"pt":["Aplicar a consistência do estilo de código durante a geração","Automatizar correções de violação via subprocessos Claude","Prevenir a manipulação de configuração por agentes de verificação de qualidade","Manter os padrões de qualidade em cada edição de arquivo"],"ru":["Обеспечение согласованности стиля кода во время генерации","Автоматизация исправлений нарушений через подпроцессы Claude","Предотвращение манипуляций с конфигурацией агентами проверки качества","Поддержание стандартов качества при каждом редактировании файла"],"ar":["فرض اتساق نمط التعليمات البرمجية أثناء التوليد","أتمتة إصلاح الانتهاكات عبر العمليات الفرعية لـ Claude","منع التلاعب بالإعدادات من قبل وكلاء فحص الجودة","الحفاظ على معايير الجودة في كل تعديل على الملف"]},"limitations":{"en":["Requires integration with PostToolUse hooks","Depends on Claude subprocess availability","Limited to file edit triggers rather than continuous monitoring"],"zh":["需要与PostToolUse hooks集成","依赖于Claude子进程的可用性","仅限文件编辑触发器，而不是连续监控"],"ja":["PostToolUse hooksとの統合が必要","Claudeサブプロセスの可用性に依存する","ファイル編集トリガーに限定され、連続モニタリングには対応していない"],"ko":["PostToolUse hooks와의 통합이 필요","Claude 서브 프로세스의 가용성에 의존","파일 편집 트리거에만 제한되어连续 모니터링에는対応하지 않음"],"es":["Requiere integración con hooks PostToolUse","Depende de la disponibilidad de subprocesos de Claude","Limitado a desencadenadores de edición de archivos en lugar de monitoreo continuo"],"fr":["Nécessite une intégration avec les hooks PostToolUse","Dépend de la disponibilité des sous-processus Claude","Limité aux déclencheurs de modification de fichier plutôt qu''à une surveillance continue"],"de":["Erfordert Integration mit PostToolUse-Hooks","Hängt von der Verfügbarkeit von Claude-Subprozessen ab","Beschränkt auf Dateibearbeitungsauslöser anstatt auf kontinuierliche Überwachung"],"pt":["Requer integração com hooks PostToolUse","Depende da disponibilidade de subprocessos Claude","Limitado a acionadores de edição de arquivo em vez de monitoramento contínuo"],"ru":["Требует интеграции с хуками PostToolUse","Зависит от доступности подпроцессов Claude","Ограничено триггерами редактирования файлов, а не непрерывным мониторингом"],"ar":["يتطلب التكامل مع خطافات PostToolUse","يعتمد على توفر العمليات الفرعية لـ Claude","مقتصر على محركات تعديل الملفات بدلاً من المراقبة المستمرة"]},"version":4},"contentHash":"e75be8a685f21a10c12e137a6500e349c242791c24d98dd118d5c1845f2070c2","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":89}');
