INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/plankton-code-quality', 'plankton-code-quality', 'affaan-m', 'everything-claude-code', 'official', 'plankton-code-quality affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity Plankton-code-quality is a developer tool that enforces code quality at write-time by running formatters and linters on every file edit through PostToolUse hooks. It automatically spawns Claude subprocesses to fix violations that weren''t caught by initial linting, providing continuous code qualit... Plankton代码质量技能在每次文件编辑时通过PostToolUse钩子自动运行格式化程序和linter，并使用Claude子进程修复代理未捕获的违规。提供实时代码质量保障。 Planktonコード品質スキルはファイル編集のたびにPostToolUseフックでフォーマッタとリンターを実行し、Claudeサブプロセスがエージェントが検出できなかった違反を修正します。 Plankton 코드 품질 스킬은 모든 파일 편집 시 PostToolUse 훅을 통해 포맷터와 린터를 실행하고 Claude 서브프로세스가 에이전트가 놓친 위반 사항을 수정합니다. Plankton es un sistema de calidad de código en tiempo de escritura para Claude Code. Ejecuta formateadores y linters en cada edición de archivo mediante hooks PostToolUse y utiliza subprocesos de Claude para corregir violaciones. Plankton est un système de qualité de code en temps d''écriture pour Claude Code. Il exécoute des formateurs et linters à chaque modification de fichier via des hooks PostToolUse et utilise des sous-processus Claude pour corriger les violations. Plankton ist ein Code-Qualitätssystem zur Schreibzeit für Claude Code. Es führt Formatter und Linter bei jedem Datei-Edit via PostToolUse Hooks aus und nutzt Claude Subprozesse zur Behebung von Verstößen. O Plankton Code Quality é uma ferramenta de garantia de qualidade de código em tempo de escrita que utiliza auto-formatação, linting e correções do Claude Plankton Code Quality — это инструмент обеспечения качества кода в режиме реального времени, использующий форматирование, линтинг и исправления от Claude Plankton Code Quality هو أداة لضمان جودة الكود في وقت الكتابة باستخدام التنسيق التلقائي وlinting وتصحيحات من Claude plankton-code-quality setup write-time code enforcement PostToolUse hooks integration Claude-powered code fixes real-time linting formatting plankton-code-quality vs pre-commit hooks how to use plankton-code-quality AI-assisted code quality tool developer workflow code enforcement plankton-code-quality install guide plankton代码质量 PostToolUse钩子 Claude子进程 实时代码格式化 AI代理代码修复 写入时代码检查 MCP开发者工具 防止lint配置修改 Claude Code集成 Real-time code formatting on file edits via PostToolUse hooks Integrated linter execution with automatic violation detection Claude subprocess spawning for AI-powered code corrections Write-time quality enforcement (not just commit-time) Defense against agents modifying linter configs instead of fixing code Plankton-code-quality is a write-time code quality enforcement system that integrates formatting, linting, and Claude-powered fixes directly into developer workflows via PostToolUse hooks. It automatically processes code modifications and applies corrections through AI-assisted subprocesses.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/create-branch', 'official', 'getsentry', 'skills', 'getsentry/skills', 'create-branch', 360, 11, 89, '2026-03-06T00:20:36Z', '2026-03-06T05:03:00.295Z', '9117cf36425cd92381ddc8208e2863cb653c85170077f78ac8a8e11b730688d4', '{"id":"getsentry/skills/create-branch","name":"create-branch","description":{"en":"The create-branch AI skill automates the creation of Git branches that follow Sentry''s naming conventions. It is designed for developers who use Git and GitHub CLI (`gh`), fetching the username prefix and generating a descriptive branch name from provided arguments or local changes.","zh":"Create-Branch AI工具通过GitHub CLI自动获取用户名前缀，根据输入参数或本地git变更创建符合Sentry命名规范的分支。支持默认分支切换和新工作流启动。","ja":"Create-Branch AIエージェントはGitHub CLIでユーザー名プレフィックスを自動取得し、引数またはローカルのgit変更からSentry命名規則に沿ったブランチを作成。デフォルトブランチへの切り替えと新規作業開始をサポート。","ko":"Create-Branch AI 에이전트는 GitHub CLI로 사용자명 프리픽스를 자동 획득하며, 인수 또는 로컬 git 변경사항으로 Sentry 네이밍 규칙을 따르는 브랜치 생성. 기본 브랜치 전환 및 새 작업 시작 지원.","pt":"Um agente de IA que automatiza a criação de branches Git seguindo as convenções de nomenclatura da Sentry. Ele utiliza a CLI do GitHub para obter o prefixo do usuário e gera um nome de branch descritivo a partir dos argumentos fornecidos ou das alterações locais.","ru":"ИИ агент, автоматизирующий создание веток Git в соответствии с соглашениями об именах Sentry. Он использует CLI GitHub для получения префикса пользователя и генерирует описательное имя ветки из предоставленных аргументов или локальных изменений.","ar":"وكيل ذكاء اصطناعي يقوم بأتمتة إنشاء فروع Git باتباع اصطلاحات التسمية Sentry. يستخدم واجهة سطر أوامر GitHub للحصول على بادئة المستخدم وإنشاء اسم فرع وصفي من الوسائط المقدمة أو من التغييرات المحلية."},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"create-branch","description":"Create a git branch following Sentry naming conventions. Use when asked to create a branch, new branch, start a branch, make a branch, switch to a new branch, or when starting new work on the default branch.","bodyPreview":"# Create Branch\n\nCreate a git branch with the correct type prefix and a descriptive name following Sentry conventions.\n\n## Step 1: Get the Username Prefix\n\nRun `gh api user --jq .login` to get the GitHub username.\n\nIf the command fails (e.g. not authenticated), ask the user for their preferred prefix.\n\n## Step 2: Determine the Branch Description\n\n**If `$ARGUMENTS` is provided**, use it as the description of the work.\n\n**If no arguments**, check for local changes:\n\n```bash\ngit diff\ngit diff --cac","body":"# Create Branch\n\nCreate a git branch with the correct type prefix and a descriptive name following Sentry conventions.\n\n## Step 1: Get the Username Prefix\n\nRun `gh api user --jq .login` to get the GitHub username.\n\nIf the command fails (e.g. not authenticated), ask the user for their preferred prefix.\n\n## Step 2: Determine the Branch Description\n\n**If `$ARGUMENTS` is provided**, use it as the description of the work.\n\n**If no arguments**, check for local changes:\n\n```bash\ngit diff\ngit diff --cached\ngit status --short\n```\n\n- **Changes exist**: read the diff content to understand what the work is about and generate a description.\n- **No changes**: ask the user what they are about to work on.\n\n## Step 3: Classify the Type\n\nPick the type from this table based on the description:\n\n| Type      | Use when                                                              |\n| --------- | --------------------------------------------------------------------- |\n| `feat`    | New user-facing functionality                                         |\n| `fix`     | Broken behavior now works                                             |\n| `ref`     | Same behavior, different structure                                    |\n| `chore`   | Deps, config, version bumps, updating existing tooling — no new logic |\n| `perf`    | Same behavior, faster                                                 |\n| `style`   | CSS, formatting, visual-only                                          |\n| `docs`    | Documentation only                                                    |\n| `test`    | Tests only                                                            |\n| `ci`      | CI/CD config                                                          |\n| `build`   | Build system                                                          |\n| `meta`    | Repo metadata changes                                                 |\n| `license` | License changes                                                       |\n\nWhen unsure: `feat` for new things (including new scripts, skills, or tools), `ref` for restructuring existing things, `chore` only when updating/maintaining something that already exists.\n\n## Step 4: Generate and Propose\n\nBuild the branch name as `<username>/<type>/<short-description>`.\n\nRules for `<short-description>`:\n\n- Kebab-case, lowercase\n- 3 to 6 words, concise but clear\n- Describe the change, not file names\n- Only use ASCII letters, digits, and hyphens — no spaces, dots, colons, tildes, or other git-forbidden characters\n\nPresent it to the user and ask if they want to use it, modify it, or change the type.\n\n### Examples\n\n| Work description                           | Branch name                                 |\n| ------------------------------------------ | ------------------------------------------- |\n| Dropdown menu not closing on outside click | `priscila/fix/dropdown-not-closing-on-blur` |\n| Adding search to conversations page        | `priscila/feat/add-search-to-conversations` |\n| Restructuring drawer components            | `priscila/ref/simplify-drawer-components`   |\n| Updating test fixtures                     | `priscila/chore/update-test-fixtures`       |\n| Bumping @sentry/react to latest version    | `priscila/chore/bump-sentry-react`          |\n| Adding a new agent skill                   | `priscila/feat/add-create-branch-skill`     |\n\n## Step 5: Create the Branch\n\nOnce confirmed, detect the current and default branch:\n\n```bash\ngit branch --show-current\ngit remote | grep -qx origin && echo origin || git remote | head -1\ngit symbolic-ref refs/remotes/<remote>/HEAD 2>/dev/null | sed ''s|refs/remotes/<remote>/||'' | tr -d ''[:space:]''\n```\n\nIf `symbolic-ref` fails, fall back to `git branch --list main master`: use the one that exists; if both or neither exist, ask the user.\n\nIf `git branch --show-current` is empty (detached HEAD), show the current commit (`git rev-parse --short HEAD`) and ask whether to branch from it or switch to the default branch first.\n\nOtherwise, if the current branch is not the default branch, warn the user and ask whether to branch from the current branch or switch to the default branch first.\n\nIf the user wants to switch to the default branch, handle any uncommitted changes appropriately (offer to stash them if present), then run `git checkout <default-branch>`. On any failure, restore stashed changes if applicable and stop.\n\nBefore creating the branch, check that the name doesn''t already exist locally or on the remote (`git show-ref`). If it does, ask the user to choose a different name.\n\nCreate the branch:\n\n```bash\ngit checkout -b <branch-name>\n```\n\nRestore any stashed changes after the branch is created.\n\n## References\n\n- [Sentry Branch Naming](https://develop.sentry.dev/sdk/getting-started/standards/code-submission/#branch-naming)\n"},"category":"official","lastSynced":"2026-03-06T05:03:00.295Z","seo":{"title":{"en":"create-branch: Automate Git Branch Naming Conventions | A...","zh":"Create-Branch AI工具：Sentry分支命名规范设置指南","ja":"Create-Branch AIエージェント：Sentryブランチ命名規則ベストプラクティス","ko":"Create-Branch AI 에이전트: Sentry 브랜치 네이밍 규칙 설정 가이드","pt":"create-branch: Guia para Criar Branches Git com Convençõe...","ru":"create-branch: Руководство по созданию веток Git с конвен...","ar":"create-branch: دليل إنشاء فروع Git باستخدام اصطلاحات Sentry"},"description":{"en":"This AI agent skill automates Sentry-compliant Git branch creation. It uses `gh api` to fetch your GitHub username and intelligently generates a descriptive ...","zh":"专为开发者设计的AI工具，自动创建符合Sentry命名规范的git分支。集成GitHub CLI获取用户名前缀，支持参数输入或本地变更检测生成描述性分支名称。","ja":"開発者向けAIエージェントがSentryの命名規則に準拠したgitブランチを自動生成。GitHub CLI連携でユーザー名プレフィックスを取得し、引数またはローカル変更から記述的なブランチ名を作成。","ko":"개발자용 AI 에이전트로 Sentry 네이밍 규칙을 준수하는 git 브랜치 자동 생성. GitHub CLI 연동으로 사용자명 프리픽스 획득, 인수 또는 로컬 변경사항으로 기술적 브랜치명 생성.","pt":"Automatize a criação de branches Git seguindo as convenções de nomenclatura da Sentry. Este agente de IA usa a CLI gh para obter o prefixo do usuário e gera ...","ru":"Автоматизируйте создание веток Git в соответствии с соглашениями об именах Sentry. Этот ИИ агент использует CLI gh для получения префикса пользователя и гене...","ar":"أتمتة إنشاء فروع Git باتباع اصطلاحات التسمية Sentry. يستخدم وكيل الذكاء الاصطناعي هذا واجهة سطر الأوامر gh للحصول على بادئة المستخدم وإنشاء أسماء وصفيّة."},"definition":{"en":"create-branch is an AI agent skill that programmatically creates a Git branch following specific naming conventions. It uses the GitHub CLI (`gh api`) to fetch a username prefix and generates a descriptive branch name from command-line arguments or local Git diffs.","zh":"Create-Branch是一款AI工具，专为遵循Sentry命名规范创建git分支而设计。它通过GitHub CLI获取用户名前缀，并根据用户参数或本地git差异自动生成描述性分支名称。","ja":"Create-BranchはSentryの命名規則に従ったgitブランチ作成専用のAIエージェントです。GitHub CLIでユーザー名プレフィックスを取得し、引数またはローカルのgit差分から記述的なブランチ名を自動生成します。","ko":"Create-Branch는 Sentry 네이밍 규칙을 준수하는 git 브랜치 생성을 위한 AI 에이전트입니다. GitHub CLI로 사용자명 프리픽스를 획득하며, 인수 또는 로컬 git 차이로 기술적 브랜치명을 자동 생성합니다.","pt":"O create-branch é um agente de IA que cria automaticamente um branch Git seguindo as convenções de nomenclatura da Sentry. Ele obtém um prefixo do usuário via GitHub CLI e deriva um nome descritivo a partir de argumentos ou do diff Git local para padronização.","ru":"Create-branch — это ИИ агент для автоматического создания ветки Git в соответствии с соглашениями об именах Sentry. Он получает префикс пользователя через GitHub CLI и создает описательное имя из аргументов или локального Git diff для стандартизации.","ar":"create-branch هو وكيل ذكاء اصطناعي ينشئ تلقائيًا فرع Git باتباع اصطلاحات تسمية Sentry. يحصل على بادئة المستخدم عبر واجهة سطر أوامر GitHub ويشتق اسمًا وصفيًا من الوسائط أو من فرق Git المحلي للتstandardization."},"features":{"en":["Fetches GitHub username prefix automatically via `gh api user --jq .login`","Accepts a custom branch description directly from `$ARGUMENTS`","Falls back to checking local Git changes (`git diff`, `git diff --cached`) for context if no arguments are provided","Implements a user prompt for a preferred prefix if GitHub CLI authentication fails","Enforces Sentry''s branch naming conventions with a type prefix and descriptive name"],"zh":["集成GitHub CLI（gh api user）自动获取用户名前缀","支持$ARGUMENTS参数直接作为分支描述来源","无参数时自动检测git diff和git diff --cached变更","遵循Sentry约定的类型前缀和描述性命名规范","支持默认分支切换和新工作分支创建场景"],"ja":["GitHub CLI（gh api user）連携でユーザー名プレフィックス自動取得","$ARGUMENTS引数をブランチ記述として直接利用","引数なし時にgit diffとgit diff --cached変更を自動検出","Sentry規約のタイププレフィックスと記述的命名規則準拠","デフォルトブランチ切り替えと新規作業ブランチ作成シナリオ対応"],"ko":["GitHub CLI（gh api user） 연동으로 사용자명 프리픽스 자동 획득","$ARGUMENTS 인수를 브랜치 설명으로 직접 사용","인수 없을 시 git diff 및 git diff --cached 변경사항 자동 감지","Sentry 규약의 타입 프리픽스와 기술적 명명 규칙 준수","기본 브랜치 전환 및 새 작업 브랜치 생성 시나리오 지원"],"pt":["Gera prefixos de usuário automaticamente via comando `gh api user`","Utiliza argumentos fornecidos (`$ARGUMENTS`) como descrição do branch","Falls back para verificar mudanças locais (`git diff`) se nenhum argumento for fornecido","Solicita entrada do usuário para prefixo se a autenticação GitHub falhar","Implementa convenções de nomenclatura específicas da Sentry","Projetado para integração com fluxo de trabalho de desenvolvimento padrão"],"ru":["Автоматически генерирует префиксы пользователей с помощью команды `gh api user`","Использует предоставленные аргументы (`$ARGUMENTS`) в качестве описания ветки","Переходит к проверке локальных изменений (`git diff`), если аргументы не предоставлены","Запрашивает ввод префикса у пользователя при сбое аутентификации GitHub","Реализует специфичные для Sentry соглашения об именах","Предназначен для интеграции со стандартным рабочим процессом разработки"],"ar":["يولد بادئات المستخدم تلقائيًا عبر أمر `gh api user`","يستخدم الوسائط المقدمة (`$ARGUMENTS`) كوصف للفرع","يرجع إلى فحص التغييرات المحلية (`git diff`) إذا لم يتم تقديم وسائط","يطلب إدخال البادئة من المستخدم إذا فشل مصادقة GitHub","ينفذ اصطلاحات تسمية Sentry المحددة","مصمم للتكامل مع سير عمل التطوير القياسي"]},"keywords":{"en":["how to use create-branch skill","what is create-branch ai agent","create-branch vs manual git branch","create-branch setup guide","automate git branch naming","sentry git branch conventions","gh cli create branch","create-branch install"],"zh":["create-branch AI工具","Sentry分支命名规范","GitHub CLI分支创建","git分支最佳实践","自动化git工作流","开发者AI助手","分支命名约定","git diff自动检测"],"ja":["create-branch AIエージェント","Sentryブランチ命名規則","GitHub CLIブランチ作成","gitブランチベストプラクティス","自動化gitワークフロー","開発者AIアシスタント","ブランチ命名規約","git diff自動検出"],"ko":["create-branch AI 에이전트","Sentry 브랜치 네이밍 규칙","GitHub CLI 브랜치 생성","git 브랜치 베스트 프랙티스","자동화 git 워크플로우","개발자 AI 어시스턴트","브랜치 명명 규약","git diff 자동 감지"],"pt":["agente IA criar branch git","convenções nomenclatura sentry git","automatização criação branch","cli github gh api user","git diff para nome branch","padrão prefixo usuário git","ferramenta desenvolvedor git sentry"],"ru":["ИИ агент создать ветку git","соглашения именования sentry git","автоматизация создания ветки","cli github gh api user","git diff для имени ветки","стандарт префикса пользователя git","инструмент разработчика git sentry"],"ar":["وكيل ذكاء اصطناعي إنشاء فرع git","اصطلاحات تسمية sentry git","أتمتة إنشاء الفرع","واجهة سطر أوامر github gh api user","git diff لاسم الفرع","معيار بادئة مستخدم git","أداة مطور git sentry"]}},"agentAnalysis":{"suitability":{"en":"Essential for Development Agents automating Git workflows with Sentry compliance.","zh":"对于自动化具有Sentry合规的Git工作流的开发代理来说是必不可少的","ja":"Sentryのコンプライアンスを備えたGitワークフローを自動化する開発エージェントに不可欠","ko":"Sentry 규정 준수를 갖춘 Git 워크플로를 자동화하는 개발 에이전트에게 필수적","es":"Esencial para los agentes de desarrollo que automatizan flujos de trabajo de Git con cumplimiento de Sentry.","fr":"Essentiel pour les agents de développement automatisant les flux de travail Git avec conformité Sentry.","de":"Wesentlich für Entwicklungsmittel, die Git-Workflows mit Sentry-Konformität automatisieren.","pt":"Essencial para Agentes de Desenvolvimento que automatizam fluxos de trabalho do Git com conformidade do Sentry.","ru":"Необходим для агентов разработки, автоматизирующих рабочие процессы Git с соблюдением требований Sentry.","ar":"ضروري للوكلاء النموذجية الذين يقومون بتشغيل عمليات العمل الخاصة بـ Git مع امتثال Sentry."},"recommendation":{"en":"Enables automated branch creation following Sentry''s strict naming conventions, ensuring consistency across development cycles. It intelligently sources username prefixes from GitHub CLI or user input and generates descriptive branch names from either provided arguments or local Git changes.","zh":"实现自动创建分支，遵循Sentry的严格命名约定，确保在整个开发周期中保持一致性。它可以智能地从GitHub CLI或用户输入中获取用户名前缀，并从提供的参数或本地Git更改中生成描述性的分支名称","ja":"Sentryの厳格な命名規約に従った自動ブランチ作成を実現し、開発サイクル全体で一貫性を保証する。GitHub CLIまたはユーザー入力からユーザー名プレフィックスをスマートに抽出し、提供された引数またはローカルのGit変更から説明的なブランチ名を生成する","ko":"Sentry의 엄격한 명명 규칙을 따르는 자동 분기 생성을 가능하게 하여 개발 주기 전체에서 일관성을 보장한다. GitHub CLI 또는 사용자 입력에서 사용자 이름 접두사를 지능적으로 소싱하여 제공된 인수 또는 로컬 Git 변경에서 설명적인 분기 이름을 생성","es":"Permite la creación automática de ramas siguiendo las estrictas convenciones de nomenclatura de Sentry, asegurando la coherencia en los ciclos de desarrollo. Inteligentemente, toma prefijos de nombres de usuario desde GitHub CLI o entrada de usuario y genera nombres de ramas descriptivos a partir de argumentos proporcionados o cambios locales de Git.","fr":"Permet la création automatique de branches suivant les conventions de nommage strictes de Sentry, assurant la cohérence tout au long des cycles de développement. Elle prend intelligemment les préfixes de nom d''utilisateur à partir de GitHub CLI ou de la saisie utilisateur et génère des noms de branches descriptifs à partir d''arguments fournis ou de modifications Git locales.","de":"Ermöglicht die automatische Erstellung von Branches unter Einhaltung der strengen Namenskonventionen von Sentry, um die Konsistenz über die Entwicklungszyklen hinweg zu gewährleisten. Es nimmt intelligent Benutzernamenspräfixe von GitHub CLI oder Benutzereingabe und generiert beschreibende Branchennamen aus entweder bereitgestellten Argumenten oder lokalen Git-Änderungen.","pt":"Permite a criação automática de branches seguindo as convenções de nomenclatura estritas do Sentry, garantindo a consistência em todo o ciclo de desenvolvimento. Ele inteligentemente obtém prefixos de nomes de usuário do GitHub CLI ou da entrada do usuário e gera nomes de branches descritivos a partir de argumentos fornecidos ou alterações locais do Git.","ru":"Позволяет автоматически создавать ветки, следуя строгим соглашениям об именах Sentry, обеспечивая согласованность на протяжении всего цикла разработки. Он умно извлекает префиксы имен пользователей из GitHub CLI или ввода пользователя и генерирует описательные имена веток либо из предоставленных аргументов, либо из локальных изменений Git.","ar":"يسمح بإنشاء فرع تلقائي يتبع الاتفاقيات الصارمة لتسمية Sentry، مما يضمن الاتساق في جميع دورات التطوير. إنه يستمد بعنط الحكمة بادئات اسم المستخدم من واجهة سطر أوامر GitHub أو إدخال المستخدم ويولد أسماء فرعية وصفية من الحجج المقدمة أو التغييرات المحلية في Git."},"useCases":{"en":["Automating branch creation for new feature development","Enforcing Sentry naming conventions in CI/CD pipelines","Switching to new branches when starting work from default branch"],"zh":["用于新功能开发的自动分支创建","在CI/CD管道中执行Sentry命名约定","从默认分支开始工作时切换到新分支"],"ja":["新機能開発の自動ブランチ作成","CI/CDパイプラインでのSentry命名規約の適用","デフォルトブランチから作業を開始する際の新規ブランチへの切り替え"],"ko":["새로운 기능 개발을 위한 자동 분기 생성","CI/CD 파이프라인에서 Sentry 명명 규칙 적용","기본 분기에서 작업을 시작할 때 새로운 분기 전환"],"es":["Automatización de la creación de ramas para el desarrollo de nuevas características","Aplicación de las convenciones de nomenclatura de Sentry en pipelines de CI/CD","Cambiar a nuevas ramas al comenzar a trabajar desde la rama predeterminada"],"fr":["Automatisation de la création de branches pour le développement de nouvelles fonctionnalités","Application des conventions de nommage de Sentry dans les pipelines de CI/CD","Basculer vers de nouvelles branches lors du démarrage du travail à partir de la branche par défaut"],"de":["Automatisierung der Erstellung von Branches für die Entwicklung neuer Funktionen","Durchsetzung der Namenskonventionen von Sentry in CI/CD-Pipelines","Umschalten auf neue Branches beim Beginn der Arbeit von der Standardbranch aus"],"pt":["Automação da criação de branches para desenvolvimento de novas funcionalidades","Aplicação das convenções de nomenclatura do Sentry em pipelines de CI/CD","Alternância para novos branches ao iniciar o trabalho a partir do branch padrão"],"ru":["Автоматизация создания веток для разработки новых функций","Применение соглашений об именах Sentry в конвейерах CI/CD","Переключение на новые ветки при начале работы из основной ветки"],"ar":["التشغيل التلقائي لإنشاء الفروع لتطوير الميزات الجديدة","تطبيق اتفاقيات تسمية Sentry في أنابيب CI/CD","التحول إلى فروع جديدة عند بدء العمل من الفرع الافتراضي"]},"limitations":{"en":["Requires GitHub CLI (gh) authentication for automatic prefix detection","Depends on local Git repository status for description generation","Limited to Sentry-specific naming conventions"],"zh":["需要GitHub CLI（gh）身份验证以实现自动前缀检测","依赖于本地Git存储库状态以生成描述","仅限Sentry特定的命名约定"],"ja":["自動プレフィックス検出にはGitHub CLI（gh）認証が必要","説明生成にはローカルのGitリポジトリ状態に依存","Sentry固有の命名規約に限定"],"ko":["자동 접두사 감지를 위해 GitHub CLI(gh) 인증이 필요","설명 생성을 위해 로컬 Git 저장소 상태에 의존","Sentry 특정 명명 규칙으로 제한"],"es":["Requiere autenticación de GitHub CLI (gh) para la detección automática de prefijos","Depende del estado del repositorio Git local para la generación de descripciones","Limitado a convenciones de nomenclatura específicas de Sentry"],"fr":["Nécessite une authentification GitHub CLI (gh) pour la détection automatique de préfixes","Dépend de l''état du référentiel Git local pour la génération de descriptions","Limité aux conventions de nommage spécifiques à Sentry"],"de":["Benötigt GitHub-CLI-(gh)-Authentifizierung für die automatische Erkennung von Präfixen","Hängt vom Status des lokalen Git-Repositorys für die Generierung von Beschreibungen ab","Begrenzt auf Sentry-spezifische Namenskonventionen"],"pt":["Exige autenticação do GitHub CLI (gh) para detecção automática de prefixos","Depende do status do repositório Git local para geração de descrições","Limitado a convenções de nomenclatura específicas do Sentry"],"ru":["Требует аутентификации GitHub CLI (gh) для автоматического обнаружения префиксов","Зависит от состояния локального репозитория Git для генерации описаний","Ограничен соглашениями об именах, специфичными для Sentry"],"ar":["يتطلب مصادقة واجهة سطر أوامر GitHub (gh) لاكتشاف البادئات تلقائيًا","يعتمد على حالة المستودع المحلي في Git لتوليد الوصف","محدود بالاتفاقيات المحددة لتسمية Sentry"]},"version":4},"contentHash":"9117cf36425cd92381ddc8208e2863cb653c85170077f78ac8a8e11b730688d4","repoEtag":"W/\"36a09bba6a611068f31a3df860388e78cbe9407beaecc6e6da77ba4b47f9eb59\"","qualityScore":89}');
