INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/create-branch', 'create-branch', 'getsentry', 'skills', 'official', 'create-branch getsentry skills official tag-production The create-branch AI skill automates the creation of Git branches that follow Sentry''s naming conventions. It is designed for developers who use Git and GitHub CLI (`gh`), fetching the username prefix and generating a descriptive branch name from provided arguments or local changes. Create-Branch AI工具通过GitHub CLI自动获取用户名前缀，根据输入参数或本地git变更创建符合Sentry命名规范的分支。支持默认分支切换和新工作流启动。 Create-Branch AIエージェントはGitHub CLIでユーザー名プレフィックスを自動取得し、引数またはローカルのgit変更からSentry命名規則に沿ったブランチを作成。デフォルトブランチへの切り替えと新規作業開始をサポート。 Create-Branch AI 에이전트는 GitHub CLI로 사용자명 프리픽스를 자동 획득하며, 인수 또는 로컬 git 변경사항으로 Sentry 네이밍 규칙을 따르는 브랜치 생성. 기본 브랜치 전환 및 새 작업 시작 지원. Um agente de IA que automatiza a criação de branches Git seguindo as convenções de nomenclatura da Sentry. Ele utiliza a CLI do GitHub para obter o prefixo do usuário e gera um nome de branch descritivo a partir dos argumentos fornecidos ou das alterações locais. ИИ агент, автоматизирующий создание веток Git в соответствии с соглашениями об именах Sentry. Он использует CLI GitHub для получения префикса пользователя и генерирует описательное имя ветки из предоставленных аргументов или локальных изменений. وكيل ذكاء اصطناعي يقوم بأتمتة إنشاء فروع Git باتباع اصطلاحات التسمية Sentry. يستخدم واجهة سطر أوامر GitHub للحصول على بادئة المستخدم وإنشاء اسم فرع وصفي من الوسائط المقدمة أو من التغييرات المحلية. how to use create-branch skill what is create-branch ai agent create-branch vs manual git branch create-branch setup guide automate git branch naming sentry git branch conventions gh cli create branch create-branch install create-branch AI工具 Sentry分支命名规范 GitHub CLI分支创建 git分支最佳实践 自动化git工作流 开发者AI助手 分支命名约定 git diff自动检测 Fetches GitHub username prefix automatically via `gh api user --jq .login` Accepts a custom branch description directly from `$ARGUMENTS` Falls back to checking local Git changes (`git diff`, `git diff --cached`) for context if no arguments are provided Implements a user prompt for a preferred prefix if GitHub CLI authentication fails Enforces Sentry''s branch naming conventions with a type prefix and descriptive name create-branch is an AI agent skill that programmatically creates a Git branch following specific naming conventions. It uses the GitHub CLI (`gh api`) to fetch a username prefix and generates a descriptive branch name from command-line arguments or local Git diffs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('expo/skills/native-data-fetching', 'official', 'expo', 'skills', 'expo/skills', 'native-data-fetching', 1349, 59, 88, '2026-03-06T04:04:30Z', '2026-03-06T05:26:35.153Z', 'eaa2f00ceed45e3149a9c6b6e1b989413bd1350fd4a256c76d89a60d9dc00026', '{"id":"expo/skills/native-data-fetching","name":"native-data-fetching","description":{"en":"The native-data-fetching skill helps developers implement and debug network requests, API calls, and data fetching. It covers fetch API, React Query, SWR, and Expo Router data loaders.","zh":"Native 数据抓取是一种使用 Fetch API、React Query 和 Expo Router 进行网络请求和数据抓取的技术，支持错误处理、缓存和离线支持","ja":"ネイティブデータフェッチングは、Fetch API、React Query、SWR を使用したネットワークリクエストとデータフェッチの実装方法です","ko":"네이티브 데이터 가져오기는 Fetch API, React Query, Expo Router를 사용하여 네트워크 요청과 데이터 가져오기를 구현하는 기술입니다","es":"Native-data-fetching es una habilidad para implementar y depurar solicitudes de red y llamadas a API, incluyendo caché y soporte offline","fr":"Native-data-fetching est une compétence pour mettre en œuvre et déboguer les requêtes réseau et les appels d''API, y compris la mise en cache et le support hors ligne","de":"Native-Data-Fetching ist eine Fähigkeit zum Implementieren und Debuggen von Netzwerkanfragen und API-Aufrufen, einschließlich Caching und Offline-Unterstützung","pt":"native-data-fetching é uma habilidade para implementar e depurar requisições de rede e busca de dados, incluindo React Query e Expo Router. Aprenda a usar fetch API, SWR e muito mais.","ru":"native-data-fetching - это навык для реализации и отладки сетевых запросов и получения данных, включая React Query и Expo Router. Узнайте, как использовать fetch API, SWR и многое другое.","ar":"إدارة البيانات الأصلية هي مهارة لتنفيذ واستكشاف الأخطاء في الطلبات الشبكية واسترجاع البيانات، بما في ذلك React Query وExpo Router. تعلم كيفية استخدام fetch API وSWR والمزيد"},"owner":"expo","repo":"skills","repoPath":"expo/skills","stars":1349,"forks":59,"updatedAt":"2026-03-06T04:04:30Z","topics":[],"skillMd":{"name":"native-data-fetching","description":"Use when implementing or debugging ANY network request, API call, or data fetching. Covers fetch API, React Query, SWR, error handling, caching, offline support, and Expo Router data loaders (useLoaderData).","version":"1.0.0","bodyPreview":"# Expo Networking\n\n**You MUST use this skill for ANY networking work including API requests, data fetching, caching, or network debugging.**\n\n## References\n\nConsult these resources as needed:\n\n```\nreferences/\n  expo-router-loaders.md   Route-level data loading with Expo Router loaders (web, SDK 55+)\n```\n\n## When to Use\n\nUse this skill when:\n\n- Implementing API requests\n- Setting up data fetching (React Query, SWR)\n- Using Expo Router data loaders (`useLoaderData`, web SDK 55+)\n- Debugging networ","body":"# Expo Networking\n\n**You MUST use this skill for ANY networking work including API requests, data fetching, caching, or network debugging.**\n\n## References\n\nConsult these resources as needed:\n\n```\nreferences/\n  expo-router-loaders.md   Route-level data loading with Expo Router loaders (web, SDK 55+)\n```\n\n## When to Use\n\nUse this skill when:\n\n- Implementing API requests\n- Setting up data fetching (React Query, SWR)\n- Using Expo Router data loaders (`useLoaderData`, web SDK 55+)\n- Debugging network failures\n- Implementing caching strategies\n- Handling offline scenarios\n- Authentication/token management\n- Configuring API URLs and environment variables\n\n## Preferences\n\n- Avoid axios, prefer expo/fetch\n\n## Common Issues & Solutions\n\n### 1. Basic Fetch Usage\n\n**Simple GET request**:\n\n```tsx\nconst fetchUser = async (userId: string) => {\n  const response = await fetch(`https://api.example.com/users/${userId}`);\n\n  if (!response.ok) {\n    throw new Error(`HTTP error! status: ${response.status}`);\n  }\n\n  return response.json();\n};\n```\n\n**POST request with body**:\n\n```tsx\nconst createUser = async (userData: UserData) => {\n  const response = await fetch(\"https://api.example.com/users\", {\n    method: \"POST\",\n    headers: {\n      \"Content-Type\": \"application/json\",\n      Authorization: `Bearer ${token}`,\n    },\n    body: JSON.stringify(userData),\n  });\n\n  if (!response.ok) {\n    const error = await response.json();\n    throw new Error(error.message);\n  }\n\n  return response.json();\n};\n```\n\n---\n\n### 2. React Query (TanStack Query)\n\n**Setup**:\n\n```tsx\n// app/_layout.tsx\nimport { QueryClient, QueryClientProvider } from \"@tanstack/react-query\";\n\nconst queryClient = new QueryClient({\n  defaultOptions: {\n    queries: {\n      staleTime: 1000 * 60 * 5, // 5 minutes\n      retry: 2,\n    },\n  },\n});\n\nexport default function RootLayout() {\n  return (\n    <QueryClientProvider client={queryClient}>\n      <Stack />\n    </QueryClientProvider>\n  );\n}\n```\n\n**Fetching data**:\n\n```tsx\nimport { useQuery } from \"@tanstack/react-query\";\n\nfunction UserProfile({ userId }: { userId: string }) {\n  const { data, isLoading, error, refetch } = useQuery({\n    queryKey: [\"user\", userId],\n    queryFn: () => fetchUser(userId),\n  });\n\n  if (isLoading) return <Loading />;\n  if (error) return <Error message={error.message} />;\n\n  return <Profile user={data} />;\n}\n```\n\n**Mutations**:\n\n```tsx\nimport { useMutation, useQueryClient } from \"@tanstack/react-query\";\n\nfunction CreateUserForm() {\n  const queryClient = useQueryClient();\n\n  const mutation = useMutation({\n    mutationFn: createUser,\n    onSuccess: () => {\n      // Invalidate and refetch\n      queryClient.invalidateQueries({ queryKey: [\"users\"] });\n    },\n  });\n\n  const handleSubmit = (data: UserData) => {\n    mutation.mutate(data);\n  };\n\n  return <Form onSubmit={handleSubmit} isLoading={mutation.isPending} />;\n}\n```\n\n---\n\n### 3. Error Handling\n\n**Comprehensive error handling**:\n\n```tsx\nclass ApiError extends Error {\n  constructor(message: string, public status: number, public code?: string) {\n    super(message);\n    this.name = \"ApiError\";\n  }\n}\n\nconst fetchWithErrorHandling = async (url: string, options?: RequestInit) => {\n  try {\n    const response = await fetch(url, options);\n\n    if (!response.ok) {\n      const error = await response.json().catch(() => ({}));\n      throw new ApiError(\n        error.message || \"Request failed\",\n        response.status,\n        error.code\n      );\n    }\n\n    return response.json();\n  } catch (error) {\n    if (error instanceof ApiError) {\n      throw error;\n    }\n    // Network error (no internet, timeout, etc.)\n    throw new ApiError(\"Network error\", 0, \"NETWORK_ERROR\");\n  }\n};\n```\n\n**Retry logic**:\n\n```tsx\nconst fetchWithRetry = async (\n  url: string,\n  options?: RequestInit,\n  retries = 3\n) => {\n  for (let i = 0; i < retries; i++) {\n    try {\n      return await fetchWithErrorHandling(url, options);\n    } catch (error) {\n      if (i === retries - 1) throw error;\n      // Exponential backoff\n      await new Promise((r) => setTimeout(r, Math.pow(2, i) * 1000));\n    }\n  }\n};\n```\n\n---\n\n### 4. Authentication\n\n**Token management**:\n\n```tsx\nimport * as SecureStore from \"expo-secure-store\";\n\nconst TOKEN_KEY = \"auth_token\";\n\nexport const auth = {\n  getToken: () => SecureStore.getItemAsync(TOKEN_KEY),\n  setToken: (token: string) => SecureStore.setItemAsync(TOKEN_KEY, token),\n  removeToken: () => SecureStore.deleteItemAsync(TOKEN_KEY),\n};\n\n// Authenticated fetch wrapper\nconst authFetch = async (url: string, options: RequestInit = {}) => {\n  const token = await auth.getToken();\n\n  return fetch(url, {\n    ...options,\n    headers: {\n      ...options.headers,\n      Authorization: token ? `Bearer ${token}` : \"\",\n    },\n  });\n};\n```\n\n**Token refresh**:\n\n```tsx\nlet isRefreshing = false;\nlet refreshPromise: Promise<string> | null = null;\n\nconst getValidToken = async (): Promise<string> => {\n  const token = await auth.getToken();\n\n  if (!token || isTokenExpired(token)) {\n    if (!isRefreshing) {\n      isRefreshing = true;\n      refreshPromise = refreshToken().finally(() => {\n        isRefreshing = false;\n        refreshPromise = null;\n      });\n    }\n    return refreshPromise!;\n  }\n\n  return token;\n};\n```\n\n---\n\n### 5. Offline Support\n\n**Check network status**:\n\n```tsx\nimport NetInfo from \"@react-native-community/netinfo\";\n\n// Hook for network status\nfunction useNetworkStatus() {\n  const [isOnline, setIsOnline] = useState(true);\n\n  useEffect(() => {\n    return NetInfo.addEventListener((state) => {\n      setIsOnline(state.isConnected ?? true);\n    });\n  }, []);\n\n  return isOnline;\n}\n```\n\n**Offline-first with React Query**:\n\n```tsx\nimport { onlineManager } from \"@tanstack/react-query\";\nimport NetInfo from \"@react-native-community/netinfo\";\n\n// Sync React Query with network status\nonlineManager.setEventListener((setOnline) => {\n  return NetInfo.addEventListener((state) => {\n    setOnline(state.isConnected ?? true);\n  });\n});\n\n// Queries will pause when offline and resume when online\n```\n\n---\n\n### 6. Environment Variables\n\n**Using environment variables for API configuration**:\n\nExpo supports environment variables with the `EXPO_PUBLIC_` prefix. These are inlined at build time and available in your JavaScript code.\n\n```tsx\n// .env\nEXPO_PUBLIC_API_URL=https://api.example.com\nEXPO_PUBLIC_API_VERSION=v1\n\n// Usage in code\nconst API_URL = process.env.EXPO_PUBLIC_API_URL;\n\nconst fetchUsers = async () => {\n  const response = await fetch(`${API_URL}/users`);\n  return response.json();\n};\n```\n\n**Environment-specific configuration**:\n\n```tsx\n// .env.development\nEXPO_PUBLIC_API_URL=http://localhost:3000\n\n// .env.production\nEXPO_PUBLIC_API_URL=https://api.production.com\n```\n\n**Creating an API client with environment config**:\n\n```tsx\n// api/client.ts\nconst BASE_URL = process.env.EXPO_PUBLIC_API_URL;\n\nif (!BASE_URL) {\n  throw new Error(\"EXPO_PUBLIC_API_URL is not defined\");\n}\n\nexport const apiClient = {\n  get: async <T,>(path: string): Promise<T> => {\n    const response = await fetch(`${BASE_URL}${path}`);\n    if (!response.ok) throw new Error(`HTTP ${response.status}`);\n    return response.json();\n  },\n\n  post: async <T,>(path: string, body: unknown): Promise<T> => {\n    const response = await fetch(`${BASE_URL}${path}`, {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify(body),\n    });\n    if (!response.ok) throw new Error(`HTTP ${response.status}`);\n    return response.json();\n  },\n};\n```\n\n**Important notes**:\n\n- Only variables prefixed with `EXPO_PUBLIC_` are exposed to the client bundle\n- Never put secrets (API keys with write access, database passwords) in `EXPO_PUBLIC_` variables—they''re visible in the built app\n- Environment variables are inlined at **build time**, not runtime\n- Restart the dev server after changing `.env` files\n- For server-side secrets in API routes, use variables without the `EXPO_PUBLIC_` prefix\n\n**TypeScript support**:\n\n```tsx\n// types/env.d.ts\ndeclare global {\n  namespace NodeJS {\n    interface ProcessEnv {\n      EXPO_PUBLIC_API_URL: string;\n      EXPO_PUBLIC_API_VERSION?: string;\n    }\n  }\n}\n\nexport {};\n```\n\n---\n\n### 7. Request Cancellation\n\n**Cancel on unmount**:\n\n```tsx\nuseEffect(() => {\n  const controller = new AbortController();\n\n  fetch(url, { signal: controller.signal })\n    .then((response) => response.json())\n    .then(setData)\n    .catch((error) => {\n      if (error.name !== \"AbortError\") {\n        setError(error);\n      }\n    });\n\n  return () => controller.abort();\n}, [url]);\n```\n\n**With React Query** (automatic):\n\n```tsx\n// React Query automatically cancels requests when queries are invalidated\n// or components unmount\n```\n\n---\n\n## Decision Tree\n\n```\nUser asks about networking\n  |-- Route-level data loading (web, SDK 55+)?\n  |   \\-- Expo Router loaders — see references/expo-router-loaders.md\n  |\n  |-- Basic fetch?\n  |   \\-- Use fetch API with error handling\n  |\n  |-- Need caching/state management?\n  |   |-- Complex app -> React Query (TanStack Query)\n  |   \\-- Simpler needs -> SWR or custom hooks\n  |\n  |-- Authentication?\n  |   |-- Token storage -> expo-secure-store\n  |   \\-- Token refresh -> Implement refresh flow\n  |\n  |-- Error handling?\n  |   |-- Network errors -> Check connectivity first\n  |   |-- HTTP errors -> Parse response, throw typed errors\n  |   \\-- Retries -> Exponential backoff\n  |\n  |-- Offline support?\n  |   |-- Check status -> NetInfo\n  |   \\-- Queue requests -> React Query persistence\n  |\n  |-- Environment/API config?\n  |   |-- Client-side URLs -> EXPO_PUBLIC_ prefix in .env\n  |   |-- Server secrets -> Non-prefixed env vars (API routes only)\n  |   \\-- Multiple environments -> .env.development, .env.production\n  |\n  \\-- Performance?\n      |-- Caching -> React Query with staleTime\n      |-- Deduplication -> React Query handles this\n      \\-- Cancellation -> AbortController or React Query\n```\n\n## Common Mistakes\n\n**Wrong: No error handling**\n\n```tsx\nconst data = await fetch(url).then((r) => r.json());\n```\n\n**Right: Check response status**\n\n```tsx\nconst response = await fetch(url);\nif (!response.ok) throw new Error(`HTTP ${response.status}`);\nconst data = await response.json();\n```\n\n**Wrong: Storing tokens in AsyncStorage**\n\n```tsx\nawait AsyncStorage.setItem(\"token\", token); // Not secure!\n```\n\n**Right: Use SecureStore for sensitive data**\n\n```tsx\nawait SecureStore.setItemAsync(\"token\", token);\n```\n\n## Example Invocations\n\nUser: \"How do I make API calls in React Native?\"\n-> Use fetch, wrap with error handling\n\nUser: \"Should I use React Query or SWR?\"\n-> React Query for complex apps, SWR for simpler needs\n\nUser: \"My app needs to work offline\"\n-> Use NetInfo for status, React Query persistence for caching\n\nUser: \"How do I handle authentication tokens?\"\n-> Store in expo-secure-store, implement refresh flow\n\nUser: \"API calls are slow\"\n-> Check caching strategy, use React Query staleTime\n\nUser: \"How do I configure different API URLs for dev and prod?\"\n-> Use EXPO*PUBLIC* env vars with .env.development and .env.production files\n\nUser: \"Where should I put my API key?\"\n-> Client-safe keys: EXPO*PUBLIC* in .env. Secret keys: non-prefixed env vars in API routes only\n\nUser: \"How do I load data for a page in Expo Router?\"\n-> See references/expo-router-loaders.md for route-level loaders (web, SDK 55+). For native, use React Query or fetch.\n"},"category":"official","lastSynced":"2026-03-06T05:26:35.153Z","seo":{"title":{"en":"native-data-fetching: API Request Setup Guide | AI Agent ...","zh":"Native 数据抓取 Setup Guide","ja":"ネイティブデータフェッチングベストプラクティス","ko":"네이티브 데이터 가져오기 튜토리얼","es":"Guía de configuración de native-data-fetching para solici...","fr":"Meilleures pratiques de native-data-fetching pour les app...","de":"Native-Data-Fetching-Setup-Anleitung für API-Anfragen und...","pt":"Guia de Configuração de native-data-fetching para Desenvo...","ru":"ИИ Агенты: Лучшие Практики native-data-fetching для Разра...","ar":"دليل الإعداد لإدارة البيانات الأصلية للبرمجة"},"description":{"en":"Learn how to implement and debug network requests with native-data-fetching. Discover best practices for fetch API, React Query, and Expo Router data loaders.","zh":"了解如何使用 Fetch API、React Query 和 Expo Router 进行网络请求和数据抓取，包括错误处理、缓存和离线支持","ja":"Fetch API、React Query、SWR を使用したネットワークリクエストとデータフェッチの実装方法について学びます","ko":"네이티브 데이터 가져오기에서 Fetch API, React Query, Expo Router를 사용하여 네트워크 요청과 데이터 가져오기를 구현하는 방법을 알아보세요","es":"Aprende a implementar y depurar solicitudes de red, llamadas a API y fetching de datos con native-data-fetching, incluyendo React Query, SWR y Expo Router","fr":"Découvrez comment mettre en œuvre et déboguer les requêtes réseau, les appels d''API et le fetching de données avec native-data-fetching, y compris React Quer...","de":"Erfahren Sie, wie Sie Netzwerkanfragen, API-Aufrufe und Datenabruf mit native-data-fetching implementieren und debuggen, einschließlich React Query, SWR und ...","pt":"Aprenda a implementar e depurar requisições de rede, chamadas de API e busca de dados com native-data-fetching, incluindo React Query e Expo Router","ru":"Изучите, как реализовать и отладить сетевые запросы, вызовы API и получение данных с помощью native-data-fetching, включая React Query и Expo Router","ar":"تعلم كيفية تنفيذ واستكشاف الأخطاء في الطلبات الشبكية واستدعاءات واجهة برمجة التطبيقات واسترجاع البيانات باستخدام إدارة البيانات الأصلية"},"definition":{"en":"native-data-fetching is a skill for implementing and debugging network requests, API calls, and data fetching in applications, covering technologies like fetch API and React Query.","zh":"Native 数据抓取是一种用于实现网络请求和数据抓取的技术，支持 Fetch API、React Query 和 Expo Router","ja":"ネイティブデータフェッチングは、ネットワークリクエストとデータフェッチの実装方法の一種です","ko":"네이티브 데이터 가져오기는 네트워크 요청과 데이터 가져오기를 구현하는 기술 중 하나입니다","es":"Native-data-fetching es una técnica para gestionar solicitudes de red y llamadas a API de manera eficiente","fr":"Native-data-fetching est une technique pour gérer les requêtes réseau et les appels d''API de manière efficace","de":"Native-Data-Fetching ist eine Technik zum effizienten Management von Netzwerkanfragen und API-Aufrufen","pt":"native-data-fetching é uma habilidade para gerenciar requisições de rede e busca de dados em aplicações nativas","ru":"native-data-fetching - это навык для управления сетевыми запросами и получением данных в родных приложениях","ar":"إدارة البيانات الأصلية هي مهارة لإدارة الطلبات الشبكية واسترجاع البيانات في التطبيقات الأصلية"},"features":{"en":["Supports fetch API for network requests","Integrates with React Query for data fetching","Utilizes SWR for caching and offline support","Works with Expo Router data loaders (useLoaderData)","Enables error handling for network requests","Provides debugging capabilities for network issues"],"zh":["支持 Fetch API","集成 React Query","使用 SWR 实现数据抓取","支持错误处理","支持缓存","支持离线支持"],"ja":["Fetch API をサポート","React Query を統合","SWR を使用したデータフェッチ","エラーハンドリングをサポート","キャッシュをサポート","オフラインサポートをサポート"],"ko":["Fetch API 지원","React Query 통합","SWR을 사용한 데이터 가져오기","에러 처리 지원","캐싱 지원","오프라인 지원"],"es":["Implementación de solicitudes de API con Fetch API","Uso de React Query y SWR para el fetching de datos","Soporte para Expo Router data loaders (useLoaderData)","Gestión de errores y caché","Soporte offline para aplicaciones"],"fr":["Mise en œuvre des appels d''API avec Fetch API","Utilisation de React Query et SWR pour le fetching de données","Prise en charge des chargeurs de données Expo Router (useLoaderData)","Gestion des erreurs et de la mise en cache","Prise en charge hors ligne pour les applications"],"de":["Implementierung von API-Anfragen mit Fetch API","Verwendung von React Query und SWR für den Datenabruf","Unterstützung für Expo Router Data-Loader (useLoaderData)","Fehler- und Caching-Management","Offline-Unterstützung für Anwendungen"],"pt":["Implementação de requisições de rede com fetch API","Uso de React Query para gerenciar estado de dados","Integração com Expo Router para carregamento de dados","Suporte a cache e offline","Tratamento de erros e depuração"],"ru":["Реализация сетевых запросов с помощью fetch API","Использование React Query для управления состоянием данных","Интеграция с Expo Router для загрузки данных","Поддержка кэша и offline","Обработка ошибок и отладка"],"ar":["تنفيذ الطلبات الشبكية باستخدام fetch API","استخدام React Query لإدارة حالة البيانات","التكامل مع Expo Router لتحميل البيانات","دعم الذاكرة المؤقتة والاتصال بدون إنترنت","معالجة الأخطاء والاستكشاف"]},"keywords":{"en":["how to use native-data-fetching","native-data-fetching vs React Query","native-data-fetching setup guide","what is native-data-fetching","native-data-fetching alternative to SWR","native-data-fetching install with Expo Router","native-data-fetching error handling","native-data-fetching debugging techniques","native-data-fetching with fetch API","native-data-fetching for data fetching"],"zh":["Native 数据抓取","Fetch API","React Query","SWR","网络请求","数据抓取","错误处理","缓存","离线支持","AIエージェント"],"ja":["ネイティブデータフェッチング","Fetch API","React Query","SWR","ネットワークリクエスト","データフェッチ","エラーハンドリング","キャッシュ","オフラインサポート","AIエージェント"],"ko":["네이티브 데이터 가져오기","Fetch API","React Query","SWR","네트워크 요청","데이터 가져오기","에러 처리","캐싱","오프라인 지원","AI 툴"],"es":["native-data-fetching","solicitudes de API","fetching de datos","React Query","SWR","Expo Router","caché","soporte offline","Herramientas de AI para desarrolladores"],"fr":["native-data-fetching","appels d''API","fetching de données","React Query","SWR","Expo Router","mise en cache","support hors ligne","Outils d''IA pour les développeurs"],"de":["native-data-fetching","API-Anfragen","Datenabruf","React Query","SWR","Expo Router","Caching","Offline-Unterstützung","KI-Tools für Entwickler"],"pt":["native-data-fetching","react query","expo router","fetch api","gerenciamento de estado de dados","cache e offline","tratamento de erros","desenvolvimento de aplicações nativas"],"ru":["native-data-fetching","react query","expo router","fetch api","управление состоянием данных","кэш и offline","обработка ошибок","разработка родных приложений"],"ar":["إدارة البيانات الأصلية","react query","expo router","fetch api","إدارة حالة البيانات","الذاكرة المؤقتة والاتصال بدون إنترنت","معالجة الأخطاء","برمجة التطبيقات الأصلية"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Full-Stack Agents needing advanced native data fetching capabilities with Expo Router and React Query.","zh":"非常适合需要使用Expo Router和React Query进行高级原生数据获取的全栈代理。","ja":"Expo RouterとReact Queryを使用して高度なネイティブデータ取得機能が必要なフルスタックエージェントに最適です。","ko":"Expo Router와 React Query를 사용하여 고급 네이티브 데이터 가져오기 기능이 필요한 풀스택 에이전트에게 적합합니다.","es":"Perfecto para Agentes Full-Stack que necesitan capacidades avanzadas de obtención de datos nativos con Expo Router y React Query.","fr":"Parfait pour les agents Full-Stack nécessitant des capacités de récupération de données natives avancées avec Expo Router et React Query.","de":"Perfekt für Full-Stack-Agents, die erweiterte native Datenabruf-Funktionen mit Expo Router und React Query benötigen.","pt":"Perfeito para Agentes Full-Stack que necessitam de capacidades avançadas de fetch de dados nativos com Expo Router e React Query.","ru":"Идеально для полноценных агентов, которым требуются продвинутые возможности получения данных с помощью Expo Router и React Query.","ar":"مثالي للوكلاء كامل الحزمة الذين يحتاجون إلى إمكانيات متقدمة لاسترجاع البيانات الأصلية مع Expo Router و React Query."},"recommendation":{"en":"Empowers agents to handle fetch API, React Query, SWR, error handling, caching, and offline support, streamlining data fetching and networking tasks with protocols like Expo Router data loaders and useLoaderData.","zh":"赋予代理处理fetch API、React Query、SWR、错误处理、缓存和离线支持的能力，通过协议如Expo Router数据加载器和useLoaderData简化数据获取和网络任务。","ja":"エージェントにfetch API、React Query、SWR、エラーハンドリング、キャッシング、オフラインサポートを処理する能力を与え、Expo RouterデータローダーとuseLoaderDataのようなプロトコルでデータ取得とネットワークタスクを簡素化します。","ko":"에이전트가 fetch API, React Query, SWR, 오류 처리, 캐싱 및 오프라인 지원을 처리할 수 있는 기능을 부여하여 Expo Router 데이터 로더 및 useLoaderData와 같은 프로토콜로 데이터 가져오기 및 네트워크 작업을简化합니다.","es":"Habilita a los agentes a manejar la API de fetch, React Query, SWR, el manejo de errores, la caché y el soporte sin conexión, simplificando las tareas de obtención y red de datos con protocolos como los cargadores de datos de Expo Router y useLoaderData.","fr":"Permet aux agents de gérer la API de fetch, React Query, SWR, la gestion des erreurs, le cache et la prise en charge hors ligne, simplifiant les tâches de récupération et de réseau de données avec des protocoles tels que les chargeurs de données Expo Router et useLoaderData.","de":"Ermächtigt die Agenten, die Fetch-API, React Query, SWR, Fehlerbehandlung, Caching und Offline-Unterstützung zu handhaben, wodurch die Datenabruf- und Netzwerkaufgaben mit Protokollen wie den Datenladern von Expo Router und useLoaderData vereinfacht werden.","pt":"Habilita os agentes a lidar com a API de fetch, React Query, SWR, tratamento de erros, cache e suporte offline, simplificando as tarefas de fetch de dados e rede com protocolos como carregadores de dados do Expo Router e useLoaderData.","ru":"Наделяет агентов возможностью работать с API запросов, React Query, SWR, обработкой ошибок, кэшированием и поддержкой offline, упрощая задачи по получению данных и сетевые задачи с помощью протоколов seperti загрузчики данных Expo Router и useLoaderData.","ar":"يسمح للوكلاء بمعالجة واجهة برمجة التطبيقات لاسترجاع، React Query، SWR، معالجة الأخطاء، الذاكرة المؤقتة، ودعم عدم الاتصال، وبذلك يبسط مهام استرجاع البيانات وشبكة البروتوكولات مثل تحميل بيانات Expo Router و useLoaderData."},"useCases":{"en":["Implementing API requests with fetch API and React Query","Debugging network issues with Expo Router loaders","Setting up caching and offline support with SWR"],"zh":["使用fetch API和React Query实现API请求","使用Expo Router加载器调试网络问题","使用SWR设置缓存和离线支持"],"ja":["fetch APIとReact Queryを使用してAPIリクエストを実装する","Expo Routerローダーを使用してネットワークの問題をデバッグする","SWRを使用してキャッシングとオフラインサポートを設定する"],"ko":["fetch API 및 React Query를 사용하여 API 요청 구현","Expo Router 로더를 사용하여 네트워크 문제 디버깅","SWR을 사용하여 캐싱 및 오프라인 지원 설정"],"es":["Implementar solicitudes de API con la API de fetch y React Query","Depurar problemas de red con los cargadores de Expo Router","Configurar la caché y el soporte sin conexión con SWR"],"fr":["Mettre en œuvre des requêtes API avec la API de fetch et React Query","Déboguer les problèmes de réseau avec les chargeurs Expo Router","Configurer le cache et la prise en charge hors ligne avec SWR"],"de":["Implementierung von API-Anfragen mit der Fetch-API und React Query","Fehlerbehebung bei Netzwerkproblemen mit den Datenladern von Expo Router","Einrichtung von Caching und Offline-Unterstützung mit SWR"],"pt":["Implementar solicitações de API com fetch API e React Query","Depurar problemas de rede com carregadores do Expo Router","Configurar cache e suporte offline com SWR"],"ru":["Реализация запросов API с помощью fetch API и React Query","Отладка сетевых проблем с помощью загрузчиков Expo Router","Настройка кэширования и поддержки offline с помощью SWR"],"ar":["تنفيذ طلبات واجهة برمجة التطبيقات باستخدام fetch API و React Query","تصحيح أخطاء الشبكة باستخدام تحميلات Expo Router","تكوين الذاكرة المؤقتة ودعم عدم الاتصال باستخدام SWR"]},"limitations":{"en":["Requires Expo Router and React Query setup","Limited to web SDK 55+ for Expo Router data loaders"],"zh":["需要Expo Router和React Query设置","仅限于Expo Router数据加载器的Web SDK 55+"],"ja":["Expo RouterとReact Queryの設定が必要","Expo RouterデータローダーのWeb SDK 55+に限定される"],"ko":["Expo Router 및 React Query 설정 필요","Expo Router 데이터 로더의 Web SDK 55+로 제한됨"],"es":["Requiere la configuración de Expo Router y React Query","Limitado al SDK web 55+ para los cargadores de datos de Expo Router"],"fr":["Nécessite la configuration d''Expo Router et React Query","Limité au SDK Web 55+ pour les chargeurs de données Expo Router"],"de":["Benötigt die Einrichtung von Expo Router und React Query","Begrenzt auf Web-SDK 55+ für die Datenlader von Expo Router"],"pt":["Requer configuração do Expo Router e React Query","Limitado ao SDK da web 55+ para carregadores de dados do Expo Router"],"ru":["Требует настройки Expo Router и React Query","Ограничен для веб-SDK 55+ для загрузчиков данных Expo Router"],"ar":["يتطلب إعداد Expo Router و React Query","محدود ل SDK الويب 55+ لتحميل بيانات Expo Router"]},"version":4},"contentHash":"eaa2f00ceed45e3149a9c6b6e1b989413bd1350fd4a256c76d89a60d9dc00026","repoEtag":"W/\"3d0b500324a01c512d7df52a068a135b350d8e49d3ce113161c97e6acbc0dfba\"","qualityScore":88}');
