INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('expo/skills/native-data-fetching', 'native-data-fetching', 'expo', 'skills', 'official', 'native-data-fetching expo skills official The native-data-fetching skill helps developers implement and debug network requests, API calls, and data fetching. It covers fetch API, React Query, SWR, and Expo Router data loaders. Native 数据抓取是一种使用 Fetch API、React Query 和 Expo Router 进行网络请求和数据抓取的技术，支持错误处理、缓存和离线支持 ネイティブデータフェッチングは、Fetch API、React Query、SWR を使用したネットワークリクエストとデータフェッチの実装方法です 네이티브 데이터 가져오기는 Fetch API, React Query, Expo Router를 사용하여 네트워크 요청과 데이터 가져오기를 구현하는 기술입니다 Native-data-fetching es una habilidad para implementar y depurar solicitudes de red y llamadas a API, incluyendo caché y soporte offline Native-data-fetching est une compétence pour mettre en œuvre et déboguer les requêtes réseau et les appels d''API, y compris la mise en cache et le support hors ligne Native-Data-Fetching ist eine Fähigkeit zum Implementieren und Debuggen von Netzwerkanfragen und API-Aufrufen, einschließlich Caching und Offline-Unterstützung native-data-fetching é uma habilidade para implementar e depurar requisições de rede e busca de dados, incluindo React Query e Expo Router. Aprenda a usar fetch API, SWR e muito mais. native-data-fetching - это навык для реализации и отладки сетевых запросов и получения данных, включая React Query и Expo Router. Узнайте, как использовать fetch API, SWR и многое другое. إدارة البيانات الأصلية هي مهارة لتنفيذ واستكشاف الأخطاء في الطلبات الشبكية واسترجاع البيانات، بما في ذلك React Query وExpo Router. تعلم كيفية استخدام fetch API وSWR والمزيد how to use native-data-fetching native-data-fetching vs React Query native-data-fetching setup guide what is native-data-fetching native-data-fetching alternative to SWR native-data-fetching install with Expo Router native-data-fetching error handling native-data-fetching debugging techniques native-data-fetching with fetch API native-data-fetching for data fetching Native 数据抓取 Fetch API React Query SWR 网络请求 数据抓取 错误处理 缓存 离线支持 AIエージェント Supports fetch API for network requests Integrates with React Query for data fetching Utilizes SWR for caching and offline support Works with Expo Router data loaders (useLoaderData) Enables error handling for network requests Provides debugging capabilities for network issues native-data-fetching is a skill for implementing and debugging network requests, API calls, and data fetching in applications, covering technologies like fetch API and React Query.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('obra/superpowers/dispatching-parallel-agents', 'official', 'obra', 'superpowers', 'obra/superpowers', 'dispatching-parallel-agents', 71924, 5546, 86, '2026-03-06T03:26:30Z', '2026-03-06T03:28:47.801Z', 'c628917689ccc12ce9991615db6824d44c4fe71f8427cd959560aebe6a1a6476', '{"id":"obra/superpowers/dispatching-parallel-agents","name":"dispatching-parallel-agents","description":{"en":"The dispatching-parallel-agents skill enables an AI agent to manage multiple independent investigations simultaneously. It is designed for developers and QA engineers facing unrelated failures across different test files or subsystems, drastically reducing investigation time.","zh":"当面对多个无关故障（不同测试文件、子系统或bug）时，使用并行代理调度技术可让每个代理独立并发工作，避免顺序调查的时间浪费。","ja":"複数の無関係な障害（異なるテストファイル、サブシステム、バグ）に直面した時、AIエージェントを並列ディスパッチすることで、各調査を独立して同時実行し、順次処理の時間ロスを防止します。","ko":"서로 관련 없는 여러 장애(다른 테스트 파일, 하위 시스템, 버그)가 있을 때 병렬 에이전트를 디스패치하여 각 조사를 독립적으로 동시 실행함으로써 순차 처리의 시간 낭비를 방지합니다.","es":"Esta habilidad técnica permite despachar múltiples agentes de IA para trabajar concurrentemente en problemas independientes, como diferentes fallos de testing o subsistemas, eliminando la pérdida de tiempo de las investigaciones secuenciales.","fr":"Cette compétence technique permet de dispatcher plusieurs agents IA pour travailler concurremment sur des problèmes indépendants, comme différents bogues de test ou sous-systèmes, éliminant le gaspillage de temps des enquêtes séquentielles.","de":"Diese technische Fähigkeit ermöglicht das Verteilen mehrerer KI-Agents zur gleichzeitigen Bearbeitung unabhängiger Probleme, wie verschiedene Testfehler oder Subsysteme, und eliminiert den Zeitverlust durch sequentielle Untersuchungen.","pt":"Esta skill técnica permite despachar múltiplos AI Agents para trabalhar concurrentemente em problemas independentes, como diferentes arquivos de teste ou subsistemas, eliminando dependências sequenciais e economizando tempo.","ru":"Этот технический навык позволяет запускать несколько ИИ Агентов для параллельной работы над независимыми проблемами, такими как разные тестовые файлы или подсистемы, устраняя последовательные зависимости и экономя время.","ar":"تسمح هذه المهارة التقنية بتوزيع عدة وكلاء ذكاء اصطناعي للعمل بشكل متزامن على مشاكل مستقلة، مثل ملفات اختبار أو أنظمة فرعية مختلفة، مما يلغي التبعيات التسلسلية ويوفر الوقت."},"owner":"obra","repo":"superpowers","repoPath":"obra/superpowers","stars":71924,"forks":5546,"updatedAt":"2026-03-06T03:26:30Z","topics":[],"skillMd":{"name":"dispatching-parallel-agents","description":"Use when facing 2+ independent tasks that can be worked on without shared state or sequential dependencies","bodyPreview":"# Dispatching Parallel Agents\n\n## Overview\n\nWhen you have multiple unrelated failures (different test files, different subsystems, different bugs), investigating them sequentially wastes time. Each investigation is independent and can happen in parallel.\n\n**Core principle:** Dispatch one agent per independent problem domain. Let them work concurrently.\n\n## When to Use\n\n```dot\ndigraph when_to_use {\n    \"Multiple failures?\" [shape=diamond];\n    \"Are they independent?\" [shape=diamond];\n    \"Single","body":"# Dispatching Parallel Agents\n\n## Overview\n\nWhen you have multiple unrelated failures (different test files, different subsystems, different bugs), investigating them sequentially wastes time. Each investigation is independent and can happen in parallel.\n\n**Core principle:** Dispatch one agent per independent problem domain. Let them work concurrently.\n\n## When to Use\n\n```dot\ndigraph when_to_use {\n    \"Multiple failures?\" [shape=diamond];\n    \"Are they independent?\" [shape=diamond];\n    \"Single agent investigates all\" [shape=box];\n    \"One agent per problem domain\" [shape=box];\n    \"Can they work in parallel?\" [shape=diamond];\n    \"Sequential agents\" [shape=box];\n    \"Parallel dispatch\" [shape=box];\n\n    \"Multiple failures?\" -> \"Are they independent?\" [label=\"yes\"];\n    \"Are they independent?\" -> \"Single agent investigates all\" [label=\"no - related\"];\n    \"Are they independent?\" -> \"Can they work in parallel?\" [label=\"yes\"];\n    \"Can they work in parallel?\" -> \"Parallel dispatch\" [label=\"yes\"];\n    \"Can they work in parallel?\" -> \"Sequential agents\" [label=\"no - shared state\"];\n}\n```\n\n**Use when:**\n- 3+ test files failing with different root causes\n- Multiple subsystems broken independently\n- Each problem can be understood without context from others\n- No shared state between investigations\n\n**Don''t use when:**\n- Failures are related (fix one might fix others)\n- Need to understand full system state\n- Agents would interfere with each other\n\n## The Pattern\n\n### 1. Identify Independent Domains\n\nGroup failures by what''s broken:\n- File A tests: Tool approval flow\n- File B tests: Batch completion behavior\n- File C tests: Abort functionality\n\nEach domain is independent - fixing tool approval doesn''t affect abort tests.\n\n### 2. Create Focused Agent Tasks\n\nEach agent gets:\n- **Specific scope:** One test file or subsystem\n- **Clear goal:** Make these tests pass\n- **Constraints:** Don''t change other code\n- **Expected output:** Summary of what you found and fixed\n\n### 3. Dispatch in Parallel\n\n```typescript\n// In Claude Code / AI environment\nTask(\"Fix agent-tool-abort.test.ts failures\")\nTask(\"Fix batch-completion-behavior.test.ts failures\")\nTask(\"Fix tool-approval-race-conditions.test.ts failures\")\n// All three run concurrently\n```\n\n### 4. Review and Integrate\n\nWhen agents return:\n- Read each summary\n- Verify fixes don''t conflict\n- Run full test suite\n- Integrate all changes\n\n## Agent Prompt Structure\n\nGood agent prompts are:\n1. **Focused** - One clear problem domain\n2. **Self-contained** - All context needed to understand the problem\n3. **Specific about output** - What should the agent return?\n\n```markdown\nFix the 3 failing tests in src/agents/agent-tool-abort.test.ts:\n\n1. \"should abort tool with partial output capture\" - expects ''interrupted at'' in message\n2. \"should handle mixed completed and aborted tools\" - fast tool aborted instead of completed\n3. \"should properly track pendingToolCount\" - expects 3 results but gets 0\n\nThese are timing/race condition issues. Your task:\n\n1. Read the test file and understand what each test verifies\n2. Identify root cause - timing issues or actual bugs?\n3. Fix by:\n   - Replacing arbitrary timeouts with event-based waiting\n   - Fixing bugs in abort implementation if found\n   - Adjusting test expectations if testing changed behavior\n\nDo NOT just increase timeouts - find the real issue.\n\nReturn: Summary of what you found and what you fixed.\n```\n\n## Common Mistakes\n\n**❌ Too broad:** \"Fix all the tests\" - agent gets lost\n**✅ Specific:** \"Fix agent-tool-abort.test.ts\" - focused scope\n\n**❌ No context:** \"Fix the race condition\" - agent doesn''t know where\n**✅ Context:** Paste the error messages and test names\n\n**❌ No constraints:** Agent might refactor everything\n**✅ Constraints:** \"Do NOT change production code\" or \"Fix tests only\"\n\n**❌ Vague output:** \"Fix it\" - you don''t know what changed\n**✅ Specific:** \"Return summary of root cause and changes\"\n\n## When NOT to Use\n\n**Related failures:** Fixing one might fix others - investigate together first\n**Need full context:** Understanding requires seeing entire system\n**Exploratory debugging:** You don''t know what''s broken yet\n**Shared state:** Agents would interfere (editing same files, using same resources)\n\n## Real Example from Session\n\n**Scenario:** 6 test failures across 3 files after major refactoring\n\n**Failures:**\n- agent-tool-abort.test.ts: 3 failures (timing issues)\n- batch-completion-behavior.test.ts: 2 failures (tools not executing)\n- tool-approval-race-conditions.test.ts: 1 failure (execution count = 0)\n\n**Decision:** Independent domains - abort logic separate from batch completion separate from race conditions\n\n**Dispatch:**\n```\nAgent 1 → Fix agent-tool-abort.test.ts\nAgent 2 → Fix batch-completion-behavior.test.ts\nAgent 3 → Fix tool-approval-race-conditions.test.ts\n```\n\n**Results:**\n- Agent 1: Replaced timeouts with event-based waiting\n- Agent 2: Fixed event structure bug (threadId in wrong place)\n- Agent 3: Added wait for async tool execution to complete\n\n**Integration:** All fixes independent, no conflicts, full suite green\n\n**Time saved:** 3 problems solved in parallel vs sequentially\n\n## Key Benefits\n\n1. **Parallelization** - Multiple investigations happen simultaneously\n2. **Focus** - Each agent has narrow scope, less context to track\n3. **Independence** - Agents don''t interfere with each other\n4. **Speed** - 3 problems solved in time of 1\n\n## Verification\n\nAfter agents return:\n1. **Review each summary** - Understand what changed\n2. **Check for conflicts** - Did agents edit same code?\n3. **Run full suite** - Verify all fixes work together\n4. **Spot check** - Agents can make systematic errors\n\n## Real-World Impact\n\nFrom debugging session (2025-10-03):\n- 6 failures across 3 files\n- 3 agents dispatched in parallel\n- All investigations completed concurrently\n- All fixes integrated successfully\n- Zero conflicts between agent changes\n"},"category":"official","lastSynced":"2026-03-06T03:28:47.801Z","seo":{"title":{"en":"dispatching-parallel-agents: Concurrent Failure Investiga...","zh":"并行AI代理调度指南：独立任务并发处理最佳实践","ja":"AIエージェント並列ディスパッチ実装ガイド：独立タスクの効率化","ko":"병렬 AI 에이전트 디스패칭 가이드: 독립 작업 동시 처리 최적화","es":"Agentes Paralelos: Guía de Implementación para Tareas Ind...","fr":"Agents Parallèles : Guide de Configuration pour Tâches In...","de":"Parallele Agents: Setup-Anleitung für unabhängige Aufgaben","pt":"Dispatching Parallel Agents: Guia de Implementação para T...","ru":"Dispatching Parallel Agents: Руководство по распараллелив...","ar":"Dispatching Parallel Agents: دليل إعداد وكيل الذكاء الاصط..."},"description":{"en":"Stop wasting time on sequential debugging. This AI agent skill dispatches parallel agents to independently investigate multiple, unrelated failures concurren...","zh":"学习如何调度并行AI代理处理多个独立故障。适用于不同测试文件、子系统或bug的并发调查，避免顺序处理的时间浪费，提高开发效率。","ja":"複数の独立した障害（テストファイル、サブシステム、バグ）を並列調査するAIエージェントのディスパッチ方法。順次処理の時間ロスを排除し開発効率を向上。","ko":"다른 테스트 파일, 하위 시스템, 버그 등 여러 독립적 장애를 동시 조사하는 병렬 AI 에이전트 디스패칭 기술. 순차 처리 시간 낭비 방지 및 개발 효율 향상.","es":"Aprende a implementar agentes de IA en paralelo para múltiples tareas independientes sin estado compartido. Mejora la eficiencia en la resolución de fallos d...","fr":"Apprenez à déployer des agents IA en parallèle pour plusieurs tâches indépendantes sans état partagé. Augmentez l''efficacité du débogage de fichiers de test ...","de":"Erfahren Sie, wie Sie KI-Agents parallel für mehrere unabhängige Aufgaben ohne gemeinsamen Status einsetzen. Steigern Sie die Effizienz bei der Fehlerbehebun...","pt":"Aprenda a usar a skill dispatching-parallel-agents para executar tarefas independentes em paralelo, como testes ou debugging, acelerando fluxos de trabalho d...","ru":"Узнайте, как использовать навык dispatching-parallel-agents для параллельного выполнения независимых задач, таких как тестирование или отладка, ускоряя рабоч...","ar":"تعلم كيفية استخدام أداة dispatching-parallel-agents لتشغيل مهام مستقلة بالتوازي، مثل اختبارات أو تصحيح أخطاء مختلفة، لتسريع سير عمل التطوير."},"definition":{"en":"dispatching-parallel-agents is an AI agent skill for managing concurrent workflows. It operates on the core principle of dispatching one agent per independent problem domain, allowing them to work in parallel on tasks without shared state or sequential dependencies.","zh":"并行代理调度是一种技术方法，当存在两个以上无需共享状态或顺序依赖的独立任务时，为每个问题域分配一个代理并发执行。核心原则是让代理同时工作，避免顺序处理的时间浪费。","ja":"ディスパッチング・パラレル・エージェントは、共有状態や順次依存性が必要ない2つ以上の独立タスクがある場合、各問題領域に1つのAIエージェントを割り当て並列実行する技術です。核心原則はエージェントを同時に動作させ、順次処理の時間ロスを防ぐことです。","ko":"디스패칭 병렬 에이전트는 공유 상태나 순차적 종속성이 필요 없는 2개 이상의 독립적 작업이 있을 때 각 문제 영역별로 하나의 에이전트를 할당하여 동시에 실행하는 기술입니다. 핵심 원리는 에이전트를 동시에 작동시켜 순차 처리의 시간 낭비를 방지하는 것입니다.","es":"Dispatching Parallel Agents es una técnica de desarrollo donde se despliegan múltiples agentes de IA para trabajar de forma concurrente en tareas independientes que no comparten estado ni tienen dependencias secuenciales, optimizando el tiempo de investigación y resolución de problemas.","fr":"Dispatching Parallel Agents est une technique de développement où plusieurs agents IA sont déployés pour travailler concurremment sur des tâches indépendantes sans état partagé ni dépendances séquentielles, optimisant le temps d''investigation et de résolution de problèmes.","de":"Dispatching Parallel Agents ist eine Entwicklungstechnik, bei der mehrere KI-Agents eingesetzt werden, um gleichzeitig an unabhängigen Aufgaben ohne gemeinsamen Status oder sequentielle Abhängigkeiten zu arbeiten, was die Untersuchungs- und Problemlösungszeit optimiert.","pt":"Dispatching Parallel Agents é uma técnica de orquestração de AI Agents que envolve lançar um agente por domínio de problema independente para trabalhar concorrentemente, ideal quando não há estado compartilhado ou dependências sequenciais entre tarefas.","ru":"Dispatching Parallel Agents — это техника оркестровки ИИ Агентов, которая involves запуск одного агента на каждую независимую проблемную область для concurrent работы, идеально когда нет общего состояния или sequential зависимостей между задачами.","ar":"Dispatching Parallel Agents هي تقنية تنظيم لوكلاء الذكاء الاصطناعي تتضمن إطلاق وكيل لكل مجال مشكلة مستقل للعمل بشكل متزامن، ideal عندما لا توجد حالة مشتركة أو تبعيات تسلسلية بين المهام."},"features":{"en":["Dispatches one agent per independent problem domain for concurrent execution","Designed for investigating multiple unrelated failures across different test files","Optimized for scenarios involving different subsystems or different bugs","Eliminates time wasted on sequential investigation of independent tasks"],"zh":["为每个独立问题域分配专用代理","处理不同测试文件的并发故障调查","支持多个子系统的并行bug分析","无需共享状态或顺序依赖的并发执行","避免顺序调查造成的时间浪费","基于独立性问题识别的调度决策"],"ja":["各独立問題領域専用のAIエージェント割り当て","異なるテストファイルの同時故障調査対応","複数サブシステムの並列バグ分析サポート","共有状態や順次依存性不要の並列実行","順次調査による時間ロスの排除","独立性識別に基づくディスパッチ判断"],"ko":["각 독립 문제 영역 전용 에이전트 할당","다른 테스트 파일의 동시 장애 조사 처리","다중 하위 시스템 병렬 버그 분석 지원","공유 상태나 순차 종속성 불필요한 동시 실행","순차 조사로 인한 시간 낭비 방지","독립성 식별 기반 디스패칭 결정"],"es":["Despacho de un agente por dominio de problema independiente","Ejecución concurrente para múltiples fallos no relacionados","Elimina dependencias de estado compartido entre tareas","Optimizado para investigar diferentes archivos de test y subsistemas en paralelo","Principio central: Trabajo concurrente en dominios de problema independientes","Evita la pérdida de tiempo de las investigaciones secuenciales"],"fr":["Dispatch d''un agent par domaine problématique indépendant","Exécution concurrente pour multiples défaillances non liées","Élimine les dépendances d''état partagé entre les tâches","Optimisé pour investiguer différents fichiers de test et sous-systèmes en parallèle","Principe central : Travail concurrent sur des domaines problématiques indépendants","Évite le gaspillage de temps des enquêtes séquentielles"],"de":["Verteilung eines Agents pro unabhängiger Problemdomäne","Gleichzeitige Ausführung für mehrere nicht zusammenhängende Fehler","Beseitigt Abhängigkeiten von gemeinsam genutztem Status zwischen Aufgaben","Optimiert für die parallele Untersuchung verschiedener Testdateien und Subsysteme","Kernprinzip: Gleichzeitige Arbeit an unabhängigen Problemdomänen","Vermeidet Zeitverlust durch sequentielle Untersuchungen"],"pt":["Despacho de um agente por domínio de problema independente","Execução concorrente para investigar múltiplas falhas simultaneamente","Elimina o desperdício de tempo de investigações sequenciais","Aplicável a diferentes arquivos de teste e subsistemas","Opera sem a necessidade de estado compartilhado entre agents","Evita dependências sequenciais entre tarefas"],"ru":["Запуск одного агента на каждую независимую проблемную область","Concurrent выполнение для исследования нескольких сбоев одновременно","Устраняет потерю времени на sequential расследования","Применимо к разным тестовым файлам и подсистемам","Работает без необходимости общего состояния между агентами","Избегает sequential зависимостей между задачами"],"ar":["إطلاق وكيل واحد لكل مجال مشكلة مستقل","تنفيذ متزامن للتحقيق في أعطال متعددة في وقت واحد","يقضي على إهدار الوقت في التحقيقات التسلسلية","ينطبق على ملفات اختبار وأنظمة فرعية مختلفة","يعمل بدون الحاجة إلى حالة مشتركة بين الوكلاء","يتجنب التبعيات التسلسلية بين المهام"]},"keywords":{"en":["what is dispatching-parallel-agents","how to use dispatching-parallel-agents for parallel tasks","dispatching-parallel-agents vs sequential debugging","dispatching-parallel-agents for independent failures","dispatching-parallel-agents setup guide","AI agent parallel execution skill","concurrent agent dispatch","investigating multiple test files with AI agents"],"zh":["并行AI代理调度","独立任务并发处理","多故障并行调查","AI代理并发编程","无共享状态任务处理","测试文件并行分析","子系统并发调试","并行代理最佳实践"],"ja":["AIエージェント並列ディスパッチ","独立タスク並列処理","複数障害同時調査","AIエージェント並列プログラミング","共有状態不要タスク処理","テストファイル並列分析","サブシステム並列デバッグ","並列エージェントベストプラクティス"],"ko":["병렬 AI 에이전트 디스패칭","독립 작업 동시 처리","다중 장애 병렬 조사","AI 에이전트 동시성 프로그래밍","공유 상태 불필요 작업 처리","테스트 파일 병렬 분석","하위 시스템 동시 디버깅","병렬 에이전트 최적화 방법"],"es":["agentes de IA en paralelo","despachar agentes concurrentes","tareas independientes sin estado compartido","investigación de fallos de testing en paralelo","optimización de tiempo de debugging","subsistemas independientes IA","arquitectura de agentes paralelos","concurrencia en agentes de IA"],"fr":["agents IA en parallèle","dispatcher agents concurrents","tâches indépendantes sans état partagé","investigation de bogues de test en parallèle","optimisation temps débogage","sous-systèmes indépendants IA","architecture agents parallèles","concurrence agents IA"],"de":["KI-Agents parallel einsetzen","gleichzeitige Agents verteilen","unabhängige Aufgaben ohne gemeinsamen Status","Testfehler parallel untersuchen","Debugging-Zeit optimieren","unabhängige Subsysteme KI","Architektur paralleler Agents","Nebenläufigkeit KI-Agents"],"pt":["dispatching parallel agents","ai agents paralelos","tarefas independentes concorrentes","despacho de agentes","investigação de falhas em paralelo","testes paralelos ai agent","otimização de tempo desenvolvimento","arquitetura sem estado compartilhado"],"ru":["dispatching parallel agents","параллельные ИИ Агенты","независимые concurrent задачи","оркестровка агентов","расследование сбоев параллельно","параллельное тестирование ИИ Агентов","оптимизация времени разработки","архитектура без общего состояния"],"ar":["dispatching parallel agents","وكلاء الذكاء الاصطناعي المتوازي","مهام مستقلة متزامنة","توزيع الوكلاء","تحقيق أعطال بالتوازي","اختبارات متوازية بواسطة وكيل","تحسين وقت التطوير","هندسة بدون حالة مشتركة"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Debugging and Analysis Agents needing to accelerate root cause investigation across multiple independent failures.","zh":"非常适合需要加速跨多个独立故障的根本原因调查的调试和分析Agent。","ja":"複数の独立した障害にわたる根本原因調査を加速する必要があるデバッグおよび分析Agentに最適です。","ko":"다중 독립적 장애에 걸친 근본 원인 조사를 가속화해야 하는 디버깅 및 분석 에이전트에 완벽하게 적합합니다.","es":"Perfecto para agentes de depuración y análisis que necesitan acelerar la investigación de la causa raíz a través de múltiples fallos independientes.","fr":"Parfait pour les agents de débogage et d''analyse ayant besoin d''accélérer l''investigation de la cause première à travers de multiples défaillances indépendantes.","de":"Perfekt für Debugging- und Analyse-Agents, die die Untersuchung der Ursache über mehrere unabhängige Fehler hinweg beschleunigen müssen.","pt":"Perfeito para Agentes de Debugging e Análise que precisam acelerar a investigação de causa raiz em múltiplas falhas independentes.","ru":"Идеально подходит для Агентов Отладки и Анализа, которым необходимо ускорить исследование первопричин множественных независимых сбоев.","ar":"مثالي لوكلاء التصحيح والتحليل الذين يحتاجون إلى تسريع التحقيق في السبب الجذري عبر أعطال متعددة مستقلة."},"recommendation":{"en":"Enables concurrent execution of multiple independent investigations by dispatching specialized agents to work in parallel. Eliminates sequential bottlenecks when dealing with unrelated test failures, subsystem bugs, or distinct problem domains without shared state dependencies.","zh":"通过派遣专门的Agent并行工作，实现多个独立调查的并发执行。在处理不相关的测试故障、子系统错误或没有共享状态依赖关系的不同问题域时，消除了顺序瓶颈。","ja":"専門のAgentを並行して動作させるようにディスパッチすることで、複数の独立した調査の同時実行を可能にします。共有状態の依存関係がない無関係なテスト障害、サブシステムのバグ、または異なる問題領域を扱う際の順次的なボトルネックを排除します。","ko":"전문화된 에이전트를 병렬로 작업하도록 디스패치하여 다수의 독립적 조사를 동시에 실행할 수 있게 합니다. 공유 상태 종속성이 없는 관련 없는 테스트 실패, 서브시스템 버그 또는 distinct 문제 영역을 다룰 때 순차적 병목 현상을 제거합니다.","es":"Permite la ejecución concurrente de múltiples investigaciones independientes mediante el envío de agentes especializados para trabajar en paralelo. Elimina los cuellos de botella secuenciales al tratar con fallos de prueba no relacionados, errores de subsistemas o dominios de problemas distintos sin dependencias de estado compartido.","fr":"Permet l''exécution concurrente de multiples investigations indépendantes en dispatchant des agents spécialisés pour travailler en parallèle. Élimine les goulots d''étranglement séquentiels lors du traitement de défaillances de test non liées, de bogues de sous-systèmes ou de domaines de problèmes distincts sans dépendances d''état partagé.","de":"Ermöglicht die gleichzeitige Ausführung mehrerer unabhängiger Untersuchungen, indem spezialisierte Agents parallel arbeiten. Beseitigt sequenzielle Engpässe beim Umgang mit nicht verwandten Testfehlern, Subsystem-Bugs oder unterschiedlichen Problemdomänen ohne gemeinsame Zustandsabhängigkeiten.","pt":"Permite a execução concorrente de múltiplas investigações independentes, despachando agentes especializados para trabalhar em paralelo. Elimina gargalos sequenciais ao lidar com falhas de teste não relacionadas, bugs de subsistema ou domínios de problema distintos sem dependências de estado compartilhado.","ru":"Обеспечивает параллельное выполнение множественных независимых исследований путем распределения специализированных агентов для работы параллельно. Устраняет последовательные узкие места при работе с несвязанными сбоями тестов, ошибками подсистем или различными проблемными областями без зависимостей общего состояния.","ar":"يتيح التنفيذ المتزامن للتحقيقات المستقلة المتعددة من خلال إرسال وكلاء متخصصين للعمل بشكل متوازي. يزيل الاختناقات التسلسلية عند التعامل مع أعطال اختبار غير مرتبطة، أو أخطاء في النظم الفرعية، أو مجالات مشكلة متميزة بدون تبعيات حالة مشتركة."},"useCases":{"en":["Debugging multiple unrelated test failures simultaneously","Investigating independent subsystem bugs concurrently","Parallelizing root cause analysis across distinct problem domains","Accelerating triage of multiple independent production incidents"],"zh":["同时调试多个不相关的测试故障","并发调查独立的子系统错误","跨不同问题域并行化根本原因分析","加速多个独立生产事件的分类"],"ja":["複数の無関係なテスト障害の同時デバッグ","独立したサブシステムのバグの並行調査","異なる問題領域にわたる根本原因分析の並列化","複数の独立した生産インシデントのトリアージの加速"],"ko":["여러 개의 관련 없는 테스트 실패를 동시에 디버깅","독립적인 서브시스템 버그 동시 조사","서로 다른 문제 영역에 걸친 근본 원인 분석의 병렬화","다수의 독립적 프로덕션 인시던트 트라이아지 가속화"],"es":["Depurar múltiples fallos de prueba no relacionados simultáneamente","Investigar errores de subsistemas independientes de forma concurrente","Paralelizar el análisis de causa raíz en distintos dominios de problemas","Acelerar la clasificación de múltiples incidentes de producción independientes"],"fr":["Déboguer simultanément de multiples défaillances de test non liées","Investiguer concurremment des bogues de sous-systèmes indépendants","Paralléliser l''analyse de cause première sur des domaines de problèmes distincts","Accélérer la triage de multiples incidents de production indépendants"],"de":["Gleichzeitiges Debuggen mehrerer nicht verwandter Testfehler","Gleichzeitige Untersuchung unabhängiger Subsystem-Bugs","Parallelisierung der Ursachenanalyse über verschiedene Problemdomänen hinweg","Beschleunigung der Priorisierung mehrerer unabhängiger Produktionsvorfälle"],"pt":["Debugging de múltiplas falhas de teste não relacionadas simultaneamente","Investigação de bugs independentes de subsistema de forma concorrente","Paralelização da análise de causa raiz em domínios de problema distintos","Aceleração do triagem de múltiplos incidentes de produção independentes"],"ru":["Отладка множественных несвязанных сбоев тестов одновременно","Параллельное исследование независимых ошибок подсистем","Распараллеливание анализа первопричин в различных проблемных областях","Ускорение сортировки множественных независимых производственных инцидентов"],"ar":["تصحيح أعطال اختبار متعددة غير مرتبطة في وقت واحد","التحقيق في أخطاء النظم الفرعية المستقلة بشكل متزامن","توازي تحليل السبب الجذري عبر مجالات مشكلة متميزة","تسريع فرز حوادث الإنتاج المتعددة المستقلة"]},"limitations":{"en":["Requires independent tasks without shared state dependencies","Ineffective for sequential or interdependent problem chains","Assumes agent ecosystem supports concurrent execution"],"zh":["需要没有共享状态依赖关系的独立任务","对顺序或相互依赖的问题链无效","假设Agent生态系统支持并发执行"],"ja":["共有状態の依存関係がない独立したタスクが必要","順次的または相互依存的な問題チェーンには効果がない","Agentエコシステムが同時実行をサポートしていることを前提とする"],"ko":["공유 상태 종속성이 없는 독립적 작업이 필요함","순차적 또는 상호 의존적인 문제 체인에는 효과적이지 않음","에이전트 생태계가 동시 실행을 지원한다고 가정"],"es":["Requiere tareas independientes sin dependencias de estado compartido","Inefectivo para cadenas de problemas secuenciales o interdependientes","Asume que el ecosistema de agentes admite la ejecución concurrente"],"fr":["Nécessite des tâches indépendantes sans dépendances d''état partagé","Inefficace pour les chaînes de problèmes séquentielles ou interdépendantes","Suppose que l''écosystème d''agents prend en charge l''exécution concurrente"],"de":["Erfordert unabhängige Aufgaben ohne gemeinsame Zustandsabhängigkeiten","Unwirksam für sequentielle oder voneinander abhängige Problemketten","Setzt voraus, dass das Agent-Ökosystem die gleichzeitige Ausführung unterstützt"],"pt":["Requer tarefas independentes sem dependências de estado compartilhado","Ineficaz para cadeias de problemas sequenciais ou interdependentes","Assume que o ecossistema de agentes suporta execução concorrente"],"ru":["Требует независимых задач без зависимостей общего состояния","Неэффективен для последовательных или взаимозависимых цепочек проблем","Предполагает, что экосистема агентов поддерживает параллельное выполнение"],"ar":["يتطلب مهام مستقلة بدون تبعيات حالة مشتركة","غير فعال للسلاسل المتسلسلة أو المترابطة من المشاكل","يفترض أن نظام الوكلاء يدعم التنفيذ المتزامن"]},"version":4},"contentHash":"c628917689ccc12ce9991615db6824d44c4fe71f8427cd959560aebe6a1a6476","repoEtag":"W/\"a8a266458ca9bbf6c9312a7647f733e0f1891eedfa2dde0bddcec7f7d186089e\"","qualityScore":86}');
