INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('obra/superpowers/dispatching-parallel-agents', 'dispatching-parallel-agents', 'obra', 'superpowers', 'official', 'dispatching-parallel-agents obra superpowers official The dispatching-parallel-agents skill enables an AI agent to manage multiple independent investigations simultaneously. It is designed for developers and QA engineers facing unrelated failures across different test files or subsystems, drastically reducing investigation time. 当面对多个无关故障（不同测试文件、子系统或bug）时，使用并行代理调度技术可让每个代理独立并发工作，避免顺序调查的时间浪费。 複数の無関係な障害（異なるテストファイル、サブシステム、バグ）に直面した時、AIエージェントを並列ディスパッチすることで、各調査を独立して同時実行し、順次処理の時間ロスを防止します。 서로 관련 없는 여러 장애(다른 테스트 파일, 하위 시스템, 버그)가 있을 때 병렬 에이전트를 디스패치하여 각 조사를 독립적으로 동시 실행함으로써 순차 처리의 시간 낭비를 방지합니다. Esta habilidad técnica permite despachar múltiples agentes de IA para trabajar concurrentemente en problemas independientes, como diferentes fallos de testing o subsistemas, eliminando la pérdida de tiempo de las investigaciones secuenciales. Cette compétence technique permet de dispatcher plusieurs agents IA pour travailler concurremment sur des problèmes indépendants, comme différents bogues de test ou sous-systèmes, éliminant le gaspillage de temps des enquêtes séquentielles. Diese technische Fähigkeit ermöglicht das Verteilen mehrerer KI-Agents zur gleichzeitigen Bearbeitung unabhängiger Probleme, wie verschiedene Testfehler oder Subsysteme, und eliminiert den Zeitverlust durch sequentielle Untersuchungen. Esta skill técnica permite despachar múltiplos AI Agents para trabalhar concurrentemente em problemas independentes, como diferentes arquivos de teste ou subsistemas, eliminando dependências sequenciais e economizando tempo. Этот технический навык позволяет запускать несколько ИИ Агентов для параллельной работы над независимыми проблемами, такими как разные тестовые файлы или подсистемы, устраняя последовательные зависимости и экономя время. تسمح هذه المهارة التقنية بتوزيع عدة وكلاء ذكاء اصطناعي للعمل بشكل متزامن على مشاكل مستقلة، مثل ملفات اختبار أو أنظمة فرعية مختلفة، مما يلغي التبعيات التسلسلية ويوفر الوقت. what is dispatching-parallel-agents how to use dispatching-parallel-agents for parallel tasks dispatching-parallel-agents vs sequential debugging dispatching-parallel-agents for independent failures dispatching-parallel-agents setup guide AI agent parallel execution skill concurrent agent dispatch investigating multiple test files with AI agents 并行AI代理调度 独立任务并发处理 多故障并行调查 AI代理并发编程 无共享状态任务处理 测试文件并行分析 子系统并发调试 并行代理最佳实践 Dispatches one agent per independent problem domain for concurrent execution Designed for investigating multiple unrelated failures across different test files Optimized for scenarios involving different subsystems or different bugs Eliminates time wasted on sequential investigation of independent tasks dispatching-parallel-agents is an AI agent skill for managing concurrent workflows. It operates on the core principle of dispatching one agent per independent problem domain, allowing them to work in parallel on tasks without shared state or sequential dependencies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('obra/superpowers/subagent-driven-development', 'official', 'obra', 'superpowers', 'obra/superpowers', 'subagent-driven-development', 71924, 5546, 86, '2026-03-06T03:26:30Z', '2026-03-06T03:33:08.267Z', '994b89a5d294eadd6a1611edb51377bac748d5f5fb7f4139d3c736b616b3a46a', '{"id":"obra/superpowers/subagent-driven-development","name":"subagent-driven-development","description":{"en":"The subagent-driven-development skill executes implementation plans by dispatching a new subagent per independent task within the current session. It enforces a two-stage review process, first for spec compliance and then for code quality, ensuring high-fidelity output for developers.","zh":"子代理驱动开发是一种通过分配新子代理来执行独立任务的开发方法，具有两阶段审查机制","ja":"サブエージェント駆動開発は、独立したタスクを新しいサブエージェントに割り当てることで実現する開発方法で、二段階のレビューが特徴","ko":"서브 에이전트 주도 개발은 독립적인 태스크를 새로운 서브 에이전트에 할당하여 개발하는 방법으로, 2단계 리뷰 프로세스를 갖추고 있습니다","es":"Desarrollo dirigido por subagentes es una técnica que ejecuta planes de implementación con tareas independientes en la sesión actual, utilizando subagentes frescos por tarea y revisiones de dos etapas","fr":"Le développement piloté par subagents est une technique qui exécute des plans de mise en œuvre avec des tâches indépendantes dans la session actuelle, en utilisant des subagents frais par tâche et des examens en deux étapes","de":"Die subagenten-gesteuerte Entwicklung ist eine Technik, die Implementierungspläne mit unabhängigen Aufgaben in der aktuellen Sitzung ausführt, indem sie frische Subagenten pro Aufgabe und zweistufige Überprüfungen verwendet","pt":"O desenvolvimento dirigido por subagentes executa planos usando subagentes frescos por tarefa com revisões de duas etapas para garantir alta qualidade e iteração rápida","ru":"Разработка на основе субагентов выполняет планы, используя свежих субагентов для каждой задачи с двухэтапными проверками для обеспечения высокого качества и быстрой итерации","ar":"التطوير الموجه بالوسيط الفرعي ينفذ الخطط باستخدام وكلاء فرعيون جدد لكل مهمة مع مراجعات مرحلتين لضمان الجودة العالية والتحديث السريع"},"owner":"obra","repo":"superpowers","repoPath":"obra/superpowers","stars":71924,"forks":5546,"updatedAt":"2026-03-06T03:26:30Z","topics":[],"skillMd":{"name":"subagent-driven-development","description":"Use when executing implementation plans with independent tasks in the current session","bodyPreview":"# Subagent-Driven Development\n\nExecute plan by dispatching fresh subagent per task, with two-stage review after each: spec compliance review first, then code quality review.\n\n**Core principle:** Fresh subagent per task + two-stage review (spec then quality) = high quality, fast iteration\n\n## When to Use\n\n```dot\ndigraph when_to_use {\n    \"Have implementation plan?\" [shape=diamond];\n    \"Tasks mostly independent?\" [shape=diamond];\n    \"Stay in this session?\" [shape=diamond];\n    \"subagent-driven-d","body":"# Subagent-Driven Development\n\nExecute plan by dispatching fresh subagent per task, with two-stage review after each: spec compliance review first, then code quality review.\n\n**Core principle:** Fresh subagent per task + two-stage review (spec then quality) = high quality, fast iteration\n\n## When to Use\n\n```dot\ndigraph when_to_use {\n    \"Have implementation plan?\" [shape=diamond];\n    \"Tasks mostly independent?\" [shape=diamond];\n    \"Stay in this session?\" [shape=diamond];\n    \"subagent-driven-development\" [shape=box];\n    \"executing-plans\" [shape=box];\n    \"Manual execution or brainstorm first\" [shape=box];\n\n    \"Have implementation plan?\" -> \"Tasks mostly independent?\" [label=\"yes\"];\n    \"Have implementation plan?\" -> \"Manual execution or brainstorm first\" [label=\"no\"];\n    \"Tasks mostly independent?\" -> \"Stay in this session?\" [label=\"yes\"];\n    \"Tasks mostly independent?\" -> \"Manual execution or brainstorm first\" [label=\"no - tightly coupled\"];\n    \"Stay in this session?\" -> \"subagent-driven-development\" [label=\"yes\"];\n    \"Stay in this session?\" -> \"executing-plans\" [label=\"no - parallel session\"];\n}\n```\n\n**vs. Executing Plans (parallel session):**\n- Same session (no context switch)\n- Fresh subagent per task (no context pollution)\n- Two-stage review after each task: spec compliance first, then code quality\n- Faster iteration (no human-in-loop between tasks)\n\n## The Process\n\n```dot\ndigraph process {\n    rankdir=TB;\n\n    subgraph cluster_per_task {\n        label=\"Per Task\";\n        \"Dispatch implementer subagent (./implementer-prompt.md)\" [shape=box];\n        \"Implementer subagent asks questions?\" [shape=diamond];\n        \"Answer questions, provide context\" [shape=box];\n        \"Implementer subagent implements, tests, commits, self-reviews\" [shape=box];\n        \"Dispatch spec reviewer subagent (./spec-reviewer-prompt.md)\" [shape=box];\n        \"Spec reviewer subagent confirms code matches spec?\" [shape=diamond];\n        \"Implementer subagent fixes spec gaps\" [shape=box];\n        \"Dispatch code quality reviewer subagent (./code-quality-reviewer-prompt.md)\" [shape=box];\n        \"Code quality reviewer subagent approves?\" [shape=diamond];\n        \"Implementer subagent fixes quality issues\" [shape=box];\n        \"Mark task complete in TodoWrite\" [shape=box];\n    }\n\n    \"Read plan, extract all tasks with full text, note context, create TodoWrite\" [shape=box];\n    \"More tasks remain?\" [shape=diamond];\n    \"Dispatch final code reviewer subagent for entire implementation\" [shape=box];\n    \"Use superpowers:finishing-a-development-branch\" [shape=box style=filled fillcolor=lightgreen];\n\n    \"Read plan, extract all tasks with full text, note context, create TodoWrite\" -> \"Dispatch implementer subagent (./implementer-prompt.md)\";\n    \"Dispatch implementer subagent (./implementer-prompt.md)\" -> \"Implementer subagent asks questions?\";\n    \"Implementer subagent asks questions?\" -> \"Answer questions, provide context\" [label=\"yes\"];\n    \"Answer questions, provide context\" -> \"Dispatch implementer subagent (./implementer-prompt.md)\";\n    \"Implementer subagent asks questions?\" -> \"Implementer subagent implements, tests, commits, self-reviews\" [label=\"no\"];\n    \"Implementer subagent implements, tests, commits, self-reviews\" -> \"Dispatch spec reviewer subagent (./spec-reviewer-prompt.md)\";\n    \"Dispatch spec reviewer subagent (./spec-reviewer-prompt.md)\" -> \"Spec reviewer subagent confirms code matches spec?\";\n    \"Spec reviewer subagent confirms code matches spec?\" -> \"Implementer subagent fixes spec gaps\" [label=\"no\"];\n    \"Implementer subagent fixes spec gaps\" -> \"Dispatch spec reviewer subagent (./spec-reviewer-prompt.md)\" [label=\"re-review\"];\n    \"Spec reviewer subagent confirms code matches spec?\" -> \"Dispatch code quality reviewer subagent (./code-quality-reviewer-prompt.md)\" [label=\"yes\"];\n    \"Dispatch code quality reviewer subagent (./code-quality-reviewer-prompt.md)\" -> \"Code quality reviewer subagent approves?\";\n    \"Code quality reviewer subagent approves?\" -> \"Implementer subagent fixes quality issues\" [label=\"no\"];\n    \"Implementer subagent fixes quality issues\" -> \"Dispatch code quality reviewer subagent (./code-quality-reviewer-prompt.md)\" [label=\"re-review\"];\n    \"Code quality reviewer subagent approves?\" -> \"Mark task complete in TodoWrite\" [label=\"yes\"];\n    \"Mark task complete in TodoWrite\" -> \"More tasks remain?\";\n    \"More tasks remain?\" -> \"Dispatch implementer subagent (./implementer-prompt.md)\" [label=\"yes\"];\n    \"More tasks remain?\" -> \"Dispatch final code reviewer subagent for entire implementation\" [label=\"no\"];\n    \"Dispatch final code reviewer subagent for entire implementation\" -> \"Use superpowers:finishing-a-development-branch\";\n}\n```\n\n## Prompt Templates\n\n- `./implementer-prompt.md` - Dispatch implementer subagent\n- `./spec-reviewer-prompt.md` - Dispatch spec compliance reviewer subagent\n- `./code-quality-reviewer-prompt.md` - Dispatch code quality reviewer subagent\n\n## Example Workflow\n\n```\nYou: I''m using Subagent-Driven Development to execute this plan.\n\n[Read plan file once: docs/plans/feature-plan.md]\n[Extract all 5 tasks with full text and context]\n[Create TodoWrite with all tasks]\n\nTask 1: Hook installation script\n\n[Get Task 1 text and context (already extracted)]\n[Dispatch implementation subagent with full task text + context]\n\nImplementer: \"Before I begin - should the hook be installed at user or system level?\"\n\nYou: \"User level (~/.config/superpowers/hooks/)\"\n\nImplementer: \"Got it. Implementing now...\"\n[Later] Implementer:\n  - Implemented install-hook command\n  - Added tests, 5/5 passing\n  - Self-review: Found I missed --force flag, added it\n  - Committed\n\n[Dispatch spec compliance reviewer]\nSpec reviewer: ✅ Spec compliant - all requirements met, nothing extra\n\n[Get git SHAs, dispatch code quality reviewer]\nCode reviewer: Strengths: Good test coverage, clean. Issues: None. Approved.\n\n[Mark Task 1 complete]\n\nTask 2: Recovery modes\n\n[Get Task 2 text and context (already extracted)]\n[Dispatch implementation subagent with full task text + context]\n\nImplementer: [No questions, proceeds]\nImplementer:\n  - Added verify/repair modes\n  - 8/8 tests passing\n  - Self-review: All good\n  - Committed\n\n[Dispatch spec compliance reviewer]\nSpec reviewer: ❌ Issues:\n  - Missing: Progress reporting (spec says \"report every 100 items\")\n  - Extra: Added --json flag (not requested)\n\n[Implementer fixes issues]\nImplementer: Removed --json flag, added progress reporting\n\n[Spec reviewer reviews again]\nSpec reviewer: ✅ Spec compliant now\n\n[Dispatch code quality reviewer]\nCode reviewer: Strengths: Solid. Issues (Important): Magic number (100)\n\n[Implementer fixes]\nImplementer: Extracted PROGRESS_INTERVAL constant\n\n[Code reviewer reviews again]\nCode reviewer: ✅ Approved\n\n[Mark Task 2 complete]\n\n...\n\n[After all tasks]\n[Dispatch final code-reviewer]\nFinal reviewer: All requirements met, ready to merge\n\nDone!\n```\n\n## Advantages\n\n**vs. Manual execution:**\n- Subagents follow TDD naturally\n- Fresh context per task (no confusion)\n- Parallel-safe (subagents don''t interfere)\n- Subagent can ask questions (before AND during work)\n\n**vs. Executing Plans:**\n- Same session (no handoff)\n- Continuous progress (no waiting)\n- Review checkpoints automatic\n\n**Efficiency gains:**\n- No file reading overhead (controller provides full text)\n- Controller curates exactly what context is needed\n- Subagent gets complete information upfront\n- Questions surfaced before work begins (not after)\n\n**Quality gates:**\n- Self-review catches issues before handoff\n- Two-stage review: spec compliance, then code quality\n- Review loops ensure fixes actually work\n- Spec compliance prevents over/under-building\n- Code quality ensures implementation is well-built\n\n**Cost:**\n- More subagent invocations (implementer + 2 reviewers per task)\n- Controller does more prep work (extracting all tasks upfront)\n- Review loops add iterations\n- But catches issues early (cheaper than debugging later)\n\n## Red Flags\n\n**Never:**\n- Start implementation on main/master branch without explicit user consent\n- Skip reviews (spec compliance OR code quality)\n- Proceed with unfixed issues\n- Dispatch multiple implementation subagents in parallel (conflicts)\n- Make subagent read plan file (provide full text instead)\n- Skip scene-setting context (subagent needs to understand where task fits)\n- Ignore subagent questions (answer before letting them proceed)\n- Accept \"close enough\" on spec compliance (spec reviewer found issues = not done)\n- Skip review loops (reviewer found issues = implementer fixes = review again)\n- Let implementer self-review replace actual review (both are needed)\n- **Start code quality review before spec compliance is ✅** (wrong order)\n- Move to next task while either review has open issues\n\n**If subagent asks questions:**\n- Answer clearly and completely\n- Provide additional context if needed\n- Don''t rush them into implementation\n\n**If reviewer finds issues:**\n- Implementer (same subagent) fixes them\n- Reviewer reviews again\n- Repeat until approved\n- Don''t skip the re-review\n\n**If subagent fails task:**\n- Dispatch fix subagent with specific instructions\n- Don''t try to fix manually (context pollution)\n\n## Integration\n\n**Required workflow skills:**\n- **superpowers:using-git-worktrees** - REQUIRED: Set up isolated workspace before starting\n- **superpowers:writing-plans** - Creates the plan this skill executes\n- **superpowers:requesting-code-review** - Code review template for reviewer subagents\n- **superpowers:finishing-a-development-branch** - Complete development after all tasks\n\n**Subagents should use:**\n- **superpowers:test-driven-development** - Subagents follow TDD for each task\n\n**Alternative workflow:**\n- **superpowers:executing-plans** - Use for parallel session instead of same-session execution\n"},"category":"official","lastSynced":"2026-03-06T03:33:08.267Z","seo":{"title":{"en":"Subagent-Driven Development: Parallel Task Execution & Re...","zh":"子代理驱动开发 Setup Guide - 高质量、快速迭代","ja":"サブエージェント駆動開発ベストプラクティス - AIエージェントを活用","ko":"서브 에이전트 주도 개발 설정 가이드 - 빠른 반복과 높은 품질","es":"Guía de Configuración de Desarrollo Dirigido por Subagent...","fr":"Guide de Mise en Place du Développement Piloté par Subage...","de":"Einrichtungsleitfaden für Subagenten-gesteuerte Entwicklu...","pt":"Guia de Configuração do Desenvolvimento Dirigido por Suba...","ru":"Настройка ИИ Агентов: Руководство по разработке на основе...","ar":"إعداد الإージنتين الذكية: دليل تطوير مدفوع بالوسيط الفرعي"},"description":{"en":"Execute AI agent implementation plans faster. This skill dispatches a fresh subagent for each independent task, followed by a rigorous two-stage spec and cod...","zh":"了解子代理驱动开发的核心原则和应用场景，实现高质量、快速迭代的开发流程","ja":"サブエージェント駆動開発の概要と活用方法を紹介。AIエージェントを用いた効率的な開発を実現","ko":"서브 에이전트 주도 개발의 핵심 원리와 사용 사례를 살펴보세요. 빠른 반복과 높은 품질의 개발 프로세스를 실현","es":"Aprende a ejecutar planes de implementación con tareas independientes en la sesión actual con desarrollo dirigido por subagentes para AI Agentes","fr":"Découvrez comment exécuter des plans de mise en œuvre avec des tâches indépendantes dans la session actuelle avec le développement piloté par subagents pour ...","de":"Erfahren Sie, wie Sie Implementierungspläne mit unabhängigen Aufgaben in der aktuellen Sitzung mit subagenten-gesteuerter Entwicklung für KI-Tools ausführen","pt":"Aprenda a implementar planos com tarefas independentes usando subagentes frescos e revisões de duas etapas para alta qualidade e iteração rápida","ru":"Изучите, как реализовать планы с независимыми задачами, используя свежих субагентов и двухэтапные проверки для высокого качества и быстрой итерации","ar":"تعرف على كيفية تنفيذ الخطط ذات المهام المستقلة باستخدام وكلاء فرعيون جدد ومراجعات مرحلتين لضمان الجودة العالية والتحديث السريع"},"definition":{"en":"subagent-driven-development is an AI agent execution pattern that uses a fresh subagent for each independent task within a session. It is defined by a mandatory two-stage review process conducted after each task: a specification compliance review followed by a code quality review.","zh":"子代理驱动开发是一种开发方法，通过分配新子代理来执行独立任务，并进行两阶段审查","ja":"サブエージェント駆動開発とは、独立したタスクを新しいサブエージェントに割り当て、二段階のレビューを実施する開発方法","ko":"서브 에이전트 주도 개발은 독립적인 태스크를 새로운 서브 에이전트에 할당하고, 2단계 리뷰 프로세스를 거치는 개발 방법","es":"Desarrollo dirigido por subagentes es una técnica de desarrollo que utiliza subagentes frescos por tarea y revisiones de dos etapas para ejecutar planes de implementación","fr":"Le développement piloté par subagents est une technique de développement qui utilise des subagents frais par tâche et des examens en deux étapes pour exécuter des plans de mise en œuvre","de":"Die subagenten-gesteuerte Entwicklung ist eine Entwicklungstechnik, die frische Subagenten pro Aufgabe und zweistufige Überprüfungen verwendet, um Implementierungspläne auszuführen","pt":"Desenvolvimento dirigido por subagentes é uma abordagem que executa planos com subagentes frescos por tarefa e revisões de duas etapas","ru":"Разработка на основе субагентов - это подход, который выполняет планы с использованием свежих субагентов для каждой задачи и двухэтапных проверок","ar":"التطوير الموجه بالوسيط الفرعي هو نهج ينفذ الخطط باستخدام وكلاء فرعيون جدد لكل مهمة ومراجعات مرحلتين"},"features":{"en":["Dispatches a fresh subagent instance for each individual task execution","Enforces a mandatory two-stage review process after every task completion","Performs a first-stage review for strict specification compliance","Conducts a second-stage review for overall code quality and standards","Operates within the constraints of a single, persistent session context","Optimized for plans containing multiple independent, parallelizable tasks"],"zh":["独立任务分配","新子代理分配","两阶段审查机制","Spec Compliance Review","Code Quality Review"],"ja":["独立したタスクの割り当て","新しいサブエージェントの割り当て","二段階のレビュー","Spec Compliance Review","Code Quality Review"],"ko":["독립적인 태스크 할당","新的 서브 에이전트 할당","2단계 리뷰 프로세스","Spec Compliance Review","Code Quality Review"],"es":["Ejecución de planes de implementación con tareas independientes","Uso de subagentes frescos por tarea","Revisiones de dos etapas: cumplimiento de especificaciones y calidad del código","Mejora de la calidad y velocidad de iteración","Compatibilidad con la sesión actual"],"fr":["Exécution de plans de mise en œuvre avec des tâches indépendantes","Utilisation de subagents frais par tâche","Examens en deux étapes : conformité aux spécifications et qualité du code","Amélioration de la qualité et de la vitesse d''itération","Compatibilité avec la session actuelle"],"de":["Ausführung von Implementierungsplänen mit unabhängigen Aufgaben","Verwendung von frischen Subagenten pro Aufgabe","Zweistufige Überprüfungen: Spezifikationskonformität und Codequalität","Verbesserung der Qualität und Iterationsgeschwindigkeit","Kompatibilität mit der aktuellen Sitzung"],"pt":["Execução de planos com subagentes frescos por tarefa","Revisões de duas etapas para garantir alta qualidade","Iteração rápida e flexível","Compatibilidade com planos de implementação","Tarefas independentes para melhor eficiência"],"ru":["Выполнение планов с использованием свежих субагентов для каждой задачи","Двухэтапные проверки для обеспечения высокого качества","Быстрая и гибкая итерация","Совместимость с планами реализации","Независимые задачи для лучшей эффективности"],"ar":["تنفيذ الخطط باستخدام وكلاء فرعيون جدد لكل مهمة","مراجعات مرحلتين لضمان الجودة العالية","التحديث السريع والموحد","التوافق مع خطط التنفيذ","المهام المستقلة لتحقيق أفضل كفاءة"]},"keywords":{"en":["what is subagent-driven-development","how to use subagent-driven-development","subagent-driven-development two-stage review","subagent-driven-development vs multi-agent systems","subagent-driven-development implementation guide","AI agent task execution pattern","spec compliance review AI agent","code quality review subagent"],"zh":["子代理驱动开发","AI代理","独立任务","两阶段审查","开发方法","快速迭代","高质量开发"],"ja":["サブエージェント駆動開発","AIエージェント","独立したタスク","二段階のレビュー","開発方法","効率的な開発","AIツール"],"ko":["서브 에이전트 주도 개발","AI 에이전트","독립적인 태스크","2단계 리뷰","개발 방법","빠른 반복","높은 품질의 개발"],"es":["desarrollo dirigido por subagentes","AI Agentes","tareas independientes","planes de implementación","subagentes frescos","revisiones de dos etapas","cumplimiento de especificaciones","calidad del código"],"fr":["développement piloté par subagents","Outils IA","tâches indépendantes","plans de mise en œuvre","subagents frais","examens en deux étapes","conformité aux spécifications","qualité du code"],"de":["subagenten-gesteuerte Entwicklung","KI-Tools","unabhängige Aufgaben","Implementierungspläne","frische Subagenten","zweistufige Überprüfungen","Spezifikationskonformität","Codequalität"],"pt":["desenvolvimento dirigido por subagentes","subagentes frescos","revisões de duas etapas","alta qualidade","iteração rápida","planos de implementação","tarefas independentes"],"ru":["ИИ Агенты","разработка на основе субагентов","свежие субагенты","двухэтапные проверки","высокое качество","быстрая итерация","планы реализации","независимые задачи"],"ar":["الإージنتين الذكية","التطوير الموجه بالوسيط الفرعي","وكلاء فرعيون جدد","مراجعات مرحلتين","الجودة العالية","التحديث السريع","خطط التنفيذ","المهام المستقلة"]}},"agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing to execute complex implementation plans by dynamically managing independent tasks through fresh subagents.","zh":"非常适合需要通过动态管理独立任务的新子代理来执行复杂实施计划的AI Agent。","ja":"独立したタスクを新しいサブエージェントを通じて動的に管理することで、複雑な実装計画を実行する必要があるAIエージェントに最適です。","ko":"새로운 하위 에이전트를 통해 독립적인 작업을 동적으로 관리하여 복잡한 구현 계획을 실행해야 하는 AI 에이전트에 완벽합니다.","es":"Ideal para Agentes de IA que necesitan ejecutar planes de implementación complejos mediante la gestión dinámica de tareas independientes a través de nuevos subagentes.","fr":"Parfait pour les Agents IA ayant besoin d''exécuter des plans de mise en œuvre complexes en gérant dynamiquement des tâches indépendantes via de nouveaux sous-agents.","de":"Perfekt für KI-Agenten, die komplexe Implementierungspläne ausführen müssen, indem sie unabhängige Aufgaben dynamisch durch neue Subagenten verwalten.","pt":"Ideal para Agentes de IA que necessitam executar planos de implementação complexos, gerenciando dinamicamente tarefas independentes através de novos subagentes.","ru":"Идеально подходит для ИИ-агентов, которым необходимо выполнять сложные планы реализации путем динамического управления независимыми задачами через создание новых субагентов.","ar":"مثالي لوكلاء الذكاء الاصطناعي الذين يحتاجون إلى تنفيذ خطط تنفيذ معقدة من خلال الإدارة الديناميكية للمهام المستقلة عبر وكلاء فرعيين جدد."},"recommendation":{"en":"Empowers agents to handle multi-task execution with precision by dispatching specialized subagents for each task, followed by a rigorous two-stage review process for both specification compliance and code quality, ensuring high standards and rapid iteration.","zh":"通过为每个任务派遣专门的子代理，随后进行规范合规性和代码质量的严格两阶段审查流程，使代理能够精确处理多任务执行，确保高标准和快速迭代。","ja":"各タスクに特化したサブエージェントを派遣し、その後、仕様準拠とコード品質の両方について厳格な2段階のレビュープロセスを実施することで、エージェントがマルチタスク実行を精密に処理できるようにし、高水準と迅速な反復を保証します。","ko":"각 작업에 대해 전문적인 하위 에이전트를 파견하고, 이어서 사양 준수 및 코드 품질에 대한 엄격한 2단계 검토 프로세스를 통해 에이전트가 다중 작업 실행을 정밀하게 처리할 수 있도록 하여 높은 기준과 빠른 반복을 보장합니다.","es":"Permite a los agentes manejar la ejecución de múltiples tareas con precisión mediante el envío de subagentes especializados para cada tarea, seguido de un riguroso proceso de revisión en dos etapas para el cumplimiento de especificaciones y la calidad del código, garantizando altos estándares y una iteración rápida.","fr":"Permet aux agents de gérer l''exécution multi-tâches avec précision en déployant des sous-agents spécialisés pour chaque tâche, suivi d''un processus de revue rigoureux en deux étapes pour la conformité aux spécifications et la qualité du code, garantissant des normes élevées et une itération rapide.","de":"Ermöglicht Agenten die präzise Ausführung mehrerer Aufgaben, indem spezialisierte Subagenten für jede Aufgabe eingesetzt werden, gefolgt von einem rigorosen zweistufigen Überprüfungsprozess für die Spezifikationskonformität und Codequalität, um hohe Standards und schnelle Iteration zu gewährleisten.","pt":"Capacita os agentes a lidar com a execução de múltiplas tarefas com precisão, despachando subagentes especializados para cada tarefa, seguido por um rigoroso processo de revisão em duas etapas para conformidade de especificação e qualidade de código, garantindo altos padrões e iteração rápida.","ru":"Позволяет агентам точно выполнять многозадачные операции, распределяя специализированных субагентов для каждой задачи, с последующим строгим двухэтапным процессом проверки на соответствие спецификации и качеству кода, что обеспечивает высокие стандарты и быструю итерацию.","ar":"يمكن الوكلاء من التعامل مع تنفيذ المهام المتعددة بدقة من خلال إيفاد وكلاء فرعيين متخصصين لكل مهمة، يليها عملية مراجعة صارمة من مرحلتين للتحقق من الامتثال للمواصفات وجودة الكود، مما يضمن معايير عالية والتكرار السريع."},"useCases":{"en":["Automating parallel task execution","Generating compliant code outputs","Debugging and refining implementation plans"],"zh":["自动化并行任务执行","生成合规的代码输出","调试和改进实施计划"],"ja":["並列タスク実行の自動化","準拠したコード出力の生成","実装計画のデバッグと改良"],"ko":["병렬 작업 실행 자동화","준수하는 코드 출력 생성","구현 계획 디버깅 및 개선"],"es":["Automatización de la ejecución de tareas paralelas","Generación de salidas de código compatibles","Depuración y refinamiento de planes de implementación"],"fr":["Automatisation de l''exécution de tâches parallèles","Génération de sorties de code conformes","Débogage et affinement des plans de mise en œuvre"],"de":["Automatisierung der parallelen Aufgabenausführung","Erzeugung konformer Code-Ausgaben","Debugging und Verfeinerung von Implementierungsplänen"],"pt":["Automatização da execução de tarefas paralelas","Geração de saídas de código em conformidade","Depuração e refinamento de planos de implementação"],"ru":["Автоматизация параллельного выполнения задач","Генерация соответствующих требований выходных данных кода","Отладка и доработка планов реализации"],"ar":["أتمتة التنفيذ المتوازي للمهام","إنشاء مخرجات كود متوافقة","تصحيح الأخطاء وتحسين خطط التنفيذ"]},"limitations":{"en":["Requires clear task independence","Depends on robust subagent management","Needs structured review protocols"],"zh":["需要清晰的任务独立性","依赖强大的子代理管理","需要结构化的审查协议"],"ja":["明確なタスクの独立性が必要","堅牢なサブエージェント管理に依存","構造化されたレビュープロトコルが必要"],"ko":["명확한 작업 독립성 필요","강력한 하위 에이전트 관리에 의존","구조화된 검토 프로토콜 필요"],"es":["Requiere una clara independencia de las tareas","Depende de una gestión robusta de subagentes","Necesita protocolos de revisión estructurados"],"fr":["Nécessite une indépendance claire des tâches","Dépend d''une gestion robuste des sous-agents","Nécessite des protocoles de revue structurés"],"de":["Erfordert klare Aufgabenunabhängigkeit","Hängt von einem robusten Subagenten-Management ab","Benötigt strukturierte Überprüfungsprotokolle"],"pt":["Requer independência clara das tarefas","Depende de um gerenciamento robusto de subagentes","Necessita de protocolos de revisão estruturados"],"ru":["Требует четкой независимости задач","Зависит от надежного управления субагентами","Требует структурированных протоколов проверки"],"ar":["يتطلب استقلالية واضحة للمهام","يعتمد على إدارة قوية للوكلاء الفرعيين","يحتاج إلى بروتوكولات مراجعة منظمة"]},"version":4},"contentHash":"994b89a5d294eadd6a1611edb51377bac748d5f5fb7f4139d3c736b616b3a46a","repoEtag":"W/\"a8a266458ca9bbf6c9312a7647f733e0f1891eedfa2dde0bddcec7f7d186089e\"","qualityScore":86}');
