INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('obra/superpowers/subagent-driven-development', 'subagent-driven-development', 'obra', 'superpowers', 'official', 'subagent-driven-development obra superpowers official The subagent-driven-development skill executes implementation plans by dispatching a new subagent per independent task within the current session. It enforces a two-stage review process, first for spec compliance and then for code quality, ensuring high-fidelity output for developers. 子代理驱动开发是一种通过分配新子代理来执行独立任务的开发方法，具有两阶段审查机制 サブエージェント駆動開発は、独立したタスクを新しいサブエージェントに割り当てることで実現する開発方法で、二段階のレビューが特徴 서브 에이전트 주도 개발은 독립적인 태스크를 새로운 서브 에이전트에 할당하여 개발하는 방법으로, 2단계 리뷰 프로세스를 갖추고 있습니다 Desarrollo dirigido por subagentes es una técnica que ejecuta planes de implementación con tareas independientes en la sesión actual, utilizando subagentes frescos por tarea y revisiones de dos etapas Le développement piloté par subagents est une technique qui exécute des plans de mise en œuvre avec des tâches indépendantes dans la session actuelle, en utilisant des subagents frais par tâche et des examens en deux étapes Die subagenten-gesteuerte Entwicklung ist eine Technik, die Implementierungspläne mit unabhängigen Aufgaben in der aktuellen Sitzung ausführt, indem sie frische Subagenten pro Aufgabe und zweistufige Überprüfungen verwendet O desenvolvimento dirigido por subagentes executa planos usando subagentes frescos por tarefa com revisões de duas etapas para garantir alta qualidade e iteração rápida Разработка на основе субагентов выполняет планы, используя свежих субагентов для каждой задачи с двухэтапными проверками для обеспечения высокого качества и быстрой итерации التطوير الموجه بالوسيط الفرعي ينفذ الخطط باستخدام وكلاء فرعيون جدد لكل مهمة مع مراجعات مرحلتين لضمان الجودة العالية والتحديث السريع what is subagent-driven-development how to use subagent-driven-development subagent-driven-development two-stage review subagent-driven-development vs multi-agent systems subagent-driven-development implementation guide AI agent task execution pattern spec compliance review AI agent code quality review subagent 子代理驱动开发 AI代理 独立任务 两阶段审查 开发方法 快速迭代 高质量开发 Dispatches a fresh subagent instance for each individual task execution Enforces a mandatory two-stage review process after every task completion Performs a first-stage review for strict specification compliance Conducts a second-stage review for overall code quality and standards Operates within the constraints of a single, persistent session context Optimized for plans containing multiple independent, parallelizable tasks subagent-driven-development is an AI agent execution pattern that uses a fresh subagent for each independent task within a session. It is defined by a mandatory two-stage review process conducted after each task: a specification compliance review followed by a code quality review.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('obra/superpowers/systematic-debugging', 'official', 'obra', 'superpowers', 'obra/superpowers', 'systematic-debugging', 71924, 5546, 86, '2026-03-06T03:26:30Z', '2026-03-06T03:34:09.453Z', '4999cb851360485eca5074e727bbdd62ef20549c5d5b01216fcbf5831badb473', '{"id":"obra/superpowers/systematic-debugging","name":"systematic-debugging","description":{"en":"The systematic-debugging skill is a disciplined protocol for AI Agents encountering bugs or test failures. It mandates a root cause analysis phase before any fix is proposed, preventing wasted effort and new bugs introduced by patches. It is essential for developers and QA engineers who require m...","zh":"系统调试是一种通过根因分析来解决技术问题的方法，确保在提出解决方案之前找到问题的根源","ja":"システムデバッグは、根本原因分析を使用して技術的な問題を解決する方法であり、解決策を提案する前に問題の根源を見つけることを保証します","ko":"시스템 디버깅은 루트 원인 분석을 사용하여 기술적인 문제를 해결하는 방법으로, 해결책을 제안하기 전에 문제의 근본 원인을 찾는 것을 보장합니다","es":"La depuración sistemática es crucial para identificar la causa raíz de los errores. Aprende a aplicar este enfoque para agentes de IA.","fr":"Le débogage systématique est essentiel pour identifier la cause profonde des erreurs. Découvrez comment l''appliquer pour les outils d''IA.","de":"Die systematische Fehlerbehebung ist entscheidend, um die Ursache von Fehlern zu identifizieren. Erfahren Sie, wie Sie diesen Ansatz für KI-Agents anwenden.","pt":"Uma habilidade de IA para debugging que exige a identificação da causa raiz antes de qualquer proposta de correção. Impede soluções superficiais para test failures e bugs, aplicando uma metodologia rigorosa.","ru":"Навык ИИ для отладки, требующий идентификации корневой причины до предложения исправлений. Предотвращает поверхностные решения для сбоев тестов и ошибок, применяя строгую методологию.","ar":"مهارة ذكاء اصطناعي للتصحيح تتطلب تحديد السبب الجذري قبل أي محاولة إصلاح. تمنع الحلول السطحية لأعطال الاختبار والأخطاء من خلال تطبيق منهجية صارمة."},"owner":"obra","repo":"superpowers","repoPath":"obra/superpowers","stars":71924,"forks":5546,"updatedAt":"2026-03-06T03:26:30Z","topics":[],"skillMd":{"name":"systematic-debugging","description":"Use when encountering any bug, test failure, or unexpected behavior, before proposing fixes","bodyPreview":"# Systematic Debugging\n\n## Overview\n\nRandom fixes waste time and create new bugs. Quick patches mask underlying issues.\n\n**Core principle:** ALWAYS find root cause before attempting fixes. Symptom fixes are failure.\n\n**Violating the letter of this process is violating the spirit of debugging.**\n\n## The Iron Law\n\n```\nNO FIXES WITHOUT ROOT CAUSE INVESTIGATION FIRST\n```\n\nIf you haven''t completed Phase 1, you cannot propose fixes.\n\n## When to Use\n\nUse for ANY technical issue:\n- Test failures\n- Bugs","body":"# Systematic Debugging\n\n## Overview\n\nRandom fixes waste time and create new bugs. Quick patches mask underlying issues.\n\n**Core principle:** ALWAYS find root cause before attempting fixes. Symptom fixes are failure.\n\n**Violating the letter of this process is violating the spirit of debugging.**\n\n## The Iron Law\n\n```\nNO FIXES WITHOUT ROOT CAUSE INVESTIGATION FIRST\n```\n\nIf you haven''t completed Phase 1, you cannot propose fixes.\n\n## When to Use\n\nUse for ANY technical issue:\n- Test failures\n- Bugs in production\n- Unexpected behavior\n- Performance problems\n- Build failures\n- Integration issues\n\n**Use this ESPECIALLY when:**\n- Under time pressure (emergencies make guessing tempting)\n- \"Just one quick fix\" seems obvious\n- You''ve already tried multiple fixes\n- Previous fix didn''t work\n- You don''t fully understand the issue\n\n**Don''t skip when:**\n- Issue seems simple (simple bugs have root causes too)\n- You''re in a hurry (rushing guarantees rework)\n- Manager wants it fixed NOW (systematic is faster than thrashing)\n\n## The Four Phases\n\nYou MUST complete each phase before proceeding to the next.\n\n### Phase 1: Root Cause Investigation\n\n**BEFORE attempting ANY fix:**\n\n1. **Read Error Messages Carefully**\n   - Don''t skip past errors or warnings\n   - They often contain the exact solution\n   - Read stack traces completely\n   - Note line numbers, file paths, error codes\n\n2. **Reproduce Consistently**\n   - Can you trigger it reliably?\n   - What are the exact steps?\n   - Does it happen every time?\n   - If not reproducible → gather more data, don''t guess\n\n3. **Check Recent Changes**\n   - What changed that could cause this?\n   - Git diff, recent commits\n   - New dependencies, config changes\n   - Environmental differences\n\n4. **Gather Evidence in Multi-Component Systems**\n\n   **WHEN system has multiple components (CI → build → signing, API → service → database):**\n\n   **BEFORE proposing fixes, add diagnostic instrumentation:**\n   ```\n   For EACH component boundary:\n     - Log what data enters component\n     - Log what data exits component\n     - Verify environment/config propagation\n     - Check state at each layer\n\n   Run once to gather evidence showing WHERE it breaks\n   THEN analyze evidence to identify failing component\n   THEN investigate that specific component\n   ```\n\n   **Example (multi-layer system):**\n   ```bash\n   # Layer 1: Workflow\n   echo \"=== Secrets available in workflow: ===\"\n   echo \"IDENTITY: ${IDENTITY:+SET}${IDENTITY:-UNSET}\"\n\n   # Layer 2: Build script\n   echo \"=== Env vars in build script: ===\"\n   env | grep IDENTITY || echo \"IDENTITY not in environment\"\n\n   # Layer 3: Signing script\n   echo \"=== Keychain state: ===\"\n   security list-keychains\n   security find-identity -v\n\n   # Layer 4: Actual signing\n   codesign --sign \"$IDENTITY\" --verbose=4 \"$APP\"\n   ```\n\n   **This reveals:** Which layer fails (secrets → workflow ✓, workflow → build ✗)\n\n5. **Trace Data Flow**\n\n   **WHEN error is deep in call stack:**\n\n   See `root-cause-tracing.md` in this directory for the complete backward tracing technique.\n\n   **Quick version:**\n   - Where does bad value originate?\n   - What called this with bad value?\n   - Keep tracing up until you find the source\n   - Fix at source, not at symptom\n\n### Phase 2: Pattern Analysis\n\n**Find the pattern before fixing:**\n\n1. **Find Working Examples**\n   - Locate similar working code in same codebase\n   - What works that''s similar to what''s broken?\n\n2. **Compare Against References**\n   - If implementing pattern, read reference implementation COMPLETELY\n   - Don''t skim - read every line\n   - Understand the pattern fully before applying\n\n3. **Identify Differences**\n   - What''s different between working and broken?\n   - List every difference, however small\n   - Don''t assume \"that can''t matter\"\n\n4. **Understand Dependencies**\n   - What other components does this need?\n   - What settings, config, environment?\n   - What assumptions does it make?\n\n### Phase 3: Hypothesis and Testing\n\n**Scientific method:**\n\n1. **Form Single Hypothesis**\n   - State clearly: \"I think X is the root cause because Y\"\n   - Write it down\n   - Be specific, not vague\n\n2. **Test Minimally**\n   - Make the SMALLEST possible change to test hypothesis\n   - One variable at a time\n   - Don''t fix multiple things at once\n\n3. **Verify Before Continuing**\n   - Did it work? Yes → Phase 4\n   - Didn''t work? Form NEW hypothesis\n   - DON''T add more fixes on top\n\n4. **When You Don''t Know**\n   - Say \"I don''t understand X\"\n   - Don''t pretend to know\n   - Ask for help\n   - Research more\n\n### Phase 4: Implementation\n\n**Fix the root cause, not the symptom:**\n\n1. **Create Failing Test Case**\n   - Simplest possible reproduction\n   - Automated test if possible\n   - One-off test script if no framework\n   - MUST have before fixing\n   - Use the `superpowers:test-driven-development` skill for writing proper failing tests\n\n2. **Implement Single Fix**\n   - Address the root cause identified\n   - ONE change at a time\n   - No \"while I''m here\" improvements\n   - No bundled refactoring\n\n3. **Verify Fix**\n   - Test passes now?\n   - No other tests broken?\n   - Issue actually resolved?\n\n4. **If Fix Doesn''t Work**\n   - STOP\n   - Count: How many fixes have you tried?\n   - If < 3: Return to Phase 1, re-analyze with new information\n   - **If ≥ 3: STOP and question the architecture (step 5 below)**\n   - DON''T attempt Fix #4 without architectural discussion\n\n5. **If 3+ Fixes Failed: Question Architecture**\n\n   **Pattern indicating architectural problem:**\n   - Each fix reveals new shared state/coupling/problem in different place\n   - Fixes require \"massive refactoring\" to implement\n   - Each fix creates new symptoms elsewhere\n\n   **STOP and question fundamentals:**\n   - Is this pattern fundamentally sound?\n   - Are we \"sticking with it through sheer inertia\"?\n   - Should we refactor architecture vs. continue fixing symptoms?\n\n   **Discuss with your human partner before attempting more fixes**\n\n   This is NOT a failed hypothesis - this is a wrong architecture.\n\n## Red Flags - STOP and Follow Process\n\nIf you catch yourself thinking:\n- \"Quick fix for now, investigate later\"\n- \"Just try changing X and see if it works\"\n- \"Add multiple changes, run tests\"\n- \"Skip the test, I''ll manually verify\"\n- \"It''s probably X, let me fix that\"\n- \"I don''t fully understand but this might work\"\n- \"Pattern says X but I''ll adapt it differently\"\n- \"Here are the main problems: [lists fixes without investigation]\"\n- Proposing solutions before tracing data flow\n- **\"One more fix attempt\" (when already tried 2+)**\n- **Each fix reveals new problem in different place**\n\n**ALL of these mean: STOP. Return to Phase 1.**\n\n**If 3+ fixes failed:** Question the architecture (see Phase 4.5)\n\n## your human partner''s Signals You''re Doing It Wrong\n\n**Watch for these redirections:**\n- \"Is that not happening?\" - You assumed without verifying\n- \"Will it show us...?\" - You should have added evidence gathering\n- \"Stop guessing\" - You''re proposing fixes without understanding\n- \"Ultrathink this\" - Question fundamentals, not just symptoms\n- \"We''re stuck?\" (frustrated) - Your approach isn''t working\n\n**When you see these:** STOP. Return to Phase 1.\n\n## Common Rationalizations\n\n| Excuse | Reality |\n|--------|---------|\n| \"Issue is simple, don''t need process\" | Simple issues have root causes too. Process is fast for simple bugs. |\n| \"Emergency, no time for process\" | Systematic debugging is FASTER than guess-and-check thrashing. |\n| \"Just try this first, then investigate\" | First fix sets the pattern. Do it right from the start. |\n| \"I''ll write test after confirming fix works\" | Untested fixes don''t stick. Test first proves it. |\n| \"Multiple fixes at once saves time\" | Can''t isolate what worked. Causes new bugs. |\n| \"Reference too long, I''ll adapt the pattern\" | Partial understanding guarantees bugs. Read it completely. |\n| \"I see the problem, let me fix it\" | Seeing symptoms ≠ understanding root cause. |\n| \"One more fix attempt\" (after 2+ failures) | 3+ failures = architectural problem. Question pattern, don''t fix again. |\n\n## Quick Reference\n\n| Phase | Key Activities | Success Criteria |\n|-------|---------------|------------------|\n| **1. Root Cause** | Read errors, reproduce, check changes, gather evidence | Understand WHAT and WHY |\n| **2. Pattern** | Find working examples, compare | Identify differences |\n| **3. Hypothesis** | Form theory, test minimally | Confirmed or new hypothesis |\n| **4. Implementation** | Create test, fix, verify | Bug resolved, tests pass |\n\n## When Process Reveals \"No Root Cause\"\n\nIf systematic investigation reveals issue is truly environmental, timing-dependent, or external:\n\n1. You''ve completed the process\n2. Document what you investigated\n3. Implement appropriate handling (retry, timeout, error message)\n4. Add monitoring/logging for future investigation\n\n**But:** 95% of \"no root cause\" cases are incomplete investigation.\n\n## Supporting Techniques\n\nThese techniques are part of systematic debugging and available in this directory:\n\n- **`root-cause-tracing.md`** - Trace bugs backward through call stack to find original trigger\n- **`defense-in-depth.md`** - Add validation at multiple layers after finding root cause\n- **`condition-based-waiting.md`** - Replace arbitrary timeouts with condition polling\n\n**Related skills:**\n- **superpowers:test-driven-development** - For creating failing test case (Phase 4, Step 1)\n- **superpowers:verification-before-completion** - Verify fix worked before claiming success\n\n## Real-World Impact\n\nFrom debugging sessions:\n- Systematic approach: 15-30 minutes to fix\n- Random fixes approach: 2-3 hours of thrashing\n- First-time fix rate: 95% vs 40%\n- New bugs introduced: Near zero vs common\n"},"category":"official","lastSynced":"2026-03-06T03:34:09.453Z","seo":{"title":{"en":"systematic-debugging: Root Cause Analysis Guide | AI Agen...","zh":"系统调试设置指南 - 根据根因分析进行调试","ja":"Systematic Debugging Setup Guide - AIエージェントによる根本原因分析","ko":"시스템 디버깅 설정 가이드 - 루트 원인 분석을 통한 디버깅","es":"Guía de Depuración Sistemática para Agentes de IA","fr":"Débogage Systématique pour Outils d''IA : Guide de Mise en...","de":"Systematische Fehlerbehebung für KI-Agents: Best Practices","pt":"Guia de Depuração Sistemática: Encontre a Causa Raiz de Bugs","ru":"Систематическая отладка: Руководство по поиску корневой п...","ar":"دليل التصحيح المنهجي: إيجاد السبب الجذري للأخطاء باستخدام..."},"description":{"en":"Stop random fixes. This AI Agent skill enforces root cause investigation for bugs & test failures before proposing solutions. Learn the Iron Law of debugging...","zh":"学习系统调试的最佳实践，包括根因分析和测试失败处理，使用AI工具提高调试效率","ja":"AIエージェントを使用して、根本原因分析とテスト失敗の処理を含むシステムデバッグのベストプラクティスを学びます","ko":"루트 원인 분석과 테스트 실패 처리를 포함한 시스템 디버깅의 베스트 프랙티스를 학습하고 AI 도구를 사용하여 디버깅 효율을 높이세요","es":"Aprende a depurar sistemáticamente con nuestra guía para agentes de IA. Identifica la causa raíz antes de proponer soluciones.","fr":"Découvrez comment déboguer systématiquement avec notre guide pour outils d''IA. Trouvez la cause profonde avant de proposer des correctifs.","de":"Erfahren Sie, wie Sie systematisch Fehler beheben mit unserer Anleitung für KI-Agents. Finden Sie die Ursache bevor Sie Lösungen vorschlagen.","pt":"Evite correções aleatórias que criam novos bugs. Esta habilidade de IA aplica o princípio ''Nenhuma correção sem investigação da causa raiz'' para test failure...","ru":"Исключите случайные исправления, создающие новые ошибки. Этот ИИ агент применяет принцип ''Никаких исправлений без исследования первопричины'' для сбоев тестов...","ar":"تجنب التصحيحات العشوائية التي تخلق أخطاء جديدة. تلتزم أداة الذكاء الاصطناعي هذه بمبدأ ''لا يوجد إصلاح دون التحقيق أولاً في السبب الجذري'' لأعطال الاختبار والمش..."},"definition":{"en":"systematic-debugging is an AI Agent skill that enforces a strict debugging process. It prohibits proposing fixes until a root cause investigation is complete, ensuring that solutions address underlying issues rather than just symptoms.","zh":"系统调试是一种通过根因分析来解决技术问题的方法","ja":"システムデバッグは、根本原因分析を使用して技術的な問題を解決する方法です","ko":"시스템 디버깅은 루트 원인 분석을 사용하여 기술적인 문제를 해결하는 방법입니다","es":"La depuración sistemática es un método para identificar la causa raíz de errores y fallos en agentes de IA.","fr":"Le débogage systématique est une méthode pour identifier la cause profonde des erreurs et des défaillances dans les outils d''IA.","de":"Die systematische Fehlerbehebung ist eine Methode, um die Ursache von Fehlern und Ausfällen in KI-Agents zu identifizieren.","pt":"Systematic Debugging é uma habilidade de IA que aplica uma lei rígida: nenhuma correção pode ser proposta sem uma investigação completa da causa raiz primeiro. É usada para bugs, test failures e comportamentos inesperados.","ru":"Systematic Debugging — это навык ИИ, применяющий жесткое правило: никакие исправления не могут быть предложены без полного исследования первопричины. Используется для ошибок, сбоев тестов и неожиданного поведения.","ar":"التصحيح المنهجي هو مهارة للذكاء الاصطناعي تلتزم بقاعدة صارمة: لا يمكن اقتراح أي إصلاح دون تحقيق كامل في السبب الجذري أولاً. تُستخدم للأخطاء وأعطال الاختبار والسلوك غير المتوقع."},"features":{"en":["Enforces the Iron Law: ''NO FIXES WITHOUT ROOT CAUSE INVESTIGATION FIRST''","Triggered automatically by any bug, test failure, or unexpected behavior","Prevents symptom fixes that mask underlying problems","Designed to stop random fixes that waste time and create new bugs"],"zh":["根因分析","测试失败处理","遵循铁律：无根因分析则无修复","适用于任何技术问题","提高调试效率"],"ja":["根本原因分析","テスト失敗の処理","鉄則の遵守：根本原因分析なしには修復なし"," любое技術的な問題に適用可能","デバッグ効率の向上"],"ko":["루트 원인 분석","테스트 실패 처리","鉄則 준수: 루트 원인 분석 없이는 수정 없음","어떤 기술적인 문제에도 적용 가능","디버깅 효율 향상"],"es":["Identificación de la causa raíz de errores y fallos","Aplicación de la Ley de Hierro: NO arreglos sin investigación previa","Depuración sistemática para pruebas fallidas y errores","Análisis detallado de los síntomas para encontrar la solución","Evitación de soluciones rápidas que masken problemas subyacentes"],"fr":["Identification de la cause profonde des erreurs et des défaillances","Application de la Loi de Fer : PAS de correctifs sans investigation préalable","Débogage systématique pour les tests échoués et les erreurs","Analyse détaillée des symptômes pour trouver la solution","Évitement des solutions rapides qui masquent les problèmes sous-jacents"],"de":["Identifizierung der Ursache von Fehlern und Ausfällen","Anwendung des Eisernen Gesetzes: KEINE Reparaturen ohne vorherige Untersuchung","Systematische Fehlerbehebung für fehlgeschlagene Tests und Fehler","Detaillierte Analyse der Symptome, um die Lösung zu finden","Vermeidung von schnellen Lösungen, die zugrunde liegende Probleme verbergen"],"pt":["Aplica a ''Iron Law'': Nenhuma correção sem investigação da causa raiz","Evita correções aleatórias que desperdiçam tempo e criam novos bugs","Proíbe soluções superficiais que mascaram problemas subjacentes","Metodologia obrigatória para qualquer test failure ou bug","Foca na identificação da causa raiz antes de propor fixes","Processo sistemático para qualquer comportamento técnico inesperado"],"ru":["Применяет ''Железное правило'': Никаких исправлений без исследования первопричины","Исключает случайные исправления, тратящие время и создающие новые ошибки","Запрещает поверхностные решения, маскирующие основные проблемы","Обязательная методология для любого сбоя теста или ошибки","Фокусируется на идентификации корневой причины до предложения исправлений","Системный процесс для любого неожиданного технического поведения"],"ar":["تطبق ''القاعدة الحديدية'': لا يوجد إصلاح دون التحقيق أولاً في السبب الجذري","تتجنب التصحيحات العشوائية التي تهدر الوقت وتخلق أخطاء جديدة","تحظر الحلول السطحية التي تخفي المشاكل الأساسية","منهجية إلزامية لأي عطل في الاختبار أو خطأ","تركز على تحديد السبب الجذري قبل اقتراح الإصلاحات","عملية منهجية لأي سلوك تقني غير متوقع"]},"keywords":{"en":["systematic-debugging root cause analysis","how to use systematic-debugging skill","AI agent debugging protocol","systematic-debugging vs random fixes","install systematic-debugging skill","systematic-debugging for test failures","what is systematic-debugging","systematic-debugging setup guide"],"zh":["系统调试","根因分析","测试失败处理","AI工具","技术问题解决","调试最佳实践","系统调试设置指南"],"ja":["システムデバッグ","根本原因分析","テスト失敗の処理","AIエージェント","技術的な問題の解決","デバッグのベストプラクティス","システムデバッグの設定ガイド"],"ko":["시스템 디버깅","루트 원인 분석","테스트 실패 처리","AI 도구","기술적인 문제의 해결","디버깅의 베스트 프랙티스","시스템 디버깅 설정 가이드"],"es":["depuración sistemática","agentes de IA","causa raíz","Ley de Hierro","pruebas fallidas","errores","solución de problemas","desarrollo de software","herramientas de IA"],"fr":["débogage systématique","outils d''IA","cause profonde","Loi de Fer","tests échoués","erreurs","résolution de problèmes","développement de logiciels","outils d''IA"],"de":["systematische Fehlerbehebung","KI-Agents","Ursache","Eisernes Gesetz","fehlgeschlagene Tests","Fehler","Fehlerbehebung","Software-Entwicklung","KI-Tools"],"pt":["depuração sistemática causa raiz","skill debugging AI agent","como encontrar causa raiz de bugs","metodologia debugging test failures","evitar correções aleatórias","iron law debugging","investigar bug antes de corrigir","princípios debugging IA"],"ru":["систематическая отладка первопричина","навык отладки ИИ агент","как найти корневую причину ошибок","методология отладки сбоев тестов","избегать случайных исправлений","железное правило отладки","исследовать ошибку перед исправлением","принципы отладки ИИ"],"ar":["التصحيح المنهجي السبب الجذري","مهارة التصحيح أدوات الذكاء الاصطناعي","كيفية العثور على السبب الجذري للأخطاء","منهجية تصحيح أعطال الاختبار","تجنب التصحيحات العشوائية","القاعدة الحديدية للتصحيح","التحقق من الخطأ قبل الإصلاح","مبادئ التصحيح بالذكاء الاصطناعي"]}},"agentAnalysis":{"suitability":{"en":"Essential for Debugging Agents that enforce root cause analysis before proposing any code changes.","zh":"适用于调试代理，强制在提出任何代码更改之前进行根本原因分析。","ja":"根本原因分析を行う前に提案されるコードの変更を強制するデバッグ エージェントに適しています。","ko":"코드 변경을 제안하기 전에 근본 원인 분석을 강제하는 디버깅 에이전트에 적합합니다.","es":"Esencial para depurar agentes que aplican análisis de causa raíz antes de proponer cualquier cambio de código.","fr":"Essentiel pour déboguer les agents qui appliquent une analyse de cause racine avant de proposer toute modification de code.","de":"Essenziell für das Debuggen von Agenten, die eine Analyse der Ursache erzwingen, bevor Codeänderungen vorgeschlagen werden.","pt":"Essencial para Debugging Agents que aplicam a análise de causa raiz antes de propor qualquer alteração de código.","ru":"Необходимо для Debugging Agents, которые проводят анализ первопричин перед предложением любых изменений кода.","ar":"أساسي لـ Debugging Agents التي تفرض تحليل السبب الجذري قبل اقتراح أي تغييرات على الكود."},"recommendation":{"en":"Enforces the Iron Law of systematic debugging: NO FIXES WITHOUT ROOT CAUSE INVESTIGATION FIRST. This prevents agents from wasting time on random fixes or quick patches that mask underlying issues and create new bugs, ensuring all proposed solutions address the actual problem.","zh":"强制执行系统化调试的铁律：在进行根本原因调查之前，不得提出任何修复方案。这可以防止代理浪费时间在随机修复或快速补丁上，这些修复或补丁可能会掩盖潜在问题并创建新的错误，确保所有提出的解决方案都解决了实际问题。","ja":"体系的なデバッグの鉄則を強制実行します。根本原因の調査を行う前に、修正を提案しないこと。これにより、エージェントがランダムな修正やクイックパッチに時間を浪費するのを防ぎ、根本的な問題を隠し、新しいバグを作成するのを防ぎ、提案されたすべての解決策が実際の問題に対処することを保証します。","ko":"체계적인 디버깅의 철칙을 강제 적용합니다. 근본 원인 조사를 수행하기 전에 수정을 제안하지 않는다. 이것은 에이전트가 무작위 수정이나 빠른 패치에 시간을浪費하는 것을 방지하고, 기본적인 문제를 숨기고 새로운 버그를 생성하는 것을 방지하며, 제안된 모든 해결책이 실제 문제를 해결하는 것을 보장한다.","es":"Impone la Ley de Hierro del debugging sistemático: SIN SOLUCIONES SIN INVESTIGACIÓN DE CAUSA RAIZ PRIMERO. Esto evita que los agentes pierdan tiempo en soluciones aleatorias o parches rápidos que enmascaran problemas subyacentes y crean nuevos errores, garantizando que todas las soluciones propuestas aborden el problema real.","fr":"Applique la Loi de Fer du débogage systématique : AUCUNE CORRECTION SANS ENQUÊTE SUR LA CAUSE RACINE D''ABORD. Cela empêche les agents de perdre du temps sur des corrections aléatoires ou des correctifs rapides qui masquent les problèmes sous-jacents et créent de nouveaux bogues, garantissant que toutes les solutions proposées traitent le problème réel.","de":"Erzwingt das Eiserne Gesetz des systematischen Debuggens: KEINE FIXES OHNE ZUERST DIE URSACHE ZU UNTERSUCHEN. Dies verhindert, dass Agenten Zeit mit zufälligen Fixes oder schnellen Patches verschwenden, die zugrunde liegende Probleme verdecken und neue Fehler erzeugen, und stellt sicher, dass alle vorgeschlagenen Lösungen das tatsächliche Problem angehen.","pt":"Impõe a Lei de Ferro da depuração sistemática: SEM CORREÇÕES SEM INVESTIGAÇÃO PRÉVIA DA CAUSA RAIZ. Isso impede que os agents percam tempo com correções aleatórias ou patches rápidos que mascaram problemas subjacentes e criam novos bugs, garantindo que todas as soluções propostas abordem o problema real.","ru":"Внедряет железное правило систематической отладки: НЕТ ИСПРАВЛЕНИЙ БЕЗ ПРЕДВАРИТЕЛЬНОГО ИССЛЕДОВАНИЯ ПЕРВОПРИЧИНЫ. Это предотвращает трату времени agents на случайные исправления или быстрые патчи, которые маскируют основные проблемы и создают новые баги, гарантируя, что все предлагаемые решения устраняют фактическую проблему.","ar":"يفرض القانون الحديدي لتصحيح الأخطاء المنهجي: لا يوجد إصلاحات بدون التحقيق أولاً في السبب الجذري. هذا يمنع العوامل من إضاعة الوقت في إصلاحات عشوائية أو تصحيحات سريعة تخفي المشكلات الأساسية وتخلق أخطاءً جديدة، مما يضمن أن جميع الحلول المقترحة تعالج المشكلة الفعلية."},"useCases":{"en":["Investigating test failures systematically","Debugging unexpected software behavior","Analyzing bug reports to identify root cause","Preventing symptom-level fixes that create technical debt"],"zh":["系统地调查测试失败","调试意外的软件行为","分析错误报告以确定根本原因","防止仅解决症状的修复导致技术债务"],"ja":["テストの失敗を体系的に調査すること","予期せぬソフトウェアの動作をデバッグすること","バグレポートを分析して根本原因を特定すること","症状レベルの修正による技術債務の発生を防ぐこと"],"ko":["시스템적으로 테스트 실패를 조사한다","예상치 못한 소프트웨어 동작을 디버깅한다","버그 보고서를 분석하여 근본 원인을 식별한다","증상 수준의 수정으로 인한 기술 부채를 방지한다"],"es":["Investigación sistemática de fallos en pruebas","Depuración de comportamientos inesperados del software","Análisis de informes de errores para identificar la causa raíz","Prevención de correcciones a nivel de síntoma que generan deuda técnica"],"fr":["Enquête systématique sur les échecs de tests","Débogage de comportements logiciels inattendus","Analyse des rapports de bogues pour identifier la cause racine","Prévention des correctifs au niveau des symptômes qui créent de la dette technique"],"de":["Systematische Untersuchung von Testfehlern","Debuggen unerwarteter Softwareverhalten","Analyse von Fehlerberichten zur Identifizierung der Ursache","Verhinderung von Symptombehebungen, die technische Schulden verursachen"],"pt":["Investigação sistemática de falhas em testes","Depuração de comportamentos inesperados de software","Análise de relatórios de bugs para identificar a causa raiz","Prevenção de correções no nível do sintoma que criam technical debt"],"ru":["Систематическое исследование сбоев тестов","Отладка неожиданного поведения программного обеспечения","Анализ отчетов об ошибках для выявления первопричины","Предотвращение исправлений на уровне симптомов, которые создают технический долг"],"ar":["التحقيق المنهجي في فشل الاختبارات","تصحيح السلوك غير المتوقع للبرمجيات","تحليل تقارير الأخطاء لتحديد السبب الجذري","منع الإصلاحات على مستوى الأعراض التي تخلق دينًا فنيًا (technical debt)"]},"limitations":{"en":["Requires full diagnostic investigation before any fix proposal","Cannot be used for quick patches or immediate symptom resolution","Mandates adherence to strict root cause analysis protocol"],"zh":["需要在任何修复方案提出之前进行完整的诊断调查","不能用于快速补丁或立即的症状解决","强制遵守严格的根本原因分析协议"],"ja":["修正提案前に完全な診断調査を行う必要があること","クイックパッチや即時の症状解決には使用できないこと","厳格な根本原因分析プロトコルへの遵守を強制すること"],"ko":["任何 수정 제안 전에 완전한 진단 조사를 요구한다","빠른 패치 또는 즉각적인 증상 해결에 사용할 수 없다","엄격한 근본 원인 분석 프로토콜을 준수하도록 강제한다"],"es":["Requiere una investigación diagnóstica completa antes de cualquier propuesta de solución","No puede usarse para parches rápidos o resolución inmediata de síntomas","Obliga a seguir un protocolo estricto de análisis de causa raíz"],"fr":["Nécessite une enquête diagnostique complète avant toute proposition de correctif","Ne peut pas être utilisé pour des correctifs rapides ou une résolution immédiate des symptômes","Impose le respect d''un protocole strict d''analyse de cause racine"],"de":["Erfordert eine vollständige diagnostische Untersuchung vor jedem Lösungsvorschlag","Kann nicht für schnelle Patches oder sofortige Symptombehebung verwendet werden","Schreibt die Einhaltung eines strengen Protokolls zur Ursachenanalyse vor"],"pt":["Requer uma investigação diagnóstica completa antes de qualquer proposta de correção","Não pode ser usado para patches rápidos ou resolução imediata de sintomas","Obriga a adesão a um protocolo estrito de análise de causa raiz"],"ru":["Требует полного диагностического исследования перед любым предложением по исправлению","Не может использоваться для быстрых патчей или немедленного устранения симптомов","Обязательно требует соблюдения строгого протокола анализа первопричин"],"ar":["يتطلب تحقيقًا تشخيصيًا كاملاً قبل أي اقتراح إصلاح","لا يمكن استخدامه للتصحيحات السريعة أو حل الأعراض الفوري","يفرض الالتزام ببروتوكول صارم لتحليل السبب الجذري"]},"version":4},"contentHash":"4999cb851360485eca5074e727bbdd62ef20549c5d5b01216fcbf5831badb473","repoEtag":"W/\"a8a266458ca9bbf6c9312a7647f733e0f1891eedfa2dde0bddcec7f7d186089e\"","qualityScore":86}');
