INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('obra/superpowers/systematic-debugging', 'systematic-debugging', 'obra', 'superpowers', 'official', 'systematic-debugging obra superpowers official The systematic-debugging skill is a disciplined protocol for AI Agents encountering bugs or test failures. It mandates a root cause analysis phase before any fix is proposed, preventing wasted effort and new bugs introduced by patches. It is essential for developers and QA engineers who require m... 系统调试是一种通过根因分析来解决技术问题的方法，确保在提出解决方案之前找到问题的根源 システムデバッグは、根本原因分析を使用して技術的な問題を解決する方法であり、解決策を提案する前に問題の根源を見つけることを保証します 시스템 디버깅은 루트 원인 분석을 사용하여 기술적인 문제를 해결하는 방법으로, 해결책을 제안하기 전에 문제의 근본 원인을 찾는 것을 보장합니다 La depuración sistemática es crucial para identificar la causa raíz de los errores. Aprende a aplicar este enfoque para agentes de IA. Le débogage systématique est essentiel pour identifier la cause profonde des erreurs. Découvrez comment l''appliquer pour les outils d''IA. Die systematische Fehlerbehebung ist entscheidend, um die Ursache von Fehlern zu identifizieren. Erfahren Sie, wie Sie diesen Ansatz für KI-Agents anwenden. Uma habilidade de IA para debugging que exige a identificação da causa raiz antes de qualquer proposta de correção. Impede soluções superficiais para test failures e bugs, aplicando uma metodologia rigorosa. Навык ИИ для отладки, требующий идентификации корневой причины до предложения исправлений. Предотвращает поверхностные решения для сбоев тестов и ошибок, применяя строгую методологию. مهارة ذكاء اصطناعي للتصحيح تتطلب تحديد السبب الجذري قبل أي محاولة إصلاح. تمنع الحلول السطحية لأعطال الاختبار والأخطاء من خلال تطبيق منهجية صارمة. systematic-debugging root cause analysis how to use systematic-debugging skill AI agent debugging protocol systematic-debugging vs random fixes install systematic-debugging skill systematic-debugging for test failures what is systematic-debugging systematic-debugging setup guide 系统调试 根因分析 测试失败处理 AI工具 技术问题解决 调试最佳实践 系统调试设置指南 Enforces the Iron Law: ''NO FIXES WITHOUT ROOT CAUSE INVESTIGATION FIRST'' Triggered automatically by any bug, test failure, or unexpected behavior Prevents symptom fixes that mask underlying problems Designed to stop random fixes that waste time and create new bugs systematic-debugging is an AI Agent skill that enforces a strict debugging process. It prohibits proposing fixes until a root cause investigation is complete, ensuring that solutions address underlying issues rather than just symptoms.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/backend-patterns', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'backend-patterns', 61988, 7678, 86, '2026-03-06T03:39:20Z', '2026-03-06T03:47:38.933Z', '681c33b4e125860295ca2639083cba524c77261e81efd67a3ce30b75593e7512', '{"id":"affaan-m/everything-claude-code/backend-patterns","name":"backend-patterns","description":{"en":"The backend-patterns skill provides best practices for Node.js, Express, and Next.js API routes, helping developers design scalable server-side applications.","zh":"这是一个专注于后端架构模式的AI代理技能，为使用Node.js、Express和Next.js的开发者提供API设计、数据库优化和服务器端最佳实践的专业指导。","ja":"バックエンドアーキテクチャパターンに特化したAIエージェントスキル。Node.js、Express、Next.jsを使用する開発者にAPI設計、データベース最適化、サーバーサイドのベストプラクティスを提供します。","ko":"백엔드 아키텍처 패턴에 특화된 AI 에이전트 스킬입니다. Node.js, Express, Next.js를 사용하는 개발자에게 API 설계, 데이터베이스 최적화, 서버 사이드 최적의 방법론을 제공합니다.","es":"Un agente de IA especializado en patrones de desarrollo backend para Node.js. Proporciona mejores prácticas para diseño de API, optimización de bases de datos, caching y estructuración de capas de servicio y controlador.","fr":"Un agent IA spécialisé dans les patterns de développement backend pour Node.js. Fournit les meilleures pratiques pour la conception d''API, l''optimisation des bases de données, le caching et la structuration des couches service et contrôleur.","de":"Ein KI-Agent spezialisiert auf Backend-Entwicklungspatterns für Node.js. Bietet Best Practices für API-Design, Datenbankoptimierung, Caching und die Strukturierung von Service- und Controller-Schichten."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"backend-patterns","description":"Backend architecture patterns, API design, database optimization, and server-side best practices for Node.js, Express, and Next.js API routes.","bodyPreview":"# Backend Development Patterns\n\nBackend architecture patterns and best practices for scalable server-side applications.\n\n## When to Activate\n\n- Designing REST or GraphQL API endpoints\n- Implementing repository, service, or controller layers\n- Optimizing database queries (N+1, indexing, connection pooling)\n- Adding caching (Redis, in-memory, HTTP cache headers)\n- Setting up background jobs or async processing\n- Structuring error handling and validation for APIs\n- Building middleware (auth, loggin","body":"# Backend Development Patterns\n\nBackend architecture patterns and best practices for scalable server-side applications.\n\n## When to Activate\n\n- Designing REST or GraphQL API endpoints\n- Implementing repository, service, or controller layers\n- Optimizing database queries (N+1, indexing, connection pooling)\n- Adding caching (Redis, in-memory, HTTP cache headers)\n- Setting up background jobs or async processing\n- Structuring error handling and validation for APIs\n- Building middleware (auth, logging, rate limiting)\n\n## API Design Patterns\n\n### RESTful API Structure\n\n```typescript\n// ✅ Resource-based URLs\nGET    /api/markets                 # List resources\nGET    /api/markets/:id             # Get single resource\nPOST   /api/markets                 # Create resource\nPUT    /api/markets/:id             # Replace resource\nPATCH  /api/markets/:id             # Update resource\nDELETE /api/markets/:id             # Delete resource\n\n// ✅ Query parameters for filtering, sorting, pagination\nGET /api/markets?status=active&sort=volume&limit=20&offset=0\n```\n\n### Repository Pattern\n\n```typescript\n// Abstract data access logic\ninterface MarketRepository {\n  findAll(filters?: MarketFilters): Promise<Market[]>\n  findById(id: string): Promise<Market | null>\n  create(data: CreateMarketDto): Promise<Market>\n  update(id: string, data: UpdateMarketDto): Promise<Market>\n  delete(id: string): Promise<void>\n}\n\nclass SupabaseMarketRepository implements MarketRepository {\n  async findAll(filters?: MarketFilters): Promise<Market[]> {\n    let query = supabase.from(''markets'').select(''*'')\n\n    if (filters?.status) {\n      query = query.eq(''status'', filters.status)\n    }\n\n    if (filters?.limit) {\n      query = query.limit(filters.limit)\n    }\n\n    const { data, error } = await query\n\n    if (error) throw new Error(error.message)\n    return data\n  }\n\n  // Other methods...\n}\n```\n\n### Service Layer Pattern\n\n```typescript\n// Business logic separated from data access\nclass MarketService {\n  constructor(private marketRepo: MarketRepository) {}\n\n  async searchMarkets(query: string, limit: number = 10): Promise<Market[]> {\n    // Business logic\n    const embedding = await generateEmbedding(query)\n    const results = await this.vectorSearch(embedding, limit)\n\n    // Fetch full data\n    const markets = await this.marketRepo.findByIds(results.map(r => r.id))\n\n    // Sort by similarity\n    return markets.sort((a, b) => {\n      const scoreA = results.find(r => r.id === a.id)?.score || 0\n      const scoreB = results.find(r => r.id === b.id)?.score || 0\n      return scoreA - scoreB\n    })\n  }\n\n  private async vectorSearch(embedding: number[], limit: number) {\n    // Vector search implementation\n  }\n}\n```\n\n### Middleware Pattern\n\n```typescript\n// Request/response processing pipeline\nexport function withAuth(handler: NextApiHandler): NextApiHandler {\n  return async (req, res) => {\n    const token = req.headers.authorization?.replace(''Bearer '', '''')\n\n    if (!token) {\n      return res.status(401).json({ error: ''Unauthorized'' })\n    }\n\n    try {\n      const user = await verifyToken(token)\n      req.user = user\n      return handler(req, res)\n    } catch (error) {\n      return res.status(401).json({ error: ''Invalid token'' })\n    }\n  }\n}\n\n// Usage\nexport default withAuth(async (req, res) => {\n  // Handler has access to req.user\n})\n```\n\n## Database Patterns\n\n### Query Optimization\n\n```typescript\n// ✅ GOOD: Select only needed columns\nconst { data } = await supabase\n  .from(''markets'')\n  .select(''id, name, status, volume'')\n  .eq(''status'', ''active'')\n  .order(''volume'', { ascending: false })\n  .limit(10)\n\n// ❌ BAD: Select everything\nconst { data } = await supabase\n  .from(''markets'')\n  .select(''*'')\n```\n\n### N+1 Query Prevention\n\n```typescript\n// ❌ BAD: N+1 query problem\nconst markets = await getMarkets()\nfor (const market of markets) {\n  market.creator = await getUser(market.creator_id)  // N queries\n}\n\n// ✅ GOOD: Batch fetch\nconst markets = await getMarkets()\nconst creatorIds = markets.map(m => m.creator_id)\nconst creators = await getUsers(creatorIds)  // 1 query\nconst creatorMap = new Map(creators.map(c => [c.id, c]))\n\nmarkets.forEach(market => {\n  market.creator = creatorMap.get(market.creator_id)\n})\n```\n\n### Transaction Pattern\n\n```typescript\nasync function createMarketWithPosition(\n  marketData: CreateMarketDto,\n  positionData: CreatePositionDto\n) {\n  // Use Supabase transaction\n  const { data, error } = await supabase.rpc(''create_market_with_position'', {\n    market_data: marketData,\n    position_data: positionData\n  })\n\n  if (error) throw new Error(''Transaction failed'')\n  return data\n}\n\n// SQL function in Supabase\nCREATE OR REPLACE FUNCTION create_market_with_position(\n  market_data jsonb,\n  position_data jsonb\n)\nRETURNS jsonb\nLANGUAGE plpgsql\nAS $$\nBEGIN\n  -- Start transaction automatically\n  INSERT INTO markets VALUES (market_data);\n  INSERT INTO positions VALUES (position_data);\n  RETURN jsonb_build_object(''success'', true);\nEXCEPTION\n  WHEN OTHERS THEN\n    -- Rollback happens automatically\n    RETURN jsonb_build_object(''success'', false, ''error'', SQLERRM);\nEND;\n$$;\n```\n\n## Caching Strategies\n\n### Redis Caching Layer\n\n```typescript\nclass CachedMarketRepository implements MarketRepository {\n  constructor(\n    private baseRepo: MarketRepository,\n    private redis: RedisClient\n  ) {}\n\n  async findById(id: string): Promise<Market | null> {\n    // Check cache first\n    const cached = await this.redis.get(`market:${id}`)\n\n    if (cached) {\n      return JSON.parse(cached)\n    }\n\n    // Cache miss - fetch from database\n    const market = await this.baseRepo.findById(id)\n\n    if (market) {\n      // Cache for 5 minutes\n      await this.redis.setex(`market:${id}`, 300, JSON.stringify(market))\n    }\n\n    return market\n  }\n\n  async invalidateCache(id: string): Promise<void> {\n    await this.redis.del(`market:${id}`)\n  }\n}\n```\n\n### Cache-Aside Pattern\n\n```typescript\nasync function getMarketWithCache(id: string): Promise<Market> {\n  const cacheKey = `market:${id}`\n\n  // Try cache\n  const cached = await redis.get(cacheKey)\n  if (cached) return JSON.parse(cached)\n\n  // Cache miss - fetch from DB\n  const market = await db.markets.findUnique({ where: { id } })\n\n  if (!market) throw new Error(''Market not found'')\n\n  // Update cache\n  await redis.setex(cacheKey, 300, JSON.stringify(market))\n\n  return market\n}\n```\n\n## Error Handling Patterns\n\n### Centralized Error Handler\n\n```typescript\nclass ApiError extends Error {\n  constructor(\n    public statusCode: number,\n    public message: string,\n    public isOperational = true\n  ) {\n    super(message)\n    Object.setPrototypeOf(this, ApiError.prototype)\n  }\n}\n\nexport function errorHandler(error: unknown, req: Request): Response {\n  if (error instanceof ApiError) {\n    return NextResponse.json({\n      success: false,\n      error: error.message\n    }, { status: error.statusCode })\n  }\n\n  if (error instanceof z.ZodError) {\n    return NextResponse.json({\n      success: false,\n      error: ''Validation failed'',\n      details: error.errors\n    }, { status: 400 })\n  }\n\n  // Log unexpected errors\n  console.error(''Unexpected error:'', error)\n\n  return NextResponse.json({\n    success: false,\n    error: ''Internal server error''\n  }, { status: 500 })\n}\n\n// Usage\nexport async function GET(request: Request) {\n  try {\n    const data = await fetchData()\n    return NextResponse.json({ success: true, data })\n  } catch (error) {\n    return errorHandler(error, request)\n  }\n}\n```\n\n### Retry with Exponential Backoff\n\n```typescript\nasync function fetchWithRetry<T>(\n  fn: () => Promise<T>,\n  maxRetries = 3\n): Promise<T> {\n  let lastError: Error\n\n  for (let i = 0; i < maxRetries; i++) {\n    try {\n      return await fn()\n    } catch (error) {\n      lastError = error as Error\n\n      if (i < maxRetries - 1) {\n        // Exponential backoff: 1s, 2s, 4s\n        const delay = Math.pow(2, i) * 1000\n        await new Promise(resolve => setTimeout(resolve, delay))\n      }\n    }\n  }\n\n  throw lastError!\n}\n\n// Usage\nconst data = await fetchWithRetry(() => fetchFromAPI())\n```\n\n## Authentication & Authorization\n\n### JWT Token Validation\n\n```typescript\nimport jwt from ''jsonwebtoken''\n\ninterface JWTPayload {\n  userId: string\n  email: string\n  role: ''admin'' | ''user''\n}\n\nexport function verifyToken(token: string): JWTPayload {\n  try {\n    const payload = jwt.verify(token, process.env.JWT_SECRET!) as JWTPayload\n    return payload\n  } catch (error) {\n    throw new ApiError(401, ''Invalid token'')\n  }\n}\n\nexport async function requireAuth(request: Request) {\n  const token = request.headers.get(''authorization'')?.replace(''Bearer '', '''')\n\n  if (!token) {\n    throw new ApiError(401, ''Missing authorization token'')\n  }\n\n  return verifyToken(token)\n}\n\n// Usage in API route\nexport async function GET(request: Request) {\n  const user = await requireAuth(request)\n\n  const data = await getDataForUser(user.userId)\n\n  return NextResponse.json({ success: true, data })\n}\n```\n\n### Role-Based Access Control\n\n```typescript\ntype Permission = ''read'' | ''write'' | ''delete'' | ''admin''\n\ninterface User {\n  id: string\n  role: ''admin'' | ''moderator'' | ''user''\n}\n\nconst rolePermissions: Record<User[''role''], Permission[]> = {\n  admin: [''read'', ''write'', ''delete'', ''admin''],\n  moderator: [''read'', ''write'', ''delete''],\n  user: [''read'', ''write'']\n}\n\nexport function hasPermission(user: User, permission: Permission): boolean {\n  return rolePermissions[user.role].includes(permission)\n}\n\nexport function requirePermission(permission: Permission) {\n  return (handler: (request: Request, user: User) => Promise<Response>) => {\n    return async (request: Request) => {\n      const user = await requireAuth(request)\n\n      if (!hasPermission(user, permission)) {\n        throw new ApiError(403, ''Insufficient permissions'')\n      }\n\n      return handler(request, user)\n    }\n  }\n}\n\n// Usage - HOF wraps the handler\nexport const DELETE = requirePermission(''delete'')(\n  async (request: Request, user: User) => {\n    // Handler receives authenticated user with verified permission\n    return new Response(''Deleted'', { status: 200 })\n  }\n)\n```\n\n## Rate Limiting\n\n### Simple In-Memory Rate Limiter\n\n```typescript\nclass RateLimiter {\n  private requests = new Map<string, number[]>()\n\n  async checkLimit(\n    identifier: string,\n    maxRequests: number,\n    windowMs: number\n  ): Promise<boolean> {\n    const now = Date.now()\n    const requests = this.requests.get(identifier) || []\n\n    // Remove old requests outside window\n    const recentRequests = requests.filter(time => now - time < windowMs)\n\n    if (recentRequests.length >= maxRequests) {\n      return false  // Rate limit exceeded\n    }\n\n    // Add current request\n    recentRequests.push(now)\n    this.requests.set(identifier, recentRequests)\n\n    return true\n  }\n}\n\nconst limiter = new RateLimiter()\n\nexport async function GET(request: Request) {\n  const ip = request.headers.get(''x-forwarded-for'') || ''unknown''\n\n  const allowed = await limiter.checkLimit(ip, 100, 60000)  // 100 req/min\n\n  if (!allowed) {\n    return NextResponse.json({\n      error: ''Rate limit exceeded''\n    }, { status: 429 })\n  }\n\n  // Continue with request\n}\n```\n\n## Background Jobs & Queues\n\n### Simple Queue Pattern\n\n```typescript\nclass JobQueue<T> {\n  private queue: T[] = []\n  private processing = false\n\n  async add(job: T): Promise<void> {\n    this.queue.push(job)\n\n    if (!this.processing) {\n      this.process()\n    }\n  }\n\n  private async process(): Promise<void> {\n    this.processing = true\n\n    while (this.queue.length > 0) {\n      const job = this.queue.shift()!\n\n      try {\n        await this.execute(job)\n      } catch (error) {\n        console.error(''Job failed:'', error)\n      }\n    }\n\n    this.processing = false\n  }\n\n  private async execute(job: T): Promise<void> {\n    // Job execution logic\n  }\n}\n\n// Usage for indexing markets\ninterface IndexJob {\n  marketId: string\n}\n\nconst indexQueue = new JobQueue<IndexJob>()\n\nexport async function POST(request: Request) {\n  const { marketId } = await request.json()\n\n  // Add to queue instead of blocking\n  await indexQueue.add({ marketId })\n\n  return NextResponse.json({ success: true, message: ''Job queued'' })\n}\n```\n\n## Logging & Monitoring\n\n### Structured Logging\n\n```typescript\ninterface LogContext {\n  userId?: string\n  requestId?: string\n  method?: string\n  path?: string\n  [key: string]: unknown\n}\n\nclass Logger {\n  log(level: ''info'' | ''warn'' | ''error'', message: string, context?: LogContext) {\n    const entry = {\n      timestamp: new Date().toISOString(),\n      level,\n      message,\n      ...context\n    }\n\n    console.log(JSON.stringify(entry))\n  }\n\n  info(message: string, context?: LogContext) {\n    this.log(''info'', message, context)\n  }\n\n  warn(message: string, context?: LogContext) {\n    this.log(''warn'', message, context)\n  }\n\n  error(message: string, error: Error, context?: LogContext) {\n    this.log(''error'', message, {\n      ...context,\n      error: error.message,\n      stack: error.stack\n    })\n  }\n}\n\nconst logger = new Logger()\n\n// Usage\nexport async function GET(request: Request) {\n  const requestId = crypto.randomUUID()\n\n  logger.info(''Fetching markets'', {\n    requestId,\n    method: ''GET'',\n    path: ''/api/markets''\n  })\n\n  try {\n    const markets = await fetchMarkets()\n    return NextResponse.json({ success: true, data: markets })\n  } catch (error) {\n    logger.error(''Failed to fetch markets'', error as Error, { requestId })\n    return NextResponse.json({ error: ''Internal error'' }, { status: 500 })\n  }\n}\n```\n\n**Remember**: Backend patterns enable scalable, maintainable server-side applications. Choose patterns that fit your complexity level.\n"},"category":"official","lastSynced":"2026-03-06T03:47:38.933Z","seo":{"title":{"en":"backend-patterns: API Design and Server-Side Best Practic...","zh":"Backend-Patterns AI 代理：Node.js 后端架构模式最佳实践","ja":"Backend-Patterns AIエージェント：Node.js バックエンドパターン実践ガイド","ko":"Backend-Patterns AI 에이전트: Node.js 백엔드 아키텍처 패턴 최적화 가이드","es":"Patrones Backend: Guía de Patrones y Mejores Prácticas pa...","fr":"Modèles Backend : Guide des Patterns et Bonnes Pratiques ...","de":"Backend Patterns: Leitfaden für Patterns und Best Practic..."},"description":{"en":"Unlock scalable server-side applications with backend-patterns. Learn API design, database optimization, and more. Get started now!","zh":"专为Node.js、Express和Next.js设计的AI代理，提供REST/GraphQL API设计、数据库查询优化、Redis缓存和中间件架构等后端模式最佳实践，提升开发效率。","ja":"Node.js、Express、Next.js APIルート向けAIエージェント。REST/GraphQL API設計、データベース最適化(N+1、インデックス)、Redisキャッシュ、ミドルウェア実装のベストプラクティスを提供。","ko":"Node.js, Express, Next.js API 경로를 위한 AI 에이전트. REST/GraphQL API 엔드포인트 설계, 데이터베이스 쿼리 최적화(N+1, 인덱싱), Redis 캐싱, 미들웨어 아키텍처 구현을 지원하는 백엔드 패턴 전문 도구.","es":"Optimiza tus APIs con este agente de IA. Domina patrones de arquitectura backend, diseño de API REST/GraphQL, optimización de consultas DB, caching con Redis...","fr":"Optimisez vos APIs avec cet outil IA. Maîtrisez les patterns d''architecture backend, la conception d''API REST/GraphQL, l''optimisation des requêtes DB, le cac...","de":"Optimiere deine APIs mit diesem KI-Tool. Beherrsche Backend-Architekturpatterns, REST/GraphQL-API-Design, Datenbankabfrageoptimierung, Caching mit Redis und ..."},"definition":{"en":"backend-patterns is a set of techniques for designing and implementing efficient server-side architectures, including REST and GraphQL API endpoints","zh":"Backend-Patterns是一个AI代理技能，专门为Node.js生态系统提供后端开发模式指导。它涵盖API端点设计、数据库查询优化、缓存策略实施、中间件架构以及异步处理等服务器端最佳实践。","ja":"Backend-Patternsは、Node.jsエコシステム向けのバックエンド開発パターンを指導するAIエージェントスキルです。APIエンドポイント設計、データベースクエリ最適化、キャッシュ戦略実装、ミドルウェアアーキテクチャ、非同期処理などのサーバーサイドベストプラクティスをカバーします。","ko":"Backend-Patterns는 Node.js 생태계를 위한 백엔드 개발 패턴 지도를 제공하는 AI 에이전트 스킬입니다. API 엔드포인트 설계, 데이터베이스 쿼리 최적화, 캐싱 전략 구현, 미들웨어 아키텍처, 비동기 처리 등의 서버 사이드 최적의 방법론을 다룹니다.","es":"backend-patterns es un agente de IA que ayuda a desarrolladores a implementar patrones de arquitectura backend escalables. Se enfoca en diseño de API, optimización de bases de datos, caching y mejores prácticas para Node.js, Express y Next.js API routes.","fr":"backend-patterns est un outil IA qui aide les développeurs à implémenter des patterns d''architecture backend évolutifs. Il se concentre sur la conception d''API, l''optimisation des bases de données, le caching et les bonnes pratiques pour Node.js, Express et Next.js API routes.","de":"backend-patterns ist ein KI-Tool, das Entwicklern hilft, skalierbare Backend-Architekturpatterns umzusetzen. Der Fokus liegt auf API-Design, Datenbankoptimierung, Caching und Best Practices für Node.js, Express und Next.js API routes."},"features":{"en":["Designs REST and GraphQL API endpoints for Node.js, Express, and Next.js","Optimizes database queries using N+1, indexing, and connection pooling","Implements caching using Redis, in-memory, and HTTP cache headers","Structures error handling and validation for APIs","Sets up background jobs and async processing for efficient server-side operations"],"zh":["REST和GraphQL API端点设计指导","数据库查询优化（解决N+1问题、索引优化、连接池）","Redis缓存和HTTP缓存头实现","中间件架构（身份验证、日志记录）","异步处理和后台作业设置","API错误处理和验证结构"],"ja":["REST及びGraphQL APIエンドポイント設計ガイダンス","データベースクエリ最適化（N+1問題対策、インデックス、接続プール）","RedisキャッシュとHTTPキャッシュヘッダー実装","ミドルウェアアーキテクチャ（認証、ロギング）","非同期処理とバックグラウンドジョブ設定","APIエラーハンドリングと検証構造"],"ko":["REST 및 GraphQL API 엔드포인트 설계 가이드","데이터베이스 쿼리 최적화 (N+1 문제 해결, 인덱싱, 연결 풀링)","Redis 캐싱 및 HTTP 캐시 헤더 구현","미들웨어 아키텍처 (인증, 로깅)","비동기 처리 및 백그라운드 작업 설정","API 오류 처리 및 유효성 검사 구조"],"es":["Diseño de endpoints API REST y GraphQL","Implementación de capas repository, service y controller","Optimización de consultas de base de datos (N+1, indexing, connection pooling)","Configuración de caching con Redis y headers HTTP","Estructuración de manejo de errores y validación para APIs","Construcción de middleware para autenticación y logging"],"fr":["Conception d''endpoints API REST et GraphQL","Implémentation des couches repository, service et controller","Optimisation des requêtes de base de données (N+1, indexing, connection pooling)","Configuration du caching avec Redis et en-têtes HTTP","Structuration de la gestion des erreurs et validation pour les APIs","Construction de middleware pour l''authentification et la journalisation"],"de":["Design von REST- und GraphQL-API-Endpunkten","Umsetzung von Repository-, Service- und Controller-Schichten","Optimierung von Datenbankabfragen (N+1, Indexierung, Connection Pooling)","Einrichtung von Caching mit Redis und HTTP-Headern","Strukturierung der Fehlerbehandlung und Validierung für APIs","Erstellung von Middleware für Authentifizierung und Protokollierung"]},"keywords":{"en":["how to use backend-patterns","backend-patterns for Node.js","API design best practices","backend-patterns vs REST","backend-patterns setup guide","scalable server-side applications","GraphQL API endpoint design","database optimization techniques"],"zh":["Node.js后端模式","Express API设计","Next.js API路由优化","数据库查询优化AI工具","Redis缓存实现","GraphQL API最佳实践","后端架构AI代理","服务器端中间件开发"],"ja":["Node.js バックエンドパターン","Express API設計","Next.js APIルート最適化","データベースクエリ最適化 AIエージェント","Redisキャッシュ実装","GraphQL API ベストプラクティス","バックエンドアーキテクチャ AIツール","サーバーサイドミドルウェア開発"],"ko":["Node.js 백엔드 패턴","Express API 설계","Next.js API 경로 최적화","데이터베이스 쿼리 최적화 AI 에이전트","Redis 캐싱 구현","GraphQL API 최적의 방법론","백엔드 아키텍처 AI 도구","서버 사이드 미들웨어 개발"],"es":["patrones backend Node.js","optimización consultas base de datos","API design REST GraphQL","caching Redis Express","middleware autenticación Next.js","agente IA desarrollo backend","mejores prácticas Express.js","estructura capas servicio controlador"],"fr":["patterns backend Node.js","optimisation requêtes base de données","conception API REST GraphQL","caching Redis Express","middleware authentification Next.js","outil IA développement backend","bonnes pratiques Express.js","structure couches service contrôleur"],"de":["Backend Patterns Node.js","Datenbankabfragen optimieren","API Design REST GraphQL","Caching Redis Express","Middleware Authentifizierung Next.js","KI-Tool Backend Entwicklung","Best Practices Express.js","Service Controller Schichten Struktur"]}},"agentAnalysis":{"suitability":{"en":"Essential for Backend Engineering Agents specializing in Node.js ecosystem API development and database optimization.","zh":"对于专注于 Node.js 生态系统 API 开发和数据库优化的后端工程代理至关重要。","ja":"Node.js エコシステムの API 開発とデータベースの最適化を専門とするバックエンドエンジニアリングエージェントに不可欠です。","ko":"Node.js 생태계 API 개발 및 데이터베이스 최적화를 전문으로 하는 백엔드 엔지니어링 에이전트에게 필수적입니다.","es":"Esencial para agentes de ingeniería de Backend especializados en el desarrollo de API del ecosistema Node.js y optimización de bases de datos.","fr":"Essentiel pour les agents d''ingénierie Backend spécialisés dans le développement d''API de l''écosystème Node.js et l''optimisation de bases de données.","de":"Essenziell für Backend Engineering Agents, die sich auf die API-Entwicklung im Node.js-Ökosystem und die Datenbankoptimierung spezialisieren.","pt":"Essencial para Agentes de Engenharia de Backend especializados no desenvolvimento de API no ecossistema Node.js e otimização de banco de dados.","ru":"Важно для Backend Engineering Agents, специализирующихся на разработке API в экосистеме Node.js и оптимизации баз данных.","ar":"أساسي لوكلات هندسة الخلفية المتخصصة في تطوير واجهات برمجة التطبيقات (API) في بيئة Node.js وتحسين قواعد البيانات."},"recommendation":{"en":"Provides comprehensive backend architecture patterns for implementing repository, service, and controller layers in Express and Next.js API routes. Enables advanced database optimization techniques including N+1 query resolution, indexing strategies, and Redis caching implementation.","zh":"为在 Express 和 Next.js API 路由中实现 Repository、Service 和 Controller 层提供了全面的后端架构模式。支持包括 N+1 查询解决方案、索引策略和 Redis 缓存实现在内的高级数据库优化技术。","ja":"Express および Next.js の API ルートで Repository、Service、Controller レイヤーを実装するための包括的なバックエンドアーキテクチャパターンを提供します。N+1 クエリの解決、インデックス戦略、Redis キャッシュの実装などの高度なデータベース最適化技術を可能にします。","ko":"Express 및 Next.js API 경로에서 Repository, Service 및 Controller 계층을 구현하기 위한 포괄적인 백엔드 아키텍처 패턴을 제공합니다. N+1 쿼리 해결, 인덱싱 전략 및 Redis 캐싱 구현을 포함한 고급 데이터베이스 최적화 기술을 가능하게 합니다.","es":"Proporciona patrones completos de arquitectura backend para implementar las capas de repositorio, servicio y controlador en rutas API de Express y Next.js. Permite técnicas avanzadas de optimización de bases de datos que incluyen la resolución de consultas N+1, estrategias de indexación e implementación de almacenamiento en caché con Redis.","fr":"Fournit des modèles d''architecture backend complets pour mettre en œuvre les couches de repository, service et contrôleur dans les routes API d''Express et de Next.js. Permet des techniques avancées d''optimisation de bases de données incluant la résolution de requêtes N+1, les stratégies d''indexation et la mise en œuvre de la mise en cache avec Redis.","de":"Bietet umfassende Backend-Architekturmuster zur Implementierung von Repository-, Service- und Controller-Schichten in Express- und Next.js-API-Routen. Ermöglicht fortgeschrittene Datenbankoptimierungstechniken, einschließlich der Lösung von N+1-Abfragen, Indexierungsstrategien und der Implementierung von Redis-Caching.","pt":"Fornece padrões abrangentes de arquitetura de backend para implementar camadas de repositório, serviço e controlador em rotas de API do Express e Next.js. Permite técnicas avançadas de otimização de banco de dados, incluindo resolução de consultas N+1, estratégias de indexação e implementação de cache com Redis.","ru":"Предоставляет комплексные шаблоны архитектуры бэкенда для реализации слоев репозитория, сервиса и контроллера в маршрутах API Express и Next.js. Позволяет применять передовые методы оптимизации баз данных, включая разрешение запросов N+1, стратегии индексирования и реализацию кэширования Redis.","ar":"يوفر أنماطًا شاملة لهندسة الخلفية لتطبيق طبقات المستودع والخدمة والتحكم في مسارات واجهات برمجة التطبيقات (API) الخاصة بـ Express وNext.js. يتيح تقنيات متقدمة لتحسين قواعد البيانات بما في ذلك حل استعلامات N+1، واستراتيجيات الفهرسة، وتنفيذ التخزين المؤقت باستخدام Redis."},"useCases":{"en":["Designing REST or GraphQL API endpoints","Optimizing database queries and connection pooling","Implementing middleware for authentication and logging","Structuring error handling and validation for server-side applications","Setting up background jobs and async processing systems"],"zh":["设计 REST 或 GraphQL API 端点","优化数据库查询和连接池","实现用于身份验证和日志记录的中间件","构建服务器端应用程序的错误处理和验证结构","设置后台作业和异步处理系统"],"ja":["REST または GraphQL API エンドポイントの設計","データベースクエリと接続プールの最適化","認証とロギングのためのミドルウェアの実装","サーバーサイドアプリケーションのエラー処理と検証の構造化","バックグラウンドジョブと非同期処理システムの設定"],"ko":["REST 또는 GraphQL API 엔드포인트 설계","데이터베이스 쿼리 및 연결 풀링 최적화","인증 및 로깅을 위한 미들웨어 구현","서버 측 애플리케이션의 오류 처리 및 검증 구조화","백그라운드 작업 및 비동기 처리 시스템 설정"],"es":["Diseño de endpoints API REST o GraphQL","Optimización de consultas de base de datos y agrupación de conexiones","Implementación de middleware para autenticación y registro","Estructuración del manejo de errores y validación para aplicaciones del lado del servidor","Configuración de trabajos en segundo plano y sistemas de procesamiento asíncrono"],"fr":["Conception d''endpoints API REST ou GraphQL","Optimisation des requêtes de base de données et du regroupement de connexions","Mise en œuvre de middleware pour l''authentification et la journalisation","Structuration de la gestion des erreurs et de la validation pour les applications côté serveur","Mise en place de travaux en arrière-plan et de systèmes de traitement asynchrone"],"de":["Entwurf von REST- oder GraphQL-API-Endpunkten","Optimierung von Datenbankabfragen und Connection Pooling","Implementierung von Middleware für Authentifizierung und Protokollierung","Strukturierung der Fehlerbehandlung und Validierung für serverseitige Anwendungen","Einrichtung von Hintergrundjobs und asynchronen Verarbeitungssystemen"],"pt":["Projetar endpoints de API REST ou GraphQL","Otimizar consultas de banco de dados e pool de conexões","Implementar middleware para autenticação e registro de logs","Estruturar tratamento de erros e validação para aplicações do lado do servidor","Configurar trabalhos em segundo plano e sistemas de processamento assíncrono"],"ru":["Проектирование конечных точек REST или GraphQL API","Оптимизация запросов к базе данных и пула соединений","Реализация middleware для аутентификации и логирования","Структурирование обработки ошибок и валидации для серверных приложений","Настройка фоновых заданий и систем асинхронной обработки"],"ar":["تصيف نقاط نهاية لواجهات برمجة التطبيقات (API) من نوع REST أو GraphQL","تحسين استعلامات قواعد البيانات وتجميع الاتصالات","تنفيح middleware للمصادقة وتسجيل الأحداث","هيكلة معالجة الأخطاء والتحقق من صحة التطبيقات من جانب الخادم","إعداد المهام الخلفية وأنظمة المعالجة غير المتزامنة"]},"limitations":{"en":["Node.js/Express/Next.js specific implementation","Requires database integration knowledge","Caching implementation depends on external services like Redis"],"zh":["Node.js/Express/Next.js 特定的实现","需要数据库集成知识","缓存实现依赖于 Redis 等外部服务"],"ja":["Node.js/Express/Next.js 固有の実装","データベース統合の知識が必要","キャッシュの実装は Redis などの外部サービスに依存"],"ko":["Node.js/Express/Next.js 특정 구현","데이터베이스 통합 지식 필요","캐싱 구현은 Redis와 같은 외부 서비스에 의존"],"es":["Implementación específica de Node.js/Express/Next.js","Requiere conocimientos de integración de bases de datos","La implementación de la caché depende de servicios externos como Redis"],"fr":["Implémentation spécifique à Node.js/Express/Next.js","Nécessite des connaissances en intégration de base de données","La mise en œuvre de la mise en cache dépend de services externes comme Redis"],"de":["Node.js/Express/Next.js-spezifische Implementierung","Erfordert Kenntnisse in der Datenbankintegration","Die Caching-Implementierung hängt von externen Diensten wie Redis ab"],"pt":["Implementação específica para Node.js/Express/Next.js","Requer conhecimento de integração com banco de dados","A implementação de cache depende de serviços externos como Redis"],"ru":["Специфичная реализация для Node.js/Express/Next.js","Требует знаний по интеграции с базами данных","Реализация кэширования зависит от внешних сервисов, таких как Redis"],"ar":["تنفيذ محدد لـ Node.js/Express/Next.js","يتطلب معرفة بدمج قواعد البيانات","يعتمد تنفيذ التخزين المؤقت على خدمات خارجية مثل Redis"]},"version":4},"contentHash":"681c33b4e125860295ca2639083cba524c77261e81efd67a3ce30b75593e7512","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":86}');
