INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/content-hash-cache-pattern', 'content-hash-cache-pattern', 'affaan-m', 'everything-claude-code', 'official', 'content-hash-cache-pattern affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The content-hash-cache-pattern skill caches expensive file processing results like PDF parsing and text extraction using SHA-256 content hashes as keys. It is designed for developers building file processing pipelines who need path-independent, auto-invalidating caching. 内容哈希缓存模式使用SHA-256内容哈希作为缓存键，优化文件处理管道，提高性能 コンテンツハッシュキャッシュパターンは、SHA-256コンテンツハッシュを使用してファイル処理パイプラインを最適化します 콘텐츠 해시 캐시 패턴은 SHA-256 콘텐츠 해시를 사용하여 파일 처리 파이프라인을 최적화합니다 El patrón de cache de hash de contenido utiliza hashes SHA-256 para almacenar resultados de procesamiento de archivos, lo que mejora la eficiencia y reduce la carga de trabajo Le modèle de cache de hachage de contenu utilise des hashes SHA-256 pour stocker les résultats du traitement de fichiers, ce qui améliore l''efficacité et réduit la charge de travail Das Content-Hash-Cache-Muster verwendet SHA-256-Hashes, um die Ergebnisse der Dateiverarbeitung zu speichern, was die Effizienz verbessert und die Arbeitslast reduziert Padrão de cache que usa hash de conteúdo SHA-256 para resultados caros de processamento de arquivos como análise de PDF e extração de texto. Independente de caminho, invalidação automática e separação de camada de serviço para AI Agents. Паттерн кэширования, использующий хэш содержимого SHA-256 для дорогостоящей обработки файлов, такого как анализ PDF и извлечение текста. Независим от пути, автоматическая инвалидация и разделение уровней сервиса для ИИ Агентов. نمط ذاكرة تخزين مؤقت يستخدم تجزئة محتوى SHA-256 لنتائج معالجة الملفات مكلفة مثل تحليل PDF واستخراج النص. مستقل عن المسار، إبطال تلقائي وفصل طبقة الخدمة لأدوات الذكاء الاصطناعي. content-hash-cache-pattern setup guide how to use content-hash-cache-pattern what is content-hash-cache-pattern content-hash-cache-pattern vs path-based caching content-hash-cache-pattern install SHA-256 cache key implementation MCP file processing cache auto-invalidating file cache PDF parsing cache pattern text extraction caching with content hash 内容哈希缓存模式 SHA-256内容哈希 文件处理优化 AIエージェント开发 性能优化 CLI选项 服务层分离 Uses SHA-256 content hashes as cache keys for deterministic lookups Provides path-independent caching that survives file moves and renames Auto-invalidates cache entries when source file content changes Designed for caching expensive PDF parsing and text extraction results Enables implementation of --cache/--no-cache CLI options Separates caching logic into a service layer for cleaner architecture content-hash-cache-pattern is an MCP skill that caches expensive file processing results using SHA-256 content hashes as cache keys. This provides a path-independent cache that survives file moves/renames and automatically invalidates when file content changes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/django-tdd', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'django-tdd', 61988, 7678, 86, '2026-03-06T03:39:20Z', '2026-03-06T04:04:20.375Z', '99ef0936053afecf9f1ebbca687cd4232f4baa5f491878d5157c70344f237cd6', '{"id":"affaan-m/everything-claude-code/django-tdd","name":"django-tdd","description":{"en":"The django-tdd skill enables developers to implement test-driven development for Django applications using pytest, factory_boy, and Django REST Framework, streamlining testing workflows.","zh":"Django TDD 技术提供了高效的测试解决方案，包括 pytest-django、factory_boy 和 Django REST Framework","ja":"Django TDD 技術は、pytest-django、factory_boy、Django REST Framework を使用した効率的なテスト ソリューションを提供します","ko":"Django TDD 기술은 pytest-django, factory_boy 및 Django REST Framework를 사용하여 효율적인 테스트 솔루션을 제공합니다","es":"django-tdd es una habilidad que proporciona estrategias de testing para Django con pytest-django, TDD y factory_boy","fr":"django-tdd est une compétence qui fournit des stratégies de testing pour Django avec pytest-django, TDD et factory_boy","de":"django-tdd ist eine Fähigkeit, die Testing-Strategien für Django mit pytest-django, TDD und factory_boy bereitstellt","pt":"O django-tdd é uma ferramenta para testes de Django com pytest-django, TDD e Django REST Framework.","ru":"django-tdd - это инструмент для тестирования Django с помощью pytest-django, TDD и Django REST Framework.","ar":"django-tdd هو أداة لاختبارات Django باستخدام pytest-django و TDD و Django REST Framework"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"django-tdd","description":"Django testing strategies with pytest-django, TDD methodology, factory_boy, mocking, coverage, and testing Django REST Framework APIs.","bodyPreview":"# Django Testing with TDD\n\nTest-driven development for Django applications using pytest, factory_boy, and Django REST Framework.\n\n## When to Activate\n\n- Writing new Django applications\n- Implementing Django REST Framework APIs\n- Testing Django models, views, and serializers\n- Setting up testing infrastructure for Django projects\n\n## TDD Workflow for Django\n\n### Red-Green-Refactor Cycle\n\n```python\n# Step 1: RED - Write failing test\ndef test_user_creation():\n    user = User.objects.create_user(ema","body":"# Django Testing with TDD\n\nTest-driven development for Django applications using pytest, factory_boy, and Django REST Framework.\n\n## When to Activate\n\n- Writing new Django applications\n- Implementing Django REST Framework APIs\n- Testing Django models, views, and serializers\n- Setting up testing infrastructure for Django projects\n\n## TDD Workflow for Django\n\n### Red-Green-Refactor Cycle\n\n```python\n# Step 1: RED - Write failing test\ndef test_user_creation():\n    user = User.objects.create_user(email=''test@example.com'', password=''testpass123'')\n    assert user.email == ''test@example.com''\n    assert user.check_password(''testpass123'')\n    assert not user.is_staff\n\n# Step 2: GREEN - Make test pass\n# Create User model or factory\n\n# Step 3: REFACTOR - Improve while keeping tests green\n```\n\n## Setup\n\n### pytest Configuration\n\n```ini\n# pytest.ini\n[pytest]\nDJANGO_SETTINGS_MODULE = config.settings.test\ntestpaths = tests\npython_files = test_*.py\npython_classes = Test*\npython_functions = test_*\naddopts =\n    --reuse-db\n    --nomigrations\n    --cov=apps\n    --cov-report=html\n    --cov-report=term-missing\n    --strict-markers\nmarkers =\n    slow: marks tests as slow\n    integration: marks tests as integration tests\n```\n\n### Test Settings\n\n```python\n# config/settings/test.py\nfrom .base import *\n\nDEBUG = True\nDATABASES = {\n    ''default'': {\n        ''ENGINE'': ''django.db.backends.sqlite3'',\n        ''NAME'': '':memory:'',\n    }\n}\n\n# Disable migrations for speed\nclass DisableMigrations:\n    def __contains__(self, item):\n        return True\n\n    def __getitem__(self, item):\n        return None\n\nMIGRATION_MODULES = DisableMigrations()\n\n# Faster password hashing\nPASSWORD_HASHERS = [\n    ''django.contrib.auth.hashers.MD5PasswordHasher'',\n]\n\n# Email backend\nEMAIL_BACKEND = ''django.core.mail.backends.console.EmailBackend''\n\n# Celery always eager\nCELERY_TASK_ALWAYS_EAGER = True\nCELERY_TASK_EAGER_PROPAGATES = True\n```\n\n### conftest.py\n\n```python\n# tests/conftest.py\nimport pytest\nfrom django.utils import timezone\nfrom django.contrib.auth import get_user_model\n\nUser = get_user_model()\n\n@pytest.fixture(autouse=True)\ndef timezone_settings(settings):\n    \"\"\"Ensure consistent timezone.\"\"\"\n    settings.TIME_ZONE = ''UTC''\n\n@pytest.fixture\ndef user(db):\n    \"\"\"Create a test user.\"\"\"\n    return User.objects.create_user(\n        email=''test@example.com'',\n        password=''testpass123'',\n        username=''testuser''\n    )\n\n@pytest.fixture\ndef admin_user(db):\n    \"\"\"Create an admin user.\"\"\"\n    return User.objects.create_superuser(\n        email=''admin@example.com'',\n        password=''adminpass123'',\n        username=''admin''\n    )\n\n@pytest.fixture\ndef authenticated_client(client, user):\n    \"\"\"Return authenticated client.\"\"\"\n    client.force_login(user)\n    return client\n\n@pytest.fixture\ndef api_client():\n    \"\"\"Return DRF API client.\"\"\"\n    from rest_framework.test import APIClient\n    return APIClient()\n\n@pytest.fixture\ndef authenticated_api_client(api_client, user):\n    \"\"\"Return authenticated API client.\"\"\"\n    api_client.force_authenticate(user=user)\n    return api_client\n```\n\n## Factory Boy\n\n### Factory Setup\n\n```python\n# tests/factories.py\nimport factory\nfrom factory import fuzzy\nfrom datetime import datetime, timedelta\nfrom django.contrib.auth import get_user_model\nfrom apps.products.models import Product, Category\n\nUser = get_user_model()\n\nclass UserFactory(factory.django.DjangoModelFactory):\n    \"\"\"Factory for User model.\"\"\"\n\n    class Meta:\n        model = User\n\n    email = factory.Sequence(lambda n: f\"user{n}@example.com\")\n    username = factory.Sequence(lambda n: f\"user{n}\")\n    password = factory.PostGenerationMethodCall(''set_password'', ''testpass123'')\n    first_name = factory.Faker(''first_name'')\n    last_name = factory.Faker(''last_name'')\n    is_active = True\n\nclass CategoryFactory(factory.django.DjangoModelFactory):\n    \"\"\"Factory for Category model.\"\"\"\n\n    class Meta:\n        model = Category\n\n    name = factory.Faker(''word'')\n    slug = factory.LazyAttribute(lambda obj: obj.name.lower())\n    description = factory.Faker(''text'')\n\nclass ProductFactory(factory.django.DjangoModelFactory):\n    \"\"\"Factory for Product model.\"\"\"\n\n    class Meta:\n        model = Product\n\n    name = factory.Faker(''sentence'', nb_words=3)\n    slug = factory.LazyAttribute(lambda obj: obj.name.lower().replace('' '', ''-''))\n    description = factory.Faker(''text'')\n    price = fuzzy.FuzzyDecimal(10.00, 1000.00, 2)\n    stock = fuzzy.FuzzyInteger(0, 100)\n    is_active = True\n    category = factory.SubFactory(CategoryFactory)\n    created_by = factory.SubFactory(UserFactory)\n\n    @factory.post_generation\n    def tags(self, create, extracted, **kwargs):\n        \"\"\"Add tags to product.\"\"\"\n        if not create:\n            return\n        if extracted:\n            for tag in extracted:\n                self.tags.add(tag)\n```\n\n### Using Factories\n\n```python\n# tests/test_models.py\nimport pytest\nfrom tests.factories import ProductFactory, UserFactory\n\ndef test_product_creation():\n    \"\"\"Test product creation using factory.\"\"\"\n    product = ProductFactory(price=100.00, stock=50)\n    assert product.price == 100.00\n    assert product.stock == 50\n    assert product.is_active is True\n\ndef test_product_with_tags():\n    \"\"\"Test product with tags.\"\"\"\n    tags = [TagFactory(name=''electronics''), TagFactory(name=''new'')]\n    product = ProductFactory(tags=tags)\n    assert product.tags.count() == 2\n\ndef test_multiple_products():\n    \"\"\"Test creating multiple products.\"\"\"\n    products = ProductFactory.create_batch(10)\n    assert len(products) == 10\n```\n\n## Model Testing\n\n### Model Tests\n\n```python\n# tests/test_models.py\nimport pytest\nfrom django.core.exceptions import ValidationError\nfrom tests.factories import UserFactory, ProductFactory\n\nclass TestUserModel:\n    \"\"\"Test User model.\"\"\"\n\n    def test_create_user(self, db):\n        \"\"\"Test creating a regular user.\"\"\"\n        user = UserFactory(email=''test@example.com'')\n        assert user.email == ''test@example.com''\n        assert user.check_password(''testpass123'')\n        assert not user.is_staff\n        assert not user.is_superuser\n\n    def test_create_superuser(self, db):\n        \"\"\"Test creating a superuser.\"\"\"\n        user = UserFactory(\n            email=''admin@example.com'',\n            is_staff=True,\n            is_superuser=True\n        )\n        assert user.is_staff\n        assert user.is_superuser\n\n    def test_user_str(self, db):\n        \"\"\"Test user string representation.\"\"\"\n        user = UserFactory(email=''test@example.com'')\n        assert str(user) == ''test@example.com''\n\nclass TestProductModel:\n    \"\"\"Test Product model.\"\"\"\n\n    def test_product_creation(self, db):\n        \"\"\"Test creating a product.\"\"\"\n        product = ProductFactory()\n        assert product.id is not None\n        assert product.is_active is True\n        assert product.created_at is not None\n\n    def test_product_slug_generation(self, db):\n        \"\"\"Test automatic slug generation.\"\"\"\n        product = ProductFactory(name=''Test Product'')\n        assert product.slug == ''test-product''\n\n    def test_product_price_validation(self, db):\n        \"\"\"Test price cannot be negative.\"\"\"\n        product = ProductFactory(price=-10)\n        with pytest.raises(ValidationError):\n            product.full_clean()\n\n    def test_product_manager_active(self, db):\n        \"\"\"Test active manager method.\"\"\"\n        ProductFactory.create_batch(5, is_active=True)\n        ProductFactory.create_batch(3, is_active=False)\n\n        active_count = Product.objects.active().count()\n        assert active_count == 5\n\n    def test_product_stock_management(self, db):\n        \"\"\"Test stock management.\"\"\"\n        product = ProductFactory(stock=10)\n        product.reduce_stock(5)\n        product.refresh_from_db()\n        assert product.stock == 5\n\n        with pytest.raises(ValueError):\n            product.reduce_stock(10)  # Not enough stock\n```\n\n## View Testing\n\n### Django View Testing\n\n```python\n# tests/test_views.py\nimport pytest\nfrom django.urls import reverse\nfrom tests.factories import ProductFactory, UserFactory\n\nclass TestProductViews:\n    \"\"\"Test product views.\"\"\"\n\n    def test_product_list(self, client, db):\n        \"\"\"Test product list view.\"\"\"\n        ProductFactory.create_batch(10)\n\n        response = client.get(reverse(''products:list''))\n\n        assert response.status_code == 200\n        assert len(response.context[''products'']) == 10\n\n    def test_product_detail(self, client, db):\n        \"\"\"Test product detail view.\"\"\"\n        product = ProductFactory()\n\n        response = client.get(reverse(''products:detail'', kwargs={''slug'': product.slug}))\n\n        assert response.status_code == 200\n        assert response.context[''product''] == product\n\n    def test_product_create_requires_login(self, client, db):\n        \"\"\"Test product creation requires authentication.\"\"\"\n        response = client.get(reverse(''products:create''))\n\n        assert response.status_code == 302\n        assert response.url.startswith(''/accounts/login/'')\n\n    def test_product_create_authenticated(self, authenticated_client, db):\n        \"\"\"Test product creation as authenticated user.\"\"\"\n        response = authenticated_client.get(reverse(''products:create''))\n\n        assert response.status_code == 200\n\n    def test_product_create_post(self, authenticated_client, db, category):\n        \"\"\"Test creating a product via POST.\"\"\"\n        data = {\n            ''name'': ''Test Product'',\n            ''description'': ''A test product'',\n            ''price'': ''99.99'',\n            ''stock'': 10,\n            ''category'': category.id,\n        }\n\n        response = authenticated_client.post(reverse(''products:create''), data)\n\n        assert response.status_code == 302\n        assert Product.objects.filter(name=''Test Product'').exists()\n```\n\n## DRF API Testing\n\n### Serializer Testing\n\n```python\n# tests/test_serializers.py\nimport pytest\nfrom rest_framework.exceptions import ValidationError\nfrom apps.products.serializers import ProductSerializer\nfrom tests.factories import ProductFactory\n\nclass TestProductSerializer:\n    \"\"\"Test ProductSerializer.\"\"\"\n\n    def test_serialize_product(self, db):\n        \"\"\"Test serializing a product.\"\"\"\n        product = ProductFactory()\n        serializer = ProductSerializer(product)\n\n        data = serializer.data\n\n        assert data[''id''] == product.id\n        assert data[''name''] == product.name\n        assert data[''price''] == str(product.price)\n\n    def test_deserialize_product(self, db):\n        \"\"\"Test deserializing product data.\"\"\"\n        data = {\n            ''name'': ''Test Product'',\n            ''description'': ''Test description'',\n            ''price'': ''99.99'',\n            ''stock'': 10,\n            ''category'': 1,\n        }\n\n        serializer = ProductSerializer(data=data)\n\n        assert serializer.is_valid()\n        product = serializer.save()\n\n        assert product.name == ''Test Product''\n        assert float(product.price) == 99.99\n\n    def test_price_validation(self, db):\n        \"\"\"Test price validation.\"\"\"\n        data = {\n            ''name'': ''Test Product'',\n            ''price'': ''-10.00'',\n            ''stock'': 10,\n        }\n\n        serializer = ProductSerializer(data=data)\n\n        assert not serializer.is_valid()\n        assert ''price'' in serializer.errors\n\n    def test_stock_validation(self, db):\n        \"\"\"Test stock cannot be negative.\"\"\"\n        data = {\n            ''name'': ''Test Product'',\n            ''price'': ''99.99'',\n            ''stock'': -5,\n        }\n\n        serializer = ProductSerializer(data=data)\n\n        assert not serializer.is_valid()\n        assert ''stock'' in serializer.errors\n```\n\n### API ViewSet Testing\n\n```python\n# tests/test_api.py\nimport pytest\nfrom rest_framework.test import APIClient\nfrom rest_framework import status\nfrom django.urls import reverse\nfrom tests.factories import ProductFactory, UserFactory\n\nclass TestProductAPI:\n    \"\"\"Test Product API endpoints.\"\"\"\n\n    @pytest.fixture\n    def api_client(self):\n        \"\"\"Return API client.\"\"\"\n        return APIClient()\n\n    def test_list_products(self, api_client, db):\n        \"\"\"Test listing products.\"\"\"\n        ProductFactory.create_batch(10)\n\n        url = reverse(''api:product-list'')\n        response = api_client.get(url)\n\n        assert response.status_code == status.HTTP_200_OK\n        assert response.data[''count''] == 10\n\n    def test_retrieve_product(self, api_client, db):\n        \"\"\"Test retrieving a product.\"\"\"\n        product = ProductFactory()\n\n        url = reverse(''api:product-detail'', kwargs={''pk'': product.id})\n        response = api_client.get(url)\n\n        assert response.status_code == status.HTTP_200_OK\n        assert response.data[''id''] == product.id\n\n    def test_create_product_unauthorized(self, api_client, db):\n        \"\"\"Test creating product without authentication.\"\"\"\n        url = reverse(''api:product-list'')\n        data = {''name'': ''Test Product'', ''price'': ''99.99''}\n\n        response = api_client.post(url, data)\n\n        assert response.status_code == status.HTTP_401_UNAUTHORIZED\n\n    def test_create_product_authorized(self, authenticated_api_client, db):\n        \"\"\"Test creating product as authenticated user.\"\"\"\n        url = reverse(''api:product-list'')\n        data = {\n            ''name'': ''Test Product'',\n            ''description'': ''Test'',\n            ''price'': ''99.99'',\n            ''stock'': 10,\n        }\n\n        response = authenticated_api_client.post(url, data)\n\n        assert response.status_code == status.HTTP_201_CREATED\n        assert response.data[''name''] == ''Test Product''\n\n    def test_update_product(self, authenticated_api_client, db):\n        \"\"\"Test updating a product.\"\"\"\n        product = ProductFactory(created_by=authenticated_api_client.user)\n\n        url = reverse(''api:product-detail'', kwargs={''pk'': product.id})\n        data = {''name'': ''Updated Product''}\n\n        response = authenticated_api_client.patch(url, data)\n\n        assert response.status_code == status.HTTP_200_OK\n        assert response.data[''name''] == ''Updated Product''\n\n    def test_delete_product(self, authenticated_api_client, db):\n        \"\"\"Test deleting a product.\"\"\"\n        product = ProductFactory(created_by=authenticated_api_client.user)\n\n        url = reverse(''api:product-detail'', kwargs={''pk'': product.id})\n        response = authenticated_api_client.delete(url)\n\n        assert response.status_code == status.HTTP_204_NO_CONTENT\n\n    def test_filter_products_by_price(self, api_client, db):\n        \"\"\"Test filtering products by price.\"\"\"\n        ProductFactory(price=50)\n        ProductFactory(price=150)\n\n        url = reverse(''api:product-list'')\n        response = api_client.get(url, {''price_min'': 100})\n\n        assert response.status_code == status.HTTP_200_OK\n        assert response.data[''count''] == 1\n\n    def test_search_products(self, api_client, db):\n        \"\"\"Test searching products.\"\"\"\n        ProductFactory(name=''Apple iPhone'')\n        ProductFactory(name=''Samsung Galaxy'')\n\n        url = reverse(''api:product-list'')\n        response = api_client.get(url, {''search'': ''Apple''})\n\n        assert response.status_code == status.HTTP_200_OK\n        assert response.data[''count''] == 1\n```\n\n## Mocking and Patching\n\n### Mocking External Services\n\n```python\n# tests/test_views.py\nfrom unittest.mock import patch, Mock\nimport pytest\n\nclass TestPaymentView:\n    \"\"\"Test payment view with mocked payment gateway.\"\"\"\n\n    @patch(''apps.payments.services.stripe'')\n    def test_successful_payment(self, mock_stripe, client, user, product):\n        \"\"\"Test successful payment with mocked Stripe.\"\"\"\n        # Configure mock\n        mock_stripe.Charge.create.return_value = {\n            ''id'': ''ch_123'',\n            ''status'': ''succeeded'',\n            ''amount'': 9999,\n        }\n\n        client.force_login(user)\n        response = client.post(reverse(''payments:process''), {\n            ''product_id'': product.id,\n            ''token'': ''tok_visa'',\n        })\n\n        assert response.status_code == 302\n        mock_stripe.Charge.create.assert_called_once()\n\n    @patch(''apps.payments.services.stripe'')\n    def test_failed_payment(self, mock_stripe, client, user, product):\n        \"\"\"Test failed payment.\"\"\"\n        mock_stripe.Charge.create.side_effect = Exception(''Card declined'')\n\n        client.force_login(user)\n        response = client.post(reverse(''payments:process''), {\n            ''product_id'': product.id,\n            ''token'': ''tok_visa'',\n        })\n\n        assert response.status_code == 302\n        assert ''error'' in response.url\n```\n\n### Mocking Email Sending\n\n```python\n# tests/test_email.py\nfrom django.core import mail\nfrom django.test import override_settings\n\n@override_settings(EMAIL_BACKEND=''django.core.mail.backends.locmem.EmailBackend'')\ndef test_order_confirmation_email(db, order):\n    \"\"\"Test order confirmation email.\"\"\"\n    order.send_confirmation_email()\n\n    assert len(mail.outbox) == 1\n    assert order.user.email in mail.outbox[0].to\n    assert ''Order Confirmation'' in mail.outbox[0].subject\n```\n\n## Integration Testing\n\n### Full Flow Testing\n\n```python\n# tests/test_integration.py\nimport pytest\nfrom django.urls import reverse\nfrom tests.factories import UserFactory, ProductFactory\n\nclass TestCheckoutFlow:\n    \"\"\"Test complete checkout flow.\"\"\"\n\n    def test_guest_to_purchase_flow(self, client, db):\n        \"\"\"Test complete flow from guest to purchase.\"\"\"\n        # Step 1: Register\n        response = client.post(reverse(''users:register''), {\n            ''email'': ''test@example.com'',\n            ''password'': ''testpass123'',\n            ''password_confirm'': ''testpass123'',\n        })\n        assert response.status_code == 302\n\n        # Step 2: Login\n        response = client.post(reverse(''users:login''), {\n            ''email'': ''test@example.com'',\n            ''password'': ''testpass123'',\n        })\n        assert response.status_code == 302\n\n        # Step 3: Browse products\n        product = ProductFactory(price=100)\n        response = client.get(reverse(''products:detail'', kwargs={''slug'': product.slug}))\n        assert response.status_code == 200\n\n        # Step 4: Add to cart\n        response = client.post(reverse(''cart:add''), {\n            ''product_id'': product.id,\n            ''quantity'': 1,\n        })\n        assert response.status_code == 302\n\n        # Step 5: Checkout\n        response = client.get(reverse(''checkout:review''))\n        assert response.status_code == 200\n        assert product.name in response.content.decode()\n\n        # Step 6: Complete purchase\n        with patch(''apps.checkout.services.process_payment'') as mock_payment:\n            mock_payment.return_value = True\n            response = client.post(reverse(''checkout:complete''))\n\n        assert response.status_code == 302\n        assert Order.objects.filter(user__email=''test@example.com'').exists()\n```\n\n## Testing Best Practices\n\n### DO\n\n- **Use factories**: Instead of manual object creation\n- **One assertion per test**: Keep tests focused\n- **Descriptive test names**: `test_user_cannot_delete_others_post`\n- **Test edge cases**: Empty inputs, None values, boundary conditions\n- **Mock external services**: Don''t depend on external APIs\n- **Use fixtures**: Eliminate duplication\n- **Test permissions**: Ensure authorization works\n- **Keep tests fast**: Use `--reuse-db` and `--nomigrations`\n\n### DON''T\n\n- **Don''t test Django internals**: Trust Django to work\n- **Don''t test third-party code**: Trust libraries to work\n- **Don''t ignore failing tests**: All tests must pass\n- **Don''t make tests dependent**: Tests should run in any order\n- **Don''t over-mock**: Mock only external dependencies\n- **Don''t test private methods**: Test public interface\n- **Don''t use production database**: Always use test database\n\n## Coverage\n\n### Coverage Configuration\n\n```bash\n# Run tests with coverage\npytest --cov=apps --cov-report=html --cov-report=term-missing\n\n# Generate HTML report\nopen htmlcov/index.html\n```\n\n### Coverage Goals\n\n| Component | Target Coverage |\n|-----------|-----------------|\n| Models | 90%+ |\n| Serializers | 85%+ |\n| Views | 80%+ |\n| Services | 90%+ |\n| Utilities | 80%+ |\n| Overall | 80%+ |\n\n## Quick Reference\n\n| Pattern | Usage |\n|---------|-------|\n| `@pytest.mark.django_db` | Enable database access |\n| `client` | Django test client |\n| `api_client` | DRF API client |\n| `factory.create_batch(n)` | Create multiple objects |\n| `patch(''module.function'')` | Mock external dependencies |\n| `override_settings` | Temporarily change settings |\n| `force_authenticate()` | Bypass authentication in tests |\n| `assertRedirects` | Check for redirects |\n| `assertTemplateUsed` | Verify template usage |\n| `mail.outbox` | Check sent emails |\n\nRemember: Tests are documentation. Good tests explain how your code should work. Keep them simple, readable, and maintainable.\n"},"category":"official","lastSynced":"2026-03-06T04:04:20.375Z","seo":{"title":{"en":"django-tdd: TDD Workflow Setup Guide | AI Agent Skill","zh":"Django TDD_SETUP GUIDE: pytest-django 和 factory_boy","ja":"Django TDDベストプラクティス: pytest-django と factory_boy","ko":"Django TDD 설정 가이드: pytest-django 및 factory_boy","es":"Guía de configuración de django-tdd paraTesting con Pytest","fr":"Guide de mise en place de django-tdd pour le testing avec...","de":"Einrichtungsleitfaden für django-tdd mit Pytest-Testing","pt":"Guia de Configuração do django-tdd para Testes de Django","ru":"Настройка django-tdd для тестирования Django","ar":"دليل إعداد django-tdd لاختبارات Django"},"description":{"en":"Unlock efficient testing for Django apps with django-tdd - learn how to implement TDD methodology and pytest-django for robust API testing, and get started t...","zh":"使用 django-tdd 技术实现高效的 Django 应用测试，包括 pytest-django、factory_boy 和 Django REST Framework","ja":"Django アプリケーションのテストを効率化するための django-tdd 技術、pytest-django、factory_boy、Django REST Framework","ko":"django-tdd 기술을 사용하여 효율적인 Django 애플리케이션 테스트를 구현합니다. pytest-django, factory_boy 및 Django REST Framework","es":"Aprende a implementar estrategias de testing con django-tdd, pytest-django y TDD para mejorar la calidad de tus aplicaciones Django","fr":"Découvrez comment mettre en œuvre des stratégies de testing avec django-tdd, pytest-django et TDD pour améliorer la qualité de vos applications Django","de":"Erfahren Sie, wie Sie Testing-Strategien mit django-tdd, pytest-django und TDD implementieren, um die Qualität Ihrer Django-Anwendungen zu verbessern","pt":"Aprenda a configurar o django-tdd para testes de Django com pytest-django, TDD e Django REST Framework","ru":"Узнайте, как настроить django-tdd для тестирования Django с помощью pytest-django, TDD и Django REST Framework","ar":"تعلم كيفية إعداد django-tdd لاختبارات Django باستخدام pytest-django و TDD و Django REST Framework"},"definition":{"en":"django-tdd is a testing strategy for Django applications that utilizes TDD methodology, pytest-django, and factory_boy for efficient and robust testing of Django models, views, and serializers.","zh":"Django TDD 是一种使用 pytest-django、factory_boy 和 Django REST Framework 进行测试驱动开发的技术","ja":"Django TDD は、pytest-django、factory_boy、Django REST Framework を使用したテスト駆動開発の技術です","ko":"Django TDD는 pytest-django, factory_boy 및 Django REST Framework를 사용하여 테스트 주도 개발을 하는 기술입니다","es":"django-tdd es una habilidad de testing que combina pytest-django, TDD y factory_boy para mejorar la calidad de las aplicaciones Django","fr":"django-tdd est une compétence de testing qui combine pytest-django, TDD et factory_boy pour améliorer la qualité des applications Django","de":"django-tdd ist eine Testing-Fähigkeit, die pytest-django, TDD und factory_boy kombiniert, um die Qualität von Django-Anwendungen zu verbessern","pt":"O que é django-tdd? É uma ferramenta para testes de Django com TDD e pytest-django.","ru":"Что такое django-tdd? Это инструмент для тестирования Django с помощью TDD и pytest-django.","ar":"ما هو django-tdd? هو أداة لاختبارات Django باستخدام TDD و pytest-django"},"features":{"en":["Implements TDD workflow using pytest-django for Django applications","Utilizes factory_boy for efficient test data creation","Supports testing of Django REST Framework APIs","Enables mocking for isolated unit testing","Provides test coverage analysis for Django projects"],"zh":["使用 pytest-django 进行 Django 应用测试","使用 factory_boy 自动生成测试数据","支持 Django REST Framework API 测试","实现 TDD 开发流程","使用 coverage 进行测试覆盖率分析"],"ja":["pytest-django を使用した Django アプリケーションのテスト","factory_boy を使用したテストデータの自動生成","Django REST Framework API のテストをサポート","TDD 開発プロセスの実装","coverage を使用したテストカバレッジ分析"],"ko":["pytest-django를 사용하여 Django 애플리케이션 테스트","factory_boy를 사용하여 테스트 데이터 자동 생성","Django REST Framework API 테스트 지원","TDD 개발 프로세스 구현","coverage를 사용하여 테스트 커버리지 분석"],"es":["Testing con pytest-django","Metodología TDD","Uso de factory_boy para la creación de datos de prueba","Mocking para aislar dependencias","Cobertura de código para garantizar la calidad","Testing de APIs de Django REST Framework"],"fr":["Testing avec pytest-django","Méthodologie TDD","Utilisation de factory_boy pour la création de données de test","Mocking pour isoler les dépendances","Couverture de code pour garantir la qualité","Testing d''API de Django REST Framework"],"de":["Testing mit pytest-django","TDD-Methode","Verwendung von factory_boy für die Erstellung von Testdaten","Mocking zur Isolierung von Abhängigkeiten","Code-Coverage zur Gewährleistung der Qualität","Testing von Django REST Framework-APIs"],"pt":["Testes de Django com pytest-django","Metodologia TDD para desenvolvimento de aplicativos Django","Uso de factory_boy para criação de dados de teste","Mocking para isolamento de dependências","Cobertura de código para garantia de qualidade"],"ru":["Тестирование Django с помощью pytest-django","Методология TDD для разработки приложений Django","Использование factory_boy для создания тестовых данных","Mocking для изоляции зависимостей","Покрытие кода для гарантии качества"],"ar":["اختبارات Django باستخدام pytest-django","منهجية TDD لتحwicklung تطبيقات Django","استخدام factory_boy لإنشاء بيانات الاختبار","Mocking لتحقيق العزل التابع","تغطية الشفرة لضمان الجودة"]},"keywords":{"en":["django-tdd tutorial","pytest-django installation","TDD methodology for Django","django-tdd vs unittest","factory_boy example usage","django-tdd setup guide","how to use django-tdd with Django REST Framework","django-tdd best practices","django-tdd alternative testing frameworks"],"zh":["Django TDD","pytest-django","factory_boy","Django REST Framework","TDD 开发","AIエージェント","django-tdd 技术","测试驱动开发"],"ja":["Django TDD","pytest-django","factory_boy","Django REST Framework","TDD 開発","AIエージェント","django-tdd 技術","テスト駆動開発"],"ko":["Django TDD","pytest-django","factory_boy","Django REST Framework","TDD 개발","AI 에이전트","django-tdd 기술","테스트 주도 개발"],"es":["django-tdd","testing django","pytest-django","TDD","factory_boy","mocking","cobertura de código","django rest framework","herramientas de testing para django","mejora de la calidad de las aplicaciones django"],"fr":["django-tdd","testing django","pytest-django","TDD","factory_boy","mocking","couverture de code","django rest framework","outils de testing pour django","amélioration de la qualité des applications django"],"de":["django-tdd","testing django","pytest-django","TDD","factory_boy","mocking","code-coverage","django rest framework","testing-tools für django","qualitätsverbesserung von django-anwendungen"],"pt":["django-tdd","testes de django","TDD","pytest-django","factory_boy","mocking","cobertura de código","desenvolvimento de aplicativos django","ferramentas de teste para django"],"ru":["django-tdd","тестирование django","TDD","pytest-django","factory_boy","mocking","покрытие кода","разработка приложений django","инструменты для тестирования django","ИИ Агенты для разработки"],"ar":["django-tdd","اختبارات django","TDD","pytest-django","factory_boy","mocking","تغطية الشفرة","تحwicklung تطبيقات django","أدوات اختبار django","وكلاء الذكاء الاصطناعي للتنمية"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Python Development Agents specializing in robust Django backend testing and API validation.","zh":"适合专注于强大的Django后端测试和API验证的Python开发代理。","ja":"Python開発エージェントがDjangoのバックエンドテストとAPI検証に特化している場合に最適です。","ko":"Robust한 Django 백엔드 테스트 및 API 검증에 전문적인 Python 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo de Python especializados en pruebas de backend robustas de Django y validación de API.","fr":"Idéal pour les agents de développement Python spécialisés dans les tests de backend robustes de Django et la validation d''API.","de":"Ideal für Python-Entwicklungsagenten, die sich auf robuste Django-Backend-Tests und API-Validierung spezialisiert haben.","pt":"Ideal para Agentes de Desenvolvimento Python especializados em testes de backend robustos do Django e validação de API.","ru":"Идеально подходит для агентов разработки Python, специализирующихся на надежном тестировании бэкенда Django и валидации API.","ar":"مثالي لوسيطي تطوير بايثون المتخصصون في اختبارات الباك إند القوية ل ديجانجو وتأكيد واجهة برمجة التطبيقات."},"recommendation":{"en":"Empowers agents to implement comprehensive test-driven development workflows using pytest-django, factory_boy, and mocking patterns. Provides automated testing infrastructure for Django models, views, serializers, and REST Framework APIs with coverage reporting.","zh":"赋予代理实现使用pytest-django、factory_boy和模拟模式的全面测试驱动开发工作流。为Django模型、视图、序列化程序和REST Framework API提供自动化测试基础设施，包括覆盖率报告。","ja":"pytest-django、factory_boy、モッキングパターンを使用した包括的なテスト駆動開発ワークフローを実装するエージェントを可能にします。Djangoモデル、ビュー、シリアライザー、REST Framework APIの自動テストインフラストラクチャを提供し、カバレッジレポートも提供します。","ko":"pytest-django, factory_boy 및 mocking 패턴을 사용하여 포괄적인 테스트 주도 개발 워크플ロー 구현을 에이전트에 가능하게 합니다. Django 모델, 보기, 시리얼라이저 및 REST Framework API에 대한 자동화된 테스트 인프라를 제공하고, 커버리지 보고서도 제공합니다.","es":"Habilita a los agentes a implementar flujos de trabajo de desarrollo dirigido por pruebas completos utilizando pytest-django, factory_boy y patrones de mocking. Proporciona infraestructura de prueba automatizada para modelos de Django, vistas, serializadores y API de REST Framework con informes de cobertura.","fr":"Permet aux agents de mettre en œuvre des flux de travail de développement dirigé par les tests complets en utilisant pytest-django, factory_boy et des modèles de mocking. Fournit une infrastructure de test automatisée pour les modèles Django, les vues, les sérialiseurs et les API du framework REST avec des rapports de couverture.","de":"Ermächtigt Agenten, umfassende testgetriebene Entwicklungsmethoden mithilfe von pytest-django, factory_boy und Mocking-Mustern zu implementieren. Bietet automatisierte Testinfrastruktur für Django-Modelle, Ansichten, Serializer und REST Framework-APIs mit Abdeckungsberichterstattung.","pt":"Permite que os agentes implementem fluxos de trabalho de desenvolvimento orientado a testes abrangentes usando pytest-django, factory_boy e padrões de mocking. Fornece infraestrutura de teste automatizada para modelos Django, visualizações, serializadores e APIs do REST Framework com relatórios de cobertura.","ru":"Позволяет агентам реализовывать комплексные рабочие процессы разработки, управляемые тестами, с использованием pytest-django, factory_boy и шаблонов.mocking. Предоставляет автоматизированную тестовую инфраструктуру для моделей Django, представлений, сериализаторов и API REST Framework с отчетами о покрытии.","ar":"تمكن الوسيط من تنفيذ سير عمل شاملة لتنمية مدفوعة بالاختبارات باستخدام pytest-django، factory_boy، وانماط التمثيل. توفر بنية اختبارية آلية للنماذج ديجانجو، والعرض، والأشكال، وواجهات برمجة التطبيقات الإطار.Rest مع تقارير التغطية."},"useCases":{"en":["Implementing Red-Green-Refactor cycles for new Django features","Generating factory_boy test data factories for complex model relationships","Testing Django REST Framework API endpoints with authentication and serialization validation","Setting up pytest-django configurations and coverage reporting"],"zh":["为新Django功能实现红-绿-重构周期","为复杂模型关系生成factory_boy测试数据工厂","使用身份验证和序列化验证测试Django REST Framework API端点","设置pytest-django配置和覆盖率报告"],"ja":["新しいDjango機能のRed-Green-Refactorサイクルを実装する","複雑なモデル関係のためのfactory_boyテストデータファクトリを生成する","認証とシリアライゼーションの検証を使用してDjango REST Framework APIエンドポイントをテストする","pytest-django構成とカバレッジレポートを設定する"],"ko":["새로운 Django 기능을 위한 Red-Green-Refactor 주기를 구현한다","복잡한 모델 관계를 위한 factory_boy 테스트 데이터 팩토리를 생성한다","인증 및 시리얼라이제이션 검증을 사용하여 Django REST Framework API 엔드포인트를 테스트한다","pytest-django 구성 및 커버리지 보고서를 설정한다"],"es":["Implementar ciclos de Red-Green-Refactor para nuevas características de Django","Generar fábricas de datos de prueba de factory_boy para relaciones de modelo complejas","Probar puntos finales de la API de Django REST Framework con autenticación y validación de serialización","Configurar configuraciones de pytest-django y informes de cobertura"],"fr":["Mettre en œuvre des cycles Red-Green-Refactor pour les nouvelles fonctionnalités de Django","Générer des usines de données de test de factory_boy pour des relations de modèle complexes","Tester les points de terminaison de l''API de Django REST Framework avec une authentification et une validation de sérialisation","Configurer les configurations de pytest-django et les rapports de couverture"],"de":["Implementierung von Red-Green-Refactor-Zyklen für neue Django-Funktionen","Erzeugen von factory_boy-Testdatenfabriken für komplexe Modellbeziehungen","Testen von Django-REST-Framework-API-Endpunkten mit Authentifizierung und Serialisierungsvalidierung","Einrichten von pytest-django-Konfigurationen und Abdeckungsberichterstattung"],"pt":["Implementação de ciclos Red-Green-Refactor para novos recursos do Django","Geração de fábricas de dados de teste factory_boy para relacionamentos de modelo complexos","Teste de pontos de extremidade da API do Django REST Framework com autenticação e validação de serialização","Configuração de configurações do pytest-django e relatórios de cobertura"],"ru":["Реализация циклов Red-Green-Refactor для новых функций Django","Генерация фабрик тестовых данных factory_boy для сложных отношений моделей","Тестирование точек подключения API Django REST Framework с аутентификацией и проверкой сериализации","Настройка конфигураций pytest-django и отчетов о покрытии"],"ar":["تنفيذ دورات الترميز الأحمر-الأخضر-إعادة البناء للسمات الجديدة ل ديجانجو","توليد مصانع البيانات الاختبارية factory_boy للعلاقات المعقدة للنموذج","اختبار نقاط النهاية ل واجهة برمجة التطبيقات ديجانجو.REST مع التحقق من الصحة والتحقق من الصحة","تهيئة إعدادات pytest-django وتقارير التغطية"]},"limitations":{"en":["Requires existing Django project structure","Python 3.6+ and Django 2.2+ compatibility needed","Dependent on pytest-django and factory_boy installations"],"zh":["需要现有的Django项目结构","需要Python 3.6+和Django 2.2+兼容性","依赖于pytest-django和factory_boy安装"],"ja":["既存のDjangoプロジェクト構造が必要","Python 3.6+とDjango 2.2+の互換性が必要","pytest-djangoとfactory_boyのインストールに依存する"],"ko":["기존 Django 프로젝트 구조가 필요합니다","Python 3.6+ 및 Django 2.2+ 호환성이 필요합니다","pytest-django 및 factory_boy 설치에 의존합니다"],"es":["Requiere estructura de proyecto de Django existente","Se requiere compatibilidad con Python 3.6+ y Django 2.2+","Dependiente de las instalaciones de pytest-django y factory_boy"],"fr":["Nécessite une structure de projet Django existante","Nécessite une compatibilité avec Python 3.6+ et Django 2.2+","Dépend des installations de pytest-django et de factory_boy"],"de":["Benötigt bestehende Django-Projektstruktur","Benötigt Kompatibilität mit Python 3.6+ und Django 2.2+","Abhängig von den Installationen von pytest-django und factory_boy"],"pt":["Requer estrutura de projeto Django existente","Compatibilidade com Python 3.6+ e Django 2.2+ necessária","Dependente das instalações do pytest-django e factory_boy"],"ru":["Требуется существующая структура проекта Django","Необходима совместимость с Python 3.6+ и Django 2.2+","Зависит от установки pytest-django и factory_boy"],"ar":["يتطلب هيكلا مشروع ديجانجو موجود","التوافق مع بايثون 3.6+ و ديجانجو 2.2+ ضروري","يعتمد على تثبيت pytest-django و factory_boy"]},"version":4},"contentHash":"99ef0936053afecf9f1ebbca687cd4232f4baa5f491878d5157c70344f237cd6","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":86}');
