INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/django-tdd', 'django-tdd', 'affaan-m', 'everything-claude-code', 'official', 'django-tdd affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The django-tdd skill enables developers to implement test-driven development for Django applications using pytest, factory_boy, and Django REST Framework, streamlining testing workflows. Django TDD 技术提供了高效的测试解决方案，包括 pytest-django、factory_boy 和 Django REST Framework Django TDD 技術は、pytest-django、factory_boy、Django REST Framework を使用した効率的なテスト ソリューションを提供します Django TDD 기술은 pytest-django, factory_boy 및 Django REST Framework를 사용하여 효율적인 테스트 솔루션을 제공합니다 django-tdd es una habilidad que proporciona estrategias de testing para Django con pytest-django, TDD y factory_boy django-tdd est une compétence qui fournit des stratégies de testing pour Django avec pytest-django, TDD et factory_boy django-tdd ist eine Fähigkeit, die Testing-Strategien für Django mit pytest-django, TDD und factory_boy bereitstellt O django-tdd é uma ferramenta para testes de Django com pytest-django, TDD e Django REST Framework. django-tdd - это инструмент для тестирования Django с помощью pytest-django, TDD и Django REST Framework. django-tdd هو أداة لاختبارات Django باستخدام pytest-django و TDD و Django REST Framework django-tdd tutorial pytest-django installation TDD methodology for Django django-tdd vs unittest factory_boy example usage django-tdd setup guide how to use django-tdd with Django REST Framework django-tdd best practices django-tdd alternative testing frameworks Django TDD pytest-django factory_boy Django REST Framework TDD 开发 AIエージェント django-tdd 技术 测试驱动开发 Implements TDD workflow using pytest-django for Django applications Utilizes factory_boy for efficient test data creation Supports testing of Django REST Framework APIs Enables mocking for isolated unit testing Provides test coverage analysis for Django projects django-tdd is a testing strategy for Django applications that utilizes TDD methodology, pytest-django, and factory_boy for efficient and robust testing of Django models, views, and serializers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/springboot-security', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'springboot-security', 61988, 7678, 86, '2026-03-06T03:39:20Z', '2026-03-06T04:36:22.767Z', '7bfabd0a87dd3abda4af572e913a84bd2470a876490799d3bf024e22a6870885', '{"id":"affaan-m/everything-claude-code/springboot-security","name":"springboot-security","description":{"en":"The springboot-security skill provides best practices for authentication, authorization, and security in Java Spring Boot services, benefiting developers and security teams.","zh":"Spring Boot 安全配置指南，涵盖认证、授权、输入验证和依赖安全等方面","ja":"Spring Boot セキュリティ設定ガイド。認証、認可、入力検証、依存関係のセキュリティなどをカバー","ko":"Spring Boot 보안 설정 가이드: 인증, 인가, 입력 유효성 검사 및 의존성 보안 등","es":"Spring Boot Security ofrece autenticación y autorización con JWT, OAuth2 y sesiones, así como validación de entrada y protección contra ataques de CSRF","fr":"Spring Boot Security propose une authentification et une autorisation avec JWT, OAuth2 et sessions, ainsi qu''une validation des entrées et une protection contre les attaques de CSRF","de":"Spring Boot Security bietet Authentifizierung und Autorisierung mit JWT, OAuth2 und Sitzungen, sowie Eingabevalidierung und Schutz vor CSRF-Angriffen","pt":"Spring Boot Security é uma coleção de melhores práticas para autenticação, autorização e validação em serviços Java Spring Boot.","ru":"Spring Boot Security - это коллекция лучших практик для аутентификации, авторизации и валидации в сервисах Java Spring Boot.","ar":"Spring Boot Security هو مجموعة من أفضل الممارسات للمصادقة والتفويض والتحقق في خدمات Java Spring Boot."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"springboot-security","description":"Spring Security best practices for authn/authz, validation, CSRF, secrets, headers, rate limiting, and dependency security in Java Spring Boot services.","bodyPreview":"# Spring Boot Security Review\n\nUse when adding auth, handling input, creating endpoints, or dealing with secrets.\n\n## When to Activate\n\n- Adding authentication (JWT, OAuth2, session-based)\n- Implementing authorization (@PreAuthorize, role-based access)\n- Validating user input (Bean Validation, custom validators)\n- Configuring CORS, CSRF, or security headers\n- Managing secrets (Vault, environment variables)\n- Adding rate limiting or brute-force protection\n- Scanning dependencies for CVEs\n\n## Auth","body":"# Spring Boot Security Review\n\nUse when adding auth, handling input, creating endpoints, or dealing with secrets.\n\n## When to Activate\n\n- Adding authentication (JWT, OAuth2, session-based)\n- Implementing authorization (@PreAuthorize, role-based access)\n- Validating user input (Bean Validation, custom validators)\n- Configuring CORS, CSRF, or security headers\n- Managing secrets (Vault, environment variables)\n- Adding rate limiting or brute-force protection\n- Scanning dependencies for CVEs\n\n## Authentication\n\n- Prefer stateless JWT or opaque tokens with revocation list\n- Use `httpOnly`, `Secure`, `SameSite=Strict` cookies for sessions\n- Validate tokens with `OncePerRequestFilter` or resource server\n\n```java\n@Component\npublic class JwtAuthFilter extends OncePerRequestFilter {\n  private final JwtService jwtService;\n\n  public JwtAuthFilter(JwtService jwtService) {\n    this.jwtService = jwtService;\n  }\n\n  @Override\n  protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,\n      FilterChain chain) throws ServletException, IOException {\n    String header = request.getHeader(HttpHeaders.AUTHORIZATION);\n    if (header != null && header.startsWith(\"Bearer \")) {\n      String token = header.substring(7);\n      Authentication auth = jwtService.authenticate(token);\n      SecurityContextHolder.getContext().setAuthentication(auth);\n    }\n    chain.doFilter(request, response);\n  }\n}\n```\n\n## Authorization\n\n- Enable method security: `@EnableMethodSecurity`\n- Use `@PreAuthorize(\"hasRole(''ADMIN'')\")` or `@PreAuthorize(\"@authz.canEdit(#id)\")`\n- Deny by default; expose only required scopes\n\n```java\n@RestController\n@RequestMapping(\"/api/admin\")\npublic class AdminController {\n\n  @PreAuthorize(\"hasRole(''ADMIN'')\")\n  @GetMapping(\"/users\")\n  public List<UserDto> listUsers() {\n    return userService.findAll();\n  }\n\n  @PreAuthorize(\"@authz.isOwner(#id, authentication)\")\n  @DeleteMapping(\"/users/{id}\")\n  public ResponseEntity<Void> deleteUser(@PathVariable Long id) {\n    userService.delete(id);\n    return ResponseEntity.noContent().build();\n  }\n}\n```\n\n## Input Validation\n\n- Use Bean Validation with `@Valid` on controllers\n- Apply constraints on DTOs: `@NotBlank`, `@Email`, `@Size`, custom validators\n- Sanitize any HTML with a whitelist before rendering\n\n```java\n// BAD: No validation\n@PostMapping(\"/users\")\npublic User createUser(@RequestBody UserDto dto) {\n  return userService.create(dto);\n}\n\n// GOOD: Validated DTO\npublic record CreateUserDto(\n    @NotBlank @Size(max = 100) String name,\n    @NotBlank @Email String email,\n    @NotNull @Min(0) @Max(150) Integer age\n) {}\n\n@PostMapping(\"/users\")\npublic ResponseEntity<UserDto> createUser(@Valid @RequestBody CreateUserDto dto) {\n  return ResponseEntity.status(HttpStatus.CREATED)\n      .body(userService.create(dto));\n}\n```\n\n## SQL Injection Prevention\n\n- Use Spring Data repositories or parameterized queries\n- For native queries, use `:param` bindings; never concatenate strings\n\n```java\n// BAD: String concatenation in native query\n@Query(value = \"SELECT * FROM users WHERE name = ''\" + name + \"''\", nativeQuery = true)\n\n// GOOD: Parameterized native query\n@Query(value = \"SELECT * FROM users WHERE name = :name\", nativeQuery = true)\nList<User> findByName(@Param(\"name\") String name);\n\n// GOOD: Spring Data derived query (auto-parameterized)\nList<User> findByEmailAndActiveTrue(String email);\n```\n\n## Password Encoding\n\n- Always hash passwords with BCrypt or Argon2 — never store plaintext\n- Use `PasswordEncoder` bean, not manual hashing\n\n```java\n@Bean\npublic PasswordEncoder passwordEncoder() {\n  return new BCryptPasswordEncoder(12); // cost factor 12\n}\n\n// In service\npublic User register(CreateUserDto dto) {\n  String hashedPassword = passwordEncoder.encode(dto.password());\n  return userRepository.save(new User(dto.email(), hashedPassword));\n}\n```\n\n## CSRF Protection\n\n- For browser session apps, keep CSRF enabled; include token in forms/headers\n- For pure APIs with Bearer tokens, disable CSRF and rely on stateless auth\n\n```java\nhttp\n  .csrf(csrf -> csrf.disable())\n  .sessionManagement(sm -> sm.sessionCreationPolicy(SessionCreationPolicy.STATELESS));\n```\n\n## Secrets Management\n\n- No secrets in source; load from env or vault\n- Keep `application.yml` free of credentials; use placeholders\n- Rotate tokens and DB credentials regularly\n\n```yaml\n# BAD: Hardcoded in application.yml\nspring:\n  datasource:\n    password: mySecretPassword123\n\n# GOOD: Environment variable placeholder\nspring:\n  datasource:\n    password: ${DB_PASSWORD}\n\n# GOOD: Spring Cloud Vault integration\nspring:\n  cloud:\n    vault:\n      uri: https://vault.example.com\n      token: ${VAULT_TOKEN}\n```\n\n## Security Headers\n\n```java\nhttp\n  .headers(headers -> headers\n    .contentSecurityPolicy(csp -> csp\n      .policyDirectives(\"default-src ''self''\"))\n    .frameOptions(HeadersConfigurer.FrameOptionsConfig::sameOrigin)\n    .xssProtection(Customizer.withDefaults())\n    .referrerPolicy(rp -> rp.policy(ReferrerPolicyHeaderWriter.ReferrerPolicy.NO_REFERRER)));\n```\n\n## CORS Configuration\n\n- Configure CORS at the security filter level, not per-controller\n- Restrict allowed origins — never use `*` in production\n\n```java\n@Bean\npublic CorsConfigurationSource corsConfigurationSource() {\n  CorsConfiguration config = new CorsConfiguration();\n  config.setAllowedOrigins(List.of(\"https://app.example.com\"));\n  config.setAllowedMethods(List.of(\"GET\", \"POST\", \"PUT\", \"DELETE\"));\n  config.setAllowedHeaders(List.of(\"Authorization\", \"Content-Type\"));\n  config.setAllowCredentials(true);\n  config.setMaxAge(3600L);\n\n  UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();\n  source.registerCorsConfiguration(\"/api/**\", config);\n  return source;\n}\n\n// In SecurityFilterChain:\nhttp.cors(cors -> cors.configurationSource(corsConfigurationSource()));\n```\n\n## Rate Limiting\n\n- Apply Bucket4j or gateway-level limits on expensive endpoints\n- Log and alert on bursts; return 429 with retry hints\n\n```java\n// Using Bucket4j for per-endpoint rate limiting\n@Component\npublic class RateLimitFilter extends OncePerRequestFilter {\n  private final Map<String, Bucket> buckets = new ConcurrentHashMap<>();\n\n  private Bucket createBucket() {\n    return Bucket.builder()\n        .addLimit(Bandwidth.classic(100, Refill.intervally(100, Duration.ofMinutes(1))))\n        .build();\n  }\n\n  @Override\n  protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,\n      FilterChain chain) throws ServletException, IOException {\n    String clientIp = request.getRemoteAddr();\n    Bucket bucket = buckets.computeIfAbsent(clientIp, k -> createBucket());\n\n    if (bucket.tryConsume(1)) {\n      chain.doFilter(request, response);\n    } else {\n      response.setStatus(HttpStatus.TOO_MANY_REQUESTS.value());\n      response.getWriter().write(\"{\\\"error\\\": \\\"Rate limit exceeded\\\"}\");\n    }\n  }\n}\n```\n\n## Dependency Security\n\n- Run OWASP Dependency Check / Snyk in CI\n- Keep Spring Boot and Spring Security on supported versions\n- Fail builds on known CVEs\n\n## Logging and PII\n\n- Never log secrets, tokens, passwords, or full PAN data\n- Redact sensitive fields; use structured JSON logging\n\n## File Uploads\n\n- Validate size, content type, and extension\n- Store outside web root; scan if required\n\n## Checklist Before Release\n\n- [ ] Auth tokens validated and expired correctly\n- [ ] Authorization guards on every sensitive path\n- [ ] All inputs validated and sanitized\n- [ ] No string-concatenated SQL\n- [ ] CSRF posture correct for app type\n- [ ] Secrets externalized; none committed\n- [ ] Security headers configured\n- [ ] Rate limiting on APIs\n- [ ] Dependencies scanned and up to date\n- [ ] Logs free of sensitive data\n\n**Remember**: Deny by default, validate inputs, least privilege, and secure-by-configuration first.\n"},"category":"official","lastSynced":"2026-03-06T04:36:22.767Z","seo":{"title":{"en":"springboot-security: Authentication and Authorization Bes...","zh":"Spring Boot 安全配置指南","ja":"Spring Boot セキュリティ設定ガイド","ko":"Spring Boot 보안 설정 가이드","es":"Guía de configuración de Spring Boot Security","fr":"Guide de mise en place de la sécurité Spring Boot","de":"Spring Boot Security Einrichtungsleitfaden","pt":"Guia de Configuração de Segurança Spring Boot","ru":"Руководство по Настройке Безопасности Spring Boot","ar":"دليل إعدادات أمان Spring Boot"},"description":{"en":"Boost security in your Spring Boot services with expert authn/authz, validation, and secrets management - get started now!","zh":"学习 Spring Boot 安全最佳实践，包括认证、授权、输入验证、CSRF 防护和依赖安全","ja":"Spring Boot のセキュリティベストプラクティスを学び、認証、認可、入力検証、CSRF 防止、依存関係のセキュリティを理解する","ko":"Spring Boot 보안 최고의 실천 방법을 학습하여 인증, 인가, 입력 유효성 검사, CSRF 방지 및 의존성 보안을 이해합니다","es":"Aprende a proteger tus servicios Java Spring Boot con las mejores prácticas de seguridad de Spring","fr":"Découvrez comment sécuriser vos services Java Spring Boot avec les meilleures pratiques de sécurité Spring","de":"Erfahren Sie, wie Sie Ihre Java-Spring-Boot-Dienste mit den besten Sicherheitspraktiken von Spring schützen","pt":"Aprenda a implementar autenticação, autorização e validação em serviços Java Spring Boot com as melhores práticas de segurança","ru":"Узнайте, как реализовать аутентификацию, авторизацию и валидацию в сервисах Java Spring Boot с помощью лучших практик безопасности","ar":"تعرف على كيفية تنفيذ المصادقة والتفويض والتحقق من خدمات Java Spring Boot باستخدام أفضل الممارسات الأمنية"},"definition":{"en":"springboot-security is a set of expert guidelines for securing Spring Boot applications, covering authn/authz, validation, CSRF, secrets, and dependency security.","zh":"Spring Boot 安全是指使用 Spring Boot 框架构建安全的 Web 应用，包括认证、授权和输入验证等","ja":"Spring Boot セキュリティとは、Spring Boot フレームワークを使用してセキュアな Web アプリケーションを構築すること。認証、認可、入力検証などを含む","ko":"Spring Boot 보안은 Spring Boot 프레임워크를 사용하여 보안이 높은 웹 애플리케이션을 구축하는 것을 말합니다. 인증, 인가, 입력 유효성 검사 등","es":"Spring Boot Security es un conjunto de herramientas de seguridad para proteger servicios Java Spring Boot","fr":"Spring Boot Security est un ensemble d''outils de sécurité pour protéger les services Java Spring Boot","de":"Spring Boot Security ist eine Sammlung von Sicherheitstools zum Schutz von Java-Spring-Boot-Diensten","pt":"O que é Spring Boot Security? É um conjunto de diretrizes para garantir a segurança de serviços Java Spring Boot.","ru":"Что такое Spring Boot Security? Это набор руководств для обеспечения безопасности сервисов Java Spring Boot.","ar":"ما هي Spring Boot Security؟ هي مجموعة من الإرشادات لتأمين خدمات Java Spring Boot."},"features":{"en":["Implements authentication using JWT, OAuth2, and session-based methods","Enforces authorization with @PreAuthorize and role-based access control","Validates user input using Bean Validation and custom validators","Configures CORS, CSRF, and security headers for enhanced protection","Manages secrets using Vault and environment variables"],"zh":["支持多种认证方式，包括 JWT 和 OAuth2","提供输入验证和 CSRF 防护功能","支持依赖安全扫描和漏洞修复","提供安全的 headers 和 rate limiting 功能","支持 Vault 和环境变量等密钥管理方式"],"ja":["複数の認証方式をサポート（JWT、OAuth2など）","入力検証とCSRF防止機能を提供","依存関係のセキュリティスキャンと脆弱性修復をサポート","セキュアなヘッダーとレート制限機能を提供","Vaultや環境変数など、鍵管理方式をサポート"],"ko":["다중 인증 방법 지원(JWT, OAuth2 등)","입력 유효성 검사 및 CSRF 방지 기능 제공","의존성 보안 스캔 및 취약점 수정 지원","보안 헤더 및 레이트 제한 기능 제공","Vault 및 환경 변수 등 키 관리 방법 지원"],"es":["Autenticación con JWT, OAuth2 y sesiones","Autorización con @PreAuthorize y acceso basado en roles","Validación de entrada con Bean Validation y validadores personalizados","Protección contra ataques de CSRF y configuración de headers de seguridad","Gestión de secretos con Vault y variables de entorno","Limitación de velocidad y protección contra ataques de fuerza bruta"],"fr":["Authentification avec JWT, OAuth2 et sessions","Autorisation avec @PreAuthorize et accès basé sur les rôles","Validation des entrées avec Bean Validation et validateurs personnalisés","Protection contre les attaques de CSRF et configuration des headers de sécurité","Gestion des secrets avec Vault et variables d''environnement","Limitation de la vitesse et protection contre les attaques de force brute"],"de":["Authentifizierung mit JWT, OAuth2 und Sitzungen","Autorisierung mit @PreAuthorize und rollenbasiertem Zugriff","Eingabevalidierung mit Bean Validation und benutzerdefinierten Validatoren","Schutz vor CSRF-Angriffen und Konfiguration von Sicherheitsheadern","Verwaltung von Geheimnissen mit Vault und Umgebungsvariablen","Geschwindigkeitsbegrenzung und Schutz vor Brute-Force-Angriffen"],"pt":["Autenticação com JWT e OAuth2","Autorização com @PreAuthorize e acesso baseado em papéis","Validação de entrada de usuário com Bean Validation e validadores personalizados","Configuração de CORS, CSRF e cabeçalhos de segurança","Gerenciamento de segredos com Vault e variáveis de ambiente","Limitação de taxa e proteção contra força bruta"],"ru":["Аутентификация с помощью JWT и OAuth2","Авторизация с помощью @PreAuthorize и ролевого доступа","Валидация пользовательского ввода с помощью Bean Validation и пользовательских валидаторов","Настройка CORS, CSRF и заголовков безопасности","Управление секретами с помощью Vault и переменных окружения","Ограничение скорости и защита от грубой силы"],"ar":["المصادقة باستخدام JWT و OAuth2","التفويض باستخدام @PreAuthorize ووصول आध 기반 على الأدوار","التحقق من مدخلات المستخدم باستخدام Bean Validation والمتحققين المخصصين","تكوين CORS و CSRF ورؤوس الأمان","إدارة الأسرار باستخدام Vault ومتغيرات البيئة","تحديد معدل الحماية من القوة الغاشمة"]},"keywords":{"en":["how to use springboot-security","springboot-security best practices","springboot-security vs OAuth2","springboot-security install guide","springboot-security setup tutorial","what is springboot-security"],"zh":["Spring Boot 安全","认证和授权","输入验证","CSRF 防护","依赖安全","Spring Boot 安全配置","Java 安全开发","Web 应用安全"],"ja":["Spring Boot セキュリティ","認証と認可","入力検証","CSRF 防止","依存関係のセキュリティ","Spring Boot セキュリティ設定","Java セキュア開発","Web アプリケーション セキュリティ"],"ko":["Spring Boot 보안","인증과 인가","입력 유효성 검사","CSRF 방지","의존성 보안","Spring Boot 보안 설정","Java 보안 개발","웹 애플리케이션 보안"],"es":["Spring Boot Security","seguridad de Spring","autenticación en Spring Boot","autorización en Spring Boot","validación de entrada en Spring","protección contra CSRF en Spring","gestión de secretos en Spring","limitación de velocidad en Spring","herramientas de seguridad para desarrolladores","AI Agent de seguridad para desarrolladores"],"fr":["Spring Boot Security","sécurité Spring","authentification dans Spring Boot","autorisation dans Spring Boot","validation des entrées dans Spring","protection contre les attaques de CSRF dans Spring","gestion des secrets dans Spring","limitation de la vitesse dans Spring","outils de sécurité pour les développeurs","Agent IA de sécurité pour les développeurs"],"de":["Spring Boot Security","Sicherheit in Spring","Authentifizierung in Spring Boot","Autorisierung in Spring Boot","Eingabevalidierung in Spring","Schutz vor CSRF-Angriffen in Spring","Verwaltung von Geheimnissen in Spring","Geschwindigkeitsbegrenzung in Spring","Sicherheitstools für Entwickler","KI-Agent für Sicherheit für Entwickler"],"pt":["Spring Boot Security","autenticação Java","autorização Java","validação de entrada","segurança de serviços","JWT","OAuth2","Bean Validation","CORS","CSRF","segredos","Vault","variáveis de ambiente"],"ru":["Spring Boot Security","аутентификация Java","авторизация Java","валидация ввода","безопасность сервисов","JWT","OAuth2","Bean Validation","CORS","CSRF","секреты","Vault","переменные окружения"],"ar":["Spring Boot Security","المصادقة الجافا","التفويض الجافا","التحقق من المدخلات","أمان الخدمات","JWT","OAuth2","Bean Validation","CORS","CSRF","الأسرار","Vault","متغيرات البيئة"]}},"agentAnalysis":{"suitability":{"en":"Essential for Java Spring Boot Agents implementing robust authentication, authorization, and security hardening in microservices.","zh":"对于在微服务中实现强大身份验证、授权和安全加固的 Java Spring Boot Agent 而言，这是必不可少的。","ja":"マイクロサービスにおいて強力な認証、認可、およびセキュリティ強化を実装する Java Spring Boot Agent にとって必須です。","ko":"마이크로서비스에서 강력한 인증, 인가 및 보안 강화를 구현하는 Java Spring Boot Agent에게 필수적입니다.","es":"Esencial para Agents de Java Spring Boot que implementan una autenticación robusta, autorización y fortalecimiento de la seguridad en microservicios.","fr":"Essentiel pour les Agents Java Spring Boot mettant en œuvre une authentification robuste, une autorisation et un durcissement de la sécurité dans les microservices.","de":"Essenziell für Java Spring Boot Agents, die eine robuste Authentifizierung, Autorisierung und Sicherheitshärtung in Microservices implementieren.","pt":"Essencial para Agentes Java Spring Boot que implementam autenticação robusta, autorização e reforço de segurança em microsserviços.","ru":"Необходим для агентов Java Spring Boot, реализующих надежную аутентификацию, авторизацию и усиление безопасности в микросервисах.","ar":"أساسي لوكلاء Java Spring Boot الذين ينفذون مصادقة قوية، تفويض، وتحصين أمان في الخدمات المصغرة."},"recommendation":{"en":"Enables comprehensive security implementation including JWT/OAuth2 authentication, role-based authorization with @PreAuthorize, CSRF/CORS configuration, Bean Validation, dependency vulnerability scanning, and secrets management through Vault or environment variables. Provides immediate access to Spring Security best practices for production-ready services.","zh":"支持全面的安全实现，包括 JWT/OAuth2 身份验证、使用 @PreAuthorize 进行基于角色的授权、CSRF/CORS 配置、Bean Validation、依赖项漏洞扫描，以及通过 Vault 或环境变量进行密钥管理。为生产就绪型服务提供对 Spring Security 最佳实践的即时访问。","ja":"JWT/OAuth2認証、@PreAuthorizeを使用したロールベースの認可、CSRF/CORS設定、Bean Validation、依存関係の脆弱性スキャン、Vaultまたは環境変数によるシークレット管理を含む包括的なセキュリティ実装を可能にします。プロダクションレディサービス向けのSpring Securityのベストプラクティスに即座にアクセスできます。","ko":"JWT/OAuth2 인증, @PreAuthorize를 이용한 역할 기반 인가, CSRF/CORS 설정, Bean Validation, 종속성 취약점 스캔, Vault 또는 환경 변수를 통한 시크릿 관리를 포함한 포괄적인 보안 구현을 가능하게 합니다. 프로덕션 준비 서비스를 위한 Spring Security 모범 사례에 즉시 액세스할 수 있도록 합니다.","es":"Permite la implementación integral de seguridad que incluye autenticación JWT/OAuth2, autorización basada en roles con @PreAuthorize, configuración de CSRF/CORS, Bean Validation, escaneo de vulnerabilidades de dependencias y gestión de secretos mediante Vault o variables de entorno. Proporciona acceso inmediato a las mejores prácticas de Spring Security para servicios listos para producción.","fr":"Permet une mise en œuvre complète de la sécurité incluant l''authentification JWT/OAuth2, l''autorisation basée sur les rôles avec les annotations @PreAuthorize, la configuration CSRF/CORS, la Bean Validation, l''analyse des vulnérabilités des dépendances et la gestion des secrets via Vault ou les variables d''environnement. Fournit un accès immédiat aux meilleures pratiques de Spring Security pour des services prêts pour la production.","de":"Ermöglicht eine umfassende Sicherheitsimplementierung, einschließlich JWT/OAuth2-Authentifizierung, rollenbasierter Autorisierung mit @PreAuthorize, CSRF/CORS-Konfiguration, Bean Validation, Schwachstellenscanning von Abhängigkeiten und Secrets-Management über Vault oder Umgebungsvariablen. Bietet sofortigen Zugriff auf Spring Security-Best Practices für produktionsreife Services.","pt":"Permite a implementação abrangente de segurança, incluindo autenticação JWT/OAuth2, autorização baseada em funções com @PreAuthorize, configuração de CSRF/CORS, Bean Validation, verificação de vulnerabilidades em dependências e gerenciamento de segredos através do Vault ou variáveis de ambiente. Fornece acesso imediato às melhores práticas do Spring Security para serviços prontos para produção.","ru":"Позволяет реализовать комплексную безопасность, включая аутентификацию JWT/OAuth2, авторизацию на основе ролей с аннотациями @PreAuthorize, настройку политик CORS и защиты от CSRF для веб-эндпоинтов, Bean Validation, сканирование зависимостей на наличие уязвимостей (CVE) и управление секретами через Vault или переменные окружения. Обеспечивает немедленный доступ к лучшим практикам Spring Security для готовых к эксплуатации сервисов.","ar":"يمكن من تنفيذ أمان شامل يشمل المصادقة بـ JWT/OAuth2، التفويض القائم على الأدوار مع شرح @PreAuthorize، تكوين سياسات CORS والحماية من CSRF لنقاط نهاية الويب، التحقق من صحة البيانات (Bean Validation)، فحص التبعيات عن نقاط الضعف (CVE) ومخاطر الأمان، وإدارة الأسرار عبر Vault أو متغيرات البيئة. يوفر وصولاً فورياً إلى أفضل ممارسات Spring Security للخدمات الجاهزة للإنتاج."},"useCases":{"en":["Implementing JWT token-based authentication flows","Configuring role-based access control with @PreAuthorize annotations","Setting up CORS policies and CSRF protection for web endpoints","Validating user input using Bean Validation and custom validators","Scanning dependencies for CVEs and security vulnerabilities"],"zh":["实现基于 JWT token 的身份验证流程","使用 @PreAuthorize 注解配置基于角色的访问控制","为 Web 端点设置 CORS 策略和 CSRF 保护","使用 Bean Validation 和自定义验证器验证用户输入","扫描依赖项以查找 CVE 和安全漏洞"],"ja":["JWTトークンベースの認証フローの実装","@PreAuthorizeアノテーションを使用したロールベースアクセス制御の設定","Webエンドポイントに対するCORSポリシーとCSRF保護の設定","Bean Validationおよびカスタムバリデータを使用したユーザー入力の検証","CVEおよびセキュリティ脆弱性のための依存関係のスキャン"],"ko":["JWT 토큰 기반 인증 흐름 구현","@PreAuthorize 어노테이션을 사용한 역할 기반 접근 제어 구성","웹 엔드포인트를 위한 CORS 정책 및 CSRF 보호 설정","Bean Validation 및 사용자 정의 유효성 검사기를 사용하여 사용자 입력 검증","CVE 및 보안 취약점에 대한 종속성 스캔"],"es":["Implementar flujos de autenticación basados en tokens JWT","Configurar control de acceso basado en roles con anotaciones @PreAuthorize","Configurar políticas CORS y protección CSRF para endpoints web","Validar entradas de usuario utilizando Bean Validation y validadores personalizados","Escanear dependencias en busca de CVEs y vulnerabilidades de seguridad"],"fr":["Mettre en œuvre des flux d''authentification basés sur des jetons JWT","Configurer le contrôle d''accès basé sur les rôles avec les annotations @PreAuthorize","Configurer les politiques CORS et la protection CSRF pour les endpoints web","Valider les entrées utilisateur à l''aide de Bean Validation et de validateurs personnalisés","Analyser les dépendances pour les CVE et les vulnérabilités de sécurité"],"de":["Implementierung von Authentifizierungsabläufen auf Basis von JWT-Tokens","Konfiguration der rollenbasierten Zugriffskontrolle mit @PreAuthorize-Annotationen","Einrichten von CORS-Richtlinien und CSRF-Schutz für Web-Endpoints","Validierung von Benutzereingaben mit Bean Validation und benutzerdefinierten Validatoren","Scannen von Abhängigkeiten auf CVEs und Sicherheitsschwachstellen"],"pt":["Implementação de fluxos de autenticação baseados em token JWT","Configuração de controle de acesso baseado em funções com anotações @PreAuthorize","Configuração de políticas CORS e proteção CSRF para endpoints web","Validação de entrada do usuário usando Bean Validation e validadores personalizados","Verificação de dependências em busca de CVEs e vulnerabilidades de segurança"],"ru":["Реализация потоков аутентификации на основе JWT-токенов","Настройка управления доступом на основе ролей с аннотациями @PreAuthorize","Настройка политик CORS и защиты от CSRF для веб-эндпоинтов","Проверка пользовательского ввода с помощью Bean Validation и пользовательских валидаторов","Сканирование зависимостей на наличие уязвимостей (CVE) и проблем безопасности"],"ar":["تنفيذ تدفقات المصادقة المعتمدة على رمز JWT","تكوين التحكم في الوصول القائم على الأدوار مع شرح @PreAuthorize","إعداد سياسات CORS والحماية من CSRF لنقاط نهاية الويب","التحقق من صحة إدخال المستخدم باستخدام Bean Validation والمدققات المخصصة","فحص التبعيات عن نقاط الضعف (CVE) ومخاطر الأمان"]},"limitations":{"en":["Java Spring Boot specific implementation","Requires understanding of Spring Security framework","Dependent on proper secrets management infrastructure"],"zh":["特定于 Java Spring Boot 的实现","需要理解 Spring Security 框架","依赖于适当的密钥管理基础设施"],"ja":["Java Spring Boot 固有の実装","Spring Securityフレームワークの理解が必要","適切なシークレット管理インフラストラクチャに依存"],"ko":["Java Spring Boot 특정 구현","Spring Security 프레임워크에 대한 이해 필요","적절한 시크릿 관리 인프라에 의존"],"es":["Implementación específica de Java Spring Boot","Requiere comprensión del framework Spring Security","Depende de una infraestructura adecuada de gestión de secretos"],"fr":["Implémentation spécifique à Java Spring Boot","Nécessite une compréhension du framework Spring Security","Dépend d''une infrastructure de gestion des secrets appropriée"],"de":["Spezifische Implementierung für Java Spring Boot","Erfordert ein Verständnis des Spring Security-Frameworks","Abhängig von einer geeigneten Secrets-Management-Infrastruktur"],"pt":["Implementação específica para Java Spring Boot","Requer compreensão do framework Spring Security","Dependente de uma infraestrutura adequada de gerenciamento de segredos"],"ru":["Специфичная реализация для Java Spring Boot","Требует понимания фреймворка Spring Security","Зависит от надлежащей инфраструктуры управления секретами"],"ar":["تنفيذ خاص بـ Java Spring Boot","يتطلب فهم إطار عمل Spring Security","يعتمد على بنية تحتية مناسبة لإدارة الأسرار"]},"version":4},"contentHash":"7bfabd0a87dd3abda4af572e913a84bd2470a876490799d3bf024e22a6870885","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":86}');
