INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/springboot-security', 'springboot-security', 'affaan-m', 'everything-claude-code', 'official', 'springboot-security affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The springboot-security skill provides best practices for authentication, authorization, and security in Java Spring Boot services, benefiting developers and security teams. Spring Boot 安全配置指南，涵盖认证、授权、输入验证和依赖安全等方面 Spring Boot セキュリティ設定ガイド。認証、認可、入力検証、依存関係のセキュリティなどをカバー Spring Boot 보안 설정 가이드: 인증, 인가, 입력 유효성 검사 및 의존성 보안 등 Spring Boot Security ofrece autenticación y autorización con JWT, OAuth2 y sesiones, así como validación de entrada y protección contra ataques de CSRF Spring Boot Security propose une authentification et une autorisation avec JWT, OAuth2 et sessions, ainsi qu''une validation des entrées et une protection contre les attaques de CSRF Spring Boot Security bietet Authentifizierung und Autorisierung mit JWT, OAuth2 und Sitzungen, sowie Eingabevalidierung und Schutz vor CSRF-Angriffen Spring Boot Security é uma coleção de melhores práticas para autenticação, autorização e validação em serviços Java Spring Boot. Spring Boot Security - это коллекция лучших практик для аутентификации, авторизации и валидации в сервисах Java Spring Boot. Spring Boot Security هو مجموعة من أفضل الممارسات للمصادقة والتفويض والتحقق في خدمات Java Spring Boot. how to use springboot-security springboot-security best practices springboot-security vs OAuth2 springboot-security install guide springboot-security setup tutorial what is springboot-security Spring Boot 安全 认证和授权 输入验证 CSRF 防护 依赖安全 Spring Boot 安全配置 Java 安全开发 Web 应用安全 Implements authentication using JWT, OAuth2, and session-based methods Enforces authorization with @PreAuthorize and role-based access control Validates user input using Bean Validation and custom validators Configures CORS, CSRF, and security headers for enhanced protection Manages secrets using Vault and environment variables springboot-security is a set of expert guidelines for securing Spring Boot applications, covering authn/authz, validation, CSRF, secrets, and dependency security.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/springboot-tdd', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'springboot-tdd', 61988, 7678, 86, '2026-03-06T03:39:20Z', '2026-03-06T04:37:17.352Z', '67d3d67c8f9d18109979944c028d8c0e1a219c0366ef96c95befd6fb3a0856d4', '{"id":"affaan-m/everything-claude-code/springboot-tdd","name":"springboot-tdd","description":{"en":"This AI agent skill provides test-driven development guidance for Spring Boot services. It helps developers implement features, fix bugs, and refactor code using JUnit 5, Mockito, MockMvc, Testcontainers, and JaCoCo to achieve high test coverage.","pt":"O Spring Boot TDD é uma abordagem de desenvolvimento que utiliza testes para garantir a qualidade do código","ru":"Spring Boot TDD — это подход к разработке, использующий тесты для обеспечения качества кода с ИИ Агентами","ar":"Spring Boot TDD هو نهج للتنمية يعتمد على الاختبارات لضمان جودة الكود مع أدوات الذكاء الاصطناعي"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"springboot-tdd","description":"Test-driven development for Spring Boot using JUnit 5, Mockito, MockMvc, Testcontainers, and JaCoCo. Use when adding features, fixing bugs, or refactoring.","bodyPreview":"# Spring Boot TDD Workflow\n\nTDD guidance for Spring Boot services with 80%+ coverage (unit + integration).\n\n## When to Use\n\n- New features or endpoints\n- Bug fixes or refactors\n- Adding data access logic or security rules\n\n## Workflow\n\n1) Write tests first (they should fail)\n2) Implement minimal code to pass\n3) Refactor with tests green\n4) Enforce coverage (JaCoCo)\n\n## Unit Tests (JUnit 5 + Mockito)\n\n```java\n@ExtendWith(MockitoExtension.class)\nclass MarketServiceTest {\n  @Mock MarketRepository r","body":"# Spring Boot TDD Workflow\n\nTDD guidance for Spring Boot services with 80%+ coverage (unit + integration).\n\n## When to Use\n\n- New features or endpoints\n- Bug fixes or refactors\n- Adding data access logic or security rules\n\n## Workflow\n\n1) Write tests first (they should fail)\n2) Implement minimal code to pass\n3) Refactor with tests green\n4) Enforce coverage (JaCoCo)\n\n## Unit Tests (JUnit 5 + Mockito)\n\n```java\n@ExtendWith(MockitoExtension.class)\nclass MarketServiceTest {\n  @Mock MarketRepository repo;\n  @InjectMocks MarketService service;\n\n  @Test\n  void createsMarket() {\n    CreateMarketRequest req = new CreateMarketRequest(\"name\", \"desc\", Instant.now(), List.of(\"cat\"));\n    when(repo.save(any())).thenAnswer(inv -> inv.getArgument(0));\n\n    Market result = service.create(req);\n\n    assertThat(result.name()).isEqualTo(\"name\");\n    verify(repo).save(any());\n  }\n}\n```\n\nPatterns:\n- Arrange-Act-Assert\n- Avoid partial mocks; prefer explicit stubbing\n- Use `@ParameterizedTest` for variants\n\n## Web Layer Tests (MockMvc)\n\n```java\n@WebMvcTest(MarketController.class)\nclass MarketControllerTest {\n  @Autowired MockMvc mockMvc;\n  @MockBean MarketService marketService;\n\n  @Test\n  void returnsMarkets() throws Exception {\n    when(marketService.list(any())).thenReturn(Page.empty());\n\n    mockMvc.perform(get(\"/api/markets\"))\n        .andExpect(status().isOk())\n        .andExpect(jsonPath(\"$.content\").isArray());\n  }\n}\n```\n\n## Integration Tests (SpringBootTest)\n\n```java\n@SpringBootTest\n@AutoConfigureMockMvc\n@ActiveProfiles(\"test\")\nclass MarketIntegrationTest {\n  @Autowired MockMvc mockMvc;\n\n  @Test\n  void createsMarket() throws Exception {\n    mockMvc.perform(post(\"/api/markets\")\n        .contentType(MediaType.APPLICATION_JSON)\n        .content(\"\"\"\n          {\"name\":\"Test\",\"description\":\"Desc\",\"endDate\":\"2030-01-01T00:00:00Z\",\"categories\":[\"general\"]}\n        \"\"\"))\n      .andExpect(status().isCreated());\n  }\n}\n```\n\n## Persistence Tests (DataJpaTest)\n\n```java\n@DataJpaTest\n@AutoConfigureTestDatabase(replace = AutoConfigureTestDatabase.Replace.NONE)\n@Import(TestContainersConfig.class)\nclass MarketRepositoryTest {\n  @Autowired MarketRepository repo;\n\n  @Test\n  void savesAndFinds() {\n    MarketEntity entity = new MarketEntity();\n    entity.setName(\"Test\");\n    repo.save(entity);\n\n    Optional<MarketEntity> found = repo.findByName(\"Test\");\n    assertThat(found).isPresent();\n  }\n}\n```\n\n## Testcontainers\n\n- Use reusable containers for Postgres/Redis to mirror production\n- Wire via `@DynamicPropertySource` to inject JDBC URLs into Spring context\n\n## Coverage (JaCoCo)\n\nMaven snippet:\n```xml\n<plugin>\n  <groupId>org.jacoco</groupId>\n  <artifactId>jacoco-maven-plugin</artifactId>\n  <version>0.8.14</version>\n  <executions>\n    <execution>\n      <goals><goal>prepare-agent</goal></goals>\n    </execution>\n    <execution>\n      <id>report</id>\n      <phase>verify</phase>\n      <goals><goal>report</goal></goals>\n    </execution>\n  </executions>\n</plugin>\n```\n\n## Assertions\n\n- Prefer AssertJ (`assertThat`) for readability\n- For JSON responses, use `jsonPath`\n- For exceptions: `assertThatThrownBy(...)`\n\n## Test Data Builders\n\n```java\nclass MarketBuilder {\n  private String name = \"Test\";\n  MarketBuilder withName(String name) { this.name = name; return this; }\n  Market build() { return new Market(null, name, MarketStatus.ACTIVE); }\n}\n```\n\n## CI Commands\n\n- Maven: `mvn -T 4 test` or `mvn verify`\n- Gradle: `./gradlew test jacocoTestReport`\n\n**Remember**: Keep tests fast, isolated, and deterministic. Test behavior, not implementation details.\n"},"category":"official","lastSynced":"2026-03-06T04:37:17.352Z","seo":{"title":{"en":"springboot-tdd: TDD Workflow for Spring Boot | AI Agent S...","pt":"Guia de Configuração do Spring Boot TDD","ru":"Руководство по настройке Spring Boot TDD с ИИ Агентами","ar":"دليل إعداد Spring Boot TDD مع أدوات الذكاء الاصطناعي"},"description":{"en":"Master Spring Boot TDD with this AI agent skill. Generate JUnit 5 & Mockito tests, enforce 80%+ JaCoCo coverage, and use Testcontainers for integration tests...","pt":"Aprenda a implementar o desenvolvimento orientado a testes no Spring Boot com JUnit 5, Mockito e JaCoCo","ru":"Освойте разработку через тестирование в Spring Boot с помощью JUnit 5, Mockito и JaCoCo с ИИ Агентами","ar":"تعلم كيفية تنفيذ التطوير الموجه بالاختبار في Spring Boot باستخدام JUnit 5 و Mockito و JaCoCo مع أدوات الذكاء الاصطناعي"},"definition":{"en":"springboot-tdd is an AI agent skill that provides a structured test-driven development workflow for Spring Boot applications. It guides developers through writing tests first with JUnit 5 and Mockito, implementing minimal code, and enforcing code coverage with JaCoCo.","pt":"O que é Spring Boot TDD? É uma abordagem de desenvolvimento que utiliza testes para garantir a qualidade do código","ru":"Что такое Spring Boot TDD? Это подход к разработке, использующий тесты для обеспечения качества кода","ar":"ما هو Spring Boot TDD؟ هو نهج للتنمية يعتمد على الاختبارات لضمان جودة الكود"},"features":{"en":["Guides TDD workflow: write tests first, implement code, refactor","Generates unit tests using JUnit 5 and MockitoExtension","Creates integration tests with MockMvc for endpoint testing","Supports database testing with Testcontainers for data access logic","Enforces 80%+ code coverage using JaCoCo reporting","Provides specific guidance for bug fixes, refactors, and security rules"],"pt":["Desenvolvimento orientado a testes com JUnit 5","Uso de Mockito para mockar dependências","Integração com JaCoCo para cobertura de código","Suporte a Testcontainers para testes de integração","Refatoração de código com testes verdes"],"ru":["Разработка через тестирование с помощью JUnit 5","Использование Mockito для имитации зависимостей","Интеграция с JaCoCo для покрытия кода","Поддержка Testcontainers для тестов интеграции","Рефакторинг кода с зелеными тестами"],"ar":["التطوير الموجه بالاختبار باستخدام JUnit 5","استخدام Mockito لمحاكاة الاعتماديات","التكامل مع JaCoCo لتغطية الكود","دعم Testcontainers لاختبارات التكامل","إعادة هيكلة الكود مع اختبارات خضراء"]},"keywords":{"en":["springboot-tdd setup guide","how to use springboot-tdd","springboot-tdd vs manual tdd","install springboot-tdd ai agent","junit 5 mockito spring boot testing","testcontainers integration tests spring boot","jacoco code coverage spring boot","spring boot tdd workflow best practices","what is springboot-tdd skill"],"pt":["Spring Boot TDD","Desenvolvimento orientado a testes","JUnit 5","Mockito","JaCoCo","Testcontainers","Refatoração de código","Cobertura de código"],"ru":["Spring Boot TDD","Разработка через тестирование","JUnit 5","Mockito","JaCoCo","Testcontainers","Рефакторинг кода","Покрытие кода"],"ar":["Spring Boot TDD","التطوير الموجه بالاختبار","JUnit 5","Mockito","JaCoCo","Testcontainers","إعادة هيكلة الكود","تغطية الكود"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Java-based AI Agents requiring robust test-driven development for Spring Boot applications.","zh":"适用于需要为 Spring Boot 应用程序提供强大的测试驱动开发的基于 Java 的 AI Agent。","ja":"Spring Boot アプリケーションにロバストなテスト駆動開発を必要とする Java ベースの AI エージェントに最適です。","ko":"Spring Boot 애플리케이션에 강력한 테스트 주도 개발을 필요로 하는 자바 기반 AI 에이전트에 적합합니다.","es":"Ideal para Agentes de IA basados en Java que requieren un desarrollo impulsado por pruebas robusto para aplicaciones Spring Boot.","fr":"Idéal pour les agents d''IA basés sur Java nécessitant un développement piloté par des tests robustes pour les applications Spring Boot.","de":"Ideal für Java-basierte KI-Agents, die ein robustes testgetriebenes Entwicklung für Spring Boot-Anwendungen erfordern.","pt":"Ideal para agentes de IA baseados em Java que requerem desenvolvimento orientado a testes robusto para aplicativos Spring Boot.","ru":"Идеально подходит для агентов ИИ на основе Java, требующих надежного тестирования для приложений Spring Boot.","ar":"مثالي لعميل الذكاء الاصطناعي المبني على Java الذي يتطلب تطويرًا مدفوعًا بالاختبار قويًا لتطبيقات Spring Boot."},"recommendation":{"en":"Empowers agents to write comprehensive unit and integration tests using JUnit 5, Mockito, and MockMvc, ensuring 80%+ coverage and enforcing quality with JaCoCo.","zh":"赋予代理编写使用 JUnit 5、Mockito 和 MockMvc 的全面单元和集成测试的能力，确保 80% 以上的覆盖率，并使用 JaCoCo 强制执行质量。","ja":"JUnit 5、Mockito、MockMvc を使用した包括的なユニットと統合テストをエージェントが記述できるようにし、80% 以上のカバレッジを確保し、JaCoCo で品質を強制します。","ko":"에이전트가 JUnit 5, Mockito, MockMvc를 사용하여 포괄적인 단위 및 통합 테스트를 작성할 수 있도록 하여 80% 이상의 커버리지 보장 및 JaCoCo로 품질 강제 적용","es":"Habilita a los agentes a escribir pruebas unitarias e integrales exhaustivas utilizando JUnit 5, Mockito y MockMvc, garantizando una cobertura del 80%+ y aplicando la calidad con JaCoCo.","fr":"Permet aux agents d''écrire des tests unitaires et d''intégration complets en utilisant JUnit 5, Mockito et MockMvc, garantissant une couverture de 80%+ et imposant la qualité avec JaCoCo.","de":"Ermächtigt die Agents, umfassende Einheits- und Integrationstests mit JUnit 5, Mockito und MockMvc zu schreiben, und stellt damit eine Abdeckung von 80%+ sicher und erzwingt die Qualität mit JaCoCo.","pt":"Habilita os agentes a escrever testes unitários e de integração abrangentes usando JUnit 5, Mockito e MockMvc, garantindo cobertura de 80%+ e aplicando a qualidade com JaCoCo.","ru":"Наделяет агентов возможностью создавать комплексные модульные и интеграционные тесты с помощью JUnit 5, Mockito и MockMvc, обеспечивая покрытие 80%+ и соблюдение качества с помощью JaCoCo.","ar":"تمكين العميل من كتابة الاختبارات الشاملة للوحدة والدمج باستخدام JUnit 5 و Mockito و MockMvc، مما يضمن تغطية 80%+ وتنفيذ الجودة مع JaCoCo."},"useCases":{"en":["Implementing test-driven development for new Spring Boot features","Debugging and fixing bugs in existing services with Testcontainers","Refactoring code while maintaining high test coverage"],"zh":["为新的 Spring Boot 功能实现测试驱动开发","使用 Testcontainers 调试和修复现有服务中的 bug","在保持高测试覆盖率的同时重构代码"],"ja":["新しい Spring Boot 機能のためのテスト駆動開発の実装","Testcontainers を使用して既存のサービス内のバグをデバッグおよび修正","高いテストカバレッジを維持しながらコードのリファクタリング"],"ko":["新的 Spring Boot 기능을 위한 테스트 주도 개발 구현","Testcontainers를 사용하여 기존 서비스 내의 버그를 디버깅 및 수정","높은 테스트 커버리지 유지하면서 코드 리팩토링"],"es":["Implementar el desarrollo impulsado por pruebas para nuevas características de Spring Boot","Depurar y corregir errores en servicios existentes con Testcontainers","Reestructurar el código manteniendo una alta cobertura de pruebas"],"fr":["Mettre en œuvre le développement piloté par des tests pour les nouvelles fonctionnalités de Spring Boot","Déboguer et corriger les bogues dans les services existants avec Testcontainers","Réorganiser le code tout en maintenant une couverture de tests élevée"],"de":["Implementierung des testgetriebenen Entwicklungs für neue Spring Boot-Features","Fehlerbehebung und Korrektur von Fehlern in bestehenden Diensten mit Testcontainers","Neustrukturierung des Codes unter Beibehaltung einer hohen Testabdeckung"],"pt":["Implementação do desenvolvimento orientado a testes para novos recursos do Spring Boot","Depuração e correção de bugs em serviços existentes com Testcontainers","Reorganização do código mantendo alta cobertura de testes"],"ru":["Реализация тестирования для новых функций Spring Boot","Отладка и исправление ошибок в существующих сервисах с помощью Testcontainers","Переструктуризация кода с сохранением высокой степени тестирования"],"ar":["تنفيذ التطوير الموجه بالاختبار لتطبيقات Spring Boot الجديدة","تصحيح الأخطاء وتصحيحها في الخدمات الحالية مع Testcontainers","إعادة هيكلة الكود مع الحفاظ على تغطية الاختبار العالية"]},"limitations":{"en":["Requires Java 8 or higher","Specific to Spring Boot applications","Dependent on JUnit 5 and Mockito libraries"],"zh":["需要 Java 8 或更高版本","特定于 Spring Boot 应用程序","依赖于 JUnit 5 和 Mockito 库"],"ja":["Java 8 以上が必要","Spring Boot アプリケーションに特有","JUnit 5 および Mockito ライブラリに依存"],"ko":["자바 8 이상 필요","스프링 부트 애플리케이션 전용","JUnit 5 및 Mockito 라이브러리에 의존"],"es":["Requiere Java 8 o superior","Específico para aplicaciones Spring Boot","Dependiente de las bibliotecas JUnit 5 y Mockito"],"fr":["Nécessite Java 8 ou supérieur","Spécifique aux applications Spring Boot","Dépendant des bibliothèques JUnit 5 et Mockito"],"de":["Benötigt Java 8 oder höher","Spezifisch für Spring Boot-Anwendungen","Abhängig von den Bibliotheken JUnit 5 und Mockito"],"pt":["Requer Java 8 ou superior","Específico para aplicações Spring Boot","Dependente das bibliotecas JUnit 5 e Mockito"],"ru":["Требуется Java 8 или выше","Конкретно для приложений Spring Boot","Зависит от библиотек JUnit 5 и Mockito"],"ar":["يتطلب Java 8 أو أعلى","محدد لتطبيقات Spring Boot","يعتمد على مكتبات JUnit 5 و Mockito"]},"version":4},"contentHash":"67d3d67c8f9d18109979944c028d8c0e1a219c0366ef96c95befd6fb3a0856d4","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":86}');
