INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/springboot-tdd', 'springboot-tdd', 'affaan-m', 'everything-claude-code', 'official', 'springboot-tdd affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity This AI agent skill provides test-driven development guidance for Spring Boot services. It helps developers implement features, fix bugs, and refactor code using JUnit 5, Mockito, MockMvc, Testcontainers, and JaCoCo to achieve high test coverage. O Spring Boot TDD é uma abordagem de desenvolvimento que utiliza testes para garantir a qualidade do código Spring Boot TDD — это подход к разработке, использующий тесты для обеспечения качества кода с ИИ Агентами Spring Boot TDD هو نهج للتنمية يعتمد على الاختبارات لضمان جودة الكود مع أدوات الذكاء الاصطناعي springboot-tdd setup guide how to use springboot-tdd springboot-tdd vs manual tdd install springboot-tdd ai agent junit 5 mockito spring boot testing testcontainers integration tests spring boot jacoco code coverage spring boot spring boot tdd workflow best practices what is springboot-tdd skill Guides TDD workflow: write tests first, implement code, refactor Generates unit tests using JUnit 5 and MockitoExtension Creates integration tests with MockMvc for endpoint testing Supports database testing with Testcontainers for data access logic Enforces 80%+ code coverage using JaCoCo reporting Provides specific guidance for bug fixes, refactors, and security rules springboot-tdd is an AI agent skill that provides a structured test-driven development workflow for Spring Boot applications. It guides developers through writing tests first with JUnit 5 and Mockito, implementing minimal code, and enforcing code coverage with JaCoCo.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/swift-concurrency-6-2', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'swift-concurrency-6-2', 61988, 7678, 86, '2026-03-06T03:39:20Z', '2026-03-06T04:41:19.586Z', 'f12ca9feeed25834fc06f59a70c679629962a4653c8354ecd833b68403da652c', '{"id":"affaan-m/everything-claude-code/swift-concurrency-6-2","name":"swift-concurrency-6-2","description":{"en":"The swift-concurrency-6-2 skill enables developers to adopt Swift 6.2''s concurrency model, running code single-threaded by default and introducing concurrency explicitly with @concurrent. This skill benefits developers migrating from Swift 5.x or 6.0/6.1 and designing MainActor-based app architec...","zh":"Swift 6.2 的并发处理模型提供了单线程默认和显式后台卸载等功能","ja":"Swift 6.2 のコンカレンシー機能は、シングルスレッドによるデフォルト実行とバックグラウンドへの明示的なオフロードを提供する","ko":"Swift 6.2의 동시성 처리 모델은 단일 스레드 기본값과 배경으로의 명시적 오프로드를 제공한다","es":"Swift Concurrency 6.2 ofrece un enfoque de concurrencia más seguro y eficiente, con código que se ejecuta en un solo hilo por defecto y concurrencia explícita mediante @concurrent.","fr":"La concurrence Swift 6.2 propose une approche de concurrence plus sûre et plus efficace, avec un code qui s''exécute sur un seul thread par défaut et une concurrence explicite via @concurrent.","de":"Swift Concurrency 6.2 bietet einen sichereren und effizienteren Ansatz für die Konkurrenz, mit Code, der standardmäßig in einem einzigen Thread ausgeführt wird und explizite Konkurrenz über @concurrent ermöglicht.","pt":"Swift Concurrency 6.2 é uma abordagem de concorrência mais acessível, com código que roda em uma thread por padrão e concorrência introduzida explicitamente","ru":"Swift Concurrency 6.2 - это более доступный подход к конкурентности, с кодом, который работает в одном потоке по умолчанию и конкурентность вводится явно","ar":"Swift Concurrency 6.2 هو نهج أكثر سهولة للتعامل مع التزامن، مع kode يركض على thread واحدة افتراضيًا ويتطلب التزامن صراحة"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"swift-concurrency-6-2","description":"Swift 6.2 Approachable Concurrency — single-threaded by default, @concurrent for explicit background offloading, isolated conformances for main actor types.","bodyPreview":"# Swift 6.2 Approachable Concurrency\n\nPatterns for adopting Swift 6.2''s concurrency model where code runs single-threaded by default and concurrency is introduced explicitly. Eliminates common data-race errors without sacrificing performance.\n\n## When to Activate\n\n- Migrating Swift 5.x or 6.0/6.1 projects to Swift 6.2\n- Resolving data-race safety compiler errors\n- Designing MainActor-based app architecture\n- Offloading CPU-intensive work to background threads\n- Implementing protocol conformances","body":"# Swift 6.2 Approachable Concurrency\n\nPatterns for adopting Swift 6.2''s concurrency model where code runs single-threaded by default and concurrency is introduced explicitly. Eliminates common data-race errors without sacrificing performance.\n\n## When to Activate\n\n- Migrating Swift 5.x or 6.0/6.1 projects to Swift 6.2\n- Resolving data-race safety compiler errors\n- Designing MainActor-based app architecture\n- Offloading CPU-intensive work to background threads\n- Implementing protocol conformances on MainActor-isolated types\n- Enabling Approachable Concurrency build settings in Xcode 26\n\n## Core Problem: Implicit Background Offloading\n\nIn Swift 6.1 and earlier, async functions could be implicitly offloaded to background threads, causing data-race errors even in seemingly safe code:\n\n```swift\n// Swift 6.1: ERROR\n@MainActor\nfinal class StickerModel {\n    let photoProcessor = PhotoProcessor()\n\n    func extractSticker(_ item: PhotosPickerItem) async throws -> Sticker? {\n        guard let data = try await item.loadTransferable(type: Data.self) else { return nil }\n\n        // Error: Sending ''self.photoProcessor'' risks causing data races\n        return await photoProcessor.extractSticker(data: data, with: item.itemIdentifier)\n    }\n}\n```\n\nSwift 6.2 fixes this: async functions stay on the calling actor by default.\n\n```swift\n// Swift 6.2: OK — async stays on MainActor, no data race\n@MainActor\nfinal class StickerModel {\n    let photoProcessor = PhotoProcessor()\n\n    func extractSticker(_ item: PhotosPickerItem) async throws -> Sticker? {\n        guard let data = try await item.loadTransferable(type: Data.self) else { return nil }\n        return await photoProcessor.extractSticker(data: data, with: item.itemIdentifier)\n    }\n}\n```\n\n## Core Pattern — Isolated Conformances\n\nMainActor types can now conform to non-isolated protocols safely:\n\n```swift\nprotocol Exportable {\n    func export()\n}\n\n// Swift 6.1: ERROR — crosses into main actor-isolated code\n// Swift 6.2: OK with isolated conformance\nextension StickerModel: @MainActor Exportable {\n    func export() {\n        photoProcessor.exportAsPNG()\n    }\n}\n```\n\nThe compiler ensures the conformance is only used on the main actor:\n\n```swift\n// OK — ImageExporter is also @MainActor\n@MainActor\nstruct ImageExporter {\n    var items: [any Exportable]\n\n    mutating func add(_ item: StickerModel) {\n        items.append(item)  // Safe: same actor isolation\n    }\n}\n\n// ERROR — nonisolated context can''t use MainActor conformance\nnonisolated struct ImageExporter {\n    var items: [any Exportable]\n\n    mutating func add(_ item: StickerModel) {\n        items.append(item)  // Error: Main actor-isolated conformance cannot be used here\n    }\n}\n```\n\n## Core Pattern — Global and Static Variables\n\nProtect global/static state with MainActor:\n\n```swift\n// Swift 6.1: ERROR — non-Sendable type may have shared mutable state\nfinal class StickerLibrary {\n    static let shared: StickerLibrary = .init()  // Error\n}\n\n// Fix: Annotate with @MainActor\n@MainActor\nfinal class StickerLibrary {\n    static let shared: StickerLibrary = .init()  // OK\n}\n```\n\n### MainActor Default Inference Mode\n\nSwift 6.2 introduces a mode where MainActor is inferred by default — no manual annotations needed:\n\n```swift\n// With MainActor default inference enabled:\nfinal class StickerLibrary {\n    static let shared: StickerLibrary = .init()  // Implicitly @MainActor\n}\n\nfinal class StickerModel {\n    let photoProcessor: PhotoProcessor\n    var selection: [PhotosPickerItem]  // Implicitly @MainActor\n}\n\nextension StickerModel: Exportable {  // Implicitly @MainActor conformance\n    func export() {\n        photoProcessor.exportAsPNG()\n    }\n}\n```\n\nThis mode is opt-in and recommended for apps, scripts, and other executable targets.\n\n## Core Pattern — @concurrent for Background Work\n\nWhen you need actual parallelism, explicitly offload with `@concurrent`:\n\n> **Important:** This example requires Approachable Concurrency build settings — SE-0466 (MainActor default isolation) and SE-0461 (NonisolatedNonsendingByDefault). With these enabled, `extractSticker` stays on the caller''s actor, making mutable state access safe. **Without these settings, this code has a data race** — the compiler will flag it.\n\n```swift\nnonisolated final class PhotoProcessor {\n    private var cachedStickers: [String: Sticker] = [:]\n\n    func extractSticker(data: Data, with id: String) async -> Sticker {\n        if let sticker = cachedStickers[id] {\n            return sticker\n        }\n\n        let sticker = await Self.extractSubject(from: data)\n        cachedStickers[id] = sticker\n        return sticker\n    }\n\n    // Offload expensive work to concurrent thread pool\n    @concurrent\n    static func extractSubject(from data: Data) async -> Sticker { /* ... */ }\n}\n\n// Callers must await\nlet processor = PhotoProcessor()\nprocessedPhotos[item.id] = await processor.extractSticker(data: data, with: item.id)\n```\n\nTo use `@concurrent`:\n1. Mark the containing type as `nonisolated`\n2. Add `@concurrent` to the function\n3. Add `async` if not already asynchronous\n4. Add `await` at call sites\n\n## Key Design Decisions\n\n| Decision | Rationale |\n|----------|-----------|\n| Single-threaded by default | Most natural code is data-race free; concurrency is opt-in |\n| Async stays on calling actor | Eliminates implicit offloading that caused data-race errors |\n| Isolated conformances | MainActor types can conform to protocols without unsafe workarounds |\n| `@concurrent` explicit opt-in | Background execution is a deliberate performance choice, not accidental |\n| MainActor default inference | Reduces boilerplate `@MainActor` annotations for app targets |\n| Opt-in adoption | Non-breaking migration path — enable features incrementally |\n\n## Migration Steps\n\n1. **Enable in Xcode**: Swift Compiler > Concurrency section in Build Settings\n2. **Enable in SPM**: Use `SwiftSettings` API in package manifest\n3. **Use migration tooling**: Automatic code changes via swift.org/migration\n4. **Start with MainActor defaults**: Enable inference mode for app targets\n5. **Add `@concurrent` where needed**: Profile first, then offload hot paths\n6. **Test thoroughly**: Data-race issues become compile-time errors\n\n## Best Practices\n\n- **Start on MainActor** — write single-threaded code first, optimize later\n- **Use `@concurrent` only for CPU-intensive work** — image processing, compression, complex computation\n- **Enable MainActor inference mode** for app targets that are mostly single-threaded\n- **Profile before offloading** — use Instruments to find actual bottlenecks\n- **Protect globals with MainActor** — global/static mutable state needs actor isolation\n- **Use isolated conformances** instead of `nonisolated` workarounds or `@Sendable` wrappers\n- **Migrate incrementally** — enable features one at a time in build settings\n\n## Anti-Patterns to Avoid\n\n- Applying `@concurrent` to every async function (most don''t need background execution)\n- Using `nonisolated` to suppress compiler errors without understanding isolation\n- Keeping legacy `DispatchQueue` patterns when actors provide the same safety\n- Skipping `model.availability` checks in concurrency-related Foundation Models code\n- Fighting the compiler — if it reports a data race, the code has a real concurrency issue\n- Assuming all async code runs in the background (Swift 6.2 default: stays on calling actor)\n\n## When to Use\n\n- All new Swift 6.2+ projects (Approachable Concurrency is the recommended default)\n- Migrating existing apps from Swift 5.x or 6.0/6.1 concurrency\n- Resolving data-race safety compiler errors during Xcode 26 adoption\n- Building MainActor-centric app architectures (most UI apps)\n- Performance optimization — offloading specific heavy computations to background\n"},"category":"official","lastSynced":"2026-03-06T04:41:19.586Z","seo":{"title":{"en":"swift-concurrency-6-2: Mastering Concurrent Programming f...","zh":"Swift 6.2 并发处理最佳实践","ja":"Swift 6.2 コンカレンシー実践ガイド","ko":"Swift 6.2 동시성 처리 설정 가이드","es":"Guía de configuración de Swift Concurrency 6.2 para desar...","fr":"Guide de mise en route de la concurrence Swift 6.2 pour l...","de":"Einrichtungsleitfaden für Swift Concurrency 6.2 für Entwi...","pt":"Guia de Configuração Swift Concurrency 6.2 para Desenvolv...","ru":"Руководство по настройке Swift Concurrency 6.2 для разраб...","ar":"دليل إعداد Swift Concurrency 6.2 للمطورين"},"description":{"en":"Unlock the power of Swift 6.2 concurrency! Learn how to eliminate data-race errors and improve performance with our expert guide - get started now!","zh":"了解 Swift 6.2 的并发处理模型，消除数据竞争错误，提高性能","ja":"Swift 6.2 のコンカレンシー機能を活用してデータ競合エラーを解決し、パフォーマンスを向上させる","ko":"Swift 6.2의 동시성 처리 모델을 사용하여 데이터 경쟁 오류를 제거하고 성능을 향상시키는 방법","es":"Aprende a implementar la concurrencia en Swift 6.2 con nuestro enfoque paso a paso para desarrolladores, incluyendo @concurrent y MainActor","fr":"Découvrez comment mettre en œuvre la concurrence dans Swift 6.2 avec notre approche étape par étape pour les développeurs, y compris @concurrent et MainActor","de":"Erfahren Sie, wie Sie die Konkurrenz in Swift 6.2 mit unserem Schritt-für-Schritt-Ansatz für Entwickler implementieren, einschließlich @concurrent und MainActor","pt":"Aprenda a utilizar o Swift Concurrency 6.2 com nossa guia passo a passo, incluindo padrões de adoção e resolução de erros de segurança de dados","ru":"Узнайте, как использовать Swift Concurrency 6.2 с нашей пошаговой инструкцией, включая шаблоны принятия и решение ошибок безопасности данных","ar":"تعرف على كيفية استخدام Swift Concurrency 6.2 مع دليلنا الخطوة بخطوة، بما في ذلك أنماط الإعتماد وحل أخطاء أمان البيانات"},"definition":{"en":"swift-concurrency-6-2 is a concurrency model in Swift 6.2 that runs code single-threaded by default and introduces concurrency explicitly using @concurrent for background offloading and isolated conformances for main actor types.","zh":"Swift 6.2 并发处理是指使用 @concurrent 等关键字实现显式后台卸载和主 actor 类型的隔离","ja":"Swift 6.2 コンカレンシーとは、@concurrent などのキーワードを使用して明示的なバックグラウンドオフロードとメインアクタータイプの隔離を実現する機能","ko":"Swift 6.2 동시성 처리는 @concurrent 등의 키워드를 사용하여 명시적인 배경 오프로드와 메인 액터 타입의 격리를实现하는 기능","es":"Swift Concurrency 6.2 es un modelo de concurrencia que permite a los desarrolladores escribir código concurrente de manera segura y eficiente","fr":"La concurrence Swift 6.2 est un modèle de concurrence qui permet aux développeurs d''écrire du code concurrent de manière sûre et efficace","de":"Swift Concurrency 6.2 ist ein Konkurrenzmodell, das es Entwicklern ermöglicht, konkurrierenden Code sicher und effizient zu schreiben","pt":"Swift Concurrency 6.2 é um modelo de concorrência que permite código single-threade