INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/swift-concurrency-6-2', 'swift-concurrency-6-2', 'affaan-m', 'everything-claude-code', 'official', 'swift-concurrency-6-2 affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The swift-concurrency-6-2 skill enables developers to adopt Swift 6.2''s concurrency model, running code single-threaded by default and introducing concurrency explicitly with @concurrent. This skill benefits developers migrating from Swift 5.x or 6.0/6.1 and designing MainActor-based app architec... Swift 6.2 的并发处理模型提供了单线程默认和显式后台卸载等功能 Swift 6.2 のコンカレンシー機能は、シングルスレッドによるデフォルト実行とバックグラウンドへの明示的なオフロードを提供する Swift 6.2의 동시성 처리 모델은 단일 스레드 기본값과 배경으로의 명시적 오프로드를 제공한다 Swift Concurrency 6.2 ofrece un enfoque de concurrencia más seguro y eficiente, con código que se ejecuta en un solo hilo por defecto y concurrencia explícita mediante @concurrent. La concurrence Swift 6.2 propose une approche de concurrence plus sûre et plus efficace, avec un code qui s''exécute sur un seul thread par défaut et une concurrence explicite via @concurrent. Swift Concurrency 6.2 bietet einen sichereren und effizienteren Ansatz für die Konkurrenz, mit Code, der standardmäßig in einem einzigen Thread ausgeführt wird und explizite Konkurrenz über @concurrent ermöglicht. Swift Concurrency 6.2 é uma abordagem de concorrência mais acessível, com código que roda em uma thread por padrão e concorrência introduzida explicitamente Swift Concurrency 6.2 - это более доступный подход к конкурентности, с кодом, который работает в одном потоке по умолчанию и конкурентность вводится явно Swift Concurrency 6.2 هو نهج أكثر سهولة للتعامل مع التزامن، مع kode يركض على thread واحدة افتراضيًا ويتطلب التزامن صراحة how to use swift-concurrency-6-2 swift-concurrency-6-2 tutorial swift-concurrency-6-2 vs Swift 5.x swift-concurrency-6-2 install swift-concurrency-6-2 setup guide swift-concurrency-6-2 best practices what is swift-concurrency-6-2 swift-concurrency-6-2 alternative swift-concurrency-6-2 documentation Swift 6.2 并发处理 AIエージェント 并发处理模型 单线程默认 显式后台卸载 主 actor 类型的隔离 数据竞争错误 性能优化 Runs code single-threaded by default to eliminate common data-race errors Introduces concurrency explicitly using @concurrent for background offloading Supports isolated conformances for main actor types Helps migrate Swift 5.x or 6.0/6.1 projects to Swift 6.2 Resolves data-race safety compiler errors Designs MainActor-based app architecture swift-concurrency-6-2 is a concurrency model in Swift 6.2 that runs code single-threaded by default and introduces concurrency explicitly using @concurrent for background offloading and isolated conformances for main actor types.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/swift-protocol-di-testing', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'swift-protocol-di-testing', 61988, 7678, 86, '2026-03-06T03:39:20Z', '2026-03-06T04:42:14.081Z', '780bf7d46242c38b74af0a4d56ea368f288e8dd5132e1b64850614ed2cf20a61', '{"id":"affaan-m/everything-claude-code/swift-protocol-di-testing","name":"swift-protocol-di-testing","description":{"en":"This AI agent skill implements protocol-based dependency injection to make Swift code testable by abstracting external dependencies like file systems and network APIs. It enables developers to write deterministic tests without I/O and build modules that work across app, test, and SwiftUI preview ...","zh":"Swift 协议依赖注入测试是一种使用小型、专注的协议来抽象外部依赖的方法，实现可测试的代码","ja":"Swift プロトコルベースの依存性注入テストは、小さな焦点を当てたプロトコルを使用して外部依存を抽象化し、テスト可能なコードを実現する方法です","ko":"스위프트 프로토콜 기반 의존성 주입 테스트는 작은 집중 프로토콜을 사용하여 외부 의존성을 추상화하여 테스트 가능한 코드를 구현하는 방법입니다","es":"La inyección de dependencias basada en protocolos en Swift permite escribir código testable y eficiente, abstractando dependencias externas como el sistema de archivos y la red","fr":"L''injection de dépendances basée sur les protocoles Swift permet d''écrire du code testable et efficace, en abstrayant les dépendances externes comme le système de fichiers et le réseau","de":"Die protokollbasierte Abhängigkeitsinjektion in Swift ermöglicht das Schreiben von testbarem und effizientem Code, indem externe Abhängigkeiten wie Dateisystem und Netzwerk abstrahiert werden","pt":"O swift-protocol-di-testing permite a criação de códigos Swift testáveis, utilizando injeção de dependência baseada em protocolos e testes determinísticos, sem I/O.","ru":"Swift-protocol-di-testing позволяет создавать тестируемый код Swift, используя протокол-ориентированную зависимость и детерминированные тесты, без операций ввода/вывода.","ar":"swift-protocol-di-testing يسمح بإنشاء كود سويفت قابل للاختبار، باستخدام الحقن المعتمد على البروتوكول والاختبارات المتحده، دون عمليات الإدخال/الإخراج."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"swift-protocol-di-testing","description":"Protocol-based dependency injection for testable Swift code — mock file system, network, and external APIs using focused protocols and Swift Testing.","bodyPreview":"# Swift Protocol-Based Dependency Injection for Testing\n\nPatterns for making Swift code testable by abstracting external dependencies (file system, network, iCloud) behind small, focused protocols. Enables deterministic tests without I/O.\n\n## When to Activate\n\n- Writing Swift code that accesses file system, network, or external APIs\n- Need to test error handling paths without triggering real failures\n- Building modules that work across environments (app, test, SwiftUI preview)\n- Designing testab","body":"# Swift Protocol-Based Dependency Injection for Testing\n\nPatterns for making Swift code testable by abstracting external dependencies (file system, network, iCloud) behind small, focused protocols. Enables deterministic tests without I/O.\n\n## When to Activate\n\n- Writing Swift code that accesses file system, network, or external APIs\n- Need to test error handling paths without triggering real failures\n- Building modules that work across environments (app, test, SwiftUI preview)\n- Designing testable architecture with Swift concurrency (actors, Sendable)\n\n## Core Pattern\n\n### 1. Define Small, Focused Protocols\n\nEach protocol handles exactly one external concern.\n\n```swift\n// File system access\npublic protocol FileSystemProviding: Sendable {\n    func containerURL(for purpose: Purpose) -> URL?\n}\n\n// File read/write operations\npublic protocol FileAccessorProviding: Sendable {\n    func read(from url: URL) throws -> Data\n    func write(_ data: Data, to url: URL) throws\n    func fileExists(at url: URL) -> Bool\n}\n\n// Bookmark storage (e.g., for sandboxed apps)\npublic protocol BookmarkStorageProviding: Sendable {\n    func saveBookmark(_ data: Data, for key: String) throws\n    func loadBookmark(for key: String) throws -> Data?\n}\n```\n\n### 2. Create Default (Production) Implementations\n\n```swift\npublic struct DefaultFileSystemProvider: FileSystemProviding {\n    public init() {}\n\n    public func containerURL(for purpose: Purpose) -> URL? {\n        FileManager.default.url(forUbiquityContainerIdentifier: nil)\n    }\n}\n\npublic struct DefaultFileAccessor: FileAccessorProviding {\n    public init() {}\n\n    public func read(from url: URL) throws -> Data {\n        try Data(contentsOf: url)\n    }\n\n    public func write(_ data: Data, to url: URL) throws {\n        try data.write(to: url, options: .atomic)\n    }\n\n    public func fileExists(at url: URL) -> Bool {\n        FileManager.default.fileExists(atPath: url.path)\n    }\n}\n```\n\n### 3. Create Mock Implementations for Testing\n\n```swift\npublic final class MockFileAccessor: FileAccessorProviding, @unchecked Sendable {\n    public var files: [URL: Data] = [:]\n    public var readError: Error?\n    public var writeError: Error?\n\n    public init() {}\n\n    public func read(from url: URL) throws -> Data {\n        if let error = readError { throw error }\n        guard let data = files[url] else {\n            throw CocoaError(.fileReadNoSuchFile)\n        }\n        return data\n    }\n\n    public func write(_ data: Data, to url: URL) throws {\n        if let error = writeError { throw error }\n        files[url] = data\n    }\n\n    public func fileExists(at url: URL) -> Bool {\n        files[url] != nil\n    }\n}\n```\n\n### 4. Inject Dependencies with Default Parameters\n\nProduction code uses defaults; tests inject mocks.\n\n```swift\npublic actor SyncManager {\n    private let fileSystem: FileSystemProviding\n    private let fileAccessor: FileAccessorProviding\n\n    public init(\n        fileSystem: FileSystemProviding = DefaultFileSystemProvider(),\n        fileAccessor: FileAccessorProviding = DefaultFileAccessor()\n    ) {\n        self.fileSystem = fileSystem\n        self.fileAccessor = fileAccessor\n    }\n\n    public func sync() async throws {\n        guard let containerURL = fileSystem.containerURL(for: .sync) else {\n            throw SyncError.containerNotAvailable\n        }\n        let data = try fileAccessor.read(\n            from: containerURL.appendingPathComponent(\"data.json\")\n        )\n        // Process data...\n    }\n}\n```\n\n### 5. Write Tests with Swift Testing\n\n```swift\nimport Testing\n\n@Test(\"Sync manager handles missing container\")\nfunc testMissingContainer() async {\n    let mockFileSystem = MockFileSystemProvider(containerURL: nil)\n    let manager = SyncManager(fileSystem: mockFileSystem)\n\n    await #expect(throws: SyncError.containerNotAvailable) {\n        try await manager.sync()\n    }\n}\n\n@Test(\"Sync manager reads data correctly\")\nfunc testReadData() async throws {\n    let mockFileAccessor = MockFileAccessor()\n    mockFileAccessor.files[testURL] = testData\n\n    let manager = SyncManager(fileAccessor: mockFileAccessor)\n    let result = try await manager.loadData()\n\n    #expect(result == expectedData)\n}\n\n@Test(\"Sync manager handles read errors gracefully\")\nfunc testReadError() async {\n    let mockFileAccessor = MockFileAccessor()\n    mockFileAccessor.readError = CocoaError(.fileReadCorruptFile)\n\n    let manager = SyncManager(fileAccessor: mockFileAccessor)\n\n    await #expect(throws: SyncError.self) {\n        try await manager.sync()\n    }\n}\n```\n\n## Best Practices\n\n- **Single Responsibility**: Each protocol should handle one concern — don''t create \"god protocols\" with many methods\n- **Sendable conformance**: Required when protocols are used across actor boundaries\n- **Default parameters**: Let production code use real implementations by default; only tests need to specify mocks\n- **Error simulation**: Design mocks with configurable error properties for testing failure paths\n- **Only mock boundaries**: Mock external dependencies (file system, network, APIs), not internal types\n\n## Anti-Patterns to Avoid\n\n- Creating a single large protocol that covers all external access\n- Mocking internal types that have no external dependencies\n- Using `#if DEBUG` conditionals instead of proper dependency injection\n- Forgetting `Sendable` conformance when used with actors\n- Over-engineering: if a type has no external dependencies, it doesn''t need a protocol\n\n## When to Use\n\n- Any Swift code that touches file system, network, or external APIs\n- Testing error handling paths that are hard to trigger in real environments\n- Building modules that need to work in app, test, and SwiftUI preview contexts\n- Apps using Swift concurrency (actors, structured concurrency) that need testable architecture\n"},"category":"official","lastSynced":"2026-03-06T04:42:14.081Z","seo":{"title":{"en":"Swift Protocol DI Testing: Mock File System & Network Set...","zh":"Swift 协议依赖注入测试设置指南","ja":"Swift プロトコルベースの依存性注入テストのベストプラクティス","ko":"스위프트 프로토콜 기반 의존성 주입 테스트 설정 가이드","es":"Guía de configuración de inyección de dependencias con pr...","fr":"Guide de mise en place de l''injection de dépendances basé...","de":"Einrichtungsleitfaden für Protokoll-basierte Abhängigkeit...","pt":"Guia de Configuração do swift-protocol-di-testing para Te...","ru":"Настройка swift-protocol-di-testing для тестирования кода...","ar":"دليل إعداد swift-protocol-di-testing لاختبارات كود سويفت"},"description":{"en":"Learn protocol-based dependency injection for Swift testing. Mock file system, network & external APIs without I/O. Build testable modules for apps, tests & ...","zh":"使用 Swift 协议依赖注入测试实现可测试的代码，模拟文件系统、网络和外部 API","ja":"Swift プロトコルベースの依存性注入テストを使用して、ファイルシステム、ネットワーク、外部 API をモックし、テスト可能なコードを実現する","ko":"스위프트 프로토콜 기반 의존성 주입 테스트를 사용하여 파일 시스템, 네트워크, 외부 API를 모의하고 테스트 가능한 코드를 구현하세요","es":"Aprende a utilizar la inyección de dependencias basada en protocolos en Swift para escribir código testable y eficiente, ideal para desarrolladores de aplica...","fr":"Découvrez comment utiliser l''injection de dépendances basée sur les protocoles Swift pour écrire du code testable et efficace, idéal pour les développeurs d''...","de":"Erfahren Sie, wie Sie die protokollbasierte Abhängigkeitsinjektion in Swift verwenden, um testbaren und effizienten Code zu schreiben, ideal für Mobile-App-E...","pt":"Aprenda a utilizar o swift-protocol-di-testing para criar códigos Swift testáveis, com injeção de dependência baseada em protocolos e testes determinísticos","ru":"Узнайте, как использовать swift-protocol-di-testing для создания тестируемого кода Swift с помощью протокол-ориентированной зависимости и детерминированных т...","ar":"تعرف على كيفية استخدام swift-protocol-di-testing لإنشاء كود سويفت قابل للاختبار مع الحقن المعتمد على البروتوكول والاختبارات المتحده"},"definition":{"en":"swift-protocol-di-testing is a protocol-based dependency injection approach for creating testable Swift code. It abstracts external dependencies like file systems, network calls, and external APIs behind focused protocols using Swift Testing, enabling deterministic tests without actual I/O operations.","zh":"Swift 协议依赖注入测试是指使用协议来抽象外部依赖，实现可测试的 Swift 代码","ja":"Swift プロトコルベースの依存性注入テストとは、プロトコルを使用して外部依存を抽象化し、テスト可能な Swift コードを実現することです","ko":"스위프트 프로토콜 기반 의존성 주입 테스트는 프로토콜을 사용하여 외부 의존성을 추상화하여 테스트 가능한 스위프트 코드를 구현하는 것을 말합니다","es":"La inyección de dependencias basada en protocolos en Swift es una técnica de programación que permite abstractar dependencias externas para escribir código testable","fr":"L''injection de dépendances basée sur les protocoles Swift est une technique de programmation qui permet d''abstraire les dépendances externes pour écrire du code testable","de":"Die protokollbasierte Abhängigkeitsinjektion in Swift ist eine ProgrammierTechnik, die es ermöglicht, externe Abhängigkeiten zu abstrahieren, um testbaren Code zu schreiben","pt":"O swift-protocol-di-testing é uma técnica de injeção de dependência baseada em protocolos para testar códigos Swift","ru":"Swift-protocol-di-testing - это техника протокол-ориентированной зависимости для тестирования кода Swift","ar":"swift-protocol-di-testing هو تقنية حقن التبعية المعتمدة على البروتوكول لاختبار كود سويفت"},"features":{"en":["Abstracts file system access behind focused protocols for testability","Mocks network calls and external APIs using protocol injection","Enables deterministic testing without triggering real I/O operations","Supports testing error handling paths without real failures","Builds modules that work across app, test, and SwiftUI preview environments","Uses Swift Testing framework for protocol-based mock implementations"],"zh":["使用小型、专注的协议抽象外部依赖","模拟文件系统、网络和外部 API","实现可测试的 Swift 代码","支持错误处理路径测试","适用于 app、test、SwiftUI preview 环境"],"ja":["小さな焦点を当てたプロトコルを使用して外部依存を抽象化","ファイルシステム、ネットワーク、外部 API をモック","テスト可能な Swift コードを実現","エラーハンドリングパスのテストをサポート","app、test、SwiftUI preview 環境に対応"],"ko":["작은 집중 프로토콜을 사용하여 외부 의존성을 추상화","파일 시스템, 네트워크, 외부 API를 모의","테스트 가능한 스위프트 코드를 구현","오류 처리 경로 테스트 지원","앱, 테스트, 스위프트 UI 프리뷰 환경対応"],"es":["Inyección de dependencias basada en protocolos","Mock de sistema de archivos y red","Pruebas deterministas sin I/O","Compatibilidad con Swift Testing","Diseño de módulos que funcionan en diferentes entornos"],"fr":["Injection de dépendances basée sur les protocoles","Mock de système de fichiers et de réseau","Tests déterministes sans I/O","Compatibilité avec Swift Testing","Conception de modules qui fonctionnent dans différents environnements"],"de":["Protokollbasierte Abhängigkeitsinjektion","Mock von Dateisystem und Netzwerk","Det