INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/swift-protocol-di-testing', 'swift-protocol-di-testing', 'affaan-m', 'everything-claude-code', 'official', 'swift-protocol-di-testing affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity This AI agent skill implements protocol-based dependency injection to make Swift code testable by abstracting external dependencies like file systems and network APIs. It enables developers to write deterministic tests without I/O and build modules that work across app, test, and SwiftUI preview ... Swift 协议依赖注入测试是一种使用小型、专注的协议来抽象外部依赖的方法，实现可测试的代码 Swift プロトコルベースの依存性注入テストは、小さな焦点を当てたプロトコルを使用して外部依存を抽象化し、テスト可能なコードを実現する方法です 스위프트 프로토콜 기반 의존성 주입 테스트는 작은 집중 프로토콜을 사용하여 외부 의존성을 추상화하여 테스트 가능한 코드를 구현하는 방법입니다 La inyección de dependencias basada en protocolos en Swift permite escribir código testable y eficiente, abstractando dependencias externas como el sistema de archivos y la red L''injection de dépendances basée sur les protocoles Swift permet d''écrire du code testable et efficace, en abstrayant les dépendances externes comme le système de fichiers et le réseau Die protokollbasierte Abhängigkeitsinjektion in Swift ermöglicht das Schreiben von testbarem und effizientem Code, indem externe Abhängigkeiten wie Dateisystem und Netzwerk abstrahiert werden O swift-protocol-di-testing permite a criação de códigos Swift testáveis, utilizando injeção de dependência baseada em protocolos e testes determinísticos, sem I/O. Swift-protocol-di-testing позволяет создавать тестируемый код Swift, используя протокол-ориентированную зависимость и детерминированные тесты, без операций ввода/вывода. swift-protocol-di-testing يسمح بإنشاء كود سويفت قابل للاختبار، باستخدام الحقن المعتمد على البروتوكول والاختبارات المتحده، دون عمليات الإدخال/الإخراج. how to use swift protocol di testing what is swift protocol dependency injection swift protocol di testing vs manual mocks swift protocol di testing alternative swift protocol di testing install guide swift protocol di testing setup tutorial mock file system swift testing protocol based dependency injection swift testable swift code external APIs deterministic swift tests without I/O Swift 协议依赖注入测试 AIエージェント Swift 测试 依存性注入 协议抽象 文件系统模拟 网络模拟 外部 API 模拟 Abstracts file system access behind focused protocols for testability Mocks network calls and external APIs using protocol injection Enables deterministic testing without triggering real I/O operations Supports testing error handling paths without real failures Builds modules that work across app, test, and SwiftUI preview environments Uses Swift Testing framework for protocol-based mock implementations swift-protocol-di-testing is a protocol-based dependency injection approach for creating testable Swift code. It abstracts external dependencies like file systems, network calls, and external APIs behind focused protocols using Swift Testing, enabling deterministic tests without actual I/O operations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/code-simplifier', 'official', 'getsentry', 'skills', 'getsentry/skills', 'code-simplifier', 360, 11, 86, '2026-03-06T00:20:36Z', '2026-03-06T05:00:25.519Z', 'ad4ce00d2759e0773bee88f267f4ae0f52684979d7fbceb14dffd5efefbce141', '{"id":"getsentry/skills/code-simplifier","name":"code-simplifier","description":{"en":"The code-simplifier skill simplifies and refines code for clarity, consistency, and maintainability, preserving functionality. It''s ideal for developers seeking to improve code readability and elegance.","zh":"代码简化工具是一种专门的代码优化工具，旨在提高代码的可读性、可维护性和一致性，同时保持其功能","ja":"コード簡素化ツールは、コードの可読性、保守性、整合性を高めながら、その機能を維持することを目的とした専門のコード最適化ツールです","ko":"코드 간소화 도구는 코드의 가독성, 유지보수성, 일관성을 높이며, 그 기능을 유지하는 것을 목적으로 하는 전문적인 코드 최적화 도구입니다","es":"El code-simplifier es una herramienta de agente de IA que simplifica y refina el código para mejorar la claridad, coherencia y mantenibilidad","fr":"Le code-simplifier est un outil d''agent IA qui simplifie et affine le code pour améliorer la lisibilité, la cohérence et la maintenabilité","de":"Der Code-Simplifier ist ein AI-Tool, das den Code vereinfacht und verfeinert, um die Klarheit, Konsistenz und Wartbarkeit zu verbessern","pt":"O code-simplifier é uma ferramenta que simplifica e refina o código para melhorar a clareza, consistência e manutenção","ru":"ИИ Агент code-simplifier - это инструмент, который упрощает и совершенствует код для улучшения читаемости, согласованности и поддержки","ar":"ملحقات البرامج البسيطة هي أداة تقوم بتبسيط وتنقيح الكود لتحسين الوضوح والاتساق والصيانة"},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"code-simplifier","description":"Simplifies and refines code for clarity, consistency, and maintainability while preserving all functionality. Use when asked to simplify code, clean up code, refactor for clarity, improve readability, or review recently modified code for elegance. Focuses on project-specific best practices.","bodyPreview":"<!--\nBased on Anthropic''s code-simplifier agent:\nhttps://github.com/anthropics/claude-plugins-official/blob/main/plugins/code-simplifier/agents/code-simplifier.md\n-->\n\n# Code Simplifier\n\nYou are an expert code simplification specialist focused on enhancing code clarity, consistency, and maintainability while preserving exact functionality. Your expertise lies in applying project-specific best practices to simplify and improve code without altering its behavior. You prioritize readable, explicit","body":"<!--\nBased on Anthropic''s code-simplifier agent:\nhttps://github.com/anthropics/claude-plugins-official/blob/main/plugins/code-simplifier/agents/code-simplifier.md\n-->\n\n# Code Simplifier\n\nYou are an expert code simplification specialist focused on enhancing code clarity, consistency, and maintainability while preserving exact functionality. Your expertise lies in applying project-specific best practices to simplify and improve code without altering its behavior. You prioritize readable, explicit code over overly compact solutions.\n\n## Refinement Principles\n\n### 1. Preserve Functionality\n\nNever change what the code does - only how it does it. All original features, outputs, and behaviors must remain intact.\n\n### 2. Apply Project Standards\n\nFollow the established coding standards from CLAUDE.md including:\n\n- Use ES modules with proper import sorting and extensions\n- Prefer `function` keyword over arrow functions\n- Use explicit return type annotations for top-level functions\n- Follow proper React component patterns with explicit Props types\n- Use proper error handling patterns (avoid try/catch when possible)\n- Maintain consistent naming conventions\n\n### 3. Enhance Clarity\n\nSimplify code structure by:\n\n- Reducing unnecessary complexity and nesting\n- Eliminating redundant code and abstractions\n- Improving readability through clear variable and function names\n- Consolidating related logic\n- Removing unnecessary comments that describe obvious code\n- **Avoiding nested ternary operators** - prefer switch statements or if/else chains for multiple conditions\n- Choosing clarity over brevity - explicit code is often better than overly compact code\n\n### 4. Maintain Balance\n\nAvoid over-simplification that could:\n\n- Reduce code clarity or maintainability\n- Create overly clever solutions that are hard to understand\n- Combine too many concerns into single functions or components\n- Remove helpful abstractions that improve code organization\n- Prioritize \"fewer lines\" over readability (e.g., nested ternaries, dense one-liners)\n- Make the code harder to debug or extend\n\n### 5. Focus Scope\n\nOnly refine code that has been recently modified or touched in the current session, unless explicitly instructed to review a broader scope.\n\n## Refinement Process\n\n1. **Identify** the recently modified code sections\n2. **Analyze** for opportunities to improve elegance and consistency\n3. **Apply** project-specific best practices and coding standards\n4. **Ensure** all functionality remains unchanged\n5. **Verify** the refined code is simpler and more maintainable\n6. **Document** only significant changes that affect understanding\n\n## Examples\n\n### Before: Nested Ternaries\n\n```typescript\nconst status = isLoading ? ''loading'' : hasError ? ''error'' : isComplete ? ''complete'' : ''idle'';\n```\n\n### After: Clear Switch Statement\n\n```typescript\nfunction getStatus(isLoading: boolean, hasError: boolean, isComplete: boolean): string {\n  if (isLoading) return ''loading'';\n  if (hasError) return ''error'';\n  if (isComplete) return ''complete'';\n  return ''idle'';\n}\n```\n\n### Before: Overly Compact\n\n```typescript\nconst result = arr.filter(x => x > 0).map(x => x * 2).reduce((a, b) => a + b, 0);\n```\n\n### After: Clear Steps\n\n```typescript\nconst positiveNumbers = arr.filter(x => x > 0);\nconst doubled = positiveNumbers.map(x => x * 2);\nconst sum = doubled.reduce((a, b) => a + b, 0);\n```\n\n### Before: Redundant Abstraction\n\n```typescript\nfunction isNotEmpty(arr: unknown[]): boolean {\n  return arr.length > 0;\n}\n\nif (isNotEmpty(items)) {\n  // ...\n}\n```\n\n### After: Direct Check\n\n```typescript\nif (items.length > 0) {\n  // ...\n}\n```\n"},"category":"official","lastSynced":"2026-03-06T05:00:25.519Z","seo":{"title":{"en":"code-simplifier: Refactoring Guide for AI Agents","zh":"代码简化工具：提高代码可读性和可维护性的最佳实践","ja":"コード簡素化ツール：可読性と保守性を高めるためのベストプラクティス","ko":"코드 간소화 도구: 가독성과 유지보수성을 향상시키는 방법","es":"Guía de configuración del code-simplifier para desarrolla...","fr":"Configurer le code-simplifier pour améliorer la qualité d...","de":"Code-Simplifier-Setup-Anleitung für Entwickler","pt":"Guia de Configuração do Code-Simplifier: Melhore a Legibi...","ru":"Настройка ИИ Агента Code-Simplifier: Улучшение Читаемости...","ar":"دليل إعداد ملحقات البرامج البسيطة: تحسين قراءة الكود"},"description":{"en":"Discover how code-simplifier streamlines your codebase. Learn to simplify, refactor, and optimize your code with this expert AI agent skill.","zh":"使用代码简化工具来提高代码的可读性、可维护性和一致性，同时保持其功能，适用于项目特定的最佳实践","ja":"コード簡素化ツールを使用して、コードの可読性、保守性、整合性を高めます。プロジェクト固有のベストプラクティスに適しています","ko":"코드 간소화 도구를 사용하여 코드의 가독성, 유지보수성, 일관성을 향상시키며, 프로젝트 특有的 최선의 관행에 적합합니다","es":"Mejora la claridad y mantenibilidad de tu código con el code-simplifier, una herramienta de agente de IA para desarrolladores","fr":"Améliorez la lisibilité et la maintenabilité de votre code avec le code-simplifier, un outil d''agent IA pour les développeurs","de":"Verbessern Sie die Klarheit und Wartbarkeit Ihres Codes mit dem Code-Simplifier, einem AI-Tool für Entwickler","pt":"Aprenda a usar o code-simplifier para melhorar a clareza e manutenção do código, preservando a funcionalidade","ru":"Узнайте, как использовать ИИ Агент code-simplifier для улучшения читаемости и поддержки кода","ar":"تعلم كيفية استخدام ملحقات البرامج البسيطة لتحسين وضوح وصيانة الكود مع الحفاظ على الوظائف"},"definition":{"en":"code-simplifier is a specialized AI agent skill that enhances code clarity, consistency, and maintainability while preserving exact functionality.","zh":"代码简化工具是一种AIエージェント，用于简化和优化代码，以提高可读性、可维护性和一致性","ja":"コード簡素化ツールは、AIエージェントの一種で、コードを簡素化して最適化し、可読性、保守性、整合性を高めるために使用されます","ko":"코드 간소화 도구는 코드를 간소화하고 최적화하여 가독성, 유지보수성, 일관성을 높이는 데 사용되는 AI 도구입니다","es":"El code-simplifier es un agente de IA que aplica prácticas recomendadas específicas del proyecto para simplificar y mejorar el código","fr":"Le code-simplifier est un agent IA qui applique des pratiques recommandées spécifiques au projet pour simplifier et améliorer le code","de":"Der Code-Simplifier ist ein AI-Agent, der projektspezifische Best Practices anwendet, um den Code zu vereinfachen und zu verbessern","pt":"O que é code-simplifier? Uma ferramenta de simplificação de código que melhora a legibilidade e manutenção","ru":"Что такое ИИ Агент code-simplifier? Инструмент для упрощения кода, улучшающий читаемость и поддержку","ar":"ما هي ملحقات البرامج البسيطة؟ أداة لتبسيط الكود لتحسين قراءة و صيانة الكود"},"features":{"en":["Applies project-specific best practices for code refinement","Preserves exact functionality during simplification and refactoring","Improves code readability and elegance","Focuses on consistency and maintainability","Enhances code clarity without altering behavior","Supports review of recently modified code for optimal structure"],"zh":["提高代码可读性和可维护性","保持代码功能的一致性","适用于项目特定的最佳实践","支持代码重构和优化","提高代码的一致性和规范性"],"ja":["コードの可読性と保守性を高める","コードの機能の一貫性を維持する","プロジェクト固有のベストプラクティスに対応","コードのリファクタリングと最適化をサポート","コードの一貫性と規範性を高める"],"ko":["코드의 가독성과 유지보수성을 높인다","코드의 기능的一貫性を 유지한다","프로젝트 특有的 최선의 관행에 적합하다","코드의 리팩토링과 최적화를 지원한다","코드的一貫性와 규범성을 높인다"],"es":["Simplificación de código para mejorar la claridad y la mantenibilidad","Aplicación de prácticas recomendadas específicas del proyecto","Mejora de la coherencia y la lisibilidad del código","Preservación de la funcionalidad exacta del código","Soporte para la revisión de código recientemente modificado"],"fr":["Simplification du code pour améliorer la lisibilité et la maintenabilité","Application de pratiques recommandées spécifiques au projet","Amélioration de la cohérence et de la lisibilité du code","Préservation de la fonctionnalité exacte du code","Support pour la révision de code récemment modifié"],"de":["Vereinfachung von Code zur Verbesserung der Klarheit und Wartbarkeit","Anwendung von projektspezifischen Best Practices","Verbesserung der Konsistenz und Lesbarkeit des Codes","Erhaltung der exakten Funktionalität des Codes","Unterstützung für die Überprüfung von kürzlich geändertem Code"],"pt":["Simplificação de código para melhorar a clareza e manutenção","Preservação da funcionalidade do código","Aplicação de práticas recomendadas específicas do projeto","Melhoria da legibilidade do código","Refinamento do código para consistência e manutenção"],"ru":["Упрощение кода для улучшения читаемости и поддержки","Сохранение функциональности кода","Применение проектных рекомендаций","Улучшение читаемости кода","Совершенствование кода для согласованности и поддержки"],"ar":["تبسيط الكود لتحسين قراءة و صيانة الكود","الحفاظ على وظائف الكود","تطبيق ممارسات مشروع محددة","تحسين قراءة الكود","تنقيح الكود لاتساق و صيانة"]},"keywords":{"en":["how to use code-simplifier","code-simplifier setup guide","code simplification techniques","code-simplifier vs claude","what is code-simplifier","code-simplifier install","refactoring code with code-simplifier","code-simplifier alternative","code-simplifier for AI agents","code-simplifier best practices"],"zh":["代码简化工具","代码优化","可读性","可维护性","一致性","项目最佳实践","AIエージェント","代码重构"],"ja":["コード簡素化ツール","コード最適化","可読性","保守性","整合性","プロジェクトベストプラクティス","AIエージェント","コードリファクタリング"],"ko":["코드 간소화 도구","코드 최적화","가독성","유지보수성","일관성","프로젝트 최선의 관행","AI 도구","코드 리팩토링"],"es":["code-simplifier","agente de IA para desarrolladores","simplificación de código","mejora de la claridad del código","prácticas recomendadas de código","herramientas de desarrollo de software","optimización de código","refactorización de código"],"fr":["code-simplifier","agent IA pour les développeurs","simplification de code","amélioration de la lisibilité du code","pratiques recommandées de code","outils de développement de logiciels","optimisation de code","réfactorisation de code"],"de":["Code-Simplifier","AI-Tool für Entwickler","Code-Vereinfachung","Verbesserung der Code-Klarheit","Code-Best Practices","Software-Entwicklungstools","Code-Optimierung","Code-Refaktorierung"],"pt":["code-simplifier","simplificação de código","melhoria da legibilidade","manutenção de código","práticas recomendadas de projeto","ferramentas de desenvolvimento","otimização de código"],"ru":["ИИ Агент code-simplifier","упрощение кода","улучшение читаемости","поддержка кода","проектные рекомендации","инструменты разработки","оптимизация кода"],"ar":["ملحقات البرامج البسيطة","تبسيط الكود","تحسين قراءة الكود","صيانة الكود","ممارسات مشروع محددة","أدوات التطوير","تحسين الكود"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced refactoring capabilities while preserving exact functionality.","zh":"适合需要高级重构功能的代码审查代理，同时保持完全的功能性。","ja":"高度なリファクタリング機能が必要なコードレビューエージェントに適していますが、機能性を完全に維持します。","ko":"고급 리팩토링 기능이 필요한 코드 리뷰 에이전트에게 적합하며, 기능을完全하게 유지합니다.","es":"Perfecto para los agentes de revisión de código que necesitan capacidades de refactorización avanzadas mientras preservan la funcionalidad exacta.","fr":"Parfait pour les agents de révision de code nécessitant des capacités de refactoring avancées tout en préservant la fonctionnalité exacte.","de":"Perfekt für Code-Review-Agents, die erweiterte Refactoring-Funktionen benötigen, während sie die exakte Funktionalität erhalten.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de capacidades de refatoração avançadas enquanto preservam a funcionalidade exata.","ru":"Идеально подходит для агентов код-ревью, которым требуются продвинутые возможности рефакторинга при сохранении точной функциональности.","ar":"مثالي للوكلاء المراجعين للرمز البرمجي الذين يحتاجون إلى إمكانيات إعادة هيكلة متقدمة مع الحفاظ على الوظيفة الصحيحة."},"recommendation":{"en":"Enhances code clarity, consistency, and maintainability by applying project-specific best practices to simplify and refine code without altering behavior. Focuses on readable, explicit code transformations for improved elegance and maintainability.","zh":"通过将项目特定的最佳实践应用于简化和精化代码而不改变行为，从而提高代码的清晰度、一致性和可维护性。专注于可读性、显式的代码转换，以提高优雅性和可维护性。","ja":"プロジェクト固有のベストプラクティスを適用してコードを簡素化し、精密化することで、コードの明確性、一貫性、保守性を向上させます。可読性の高い、明示的なコード変換に焦点を当て、優雅性と保守性を向上させます。","ko":"프로젝트 특정 최선의 관행을 적용하여 동작을 변경하지 않고 코드를 단순화하고 정련함으로써 코드의 명확성, 일관성, 유지보수성을 향상시킵니다. 가독성과 명확성이 높은 코드 변환에 중점을 두어 우아함과 유지보수성을 향상시킵니다.","es":"Mejora la claridad, coherencia y mantenibilidad del código aplicando las mejores prácticas específicas del proyecto para simplificar y refinar el código sin alterar su comportamiento. Se centra en transformaciones de código legibles y explícitas para mejorar la elegancia y la mantenibilidad.","fr":"Améliore la clarté, la cohérence et la maintenabilité du code en appliquant les meilleures pratiques spécifiques au projet pour simplifier et raffiner le code sans en modifier le comportement. Se concentre sur des transformations de code lisibles et explicites pour améliorer l''élégance et la maintenabilité.","de":"Verbessert die Klarheit, Konsistenz und Wartbarkeit des Codes, indem projektbezogene Best Practices angewendet werden, um den Code zu vereinfachen und zu verfeinern, ohne das Verhalten zu ändern. Konzentriert sich auf lesbare, explizite Code-Transformationen, um Eleganz und Wartbarkeit zu verbessern.","pt":"Melhora a clareza, consistência e manutenibilidade do código aplicando as melhores práticas específicas do projeto para simplificar e aprimorar o código sem alterar o comportamento. Concentra-se em transformações de código legíveis e explícitas para uma elegância e manutenibilidade melhoradas.","ru":"Улучшает ясность, последовательность и поддерживаемость кода, применяя проектно-специфические лучшие практики для упрощения и совершенствования кода без изменения поведения. Сосредоточен на читаемых, явных кодовых преобразованиях для улучшения элегантности и поддерживаемости.","ar":"تحسين وضوح وثبات واستدامة الرمز البرمجي من خلال تطبيق أفضل الممارسات المحددة للمشروع لتسهيل وتحسين الرمز البرمجي بدون تغيير السلوك. يركز على تحويلات الرمز البرمجي القابلة للقراءة والصريحة من أجل رقي وثبات محسّن."},"useCases":{"en":["Refactoring complex code for clarity","Cleaning up recently modified code","Simplifying code while preserving functionality","Improving code readability and maintainability","Reviewing code for consistency with project standards"],"zh":["为清晰度而重构复杂代码","清理最近修改的代码","在保持功能性的同时简化代码","提高代码的可读性和可维护性","审查代码以确保与项目标准的一致性"],"ja":["明確性のために複雑なコードをリファクタリングする","最近変更されたコードをクリーンアップする","機能性を維持しながらコードを簡素化する","コードの可読性と保守性を向上させる","コードをプロジェクト標準との一貫性を確保するためにレビューする"],"ko":["명확성을 위해 복잡한 코드를 리팩토링한다","최근 수정된 코드를 정리한다","기능을 유지하면서 코드를 단순화한다","코드의 가독성과 유지보수성을 향상시킨다","코드를 프로젝트 표준과 일관성을 확인하기 위해 검토한다"],"es":["Refactorización de código complejo para mejorar la claridad","Limpieza de código recientemente modificado","Simplificación de código mientras se preserva la funcionalidad","Mejora de la legibilidad y mantenibilidad del código","Revisión de código para garantizar la coherencia con los estándares del proyecto"],"fr":["Refactoring de code complexe pour améliorer la clarté","Nettoyage de code récemment modifié","Simplification de code tout en préservant la fonctionnalité","Amélioration de la lisibilité et de la maintenabilité du code","Révision de code pour garantir la cohérence avec les normes du projet"],"de":["Refactoring komplexen Codes für bessere Klarheit","Reinigung kürzlich geänderten Codes","Vereinfachung von Code bei Erhalt der Funktionalität","Verbesserung der Lesbarkeit und Wartbarkeit des Codes","Überprüfung von Code auf Übereinstimmung mit den Projektstandards"],"pt":["Refatoração de código complexo para clareza","Limpeza de código recentemente modificado","Simplificação de código enquanto se preserva a funcionalidade","Melhoria da legibilidade e manutenibilidade do código","Revisão de código para consistência com os padrões do projeto"],"ru":["Рефакторинг сложного кода для ясности","Очистка недавно измененного кода","Упрощение кода при сохранении функциональности","Улучшение читаемости и поддерживаемости кода","Проверка кода на соответствие проектным стандартам"],"ar":["إعادة هيكلة الرمز البرمجي المعقد لتحقيق الوضوح","تنظيف الرمز البرمجي المعدّل حديثًا","تسهيل الرمز البرمجي مع الحفاظ على الوظيفة","تحسين قراءة الرمز البرمجي واستدامته","مراجعة الرمز البرمجي لتطابق معايير المشروع"]},"limitations":{"en":["Preserves exact functionality only (no behavior changes)","Requires project-specific best practices knowledge","Focuses on code elegance rather than performance optimization"],"zh":["仅保持完全的功能性（无行为变化）","需要项目特定的最佳实践知识","注重代码的优雅性而非性能优化"],"ja":["完全な機能性のみを維持する（動作の変更なし）","プロジェクト固有のベストプラクティスに関する知識が必要","コードの優雅性よりもパフォーマンス最適化に焦点を当てない"],"ko":["완전한 기능만 유지합니다(동작 변경 없음)","프로젝트 특정 최선의 관행에 대한 지식이 필요합니다","코드의 우아함에 중점을 둡니다. 성능 최적화에는 중점을 두지 않습니다"],"es":["Preserva la funcionalidad exacta solo (sin cambios de comportamiento)","Requiere conocimiento de las mejores prácticas específicas del proyecto","Se centra en la elegancia del código en lugar de la optimización del rendimiento"],"fr":["Préserve la fonctionnalité exacte uniquement (sans modification de comportement)","Nécessite une connaissance des meilleures pratiques spécifiques au projet","Se concentre sur l''élégance du code plutôt que sur l''optimisation des performances"],"de":["Bewahrt die exakte Funktionalität nur (keine Verhaltensänderungen)","Benötigt Kenntnisse über projektbezogene Best Practices","Konzentriert sich auf die Eleganz des Codes anstelle der Leistungsoptimierung"],"pt":["Preserva apenas a funcionalidade exata (sem alterações de comportamento)","Exige conhecimento de melhores práticas específicas do projeto","Concentra-se na elegância do código em vez da otimização de desempenho"],"ru":["Сохраняет только точную функциональность (без изменений поведения)","Требует знания проектно-специфических лучших практик","Сосредоточен на элегантности кода, а не на оптимизации производительности"],"ar":["تحافظ فقط على الوظيفة الصحيحة (بدون تغييرات في السلوك)","يتطلب معرفة أفضل الممارسات المحددة للمشروع","يركز على رقي الرمز البرمجي بدلاً من تحسين الأداء"]},"version":4},"contentHash":"ad4ce00d2759e0773bee88f267f4ae0f52684979d7fbceb14dffd5efefbce141","repoEtag":"W/\"36a09bba6a611068f31a3df860388e78cbe9407beaecc6e6da77ba4b47f9eb59\"","qualityScore":86}');
