INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/code-simplifier', 'code-simplifier', 'getsentry', 'skills', 'official', 'code-simplifier getsentry skills official tag-production The code-simplifier skill simplifies and refines code for clarity, consistency, and maintainability, preserving functionality. It''s ideal for developers seeking to improve code readability and elegance. 代码简化工具是一种专门的代码优化工具，旨在提高代码的可读性、可维护性和一致性，同时保持其功能 コード簡素化ツールは、コードの可読性、保守性、整合性を高めながら、その機能を維持することを目的とした専門のコード最適化ツールです 코드 간소화 도구는 코드의 가독성, 유지보수성, 일관성을 높이며, 그 기능을 유지하는 것을 목적으로 하는 전문적인 코드 최적화 도구입니다 El code-simplifier es una herramienta de agente de IA que simplifica y refina el código para mejorar la claridad, coherencia y mantenibilidad Le code-simplifier est un outil d''agent IA qui simplifie et affine le code pour améliorer la lisibilité, la cohérence et la maintenabilité Der Code-Simplifier ist ein AI-Tool, das den Code vereinfacht und verfeinert, um die Klarheit, Konsistenz und Wartbarkeit zu verbessern O code-simplifier é uma ferramenta que simplifica e refina o código para melhorar a clareza, consistência e manutenção ИИ Агент code-simplifier - это инструмент, который упрощает и совершенствует код для улучшения читаемости, согласованности и поддержки ملحقات البرامج البسيطة هي أداة تقوم بتبسيط وتنقيح الكود لتحسين الوضوح والاتساق والصيانة how to use code-simplifier code-simplifier setup guide code simplification techniques code-simplifier vs claude what is code-simplifier code-simplifier install refactoring code with code-simplifier code-simplifier alternative code-simplifier for AI agents code-simplifier best practices 代码简化工具 代码优化 可读性 可维护性 一致性 项目最佳实践 AIエージェント 代码重构 Applies project-specific best practices for code refinement Preserves exact functionality during simplification and refactoring Improves code readability and elegance Focuses on consistency and maintainability Enhances code clarity without altering behavior Supports review of recently modified code for optimal structure code-simplifier is a specialized AI agent skill that enhances code clarity, consistency, and maintainability while preserving exact functionality.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/commit', 'official', 'getsentry', 'skills', 'getsentry/skills', 'commit', 360, 11, 86, '2026-03-06T00:20:36Z', '2026-03-06T05:01:35.987Z', '364102401c4fa6bcf52db0de82adec614961481da096bf390a4fd295b8763fe8', '{"id":"getsentry/skills/commit","name":"commit","description":{"en":"The commit skill automates code commits following Sentry conventions, ensuring proper commit format and issue references. It benefits developers by streamlining the commit process.","zh":"Commit AI工具帮助开发者自动化代码提交，确保遵循Sentry规范和约定。","ja":"Commit AIエージェントは、開発者がコード変更を自動化し、Sentry規約に従うのに役立ちます。","ko":"Commit AI 에이전트는 개발자가 코드 변경을 자동화하고 Sentry 규약을 준수하도록 도와줍니다.","es":"El commit es una habilidad que crea commits siguiendo las convenciones de Sentry con formato de commit convencional y referencias de problemas","fr":"Le commit est une compétence qui crée des commits suivant les conventions de Sentry avec un format de commit conventionnel et des références de problèmes","de":"Der Commit ist eine Fähigkeit, die Commits nach den Sentry-Konventionen mit konventionellem Commit-Format und Problemverweisen erstellt","pt":"O commit é uma habilidade essencial para desenvolvedores, criando commits que seguem as convenções do Sentry","ru":"Коммит - это необходимый навык для разработчиков, создающий коммиты, соответствующие конвенциям Sentry","ar":"Commit هو مهارة أساسية للمطورين، حيث يخلق Commits يتبع اتفاقيات Sentry"},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"commit","description":"ALWAYS use this skill when committing code changes — never commit directly without it. Creates commits following Sentry conventions with proper conventional commit format and issue references. Trigger on any commit, git commit, save changes, or commit message task.","bodyPreview":"# Sentry Commit Messages\n\nFollow these conventions when creating commits for Sentry projects.\n\n## Prerequisites\n\nBefore committing, always check the current branch:\n\n```bash\ngit branch --show-current\n```\n\n**If you''re on `main` or `master`, you MUST create a feature branch first** — unless the user explicitly asked to commit to main. Do not ask the user whether to create a branch; just proceed with branch creation. The `create-branch` skill will still propose a branch name for the user to confirm","body":"# Sentry Commit Messages\n\nFollow these conventions when creating commits for Sentry projects.\n\n## Prerequisites\n\nBefore committing, always check the current branch:\n\n```bash\ngit branch --show-current\n```\n\n**If you''re on `main` or `master`, you MUST create a feature branch first** — unless the user explicitly asked to commit to main. Do not ask the user whether to create a branch; just proceed with branch creation. The `create-branch` skill will still propose a branch name for the user to confirm.\n\nUse the `create-branch` skill to create the branch. After `create-branch` completes, verify the current branch has changed before proceeding:\n\n```bash\ngit branch --show-current\n```\n\nIf still on `main` or `master` (e.g., the user aborted branch creation), stop — do not commit.\n\n## Format\n\n```\n<type>(<scope>): <subject>\n\n<body>\n\n<footer>\n```\n\nThe header is required. Scope is optional. All lines must stay under 100 characters.\n\n## Commit Types\n\n| Type | Purpose |\n|------|---------|\n| `feat` | New feature |\n| `fix` | Bug fix |\n| `ref` | Refactoring (no behavior change) |\n| `perf` | Performance improvement |\n| `docs` | Documentation only |\n| `test` | Test additions or corrections |\n| `build` | Build system or dependencies |\n| `ci` | CI configuration |\n| `chore` | Maintenance tasks |\n| `style` | Code formatting (no logic change) |\n| `meta` | Repository metadata |\n| `license` | License changes |\n\n## Subject Line Rules\n\n- Use imperative, present tense: \"Add feature\" not \"Added feature\"\n- Capitalize the first letter\n- No period at the end\n- Maximum 70 characters\n\n## Body Guidelines\n\n- Explain **what** and **why**, not how\n- Use imperative mood and present tense\n- Include motivation for the change\n- Contrast with previous behavior when relevant\n\n## Footer: Issue References\n\nReference issues in the footer using these patterns:\n\n```\nFixes GH-1234\nFixes #1234\nFixes SENTRY-1234\nRefs LINEAR-ABC-123\n```\n\n- `Fixes` closes the issue when merged\n- `Refs` links without closing\n\n## AI-Generated Changes\n\nWhen changes were primarily generated by a coding agent (like Claude Code), include the Co-Authored-By attribution in the commit footer:\n\n```\nCo-Authored-By: Claude <noreply@anthropic.com>\n```\n\nThis is the only indicator of AI involvement that should appear in commits. Do not add phrases like \"Generated by AI\", \"Written with Claude\", or similar markers in the subject, body, or anywhere else in the commit message.\n\n## Examples\n\n### Simple fix\n\n```\nfix(api): Handle null response in user endpoint\n\nThe user API could return null for deleted accounts, causing a crash\nin the dashboard. Add null check before accessing user properties.\n\nFixes SENTRY-5678\nCo-Authored-By: Claude <noreply@anthropic.com>\n```\n\n### Feature with scope\n\n```\nfeat(alerts): Add Slack thread replies for alert updates\n\nWhen an alert is updated or resolved, post a reply to the original\nSlack thread instead of creating a new message. This keeps related\nnotifications grouped together.\n\nRefs GH-1234\n```\n\n### Refactor\n\n```\nref: Extract common validation logic to shared module\n\nMove duplicate validation code from three endpoints into a shared\nvalidator class. No behavior change.\n```\n\n### Breaking change\n\n```\nfeat(api)!: Remove deprecated v1 endpoints\n\nRemove all v1 API endpoints that were deprecated in version 23.1.\nClients should migrate to v2 endpoints.\n\nBREAKING CHANGE: v1 endpoints no longer available\nFixes SENTRY-9999\n```\n\n## Revert Format\n\n```\nrevert: feat(api): Add new endpoint\n\nThis reverts commit abc123def456.\n\nReason: Caused performance regression in production.\n```\n\n## Principles\n\n- Each commit should be a single, stable change\n- Commits should be independently reviewable\n- The repository should be in a working state after each commit\n\n## References\n\n- [Sentry Commit Messages](https://develop.sentry.dev/engineering-practices/commit-messages/)\n"},"category":"official","lastSynced":"2026-03-06T05:01:35.987Z","seo":{"title":{"en":"commit: Conventional Commit Setup Guide | AI Agent Skill","zh":"Commit Setup Guide: 使用AI工具自动化代码提交","ja":"Commit ベストプラクティス: AIエージェントによるコード変更の自動化","ko":"Commit 자동화 가이드: 코드 변경을 위한 AI 에이전트 활용","es":"Configuración del Commit: Guía de mejores prácticas para ...","fr":"Paramétrage du Commit: Guide des meilleures pratiques pou...","de":"Commit-Einrichtung: Leitfaden für beste Praktiken mit kün...","pt":"Guia de Configuração do Commit: Melhores Práticas para De...","ru":"ИИ Агент Commit: Настройка и Лучшие Практики для Разработ...","ar":"دليل إعداد Commit: أفضل الممارسات للاستفادة القصوى من الأ..."},"description":{"en":"Discover how to automate commits with Sentry conventions and proper formatting. Learn to trigger commits on any git commit, save changes, or commit message task","zh":"使用Commit AI工具自动化代码提交，确保遵循Sentry规范和约定","ja":"Commit AIエージェントを使用してコード変更を自動化し、Sentry規約に従う","ko":"Commit AI 에이전트를 사용하여 코드 변경을 자동화하고 Sentry 규약을 준수하십시오","es":"Aprende a configurar el commit con herramientas de AI para proyectos de Sentry, incluyendo convenciones de commit y referencias de problemas","fr":"Découvrez comment paramétrer le commit avec des outils d''IA pour les projets Sentry, y compris les conventions de commit et les références de problèmes","de":"Erfahren Sie, wie Sie den Commit mit künstlicher Intelligenz für Sentry-Projekte einrichten, einschließlich Commit-Konventionen und Problemverweisen","pt":"Aprenda a usar o commit com eficácia, seguindo as convenções do Sentry e criando branches de recurso de forma automática","ru":"Узнайте, как эффективно использовать коммит, следуя конвенциям Sentry и автоматически создавая фич-branches","ar":"تعرف على كيفية استخدام Commit بفعالية، باتباع اتفاقيات Sentry وإنشاء فروع الميزات تلقائيًا"},"definition":{"en":"commit is a skill that automates code commits using conventional commit format and Sentry conventions","zh":"Commit AI工具是一种自动化代码提交的工具，确保代码提交遵循Sentry规范和约定。","ja":"Commit AIエージェントは、コード変更を自動化するために設計されたツールで、Sentry規約に従ったコミットメッセージを作成します。","ko":"Commit AI 에이전트는 코드 변경을 자동화하기 위한 도구로, Sentry 규약에 따라 커밋 메시지를 생성합니다.","es":"¿Qué es el commit? Es una habilidad de herramientas de AI que crea commits con formato convencional y referencias de problemas","fr":"Qu''est-ce que le commit? C''est une compétence d''outils d''IA qui crée des commits avec un format conventionnel et des références de problèmes","de":"Was ist der Commit? Es ist eine Fähigkeit von künstlicher Intelligenz, die Commits mit konventionellem Format und Problemverweisen erstellt","pt":"O que é commit? É uma habilidade que cria commits seguindo as convenções do Sentry","ru":"Что такое коммит? Это навык, создающий коммиты, соответствующие конвенциям Sentry","ar":"ما هو Commit؟ إنه مهارة تخلق Commits تتبع اتفاقيات Sentry"},"features":{"en":["Creates commits following Sentry conventions with proper conventional commit format","Supports issue references in commit messages","Triggers on any commit, git commit, save changes, or commit message task","Automatically checks the current branch using `git branch --show-current`","Creates a feature branch if necessary, unless explicitly committing to main"],"zh":["自动化代码提交","遵循Sentry规范和约定","创建符合Sentry规约的提交消息","支持Git分支创建","自动检测当前分支"],"ja":["コード変更の自動化","Sentry規約に従ったコミットメッセージの作成","Gitブランチの自動作成","現在のブランチの自動検出","コミットメッセージのフォーマットの自動化"],"ko":["코드 변경 자동화","Sentry 규약에 따른 커밋 메시지 생성","Git 브랜치 자동 생성","현재 브랜치 자동 감지","커밋 메시지 형식 자동화"],"es":["Crea commits con formato convencional de Sentry","Incluye referencias de problemas en los commits","Se ejecuta en cualquier commit, git commit, guardar cambios o tarea de mensaje de commit","Proporciona un nombre de rama para que el usuario lo confirme","Revisa la rama actual antes de realizar el commit","Crea una rama de características si es necesario"],"fr":["Crée des commits avec un format conventionnel de Sentry","Inclut des références de problèmes dans les commits","S''exécute sur n''importe quel commit, git commit, enregistrer des modifications ou tâche de message de commit","Propose un nom de branche pour que l''utilisateur le confirme","Vérifie la branche actuelle avant de réaliser le commit","Crée une branche de fonctionnalités si nécessaire"],"de":["Erstellt Commits mit konventionellem Sentry-Format","Inklusive Problemverweise in den Commits","Wird bei jedem Commit, git commit, Speichern von Änderungen oder Commit-Messaging-Aufgabe ausgeführt","Bietet einen Branch-Namen an, den der Benutzer bestätigen kann","Überprüft den aktuellen Branch vor dem Commit","Erstellt einen Feature-Branch, wenn erforderlich"],"pt":["Cria commits que seguem as convenções do Sentry","Suporta a criação de branches de recurso de forma automática","Verifica a branch atual antes de commitar","Segue as melhores práticas para commits","Integração com o Git para commitar alterações"],"ru":["Создаёт коммиты, соответствующие конвенциям Sentry","Поддерживает автоматическое создание фич-branches","Проверяет текущую ветку перед коммитом","Следует лучшим практикам для коммитов","Интеграция с Git для коммита изменений"],"ar":["يخلق Commits يتبع اتفاقيات Sentry","يدعم إنشاء فروع الميزات تلقائيًا","يفحص الفرع الحالي قبل Commit","يتابع أفضل الممارسات ل Commits","التكامل مع Git ل Commit التغييرات"]},"keywords":{"en":["how to use commit skill","commit skill setup guide","Sentry commit conventions","conventional commit format","git commit automation","commit vs git flow","commit install for AI agents","commit skill for developers","automating commits with AI"],"zh":["Commit AI工具","代码提交自动化","Sentry规范","Git分支创建","代码变更管理","AI工具","代码提交最佳实践"],"ja":["Commit AIエージェント","コード変更の自動化","Sentry規約","Gitブランチの作成","コード変更管理","AIエージェント","コミットメッセージのフォーマット"],"ko":["Commit AI 에이전트","코드 변경 자동화","Sentry 규약","Git 브랜치 생성","코드 변경 관리","AI 에이전트","커밋 메시지 형식"],"es":["herramientas de AI para commit","convenciones de commit de Sentry","formato de commit convencional","referencias de problemas en commits","commit con AI","guía de commit para desarrolladores","mejores prácticas para commits","configuración del commit","commit con formato de Sentry"],"fr":["outils d''IA pour commit","conventions de commit de Sentry","format de commit conventionnel","références de problèmes dans les commits","commit avec IA","guide de commit pour les développeurs","meilleures pratiques pour les commits","paramétrage du commit","commit avec format de Sentry"],"de":["künstliche Intelligenz für Commits","Sentry-Commit-Konventionen","konventionelles Commit-Format","Problemverweise in Commits","Commit mit künstlicher Intelligenz","Leitfaden für Commits für Entwickler","beste Praktiken für Commits","Commit-Einrichtung","Commit mit Sentry-Format"],"pt":["commit","Sentry","convenções de commit","criação de branches","melhores práticas de commit","Git","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["коммит","Sentry","конвенции коммита","создание фич-branches","лучшие практики коммита","Git","разработка программного обеспечения","инструменты разработки"],"ar":["Commit","Sentry","اتفاقيات Commit","إنشاء فروع الميزات","أفضل الممارسات ل Commit","Git","تطوير البرمجيات","أدوات التطوير"]}},"agentAnalysis":{"suitability":{"en":"Essential for Git Automation Agents requiring Sentry-compliant commit message generation.","zh":"适用于需要遵循Sentry标准的Git自动化代理的提交消息生成","ja":"Sentry準拠のコミットメッセージ生成を必要とするGit自動化エージェントに不可欠","ko":"Sentry 규격의 커밋 메시지 생성을 필요로 하는 Git 자동화 에이전트에 필수","es":"Esencial para Agentes de Automatización de Git que requieran la generación de mensajes de commit compatibles con Sentry.","fr":"Essentiel pour les Agents d''Automatisation Git nécessitant la génération de messages de commit conformes à Sentry.","de":"Essenziell für Git-Automatisierungs-Agents, die eine Sentry-konforme Erstellung von Commit-Messages erfordern.","pt":"Essencial para Agentes de Automação Git que exigem geração de mensagens de commit compatíveis com o Sentry.","ru":"Необходимо для агентов автоматизации Git, требующих генерации сообщений о коммите, соответствующих Sentry.","ar":"ضروري لأجهزة العميل الآلي لإدارة Git التي تتطلب إنشاء رسائل الإلتزام المتوافقة مع Sentry."},"recommendation":{"en":"Automates conventional commit formatting with Sentry-specific issue references, ensuring compliance with project standards. Enforces branch safety protocols by preventing direct commits to main/master and automatically triggering branch creation workflows.","zh":"自动执行符合Sentry特定问题引用的传统提交格式，以确保遵守项目标准。通过防止直接提交到主分支并自动触发分支创建工作流来强制执行分支安全协议","ja":"Sentry特定問題への参照を含む従来のコミット形式を自動化し、プロジェクト標準への準拠を保証する。メイン/マスター分支への直接コミットを防止し、自動的にブランチ作成ワークフローをトリガーすることでブランチ安全性プロトコルを強制する","ko":"Sentry 특정 이슈 참조를 포함하는 표준 커밋 형식을 자동화하여 프로젝트 표준을 준수하도록 합니다. 메인/마스터 분기에 대한 직접 커밋을 방지하고 분기 생성 워크플로를 자동으로 트리거하여 분기 안전성 프로토콜을 적용","es":"Automatiza el formato de commits convencionales con referencias de incidencias específicas de Sentry, garantizando el cumplimiento de los estándares del proyecto. Impone protocolos de seguridad de ramas al evitar commits directos a main/master y activar automáticamente flujos de trabajo de creación de ramas.","fr":"Automatise le formatage de commits conventionnels avec des références de problèmes spécifiques à Sentry, assurant la conformité aux standards du projet. Applique des protocoles de sécurité des branches en empêchant les commits directs sur main/master et en déclenchant automatiquement des workflows de création de branches.","de":"Automatisiert die Formatierung konventioneller Commits mit Sentry-spezifischen Issue-Referenzen und stellt so die Einhaltung der Projektstandards sicher. Erzwingt Branch-Sicherheitsprotokolle, indem direkte Commits auf main/master verhindert und Workflows zur Branch-Erstellung automatisch ausgelöst werden.","pt":"Automatiza a formatação de commit convencional com referências de problemas específicas do Sentry, garantindo a conformidade com os padrões do projeto. Implementa protocolos de segurança de ramificação, impedindo a commit direto para main/master e acionando automaticamente fluxos de trabalho de criação de ramificação.","ru":"Автоматизирует форматирование коммитов в соответствии с Sentry-специфическими ссылками на проблемы, обеспечивая соответствие стандартам проекта. Реализует протоколы безопасности веток, предотвращая прямые коммиты в main/master и автоматически запуская рабочие процессы создания веток.","ar":"يُutomatiza تنسيق الإلتزام التقليدي مع مراجع مشاكل محددة من Sentry، مما يضمن امتثالًا لمعايير المشروع. يفرض بروتوكولات سلامة الفرع من خلال منع الإلتزام المباشر إلى main/master وتشغيل سير العمل التلقائي لإنشاء الفرع."},"useCases":{"en":["Automating Sentry-compliant commit message generation","Enforcing branch protection rules before committing","Integrating issue tracking references into commit history","Streamlining Git workflow automation for development teams"],"zh":["自动执行Sentry标准的提交消息生成","在提交前强制执行分支保护规则","将问题跟踪引用集成到提交历史记录","简化开发团队的Git工作流自动化"],"ja":["Sentry準拠のコミットメッセージ生成の自動化","コミット前にブランチ保護ルールを強制する","問題追跡リファレンスをコミット履歴に統合する","開発チームのGitワークフロー自動化の簡素化"],"ko":["Sentry 규격의 커밋 메시지 생성 자동화","커밋 전에 분기 보호 규칙 적용","문제 추적 참조를 커밋 기록에 통합","개발 팀의 Git 워크플로 자동화 간소화"],"es":["Automatización de la generación de mensajes de commit compatibles con Sentry","Aplicación de reglas de protección de ramas antes de realizar commits","Integración de referencias de seguimiento de incidencias en el historial de commits","Automatización simplificada del flujo de trabajo de Git para equipos de desarrollo"],"fr":["Automatisation de la génération de messages de commit conformes à Sentry","Application des règles de protection des branches avant de committer","Intégration des références de suivi des problèmes dans l''historique des commits","Rationalisation de l''automatisation du workflow Git pour les équipes de développement"],"de":["Automatisierung der Erstellung von Sentry-konformen Commit-Messages","Durchsetzung von Branch-Schutzregeln vor dem Committen","Integration von Issue-Tracking-Referenzen in den Commit-Verlauf","Vereinfachung der Git-Workflow-Automatisierung für Entwicklungsteams"],"pt":["Automatizar a geração de mensagens de commit compatíveis com o Sentry","Implementar regras de proteção de ramificação antes de fazer commit","Integrar referências de rastreamento de problemas ao histórico de commit","Otimizar a automação do fluxo de trabalho do Git para equipes de desenvolvimento"],"ru":["Автоматизировать генерацию сообщений о коммите, соответствующих Sentry","Реализовать правила защиты веток перед коммитом","Интегрировать ссылки на отслеживание проблем в историю коммитов","Оптимизировать автоматизацию рабочего процесса Git для команд разработки"],"ar":["تأتمتة إنشاء رسائل الإلتزام المتوافقة مع Sentry","تطبيق قواعد حماية الفرع قبل الإلتزام","دمج مراجع تتبع المشاكل في سجل الإلتزام","بسط تسهيل عمليات العمل التلقائي لإدارة Git لفريق التطوير"]},"limitations":{"en":["Requires Git repository initialization","Depends on create-branch skill for branch operations","Sentry-specific convention implementation only"],"zh":["需要Git仓库初始化","依赖于create-branch技能进行分支操作","仅Sentry特定约定实现"],"ja":["Gitリポジトリ初期化が必要","ブランチ操作にはcreate-branchスキルに依存","Sentry特定の規約実装のみ"],"ko":["Git 저장소 초기화 필요","분기 작업에는 create-branch 스킬에 의존","Sentry 특정 규약 구현만"],"es":["Requiere la inicialización de un repositorio Git","Depende de la skill create-branch para las operaciones con ramas","Implementación exclusiva de convenciones específicas de Sentry"],"fr":["Nécessite l''initialisation d''un dépôt Git","Dépend de la compétence create-branch pour les opérations sur les branches","Implémentation exclusive des conventions spécifiques à Sentry"],"de":["Erfordert die Initialisierung eines Git-Repositories","Ist für Branch-Operationen von der create-branch Skill abhängig","Nur die Implementierung von Sentry-spezifischen Konventionen"],"pt":["Exige a inicialização do repositório Git","Depende da habilidade create-branch para operações de ramificação","Implementação de convenção específica do Sentry apenas"],"ru":["Требует инициализации репозитория Git","Зависит от навыка create-branch для операций с ветками","Реализация только Sentry-специфической конвенции"],"ar":["يتطلب تهيئة مستودع Git","يعتمد على مهارة create-branch لعمليات الفرع","تنفيذ اتفاقية محددة من Sentry فقط"]},"version":4},"contentHash":"364102401c4fa6bcf52db0de82adec614961481da096bf390a4fd295b8763fe8","repoEtag":"W/\"36a09bba6a611068f31a3df860388e78cbe9407beaecc6e6da77ba4b47f9eb59\"","qualityScore":86}');
