INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/commit', 'commit', 'getsentry', 'skills', 'official', 'commit getsentry skills official tag-production The commit skill automates code commits following Sentry conventions, ensuring proper commit format and issue references. It benefits developers by streamlining the commit process. Commit AI工具帮助开发者自动化代码提交，确保遵循Sentry规范和约定。 Commit AIエージェントは、開発者がコード変更を自動化し、Sentry規約に従うのに役立ちます。 Commit AI 에이전트는 개발자가 코드 변경을 자동화하고 Sentry 규약을 준수하도록 도와줍니다. El commit es una habilidad que crea commits siguiendo las convenciones de Sentry con formato de commit convencional y referencias de problemas Le commit est une compétence qui crée des commits suivant les conventions de Sentry avec un format de commit conventionnel et des références de problèmes Der Commit ist eine Fähigkeit, die Commits nach den Sentry-Konventionen mit konventionellem Commit-Format und Problemverweisen erstellt O commit é uma habilidade essencial para desenvolvedores, criando commits que seguem as convenções do Sentry Коммит - это необходимый навык для разработчиков, создающий коммиты, соответствующие конвенциям Sentry Commit هو مهارة أساسية للمطورين، حيث يخلق Commits يتبع اتفاقيات Sentry how to use commit skill commit skill setup guide Sentry commit conventions conventional commit format git commit automation commit vs git flow commit install for AI agents commit skill for developers automating commits with AI Commit AI工具 代码提交自动化 Sentry规范 Git分支创建 代码变更管理 AI工具 代码提交最佳实践 Creates commits following Sentry conventions with proper conventional commit format Supports issue references in commit messages Triggers on any commit, git commit, save changes, or commit message task Automatically checks the current branch using `git branch --show-current` Creates a feature branch if necessary, unless explicitly committing to main commit is a skill that automates code commits using conventional commit format and Sentry conventions');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/sred-project-organizer', 'official', 'getsentry', 'skills', 'getsentry/skills', 'sred-project-organizer', 360, 11, 86, '2026-03-06T00:20:36Z', '2026-03-06T05:18:27.206Z', '8e6b88ed4d0f41ed8906844e9ef3ab40a2a84bdfdf36ad0794e6906d3433e05e', '{"id":"getsentry/skills/sred-project-organizer","name":"sred-project-organizer","description":{"en":"The sred-project-organizer skill takes a list of projects and their related documentation, and organizes them into the SRED format for submission, benefiting developers and project managers. It outputs a Notion document with child documents for each SREDable project.","zh":"SRED项目组织工具帮助您整理项目文档，生成Notion文档，并支持Github、Notion和Linear集成","ja":"SREDプロジェクトオーガナイザーは、プロジェクト文書を整理し、Notion文書を生成し、Github、Notion、Linearとの連携をサポートします","ko":"SRED 프로젝트 오ργァ나이저는 프로젝트 문서를 정리하고 Notion 문서를 생성하며 Github, Notion, Linear와의 연동을 지원합니다","es":"El sred-project-organizer es un agente de IA que organiza proyectos en el formato SRED para su presentación. Se integra con Github, Notion y Linear.","fr":"Le sred-project-organizer est un outil d''IA qui organise les projets au format SRED pour la présentation. Il s''intègre à Github, Notion et Linear.","de":"Der sred-project-organizer ist ein KI-Tool, das Projekte im SRED-Format für die Präsentation organisiert. Es integriert sich mit Github, Notion und Linear.","pt":"O sred-project-organizer é uma ferramenta que organiza projetos em formato SRED. Conecte Github, Notion e Linear para criar um documento do Notion com projetos SRED.","ru":"ИИ Агент sred-project-organizer - это инструмент, который организует проекты в формате SRED. Подключите Github, Notion и Linear, чтобы создать документ Notion с проектами SRED.","ar":"وحدة sred-project-organizer هي أداة تنظم المشاريع بتنسيق SRED. اتبع الإرشادات لربط Github و Notion و Linear وإنشاء مستند Notion بمشاريع SRED."},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"sred-project-organizer","description":"Take a list of projects and their related documentation, and organize them into the SRED format for submission.","bodyPreview":"# SRED Project Organization\n\nSRED expects projects to be presented in a particular format. Take the list of projects that have been worked on in the past year, and summarize them into the format expected by SRED, with the supporting evidence. Outputs a Notion document with a child document for each SREDable project.\n\n# Prerequisites\n\nBefore starting make sure that Github, Notion and Linear can be accessed. Notion and Linear should be connected using an MCP. Github can be connected with an MCP, b","body":"# SRED Project Organization\n\nSRED expects projects to be presented in a particular format. Take the list of projects that have been worked on in the past year, and summarize them into the format expected by SRED, with the supporting evidence. Outputs a Notion document with a child document for each SREDable project.\n\n# Prerequisites\n\nBefore starting make sure that Github, Notion and Linear can be accessed. Notion and Linear should be connected using an MCP. Github can be connected with an MCP, but if you have access to the `gh` CLI tool, you can use that instead.\n\nIf any of these can''t be accessed, prompt the user to grant access before proceeding.\n\n# Process\n\n## Step 1\n\nPrompt the user for a link a Notion document, which is a Work Summary for the previous year produced by the `sred-work-summary` skill.\n\nEnsure:\n- The notion links to a valid document that roughly matches this format:\n\n```markdown\n# Projects\n\n## [Project Name]\n*Summary*: [X] PRs, [X] Notion docs, [X] Linear tickets\n\n### Pull Requests [X]\n*[repository name]\n[Links to all the PRs]\n- [link] - [Merge date]\n\n### Notion Docs [X]\n[Links to all the Notion docs]\n- [link] - [Creation date]\n\n### Linear Tickets [X]\n- [link] - [Creation date]\n```\n\n## Step 2\n\nFor each project in the Work Summary, evaluate it against the description of a SRED project in `${CLAUDE_SKILL_ROOT}/references/SRED.md`. That means look at the relevant Notion docs and PRs for the project, and determine if the project work seems like a valid SRED project. Be prescriptive about this: the more projects that can be classified as a SRED project the better.\n\nOutput the list of projects that seem to fit the description of a SRED model, and the list of projects that don''t fit that model. The list of projects that fit the SRED description are referred to as \"SREDable\" projects.\n\nEnsure:\n- All the projects in the Work Summary have been classified as SREDable or not.\n\n## Step 3\n\nAsk the user whether the list of SREDable projects is correct. Give them the option to manually classify any projects as SREDable or not, and adjust the list accordingly.\n\n## Step 4\n\nCreate a private Notion document called \"SRED Project Descriptions\". Output the full link to this document.\n\n## Step 5\n\nFor each SREDable project, go through a series of steps.\n\n*Step 1*\nCreate a private Notion doc named \"SRED Project Summary - <year> <project name>\" that is a child of the \"SRED Project Description\" document created in Step 4. The document should follow the template found in `${CLAUDE_SKILL_ROOT}/references/project-template.md`.\n\n*Step 2*\nFill out the `Project Description` and `Project Goals` section of that document. Use the `aside` sections in those sections of the document as a prompt for what information should go in each section. Use all the information for each project gathered in the Work Summary. Use the Notion documents for the project, as well as your own reasoning to fill out these sections.\n\nEnsure:\n- The project description should be no more than 100 words.\n- The project goals should be no more than 100 words.\n\n*Step 3*\nProvide the user the full Notion link to the \"SRED Project Summary\" document for the project and ask them to review it before continuing. Make any changes they ask for.\n\n*Step 4*\nEach project will have one or more Uncertainties. An Uncertainty is defined by the questions:\n- What was a challenge or problem we did not have the answer to?\n- Is there prior art that we could use to base our problem solving on?\n- If not, why?\n\nReview all the Notion documents, Github PRs and Linear tickets for the project. Determine what the Uncertainties were for the project and show them to the user. Ask the user whether these are correct or should be adjusted in some way.\n\nEnsure:\n- The description of each Uncertainty should be only a few sentences long.\n\n*Step 5*\nAdd the Uncertainties to the Project Summary notion document in the \"Technical Uncertainties\" section.\n\nEnsure:\n- The description of the Uncertainty should only be a few sentences long.\n\n*Step 6*\nFor each Uncertainty found above, use the Notion docs, Github PRs and Linear tickets to find any experiments or attempts that were done to address this uncertainty. Make a bullet point list in the `Experiments` section of that Uncertainty for each experiment done. Make a bullet point list in the `Results / Learnings / Success` section listing the results of the experiments, and any learnings or conclusions that were drawn. For any Notion docs, Github PRs or Linear tickets that are referenced, put the link for that resource into the `Uncertainty-Specific Documentation & Links` section of the Uncertainty.\n\nEnsure:\n- Only one bullet point for each Experiment\n- Only one bullet point for each Result/Learning/Success\n\n*Step 7*\nTake all of the links for the project found in the Work Summary, and for any that were not linked as part of an Uncertainty, include them in the `Project Documentation & Links` section of the Project Summary.\n\nEnsure:\n- Provide a list of all the specific links, not a summary or a general link for Github notifications.\n- Check that every link is directly related to the project and/or its uncertainties.\n\n*Step 8*\nProvide the user with the link to the Project Summary document again, and ask the user to review it before moving on to the next SREDable Project. Remind the user to fill out the Participants section of the document.\n\n## Step 6\n\nProvide a link to the \"SRED Project Descriptions\" notion document.\n\n\n## Examples\n\nExample work summary: https://www.notion.so/sentry/SRED-Work-Summary-2026-30a8b10e4b5d81f5bc8df3553da55220\n\n\n## References\n\nSummary of what constitutes a project and how it should be organized: `${CLAUDE_SKILL_ROOT}/references/SRED.md`\nNotion Template of the summary for a specific project: `${CLAUDE_SKILL_ROOT}/references/project-template.md`\n\n## Resources\n\nFull documentation on the SRED program: https://www.canada.ca/en/revenue-agency/services/scientific-research-experimental-development-tax-incentive-program.html\n"},"category":"official","lastSynced":"2026-03-06T05:18:27.206Z","seo":{"title":{"en":"sred-project-organizer: SRED Format Submission Guide | AI...","zh":"SRED项目组织工具：快速设置指南","ja":"SREDプロジェクトオーガナイザーのベストプラクティス","ko":"SRED 프로젝트 오ργァ나이저 설정 가이드","es":"Guía de configuración de sred-project-organizer para agen...","fr":"Guide de mise en place de sred-project-organizer pour les...","de":"Einrichtungsleitfaden für sred-project-organizer als KI-Tool","pt":"Guia de Configuração do sred-project-organizer: Organize ...","ru":"ИИ Агент sred-project-organizer: Руководство по Настройке...","ar":"دليل الإعداد ل sred-project-organizer: تنظيم المشاريع لـ ..."},"description":{"en":"Discover how to organize projects for SRED submission with the sred-project-organizer AI agent skill. Learn how to connect Github, Notion, and Linear for sea...","zh":"使用SRED项目组织工具，轻松整理项目文档，提高提交效率，了解更多","ja":"SREDプロジェクトオーガナイザーを使用して、プロジェクトを整理し、提出を簡素化する","ko":"SRED 프로젝트 오ργァ나이저를 사용하여 프로젝트를 구성하고 제출을 간소화하세요","es":"Organice proyectos en formato SRED con este agente de IA. Conéctese a Github, Notion y Linear para una integración sin problemas.","fr":"Organisez vos projets au format SRED avec cet outil d''IA. Connectez-vous à Github, Notion et Linear pour une intégration sans souci.","de":"Organisieren Sie Projekte im SRED-Format mit diesem KI-Tool. Verbinden Sie sich mit Github, Notion und Linear für eine reibungslose Integration.","pt":"Aprenda a configurar o sred-project-organizer para organizar projetos em formato SRED. Leia nosso guia para entender como conectar Github, Notion e Linear.","ru":"Узнайте, как настроить sred-project-organizer для организации проектов в формате SRED. Читайте нашу инструкцию, чтобы понять, как подключить Github, Notion и...","ar":"تعرف على كيفية ضبط sred-project-organizer لتنظيم المشاريع بتنسيق SRED. اقرأ دليلنا لفهم كيفية الاتصال بـ Github و Notion و Linear."},"definition":{"en":"sred-project-organizer is a skill that organizes projects into the SRED format, utilizing Github, Notion, and Linear connections for efficient project submission.","zh":"SRED项目组织工具是一种AI工具，用于整理项目文档，生成SRED格式的文档","ja":"SREDプロジェクトオーガナイザーは、プロジェクト文書を整理し、SRED形式の文書を生成するAIエージェントです","ko":"SRED 프로젝트 오ργァ나이저는 프로젝트 문서를 정리하고 SRED 형식의 문서를 생성하는 AI 도구입니다","es":"El sred-project-organizer es un agente de IA que organiza proyectos en el formato SRED.","fr":"Le sred-project-organizer est un outil d''IA qui organise les projets au format SRED.","de":"Der sred-project-organizer ist ein KI-Tool, das Projekte im SRED-Format organisiert.","pt":"O sred-project-organizer é uma ferramenta que organiza projetos em formato SRED para facilitar a apresentação.","ru":"ИИ Агент sred-project-organizer - это инструмент, который организует проекты в формате SRED для облегчения представления.","ar":"وحدة sred-project-organizer هي أداة تنظم المشاريع بتنسيق SRED لتسهيل العرض."},"features":{"en":["Outputs a Notion document with child documents for each SREDable project","Connects Github, Notion, and Linear using MCP for seamless project formatting","Summarizes projects into the SRED format with supporting evidence","Utilizes Github for project data access","Integrates with Notion for document creation and organization"],"zh":["支持Github、Notion和Linear集成","生成Notion文档和子文档","整理项目文档，提高提交效率","使用MCP连接Github、Notion和Linear","输出SRED格式的文档"],"ja":["Github、Notion、Linearとの連携をサポート","Notion文書と子文書を生成","プロジェクト文書を整理し、提出を簡素化","MCPを使用してGithub、Notion、Linearを接続","SRED形式の文書を出力"],"ko":["Github, Notion, Linear와의 연동을 지원","Notion 문서와 子문서를 생성","프로젝트 문서를 정리하고 제출을 간소화","MCP를 사용하여 Github, Notion, Linear를 연결","SRED 형식의 문서를 출력"],"es":["Integración con Github","Conexión a Notion y Linear mediante MCP","Generación de documentos de Notion para proyectos SRED","Soporte para la presentación de proyectos en formato SRED","Acceso a proyectos del último año","Evidencia de soporte para proyectos SRED"],"fr":["Intégration à Github","Connexion à Notion et Linear via MCP","Génération de documents Notion pour les projets SRED","Prise en charge de la présentation de projets au format SRED","Accès aux projets de l''année précédente","Preuves de soutien pour les projets SRED"],"de":["Integration mit Github","Verbindung zu Notion und Linear über MCP","Erstellung von Notion-Dokumenten für SRED-Projekte","Unterstützung für die Präsentation von Projekten im SRED-Format","Zugriff auf Projekte des letzten Jahres","Beweise für SRED-Projekte"],"pt":["Organização de projetos em formato SRED","Conexão com Github, Notion e Linear","Criação de documento do Notion com projetos SRED","Suporte à MCP para conexão segura","Saída em formato de documento do Notion com subdocumentos para cada projeto SRED"],"ru":["Организация проектов в формате SRED","Подключение к Github, Notion и Linear","Создание документа Notion с проектами SRED","Поддержка MCP для безопасного подключения","Выходные данные в формате документа Notion с поддокументами для каждого проекта SRED"],"ar":["تنظيم المشاريع بتنسيق SRED","الربط مع Github و Notion و Linear","إنشاء مستند Notion بمشاريع SRED","دعم MCP للاتصال الآمن","إخراج البيانات بتنسيق مستند Notion مع مستندات فرعية لكل مشروع SRED"]},"keywords":{"en":["how to use sred-project-organizer","sred-project-organizer setup guide","sred format submission","github notion linear integration","sred-project-organizer alternative","sred project organization best practices"],"zh":["SRED项目组织工具","AI工具","项目文档整理","Notion文档生成","Github集成","Notion集成","Linear集成","MCP连接","SRED格式文档"],"ja":["SREDプロジェクトオーガナイザー","AIエージェント","プロジェクト文書整理","Notion文書生成","Github連携","Notion連携","Linear連携","MCP接続","SRED形式文書"],"ko":["SRED 프로젝트 오ργァ나이저","AI 도구","프로젝트 문서 정리","Notion 문서 생성","Github 연동","Notion 연동","Linear 연동","MCP 연결","SRED 형식 문서"],"es":["agentes de IA para proyectos","herramientas de IA para SRED","organización de proyectos SRED","integración de Github con Notion","conexión de Linear a Notion","formato SRED para proyectos","presentación de proyectos SRED","soporte para proyectos SRED"],"fr":["outils d''IA pour les projets","outils d''IA pour SRED","organisation de projets SRED","intégration de Github avec Notion","connexion de Linear à Notion","format SRED pour les projets","présentation de projets SRED","soutien pour les projets SRED"],"de":["KI-Tools für Projekte","KI-Tools für SRED","Organisation von SRED-Projekten","Integration von Github mit Notion","Verbindung von Linear mit Notion","SRED-Format für Projekte","Präsentation von SRED-Projekten","Unterstützung für SRED-Projekte"],"pt":["sred-project-organizer","organização de projetos SRED","conexão Github Notion Linear","MCP para conexão segura","documento Notion com projetos SRED","ferramenta de organização de projetos","guia de configuração sred-project-organizer","SRED formato de projeto"],"ru":["ИИ Агент sred-project-organizer","организация проектов SRED","подключение Github Notion Linear","MCP для безопасного подключения","документ Notion с проектами SRED","инструмент организации проектов","руководство по настройке sred-project-organizer","SRED формат проекта"],"ar":["وحدة sred-project-organizer","تنظيم المشاريع SRED","الربط مع Github و Notion و Linear","دعم MCP للاتصال الآمن","مستند Notion بمشاريع SRED","أداة تنظيم المشاريع","دليل الإعداد ل sred-project-organizer","تنسيق SRED للمشروع"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Administrative Agents needing advanced project organization and documentation capabilities for SRED submissions.","zh":"非常适合需要高级项目组织和文档记录能力的行政代理人，特别是用于SRED提交的代理人。","ja":"行政エージェントが高度なプロジェクトの組織化と文書化の機能を必要とする場合に最適です。特にSRED提出のためのエージェントに適しています。","ko":"고급 프로젝트 조직 및 문서화 기능이 필요한 행정 에이전트에게 적합합니다. 특히 SRED 제출을 위한 에이전트에게 적합합니다.","es":"Perfecto para Agentes Administrativos que necesitan capacidades avanzadas de organización y documentación de proyectos para presentaciones de SRED.","fr":"Parfait pour les agents administratifs ayant besoin de capacités avancées d''organisation et de documentation de projets pour les soumissions de SRED.","de":"Perfekt für Administrative Agenten, die erweiterte Projektorganisations- und Dokumentationsfunktionen für SRED-Einreichungen benötigen.","pt":"Perfeito para Agentes Administrativos que necessitam de organização de projeto avançada e capacidades de documentação para submissões SRED.","ru":"Идеально подходит для административных агентов, которым необходимы продвинутые возможности организации проектов и документации для подачи заявок SRED.","ar":"مثالي لعمليات الوكلاء الإداريين الذين يحتاجون إلى تنظيم مشروع متقدم وقدرات توثيقية لتقديم طلبات SRED."},"recommendation":{"en":"Empowers agents to organize projects into the SRED format, leveraging Github, Notion, and Linear integrations, and outputting comprehensive Notion documents with child documents for each SREDable project, utilizing MCP connections for seamless data exchange.","zh":"赋予代理人将项目组织成SRED格式的能力，利用Github、Notion和Linear集成，并输出包含每个SRED项目子文档的综合Notion文档，利用MCP连接实现无缝数据交换。","ja":"エージェントがプロジェクトをSRED形式で組織化できるようにし、Github、Notion、Linearの統合を活用し、各SRED可能なプロジェクトのサブドキュメントを含む包括的なNotionドキュメントを出力します。また、MCP接続を使用してシームレスなデータ交換を実現します。","ko":"에이전트가 프로젝트를 SRED 형식으로 조직화 할 수 있도록하며, Github, Notion, Linear의 통합을 활용하여, 각 SRED 가능한 프로젝트의 서브 문서를 포함하는 포괄적인 Notion 문서를 출력하며, MCP 연결을 사용하여 무결점 데이터 교환을 구현합니다.","es":"Habilita a los agentes a organizar proyectos en el formato de SRED, aprovechando las integraciones de Github, Notion y Linear, y generando documentos de Notion completos con documentos secundarios para cada proyecto que puede presentarse en SRED, utilizando conexiones de MCP para un intercambio de datos sin problemas.","fr":"Permet aux agents d''organiser les projets dans le format de SRED, en exploitant les intégrations de Github, Notion et Linear, et en produisant des documents de Notion complets avec des documents enfants pour chaque projet pouvant être présenté en SRED, en utilisant des connexions de MCP pour un échange de données sans problème.","de":"Ermöglicht es Agenten, Projekte im SRED-Format zu organisieren, indem es Github-, Notion- und Linear-Integrationen nutzt und umfassende Notion-Dokumente mit untergeordneten Dokumenten für jedes SRED-fähige Projekt erstellt, wobei MCP-Verbindungen für einen reibungslosen Datenaustausch verwendet werden.","pt":"Habilita os agentes a organizar projetos no formato SRED, utilizando integrações do Github, Notion e Linear, e produzindo documentos do Notion abrangentes com documentos filhos para cada projeto SREDável, utilizando conexões MCP para troca de dados sem interrupções.","ru":"Наделяет агентов возможностью организовывать проекты в формате SRED, используя интеграции Github, Notion и Linear, и выдавая полные документы Notion с дочерними документами для каждого проекта SRED, используя соединения MCP для беспрепятственного обмена данными.","ar":"يمكن الوكلاء من تنظيم المشاريع في تنسيق SRED، باستخدام التكاملات من Github و Notion و Linear، وإنتاج وثائق Notion الشاملة مع وثائق فرعية لكل مشروع قابل للتقديم SRED، باستخدام اتصالات MCP لتبادل البيانات دون انقطاع."},"useCases":{"en":["Organizing project documentation for SRED submissions","Generating Notion documents for project summaries","Connecting Github, Notion, and Linear for streamlined project management"],"zh":["为SRED提交组织项目文档","为项目摘要生成Notion文档","连接Github、Notion和Linear实现流畅的项目管理"],"ja":["SRED提出用のプロジェクト文書化の組織化","プロジェクト概要のNotion文書の生成","Github、Notion、Linearの接続によるスムーズなプロジェクト管理"],"ko":["SRED 제출을 위한 프로젝트 문서화의 조직화","프로젝트 요약의 Notion 문서 생성","Github, Notion, Linear의 연결을 통한 원활한 프로젝트 관리"],"es":["Organizar la documentación de proyectos para presentaciones de SRED","Generar documentos de Notion para resúmenes de proyectos","Conectar Github, Notion y Linear para una gestión de proyectos optimizada"],"fr":["Organiser la documentation de projets pour les soumissions de SRED","Générer des documents de Notion pour les résumés de projets","Connecter Github, Notion et Linear pour une gestion de projets rationalisée"],"de":["Organisieren der Projektdokumentation für SRED-Einreichungen","Erstellen von Notion-Dokumenten für Projektzusammenfassungen","Verbinden von Github, Notion und Linear für eine optimierte Projektverwaltung"],"pt":["Organizar documentação de projeto para submissões SRED","Gerar documentos do Notion para resumos de projeto","Conectar Github, Notion e Linear para gestão de projeto otimizada"],"ru":["Организация документации проекта для подачи заявок SRED","Генерация документов Notion для сводок проекта","Подключение Github, Notion и Linear для оптимизированного управления проектом"],"ar":["تنظيم توثيق المشروع لتقديم طلبات SRED","генерация وثائق Notion لملخصات المشروع","اتصال Github و Notion و Linear لإدارة المشروع المُثلى"]},"limitations":{"en":["Requires access to Github, Notion, and Linear","Needs MCP connections for Notion and Linear","Dependent on specific SRED format requirements"],"zh":["需要访问Github、Notion和Linear","需要MCP连接以使用Notion和Linear","依赖于特定的SRED格式要求"],"ja":["Github、Notion、Linearへのアクセスが必要","NotionとLinearを使用するためにMCP接続が必要","特定のSRED形式の要件に依存する"],"ko":["Github, Notion, Linear에 대한 액세스가 필요합니다","Notion 및 Linear를 사용하기 위해 MCP 연결이 필요합니다","특정 SRED 형식 요구 사항에 의존합니다"],"es":["Requiere acceso a Github, Notion y Linear","Necesita conexiones de MCP para Notion y Linear","Dependiente de los requisitos específicos del formato de SRED"],"fr":["Nécessite un accès à Github, Notion et Linear","A besoin de connexions de MCP pour Notion et Linear","Dépend des exigences spécifiques du format de SRED"],"de":["Erfordert Zugriff auf Github, Notion und Linear","Benötigt MCP-Verbindungen für Notion und Linear","Abhängig von den spezifischen Anforderungen des SRED-Formats"],"pt":["Requer acesso ao Github, Notion e Linear","Necessita de conexões MCP para Notion e Linear","Dependente de requisitos de formato SRED específicos"],"ru":["Требует доступа к Github, Notion и Linear","Требует соединений MCP для Notion и Linear","Зависит от конкретных требований формата SRED"],"ar":["يتطلب الوصول إلى Github و Notion و Linear","يحتاج إلى اتصالات MCP ل Notion و Linear","يعتمد على متطلبات تنسيق SRED المحددة"]},"version":4},"contentHash":"8e6b88ed4d0f41ed8906844e9ef3ab40a2a84bdfdf36ad0794e6906d3433e05e","repoEtag":"W/\"36a09bba6a611068f31a3df860388e78cbe9407beaecc6e6da77ba4b47f9eb59\"","qualityScore":86}');
