INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/sred-project-organizer', 'sred-project-organizer', 'getsentry', 'skills', 'official', 'sred-project-organizer getsentry skills official tag-production The sred-project-organizer skill takes a list of projects and their related documentation, and organizes them into the SRED format for submission, benefiting developers and project managers. It outputs a Notion document with child documents for each SREDable project. SRED项目组织工具帮助您整理项目文档，生成Notion文档，并支持Github、Notion和Linear集成 SREDプロジェクトオーガナイザーは、プロジェクト文書を整理し、Notion文書を生成し、Github、Notion、Linearとの連携をサポートします SRED 프로젝트 오ργァ나이저는 프로젝트 문서를 정리하고 Notion 문서를 생성하며 Github, Notion, Linear와의 연동을 지원합니다 El sred-project-organizer es un agente de IA que organiza proyectos en el formato SRED para su presentación. Se integra con Github, Notion y Linear. Le sred-project-organizer est un outil d''IA qui organise les projets au format SRED pour la présentation. Il s''intègre à Github, Notion et Linear. Der sred-project-organizer ist ein KI-Tool, das Projekte im SRED-Format für die Präsentation organisiert. Es integriert sich mit Github, Notion und Linear. O sred-project-organizer é uma ferramenta que organiza projetos em formato SRED. Conecte Github, Notion e Linear para criar um documento do Notion com projetos SRED. ИИ Агент sred-project-organizer - это инструмент, который организует проекты в формате SRED. Подключите Github, Notion и Linear, чтобы создать документ Notion с проектами SRED. وحدة sred-project-organizer هي أداة تنظم المشاريع بتنسيق SRED. اتبع الإرشادات لربط Github و Notion و Linear وإنشاء مستند Notion بمشاريع SRED. how to use sred-project-organizer sred-project-organizer setup guide sred format submission github notion linear integration sred-project-organizer alternative sred project organization best practices SRED项目组织工具 AI工具 项目文档整理 Notion文档生成 Github集成 Notion集成 Linear集成 MCP连接 SRED格式文档 Outputs a Notion document with child documents for each SREDable project Connects Github, Notion, and Linear using MCP for seamless project formatting Summarizes projects into the SRED format with supporting evidence Utilizes Github for project data access Integrates with Notion for document creation and organization sred-project-organizer is a skill that organizes projects into the SRED format, utilizing Github, Notion, and Linear connections for efficient project submission.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('expo/skills/expo-ui-jetpack-compose', 'official', 'expo', 'skills', 'expo/skills', 'Expo UI Jetpack Compose', 1349, 59, 86, '2026-03-06T04:04:30Z', '2026-03-06T05:24:41.513Z', '8bdda5de6c6f7b4c61f611400bae8f113d5613698cfaf7313dd57906c4d66856', '{"id":"expo/skills/expo-ui-jetpack-compose","name":"Expo UI Jetpack Compose","description":{"en":"Expo UI Jetpack Compose allows developers to use Jetpack Compose Views and modifiers in their apps, mirroring Jetpack Compose''s API. It supports native rebuilds and Material Design 3 knowledge.","es":"Expo UI Jetpack Compose permite a los desarrolladores utilizar vistas y modificadores de Jetpack Compose en sus aplicaciones. Aprende a configurarlo","fr":"Expo UI Jetpack Compose permet aux développeurs d''utiliser des vues et des modificateurs de Jetpack Compose dans leurs applications. Découvrez comment l''installer","de":"Expo UI Jetpack Compose ermöglicht es Entwicklern, Jetpack-Compose-Ansichten und -Modifikatoren in ihren Anwendungen zu verwenden. Erfahren Sie, wie Sie es einrichten","pt":"O @expo/ui/jetpack-compose permite usar vistas e modificadores do Jetpack Compose em seu aplicativo.","ru":"Пакет @expo/ui/jetpack-compose позволяет использовать представления и модификаторы Jetpack Compose в вашем приложении.","ar":"الوصفة @expo/ui/jetpack-compose تسمح باستخدام العروض والمعديلات من Jetpack Compose في تطبيقك."},"owner":"expo","repo":"skills","repoPath":"expo/skills","stars":1349,"forks":59,"updatedAt":"2026-03-06T04:04:30Z","topics":[],"skillMd":{"name":"Expo UI Jetpack Compose","description":"`@expo/ui/jetpack-compose` package lets you use Jetpack Compose Views and modifiers in your app.","bodyPreview":"> The instructions in this skill apply to SDK 55 only. For other SDK versions, refer to the Expo UI Jetpack Compose docs for that version for the most accurate information.\n\n## Installation\n\n```bash\nnpx expo install @expo/ui\n```\n\nA native rebuild is required after installation (`npx expo run:android`).\n\n## Instructions\n\n- Expo UI''s API mirrors Jetpack Compose''s API. Use Jetpack Compose and Material Design 3 knowledge to decide which components or modifiers to use.\n- Components are imported from","body":"> The instructions in this skill apply to SDK 55 only. For other SDK versions, refer to the Expo UI Jetpack Compose docs for that version for the most accurate information.\n\n## Installation\n\n```bash\nnpx expo install @expo/ui\n```\n\nA native rebuild is required after installation (`npx expo run:android`).\n\n## Instructions\n\n- Expo UI''s API mirrors Jetpack Compose''s API. Use Jetpack Compose and Material Design 3 knowledge to decide which components or modifiers to use.\n- Components are imported from `@expo/ui/jetpack-compose`, modifiers from `@expo/ui/jetpack-compose/modifiers`.\n- When about to use a component, fetch its docs to confirm the API - https://docs.expo.dev/versions/v55.0.0/sdk/ui/jetpack-compose/{component-name}/index.md\n- When unsure about a modifier''s API, refer to the docs - https://docs.expo.dev/versions/v55.0.0/sdk/ui/jetpack-compose/modifiers/index.md\n- Every Jetpack Compose tree must be wrapped in `Host`. Use `<Host matchContents>` for intrinsic sizing, or `<Host style={{ flex: 1 }}>` when you need explicit size (e.g. as a parent of `LazyColumn`). Example:\n\n```jsx\nimport { Host, Column, Button, Text } from \"@expo/ui/jetpack-compose\";\nimport { fillMaxWidth, paddingAll } from \"@expo/ui/jetpack-compose/modifiers\";\n\n<Host matchContents>\n  <Column verticalArrangement={{ spacedBy: 8 }} modifiers={[fillMaxWidth(), paddingAll(16)]}>\n    <Text style={{ typography: \"titleLarge\" }}>Hello</Text>\n    <Button onPress={() => alert(\"Pressed!\")}>Press me</Button>\n  </Column>\n</Host>;\n```\n\n## Key Components\n\n- **LazyColumn** — Use instead of react-native `ScrollView`/`FlatList` for scrollable lists. Wrap in `<Host style={{ flex: 1 }}>`.\n- **Icon** — Use `<Icon source={require(''./icon.xml'')} size={24} />` with Android XML vector drawables from [Material Symbols](https://fonts.google.com/icons).\n"},"category":"official","lastSynced":"2026-03-06T05:24:41.513Z","seo":{"title":{"en":"Expo UI Jetpack Compose: Setup Guide for AI Agents","es":"Guía de Configuración de Expo UI Jetpack Compose para Des...","fr":"Guide d''Installation d''Expo UI Jetpack Compose pour les D...","de":"Einrichtungsleitfaden für Expo UI Jetpack Compose-Entwickler","pt":"Guia de Configuração do Expo UI Jetpack Compose","ru":"Настройка Expo UI Jetpack Compose: Руководство","ar":"إعداد Expo UI Jetpack Compose: دليل المستخدم"},"description":{"en":"Discover how to install and use Expo UI Jetpack Compose with SDK 55. Get started with the official docs and example code today!","es":"Aprende a utilizar @expo/ui/jetpack-compose en tus aplicaciones móviles con nuestra guía paso a paso para desarrolladores","fr":"Découvrez comment utiliser @expo/ui/jetpack-compose dans vos applications mobiles avec notre guide étape par étape pour les développeurs","de":"Erfahren Sie, wie Sie @expo/ui/jetpack-compose in Ihren mobilen Anwendungen verwenden, mit unserer Schritt-für-Schritt-Anleitung für Entwickler","pt":"Aprenda a instalar e usar o @expo/ui/jetpack-compose para criar interfaces de usuário personalizadas com Jetpack Compose","ru":"Узнайте, как установить и использовать @expo/ui/jetpack-compose для создания пользовательских интерфейсов с помощью Jetpack Compose","ar":"تعرف على كيفية تثبيت واستخدام @expo/ui/jetpack-compose لإنشاء واجهات مستخدم مخصصة باستخدام Jetpack Compose"},"definition":{"en":"Expo UI Jetpack Compose is a package that enables the use of Jetpack Compose Views and modifiers in Expo apps, compatible with SDK 55.","es":"Expo UI Jetpack Compose es un paquete que permite la integración de Jetpack Compose en aplicaciones Expo","fr":"Expo UI Jetpack Compose est un package qui permet l''intégration de Jetpack Compose dans les applications Expo","de":"Expo UI Jetpack Compose ist ein Paket, das die Integration von Jetpack Compose in Expo-Anwendungen ermöglicht","pt":"O que é Expo UI Jetpack Compose? Um pacote que permite usar Jetpack Compose em aplicativos Expo.","ru":"Что такое Expo UI Jetpack Compose? Пакет, позволяющий использовать Jetpack Compose в приложениях Expo.","ar":"ما هو Expo UI Jetpack Compose؟ حزمة تسمح باستخدام Jetpack Compose في تطبيقات Expo."},"features":{"en":["Installs via `npx expo install @expo/ui` command","Requires native rebuild using `npx expo run:android`","Mirrors Jetpack Compose''s API for seamless integration","Supports Material Design 3 knowledge for component selection","Compatible with SDK 55 for optimal performance"],"es":["Utiliza vistas y modificadores de Jetpack Compose","Compatibilidad con SDK 55","Requiere una reconstrucción nativa después de la instalación","Utiliza la API de Jetpack Compose y Material Design 3","Importa componentes de @expo/ui"],"fr":["Utilisez des vues et des modificateurs de Jetpack Compose","Compatibilité avec le SDK 55","Requiert une reconstruction native après l''installation","Utilisez l''API de Jetpack Compose et Material Design 3","Importez des composants de @expo/ui"],"de":["Verwenden Sie Jetpack-Compose-Ansichten und -Modifikatoren","Kompatibilität mit SDK 55","Erfordert eine native Neuerstellung nach der Installation","Verwenden Sie die Jetpack-Compose-API und Material Design 3","Importieren Sie Komponenten von @expo/ui"],"pt":["Uso de vistas e modificadores do Jetpack Compose","Compatibilidade com SDK 55","Reconstrução nativa após instalação","Importação de componentes do Material Design 3","Uso da API do Jetpack Compose"],"ru":["Использование представлений и модификаторов Jetpack Compose","Совместимость с SDK 55","Пересборка родных модулей после установки","Импорт компонентов Material Design 3","Использование API Jetpack Compose"],"ar":["استخدام العروض والمعديلات من Jetpack Compose","التوافق مع SDK 55","إعادة البناء الأصلية بعد التثبيت","استيراد مكونات Material Design 3","استخدام واجهة برمجة تطبيقات Jetpack Compose"]},"keywords":{"en":["Expo UI Jetpack Compose install","how to use Expo UI Jetpack Compose","Expo UI Jetpack Compose setup guide","Expo UI Jetpack Compose vs React Native","what is Expo UI Jetpack Compose","Expo UI Jetpack Compose alternative","Jetpack Compose Views in Expo","Material Design 3 in Expo UI Jetpack Compose","SDK 55 Expo UI Jetpack Compose"],"es":["Expo UI Jetpack Compose","Jetpack Compose en Expo","Instalación de @expo/ui","SDK 55","Material Design 3","Desarrollo de aplicaciones móviles","Herramientas de desarrollo de Expo","Integración de Jetpack Compose"],"fr":["Expo UI Jetpack Compose","Jetpack Compose dans Expo","Installation de @expo/ui","SDK 55","Material Design 3","Développement d''applications mobiles","Outils de développement Expo","Intégration de Jetpack Compose"],"de":["Expo UI Jetpack Compose","Jetpack Compose in Expo","Installation von @expo/ui","SDK 55","Material Design 3","Entwicklung von mobilen Anwendungen","Expo-Entwicklungstools","Integration von Jetpack Compose"],"pt":["Expo UI Jetpack Compose","Jetpack Compose","Material Design 3","SDK 55","Reconstrução nativa","Instalação do @expo/ui","Guia de configuração","Desenvolvimento de aplicativos móveis","ИИ Агенты"],"ru":["Expo UI Jetpack Compose","Jetpack Compose","Material Design 3","SDK 55","Пересборка родных модулей","Установка @expo/ui","Руководство по настройке","Разработка мобильных приложений","ИИ Агенты"],"ar":["Expo UI Jetpack Compose","Jetpack Compose","Material Design 3","SDK 55","إعادة البناء الأصلية","تثبيت @expo/ui","دليل الإعداد","تطوير تطبيقات الجوال","أدوات الذكاء الاصطناعي"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Android Development Agents needing native Jetpack Compose UI integration within Expo projects.","zh":"非常适合需要在 Expo 项目中原生集成 Jetpack Compose UI 的 Android 开发代理。","ja":"Expo プロジェクト内で Jetpack Compose UI をネイティブに統合する必要がある Android 開発エージェントに最適です。","ko":"Expo 프로젝트에서 Jetpack Compose UI를 네이티브로 통합해야 하는 Android 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo de Android que necesitan integración de interfaz de usuario nativa Jetpack Compose dentro de proyectos Expo.","fr":"Parfait pour les agents de développement Android qui ont besoin d''une intégration native de l''interface utilisateur Jetpack Compose dans les projets Expo.","de":"Perfekt für Android-Entwicklungsagenten, die eine native Jetpack-Compose-Benutzeroberflächenintegration in Expo-Projekten benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Android que necessitam de integração de interface do usuário nativa Jetpack Compose dentro de projetos Expo.","ru":"Идеально для агентов разработки Android, которым необходима родная интеграция Jetpack Compose UI в проектах Expo.","ar":"مثالي للوكلاء الذين يحتاجون إلى دمج واجهة مستخدم أندرويد الأصلية مع جت باك كومبوز في مشاريع إكسبو."},"recommendation":{"en":"Enables agents to implement native Android UI components using Jetpack Compose API within Expo applications, providing access to Material Design 3 components and modifiers. Requires a native rebuild via `npx expo run:android` after installation for proper integration.","zh":"允许代理在 Expo 应用程序中使用 Jetpack Compose API 实现原生 Android UI 组件，提供对 Material Design 3 组件和修饰符的访问。安装后，需要通过 `npx expo run:android` 进行原生重建以实现正确的集成。","ja":"エージェントが Expo アプリケーション内で Jetpack Compose API を使用してネイティブの Android UI コンポーネントを実装できるようにし、Material Design 3 コンポーネントと修飾子へのアクセスを提供します。インストール後、正しい統合のために `npx expo run:android` を使用してネイティブのリビルドが必要です。","ko":"에이전트가 Expo 애플리케이션 내에서 Jetpack Compose API를 사용하여 네이티브 Android UI 컴포넌트를 구현할 수 있도록 하며 Material Design 3 컴포넌트 및 修飾子에 대한 액세스를 제공합니다. 설치 후 올바른 통합을 위해 `npx expo run:android`를 사용하여 네이티브 재구성을 수행해야 합니다.","es":"Permite a los agentes implementar componentes de interfaz de usuario de Android nativos utilizando la API Jetpack Compose dentro de aplicaciones Expo, proporcionando acceso a componentes y modificadores de Material Design 3. Requiere una reconstrucción nativa a través de `npx expo run:android` después de la instalación para una integración adecuada.","fr":"Permet aux agents d''implémenter des composants d''interface utilisateur Android natifs en utilisant l''API Jetpack Compose au sein d''applications Expo, en fournissant un accès aux composants et modificateurs de Material Design 3. Nécessite une reconstruction native via `npx expo run:android` après l''installation pour une intégration appropriée.","de":"Ermöglicht es Agenten, native Android-Benutzeroberflächenkomponenten unter Verwendung der Jetpack-Compose-API innerhalb von Expo-Anwendungen zu implementieren, und bietet Zugriff auf Material-Design-3-Komponenten und -Modifikatoren. Erfordert einen natürlichen Neuaufbau über `npx expo run:android` nach der Installation für eine ordnungsgemäße Integration.","pt":"Permite que os agentes implementem componentes de interface do usuário do Android nativos usando a API Jetpack Compose dentro de aplicativos Expo, fornecendo acesso a componentes e modificadores do Material Design 3. Requer uma reconstrução nativa via `npx expo run:android` após a instalação para integração adequada.","ru":"Позволяет агентам реализовывать родные компоненты интерфейса пользователя Android, используя API Jetpack Compose внутри приложений Expo, обеспечивая доступ к компонентам и модификаторам Material Design 3. Требует родной перестройки через `npx expo run:android` после установки для правильной интеграции.","ar":"يمكن للوكلاء تنفيذ مكونات واجهة المستخدم الأصلية للأندرويد باستخدام واجهة برمجة تطبيقات جت باك كومبوز داخل تطبيقات إكسبو، مع إتاحة الوصول إلى مكونات وmodifiers من التصميم المادي 3. يتطلب إعادة بناء الأصل عبر `npx expo run:android` بعد التثبيت من أجل التكامل الصحيح."},"useCases":{"en":["Implementing native Android UI components in Expo apps","Applying Material Design 3 compliant modifiers","Bridging Expo SDK 55 projects with Jetpack Compose views"],"zh":["在 Expo 应用程序中实现原生 Android UI 组件","应用符合 Material Design 3 的修饰符","将 Expo SDK 55 项目与 Jetpack Compose 视图连接起来"],"ja":["Expo アプリケーション内でネイティブの Android UI コンポーネントを実装する","Material Design 3 に準拠した修飾子を適用する","Expo SDK 55 プロジェクトを Jetpack Compose ビューとブリッジする"],"ko":["Expo 애플리케이션에서 네이티브 Android UI 컴포넌트를 구현하는 것","Material Design 3 규격의 修飾子를 적용하는 것","Expo SDK 55 프로젝트를 Jetpack Compose 뷰와 연결하는 것"],"es":["Implementar componentes de interfaz de usuario de Android nativos en aplicaciones Expo","Aplicar modificadores compatibles con Material Design 3","Conectar proyectos de Expo SDK 55 con vistas de Jetpack Compose"],"fr":["Implémenter des composants d''interface utilisateur Android natifs dans des applications Expo","Appliquer des modificateurs conformes à Material Design 3","Relier des projets de SDK Expo 55 avec des vues de Jetpack Compose"],"de":["Implementieren von nativen Android-Benutzeroberflächenkomponenten in Expo-Apps","Anwenden von Material-Design-3-konformen Modifikatoren","Verbinden von Expo-SDK-55-Projekten mit Jetpack-Compose-Ansichten"],"pt":["Implementar componentes de interface do usuário do Android nativos em aplicativos Expo","Aplicar modificadores compatíveis com o Material Design 3","Conectar projetos do SDK 55 do Expo com vistas do Jetpack Compose"],"ru":["Реализация родных компонентов интерфейса пользователя Android в приложениях Expo","Применение модификаторов, соответствующих Material Design 3","Объединение проектов SDK 55 Expo с видами Jetpack Compose"],"ar":["تنفيذ مكونات واجهة المستخدم الأصلية للأندرويد في تطبيقات إكسبو","تطبيق modificadores متوافقة مع تصميم المواد 3","ربط مشاريع SDK 55 من إكسبو مع مشاهد جت باك كومبوز"]},"limitations":{"en":["SDK 55 specific implementation only","Requires native rebuild after installation","Limited to Android platform development"],"zh":["仅限 SDK 55 的实现","安装后需要进行原生重建","仅限于 Android 平台开发"],"ja":["SDK 55 専用実装のみ","インストール後にはネイティブのリビルドが必要","Android プラットフォームの開発のみ"],"ko":["SDK 55 전용 구현만","설치 후 네이티브 재구성이 필요함","Android 플랫폼 개발만"],"es":["Implementación específica de SDK 55 solo","Requiere una reconstrucción nativa después de la instalación","Limitado al desarrollo de la plataforma Android"],"fr":["Implémentation spécifique de SDK 55 uniquement","Nécessite une reconstruction native après l''installation","Limité au développement de la plateforme Android"],"de":["Implementierung speziell für SDK 55","Erfordert einen natürlichen Neuaufbau nach der Installation","Begrenzt auf die Entwicklung der Android-Plattform"],"pt":["Implementação específica do SDK 55 apenas","Requer reconstrução nativa após instalação","Limitado ao desenvolvimento de plataforma Android"],"ru":["Реализация только для SDK 55","Требует родной перестройки после установки","Ограничен разработкой платформы Android"],"ar":["تنفيذ SDK 55 فقط","يتطلب إعادة بناء الأصل بعد التثبيت","محدود بتطوير منصة الأندرويد"]},"version":4},"contentHash":"8bdda5de6c6f7b4c61f611400bae8f113d5613698cfaf7313dd57906c4d66856","repoEtag":"W/\"3d0b500324a01c512d7df52a068a135b350d8e49d3ce113161c97e6acbc0dfba\"","qualityScore":86}');
