INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('expo/skills/expo-ui-jetpack-compose', 'Expo UI Jetpack Compose', 'expo', 'skills', 'official', 'Expo UI Jetpack Compose expo skills official Expo UI Jetpack Compose allows developers to use Jetpack Compose Views and modifiers in their apps, mirroring Jetpack Compose''s API. It supports native rebuilds and Material Design 3 knowledge. Expo UI Jetpack Compose permite a los desarrolladores utilizar vistas y modificadores de Jetpack Compose en sus aplicaciones. Aprende a configurarlo Expo UI Jetpack Compose permet aux développeurs d''utiliser des vues et des modificateurs de Jetpack Compose dans leurs applications. Découvrez comment l''installer Expo UI Jetpack Compose ermöglicht es Entwicklern, Jetpack-Compose-Ansichten und -Modifikatoren in ihren Anwendungen zu verwenden. Erfahren Sie, wie Sie es einrichten O @expo/ui/jetpack-compose permite usar vistas e modificadores do Jetpack Compose em seu aplicativo. Пакет @expo/ui/jetpack-compose позволяет использовать представления и модификаторы Jetpack Compose в вашем приложении. الوصفة @expo/ui/jetpack-compose تسمح باستخدام العروض والمعديلات من Jetpack Compose في تطبيقك. Expo UI Jetpack Compose install how to use Expo UI Jetpack Compose Expo UI Jetpack Compose setup guide Expo UI Jetpack Compose vs React Native what is Expo UI Jetpack Compose Expo UI Jetpack Compose alternative Jetpack Compose Views in Expo Material Design 3 in Expo UI Jetpack Compose SDK 55 Expo UI Jetpack Compose Installs via `npx expo install @expo/ui` command Requires native rebuild using `npx expo run:android` Mirrors Jetpack Compose''s API for seamless integration Supports Material Design 3 knowledge for component selection Compatible with SDK 55 for optimal performance Expo UI Jetpack Compose is a package that enables the use of Jetpack Compose Views and modifiers in Expo apps, compatible with SDK 55.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('expo/skills/expo-ui-swift-ui', 'official', 'expo', 'skills', 'expo/skills', 'Expo UI SwiftUI', 1349, 59, 86, '2026-03-06T04:04:30Z', '2026-03-06T05:25:41.344Z', '1eba564b9a28d1c1e391a6aa8245c37c7db6ec2df2ac4886179f47fcc1fdff5e', '{"id":"expo/skills/expo-ui-swift-ui","name":"Expo UI SwiftUI","description":{"en":"Expo UI SwiftUI allows developers to use SwiftUI Views and modifiers in their apps, leveraging the @expo/ui/swift-ui package for seamless integration.","zh":"Expo UI SwiftUI允许您在应用中使用SwiftUI视图和修饰符。通过@expo/ui/swift-ui包，实现原生重建和SDK55支持","ja":"Expo UI SwiftUIは、アプリでSwiftUIビューと修飾子を使用できるようにします。@expo/ui/swift-uiパッケージを使用して、ネイティブリビルドとSDK55サポートを実現します","ko":"Expo UI SwiftUI는 앱에서 SwiftUI 뷰와 수정자를 사용할 수 있게 해줍니다. @expo/ui/swift-ui 패키지를 사용하여 네이티브 리빌드와 SDK55 지원을 구현합니다","es":"Expo UI SwiftUI permite a los desarrolladores utilizar vistas y modificadores SwiftUI en sus aplicaciones móviles. Instale @expo/ui/swift-ui y comience a crear","fr":"Expo UI SwiftUI permet aux développeurs d''utiliser des vues et des modificateurs SwiftUI dans leurs applications mobiles. Installez @expo/ui/swift-ui et commencez à créer","de":"Expo UI SwiftUI ermöglicht es Entwicklern, SwiftUI-Ansichten und -Modifikatoren in ihren mobilen Anwendungen zu verwenden. Installieren Sie @expo/ui/swift-ui und beginnen Sie mit der Erstellung","pt":"O pacote @expo/ui/swift-ui permite usar views e modificadores do SwiftUI no Expo","ru":"Пакет @expo/ui/swift-ui позволяет использовать представления и модификаторы SwiftUI в Expo","ar":" يسمح لك حزمة @expo/ui/swift-ui باستخدام العروض والمعدلات من SwiftUI في Expo"},"owner":"expo","repo":"skills","repoPath":"expo/skills","stars":1349,"forks":59,"updatedAt":"2026-03-06T04:04:30Z","topics":[],"skillMd":{"name":"Expo UI SwiftUI","description":"`@expo/ui/swift-ui` package lets you use SwiftUI Views and modifiers in your app.","bodyPreview":"> The instructions in this skill apply to SDK 55 only. For other SDK versions, refer to the Expo UI SwiftUI docs for that version for the most accurate information.\n\n## Installation\n\n```bash\nnpx expo install @expo/ui\n```\n\nA native rebuild is required after installation (`npx expo run:ios`).\n\n## Instructions\n\n- Expo UI''s API mirrors SwiftUI''s API. Use SwiftUI knowledge to decide which components or modifiers to use.\n- Components are imported from `@expo/ui/swift-ui`, modifiers from `@expo/ui/swif","body":"> The instructions in this skill apply to SDK 55 only. For other SDK versions, refer to the Expo UI SwiftUI docs for that version for the most accurate information.\n\n## Installation\n\n```bash\nnpx expo install @expo/ui\n```\n\nA native rebuild is required after installation (`npx expo run:ios`).\n\n## Instructions\n\n- Expo UI''s API mirrors SwiftUI''s API. Use SwiftUI knowledge to decide which components or modifiers to use.\n- Components are imported from `@expo/ui/swift-ui`, modifiers from `@expo/ui/swift-ui/modifiers`.\n- When about to use a component, fetch its docs to confirm the API - https://docs.expo.dev/versions/v55.0.0/sdk/ui/swift-ui/{component-name}/index.md\n- When unsure about a modifier''s API, refer to the docs - https://docs.expo.dev/versions/v55.0.0/sdk/ui/swift-ui/modifiers/index.md\n- Every SwiftUI tree must be wrapped in `Host`.\n- `RNHostView` is specifically for embedding RN components inside a SwiftUI tree. Example:\n\n```jsx\nimport { Host, VStack, RNHostView } from \"@expo-ui/swift-ui\";\nimport { Pressable } from \"react-native\";\n\n<Host matchContents>\n  <VStack>\n    <RNHostView matchContents>\n      // Here, `Pressable` is an RN component so it is wrapped in `RNHostView`.\n      <Pressable />\n    </RNHostView>\n  </VStack>\n</Host>;\n```\n\n- If a required modifier or View is missing in Expo UI, it can be extended via a local Expo module. See: https://docs.expo.dev/guides/expo-ui-swift-ui/extending/index.md. Confirm with the user before extending.\n"},"category":"official","lastSynced":"2026-03-06T05:25:41.344Z","seo":{"title":{"en":"Expo UI SwiftUI: Setup Guide for AI Agents","zh":"Expo UI SwiftUI 安装指南","ja":"Expo UI SwiftUI セットアップガイド - AIエージェント","ko":"Expo UI SwiftUI 설정 가이드 - AI 도구","es":"Guía de configuración de Expo UI SwiftUI para desarrollad...","fr":"Guide de mise en place d''Expo UI SwiftUI pour les dévelop...","de":"Einrichtungsleitfaden für Expo UI SwiftUI-Entwickler","pt":"Guia de Configuração do Expo UI SwiftUI","ru":"Настройка Expo UI SwiftUI: Руководство","ar":"دليل إعداد Expo UI SwiftUI"},"description":{"en":"Get started with Expo UI SwiftUI by installing @expo/ui and learn how to use SwiftUI Views and modifiers in your app with our expert guide","zh":"了解如何使用 @expo/ui/swift-ui 包在您的应用中使用 SwiftUI 视图和修饰符","ja":"Expo UI SwiftUI を使用して、SwiftUI ビューと修飾子をアプリに追加する方法を学びましょう - AIエージェント","ko":"Expo UI SwiftUI를 사용하여 SwiftUI 뷰와 수정자를 앱에 추가하는 방법을 알아보세요 - AI 도구","es":"Aprende a utilizar @expo/ui/swift-ui para crear vistas y modificadores SwiftUI en tu app móvil con nuestra guía paso a paso","fr":"Découvrez comment utiliser @expo/ui/swift-ui pour créer des vues et des modificateurs SwiftUI dans votre application mobile avec notre guide étape par étape","de":"Erfahren Sie, wie Sie @expo/ui/swift-ui verwenden, um SwiftUI-Ansichten und -Modifikatoren in Ihrer mobilen App zu erstellen, mit unserem Schritt-für-Schritt...","pt":"Aprenda a usar o pacote @expo/ui/swift-ui para criar interfaces de usuário com SwiftUI no Expo","ru":"Используйте пакет @expo/ui/swift-ui для создания интерфейсов пользователя с помощью SwiftUI в Expo","ar":"استخدم حزمة @expo/ui/swift-ui لإنشاء واجهات مستخدم مع SwiftUI في Expo"},"definition":{"en":"Expo UI SwiftUI is a package that enables the use of SwiftUI Views and modifiers in Expo applications, mirroring SwiftUI''s API for native app development","zh":"Expo UI SwiftUI是一个允许在应用中使用SwiftUI视图和修饰符的包","ja":"Expo UI SwiftUIは、アプリでSwiftUIビューと修飾子を使用できるようにするパッケージです","ko":"Expo UI SwiftUI는 앱에서 SwiftUI 뷰와 수정자를 사용할 수 있게 해주는 패키지입니다","es":"Expo UI SwiftUI es un paquete que permite a los desarrolladores utilizar vistas y modificadores SwiftUI en sus aplicaciones móviles","fr":"Expo UI SwiftUI est un paquet qui permet aux développeurs d''utiliser des vues et des modificateurs SwiftUI dans leurs applications mobiles","de":"Expo UI SwiftUI ist ein Paket, das es Entwicklern ermöglicht, SwiftUI-Ansichten und -Modifikatoren in ihren mobilen Anwendungen zu verwenden","pt":"O que é Expo UI SwiftUI? É um pacote que permite usar SwiftUI no Expo","ru":"Что такое Expo UI SwiftUI? Это пакет, позволяющий использовать SwiftUI в Expo","ar":"ما هو Expo UI SwiftUI؟ هو حزمة تسمح باستخدام SwiftUI في Expo"},"features":{"en":["Installs via npx expo install @expo/ui command","Requires native rebuild using npx expo run:ios","Mirrors SwiftUI''s API for component and modifier usage","Imports components from @expo/ui/swift-ui","Supports modifiers from @expo/ui/swift-ui","Compatible with SDK 55"],"zh":["使用@expo/ui/swift-ui包","支持SDK55","原生重建","SwiftUI视图和修饰符","Expo UI API与SwiftUI API镜像"],"ja":["@expo/ui/swift-uiパッケージを使用","SDK55サポート","ネイティブリビルド","SwiftUIビューと修飾子","Expo UI APIとSwiftUI APIのミラー"],"ko":["@expo/ui/swift-ui 패키지를 사용","SDK55 지원","네이티브 리빌드","SwiftUI 뷰와 수정자","Expo UI API와 SwiftUI API의 미러"],"es":["Utiliza vistas y modificadores SwiftUI en tus aplicaciones móviles","Instalación sencilla con @expo/ui/swift-ui","Requiere una reconstrucción nativa después de la instalación","API que refleja la API de SwiftUI","Componentes importados desde @expo/ui/swift-ui","Modificadores importados desde @expo/ui/swift-ui"],"fr":["Utilisez des vues et des modificateurs SwiftUI dans vos applications mobiles","Installation simple avec @expo/ui/swift-ui","Requiert une reconstruction native après l''installation","API qui reflète l''API de SwiftUI","Composants importés depuis @expo/ui/swift-ui","Modificateurs importés depuis @expo/ui/swift-ui"],"de":["Verwenden Sie SwiftUI-Ansichten und -Modifikatoren in Ihren mobilen Anwendungen","Einfache Installation mit @expo/ui/swift-ui","Erfordert eine native Neuerstellung nach der Installation","API, die die SwiftUI-API widerspiegelt","Komponenten importiert von @expo/ui/swift-ui","Modifikatoren importiert von @expo/ui/swift-ui"],"pt":["Uso de views e modificadores do SwiftUI","Instalação via npx expo install @expo/ui","Reconstrução nativa necessária após instalação","API que espelha a API do SwiftUI","Importação de componentes de @expo/ui/swift-ui"],"ru":["Использование представлений и модификаторов SwiftUI","Установка через npx expo install @expo/ui","Требуется перестройка родных модулей после установки","API, отражающая API SwiftUI","Импорт компонентов из @expo/ui/swift-ui"],"ar":["استخدام العروض والمعدلات من SwiftUI","التثبيت عبر npx expo install @expo/ui","إعادة البناء الأصلية مطلوبة بعد التثبيت","واجهة برمجة تطبيقات تكرار واجهة برمجة تطبيقات SwiftUI","استيراد المكونات من @expo/ui/swift-ui"]},"keywords":{"en":["Expo UI SwiftUI setup guide","how to use Expo UI SwiftUI","what is Expo UI SwiftUI","Expo UI SwiftUI alternative","Expo UI SwiftUI vs React Native","install Expo UI SwiftUI","Expo UI SwiftUI documentation","SwiftUI Views in Expo","Expo UI SwiftUI SDK 55"],"zh":["Expo UI SwiftUI","SwiftUI视图","修饰符","原生重建","SDK55","AIエージェント","Expo UI API","SwiftUI API"],"ja":["Expo UI SwiftUI","SwiftUIビュー","修飾子","ネイティブリビルド","SDK55","AIエージェント","Expo UI API","SwiftUI API"],"ko":["Expo UI SwiftUI","SwiftUI 뷰","수정자","네이티브 리빌드","SDK55","AI 도구","Expo UI API","SwiftUI API"],"es":["Expo UI SwiftUI","desarrollo de aplicaciones móviles","vistas SwiftUI","modificadores SwiftUI","instalación de @expo/ui/swift-ui","reconstrucción nativa","API de SwiftUI","componentes de SwiftUI","herramientas de desarrollo de aplicaciones móviles"],"fr":["Expo UI SwiftUI","développement d''applications mobiles","vues SwiftUI","modificateurs SwiftUI","installation de @expo/ui/swift-ui","reconstruction native","API de SwiftUI","composants de SwiftUI","outils de développement d''applications mobiles"],"de":["Expo UI SwiftUI","Entwicklung von mobilen Anwendungen","SwiftUI-Ansichten","SwiftUI-Modifikatoren","Installation von @expo/ui/swift-ui","native Neuerstellung","SwiftUI-API","SwiftUI-Komponenten","Entwicklungstools für mobile Anwendungen"],"pt":["Expo UI SwiftUI","SwiftUI no Expo","Como usar SwiftUI no Expo","Guia de configuração do Expo UI SwiftUI","Instalar @expo/ui","Reconstruir aplicativo Expo"],"ru":["Expo UI SwiftUI","SwiftUI в Expo","Как использовать SwiftUI в Expo","Руководство по настройке Expo UI SwiftUI","Установить @expo/ui","Перестроить приложение Expo"],"ar":["Expo UI SwiftUI","SwiftUI في Expo","كيفية استخدام SwiftUI في Expo","دليل إعداد Expo UI SwiftUI","تثبيت @expo/ui","إعادة بناء تطبيق Expo"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Cross-Platform Agents needing native SwiftUI Views and modifiers in Expo applications.","zh":"适合于需要在 Expo 应用程序中使用原生 SwiftUI 视图和修饰符的跨平台代理。","ja":"Expo アプリケーションでネイティブの SwiftUI ビューと修飾子を使用する必要があるクロスプラットフォーム エージェントに適しています。","ko":"Expo 애플리케이션에서 네이티브 SwiftUI 뷰와 수정자를 사용해야 하는 크로스 플랫폼 에이전트에 적합합니다.","es":"Perfecto para agentes de plataforma cruzada que necesitan vistas y modificadores nativos de SwiftUI en aplicaciones de Expo.","fr":"Parfait pour les agents de plateforme croisée ayant besoin de vues et de modificateurs natifs de SwiftUI dans les applications Expo.","de":"Perfekt für Cross-Platform-Agents, die native SwiftUI-Views und -Modifikatoren in Expo-Anwendungen benötigen.","pt":"Perfeito para Agentes Cross-Platform que necessitam de visualizações SwiftUI nativas e modificadores em aplicativos Expo.","ru":"Идеально для агентов с поддержкой нескольких платформ, которым необходимы родные представления SwiftUI и модификаторы в приложениях Expo.","ar":"مثالي لعميل متعدد المنصات الذي يحتاج إلى معاينة SwiftUI الأصلية والمنظمات في تطبيقات Expo."},"recommendation":{"en":"Empowers agents to build native user interfaces using SwiftUI components and modifiers from @expo/ui/swift-ui, leveraging Expo''s SDK 55 for seamless integration and native rebuilds via npx expo run:ios.","zh":"赋予代理构建使用 @expo/ui/swift-ui 中的 SwiftUI 组件和修饰符的原生用户界面能力，利用 Expo 的 SDK 55 实现无缝集成和通过 npx expo run:ios 进行原生重建。","ja":"エージェントが @expo/ui/swift-ui にある SwiftUI コンポーネントと修飾子を使用してネイティブのユーザー インターフェイスを構築する機能を提供し、Expo の SDK 55 を使用してシームレスな統合と npx expo run:ios によるネイティブの再構築を実現します。","ko":"에이전트가 @expo/ui/swift-ui에 있는 SwiftUI 컴포넌트와 수정자를 사용하여 네이티브 사용자 인터페이스를 구축할 수 있는 기능을 제공하며, Expo의 SDK 55를 사용하여無縫な 통합과 npx expo run:ios를 통한 네이티브 재구성을 실현합니다.","es":"Habilita a los agentes a construir interfaces de usuario nativas utilizando componentes y modificadores de SwiftUI de @expo/ui/swift-ui, aprovechando el SDK 55 de Expo para una integración sin problemas y reconstrucciones nativas a través de npx expo run:ios.","fr":"Permet aux agents de créer des interfaces utilisateur natives en utilisant des composants et des modificateurs de SwiftUI de @expo/ui/swift-ui, en exploitant le SDK 55 d''Expo pour une intégration transparente et des reconstructions natives via npx expo run:ios.","de":"Ermöglicht es Agents, native Benutzeroberflächen zu erstellen, indem sie SwiftUI-Komponenten und -Modifikatoren von @expo/ui/swift-ui verwenden, und profitiert von Expo''s SDK 55 für eine nahtlose Integration und native Neuerstellungen über npx expo run:ios.","pt":"Permite que os agentes criem interfaces de usuário nativas usando componentes e modificadores SwiftUI de @expo/ui/swift-ui, aproveitando o SDK 55 do Expo para integração transparente e reconstrução nativa via npx expo run:ios.","ru":"Наделяет агентов возможностью создавать родные пользовательские интерфейсы, используя компоненты и модификаторы SwiftUI из @expo/ui/swift-ui, используя SDK 55 Expo для бесшовной интеграции и родной перестройки через npx expo run:ios.","ar":"يتمكن العملاء من إنشاء واجهات مستخدم أصلية باستخدام مكونات ووظائف تحرير SwiftUI من @expo/ui/swift-ui، واستغلال SDK 55 من Expo للحصول على دمج عديم الفواقي وإعادة بناء أصلية عبر npx expo run:ios."},"useCases":{"en":["Implementing custom SwiftUI Views in Expo apps","Utilizing SwiftUI modifiers for enhanced UI customization","Streamlining native rebuilds with npx expo run:ios"],"zh":["在 Expo 应用程序中实现自定义的 SwiftUI 视图","利用 SwiftUI 修饰符进行增强的 UI 自定义","通过 npx expo run:ios 进行原生重建的简化"],"ja":["Expo アプリケーションでカスタムの SwiftUI ビューを実装する","SwiftUI 修飾子を使用して UI カスタマイズを強化する","npx expo run:ios によるネイティブの再構築の簡素化"],"ko":["Expo 애플리케이션에서 사용자 지정 SwiftUI 뷰를 구현하는 것","SwiftUI 수정자를 사용하여 UI 사용자 지정 강화","npx expo run:ios를 통한 네이티브 재구성의 간소화"],"es":["Implementar vistas personalizadas de SwiftUI en aplicaciones de Expo","Utilizar modificadores de SwiftUI para una personalización de interfaz de usuario mejorada","Optimizar las reconstrucciones nativas con npx expo run:ios"],"fr":["Mettre en œuvre des vues personnalisées de SwiftUI dans les applications Expo","Utiliser des modificateurs de SwiftUI pour une personnalisation de l''interface utilisateur améliorée","Optimiser les reconstructions natives avec npx expo run:ios"],"de":["Implementierung benutzerdefinierter SwiftUI-Views in Expo-Apps","Verwendung von SwiftUI-Modifikatoren für eine verbesserte Benutzeroberflächenanpassung","Optimierung der nativen Neuerstellungen mit npx expo run:ios"],"pt":["Implementar visualizações SwiftUI personalizadas em aplicativos Expo","Utilizar modificadores SwiftUI para personalização de UI melhorada","Otimizar reconstruções nativas com npx expo run:ios"],"ru":["Реализация пользовательских представлений SwiftUI в приложениях Expo","Использование модификаторов SwiftUI для расширенной настройки интерфейса","Оптимизация родных перестроек с помощью npx expo run:ios"],"ar":["تنفيذ معاينة SwiftUI مخصصة في تطبيقات Expo","استخدام وظائف تحرير SwiftUI لتخصيص واجهة المستخدم المحسّن","تحسين إعادة بناء الأصلية مع npx expo run:ios"]},"limitations":{"en":["Requires SDK 55 for accurate functionality","Native rebuild required after installation"],"zh":["需要 SDK 55 以实现准确的功能","安装后需要原生重建"],"ja":["正確な機能を実現するために SDK 55 が必要","インストール後にはネイティブの再構築が必要"],"ko":["정확한 기능을 구현하기 위해 SDK 55가 필요","설치 후에는 네이티브 재구성이 필요"],"es":["Requiere SDK 55 para una funcionalidad precisa","Reconstrucción nativa necesaria después de la instalación"],"fr":["Nécessite le SDK 55 pour une fonctionnalité précise","Reconstruction native requise après l''installation"],"de":["Benötigt SDK 55 für eine genaue Funktionalität","Native Neuerstellung erforderlich nach der Installation"],"pt":["Requer SDK 55 para funcionalidade precisa","Reconstrução nativa necessária após instalação"],"ru":["Требуется SDK 55 для точной функциональности","Родная перестройка требуется после установки"],"ar":["يتطلب SDK 55 للوظيفة الدقيقة","إعادة بناء الأصلية مطلوبة بعد التثبيت"]},"version":4},"contentHash":"1eba564b9a28d1c1e391a6aa8245c37c7db6ec2df2ac4886179f47fcc1fdff5e","repoEtag":"W/\"3d0b500324a01c512d7df52a068a135b350d8e49d3ce113161c97e6acbc0dfba\"","qualityScore":86}');
