INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('expo/skills/expo-ui-swift-ui', 'Expo UI SwiftUI', 'expo', 'skills', 'official', 'Expo UI SwiftUI expo skills official Expo UI SwiftUI allows developers to use SwiftUI Views and modifiers in their apps, leveraging the @expo/ui/swift-ui package for seamless integration. Expo UI SwiftUI允许您在应用中使用SwiftUI视图和修饰符。通过@expo/ui/swift-ui包，实现原生重建和SDK55支持 Expo UI SwiftUIは、アプリでSwiftUIビューと修飾子を使用できるようにします。@expo/ui/swift-uiパッケージを使用して、ネイティブリビルドとSDK55サポートを実現します Expo UI SwiftUI는 앱에서 SwiftUI 뷰와 수정자를 사용할 수 있게 해줍니다. @expo/ui/swift-ui 패키지를 사용하여 네이티브 리빌드와 SDK55 지원을 구현합니다 Expo UI SwiftUI permite a los desarrolladores utilizar vistas y modificadores SwiftUI en sus aplicaciones móviles. Instale @expo/ui/swift-ui y comience a crear Expo UI SwiftUI permet aux développeurs d''utiliser des vues et des modificateurs SwiftUI dans leurs applications mobiles. Installez @expo/ui/swift-ui et commencez à créer Expo UI SwiftUI ermöglicht es Entwicklern, SwiftUI-Ansichten und -Modifikatoren in ihren mobilen Anwendungen zu verwenden. Installieren Sie @expo/ui/swift-ui und beginnen Sie mit der Erstellung O pacote @expo/ui/swift-ui permite usar views e modificadores do SwiftUI no Expo Пакет @expo/ui/swift-ui позволяет использовать представления и модификаторы SwiftUI в Expo يسمح لك حزمة @expo/ui/swift-ui باستخدام العروض والمعدلات من SwiftUI في Expo Expo UI SwiftUI setup guide how to use Expo UI SwiftUI what is Expo UI SwiftUI Expo UI SwiftUI alternative Expo UI SwiftUI vs React Native install Expo UI SwiftUI Expo UI SwiftUI documentation SwiftUI Views in Expo Expo UI SwiftUI SDK 55 Expo UI SwiftUI SwiftUI视图 修饰符 原生重建 SDK55 AIエージェント Expo UI API SwiftUI API Installs via npx expo install @expo/ui command Requires native rebuild using npx expo run:ios Mirrors SwiftUI''s API for component and modifier usage Imports components from @expo/ui/swift-ui Supports modifiers from @expo/ui/swift-ui Compatible with SDK 55 Expo UI SwiftUI is a package that enables the use of SwiftUI Views and modifiers in Expo applications, mirroring SwiftUI''s API for native app development');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('n8n-io/n8n/create-pr', 'official', 'n8n-io', 'n8n', 'n8n-io/n8n', 'create-pr', 177792, 55472, 86, '2026-03-06T06:12:37Z', '2026-03-06T06:18:37.259Z', 'e07cc290393b95939035ff7a6e19277f82c3285d211f23849914310c25a22873', '{"id":"n8n-io/n8n/create-pr","name":"create-pr","description":{"en":"The create-pr skill automates the creation of GitHub pull requests with properly formatted titles, passing n8n''s check-pr-title CI validation. This benefits developers by simplifying their workflow.","zh":"Create PR AI Agent创建GitHub拉取请求，标题格式为 `<type>(<scope>): <summary>`，支持feat、fix、perf等类型","ja":"Create PR AIエージェントは、GitHubプルリクエストを作成し、タイトルフォーマットは `<type>(<scope>): <summary>` です。feat、fix、perfなどのタイプをサポートしています","ko":"Create PR AI 에이전트는 GitHub 풀 리퀘스트를 생성하며, 제목 형식은 `<type>(<scope>): <summary>`입니다. feat, fix, perf 등의 유형을 지원합니다","es":"Crea solicitudes de extracción en GitHub con títulos formateados correctamente que pasan la validación de check-pr-title CI","fr":"Créez des demandes d''extraction sur GitHub avec des titres formatés correctement qui passent la validation de check-pr-title CI","de":"Erstellen Sie Pull-Requests in GitHub mit korrekt formatierten Titeln, die die check-pr-title CI-Validierung bestehen","pt":"O Create-PR cria solicitações de pull no GitHub com títulos formatados corretamente, passando na validação do CI check-pr-title","ru":"ИИ Агент Create-PR создает запросы на вытягивание в GitHub с правильными заголовками, проходящими проверку CI check-pr-title","ar":"أداة Create-PR تخلق طلبات السحب على الغيت هاب مع عناوين منسقة بشكل صحيح، وتنجح في التحقق من صحة CI check-pr-title"},"owner":"n8n-io","repo":"n8n","repoPath":"n8n-io/n8n","stars":177792,"forks":55472,"updatedAt":"2026-03-06T06:12:37Z","topics":["ai","apis","automation","cli","data-flow","development","integration-framework","integrations","ipaas","low-code","low-code-platform","mcp","mcp-client","mcp-server","n8n","no-code","self-hosted","typescript","workflow","workflow-automation"],"skillMd":{"name":"create-pr","description":"Creates GitHub pull requests with properly formatted titles that pass the check-pr-title CI validation. Use when creating PRs, submitting changes for review, or when the user says /pr or asks to create a pull request.","bodyPreview":"# Create Pull Request\n\nCreates GitHub PRs with titles that pass n8n''s `check-pr-title` CI validation.\n\n## PR Title Format\n\n```\n<type>(<scope>): <summary>\n```\n\n### Types (required)\n\n| Type       | Description                                      | Changelog |\n|------------|--------------------------------------------------|-----------|\n| `feat`     | New feature                                      | Yes       |\n| `fix`      | Bug fix                                          | Yes       |\n| `perf","body":"# Create Pull Request\n\nCreates GitHub PRs with titles that pass n8n''s `check-pr-title` CI validation.\n\n## PR Title Format\n\n```\n<type>(<scope>): <summary>\n```\n\n### Types (required)\n\n| Type       | Description                                      | Changelog |\n|------------|--------------------------------------------------|-----------|\n| `feat`     | New feature                                      | Yes       |\n| `fix`      | Bug fix                                          | Yes       |\n| `perf`     | Performance improvement                          | Yes       |\n| `test`     | Adding/correcting tests                          | No        |\n| `docs`     | Documentation only                               | No        |\n| `refactor` | Code change (no bug fix or feature)              | No        |\n| `build`    | Build system or dependencies                     | No        |\n| `ci`       | CI configuration                                 | No        |\n| `chore`    | Routine tasks, maintenance                       | No        |\n\n### Scopes (optional but recommended)\n\n- `API` - Public API changes\n- `benchmark` - Benchmark CLI changes\n- `core` - Core/backend/private API\n- `editor` - Editor UI changes\n- `* Node` - Specific node (e.g., `Slack Node`, `GitHub Node`)\n\n### Summary Rules\n\n- Use imperative present tense: \"Add\" not \"Added\"\n- Capitalize first letter\n- No period at the end\n- No ticket IDs (e.g., N8N-1234)\n- Add `(no-changelog)` suffix to exclude from changelog\n\n## Steps\n\n1. **Check current state**:\n   ```bash\n   git status\n   git diff --stat\n   git log origin/master..HEAD --oneline\n   ```\n\n2. **Analyze changes** to determine:\n   - Type: What kind of change is this?\n   - Scope: Which package/area is affected?\n   - Summary: What does the change do?\n\n3. **Push branch if needed**:\n   ```bash\n   git push -u origin HEAD\n   ```\n\n4. **Create PR** using gh CLI with the template from `.github/pull_request_template.md`:\n   ```bash\n   gh pr create --draft --title \"<type>(<scope>): <summary>\" --body \"$(cat <<''EOF''\n   ## Summary\n\n   <Describe what the PR does and how to test. Photos and videos are recommended.>\n\n   ## Related Linear tickets, Github issues, and Community forum posts\n\n   <!-- Link to Linear ticket: https://linear.app/n8n/issue/[TICKET-ID] -->\n   <!-- Use \"closes #<issue-number>\", \"fixes #<issue-number>\", or \"resolves #<issue-number>\" to automatically close issues -->\n\n   ## Review / Merge checklist\n\n   - [ ] PR title and summary are descriptive. ([conventions](../blob/master/.github/pull_request_title_conventions.md))\n   - [ ] [Docs updated](https://github.com/n8n-io/n8n-docs) or follow-up ticket created.\n   - [ ] Tests included.\n   - [ ] PR Labeled with `release/backport` (if the PR is an urgent fix that needs to be backported)\n   EOF\n   )\"\n   ```\n\n## PR Body Guidelines\n\nBased on `.github/pull_request_template.md`:\n\n### Summary Section\n- Describe what the PR does\n- Explain how to test the changes\n- Include screenshots/videos for UI changes\n\n### Related Links Section\n- Link to Linear ticket: `https://linear.app/n8n/issue/[TICKET-ID]`\n- Link to GitHub issues using keywords to auto-close:\n  - `closes #123` / `fixes #123` / `resolves #123`\n- Link to Community forum posts if applicable\n\n### Checklist\nAll items should be addressed before merging:\n- PR title follows conventions\n- Docs updated or follow-up ticket created\n- Tests included (bugs need regression tests, features need coverage)\n- `release/backport` label added if urgent fix needs backporting\n\n## Examples\n\n### Feature in editor\n```\nfeat(editor): Add workflow performance metrics display\n```\n\n### Bug fix in core\n```\nfix(core): Resolve memory leak in execution engine\n```\n\n### Node-specific change\n```\nfix(Slack Node): Handle rate limiting in message send\n```\n\n### Breaking change (add exclamation mark before colon)\n```\nfeat(API)!: Remove deprecated v1 endpoints\n```\n\n### No changelog entry\n```\nrefactor(core): Simplify error handling (no-changelog)\n```\n\n### No scope (affects multiple areas)\n```\nchore: Update dependencies to latest versions\n```\n\n## Validation\n\nThe PR title must match this pattern:\n```\n^(feat|fix|perf|test|docs|refactor|build|ci|chore|revert)(\\([a-zA-Z0-9 ]+( Node)?\\))?!?: [A-Z].+[^.]$\n```\n\nKey validation rules:\n- Type must be one of the allowed types\n- Scope is optional but must be in parentheses if present\n- Exclamation mark for breaking changes goes before the colon\n- Summary must start with capital letter\n- Summary must not end with a period\n"},"category":"official","lastSynced":"2026-03-06T06:18:37.259Z","seo":{"title":{"en":"create-pr: Automated GitHub Pull Request Creation | AI Ag...","zh":"创建GitHub拉取请求的最佳实践 - Create PR Setup Guide","ja":"GitHubプルリクエストを作成する - AIエージェントによるCreate PR","ko":"GitHub 풀 리퀘스트 생성 가이드 - Create PR Setup","es":"Guía de configuración de create-pr para GitHub","fr":"Guide de mise en place de create-pr pour GitHub","d